-- functions
CREATE OR REPLACE FUNCTION public._admin_covers_region(p_admin uuid, p_region uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (
    select 1 from public.admin_region_assignments a
    where a.admin_id = p_admin
      and (
        (a.scope = 'self' and a.region_id = p_region)
        or (a.scope = 'descendants' and p_region in (
          with recursive covered as (
            select id from public.regions where id = a.region_id
            union all
            select r.id from public.regions r join covered c on r.parent_region_id = c.id
          )
          select id from covered
        ))
      )
  );
$function$
;
CREATE OR REPLACE FUNCTION public._admin_exec_create(p_actor uuid, p_user_id uuid, p_supervisor_id uuid DEFAULT NULL::uuid, p_region_id uuid DEFAULT NULL::uuid, p_scope text DEFAULT 'descendants'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_supervisor uuid;
  v_role text;
BEGIN
  IF NOT (public._is_owner_uid(p_actor) OR public._is_active_admin_uid(p_actor)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT role INTO v_role FROM public.users WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'User not found';
  END IF;
  IF v_role = 'owner' THEN
    RAISE EXCEPTION 'Cannot manage the owner';
  END IF;
  IF EXISTS (SELECT 1 FROM public.admin_management WHERE admin_id = p_user_id) THEN
    RAISE EXCEPTION 'User is already an admin';
  END IF;
  -- (c) only owner creates admin at root level
  IF p_supervisor_id IS NULL AND NOT public._is_owner_uid(p_actor) THEN
    RAISE EXCEPTION 'Only the owner creates admins at root level';
  END IF;
  v_supervisor := COALESCE(p_supervisor_id, p_actor);
  IF v_supervisor = p_user_id THEN
    RAISE EXCEPTION 'Cannot supervise yourself';
  END IF;
  IF NOT (public._is_owner_uid(v_supervisor) OR public._is_active_admin_uid(v_supervisor)) THEN
    RAISE EXCEPTION 'Invalid supervisor';
  END IF;
  -- placement must stay inside the actor's branch
  IF NOT public._is_owner_uid(p_actor)
     AND v_supervisor <> p_actor
     AND NOT public.is_supervisor_of(p_actor, v_supervisor) THEN
    RAISE EXCEPTION 'Supervisor outside your branch';
  END IF;
  -- (b) region containment
  IF p_region_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.regions WHERE id = p_region_id) THEN
      RAISE EXCEPTION 'Region not found';
    END IF;
    IF NOT public._is_owner_uid(p_actor)
       AND NOT public._region_in_scope(p_actor, p_region_id) THEN
      RAISE EXCEPTION 'Region outside your scope';
    END IF;
  END IF;

  INSERT INTO public.admin_management (admin_id, supervisor_id, is_active, created_by)
  VALUES (p_user_id, v_supervisor, true, p_actor);

  UPDATE public.users SET role = 'admin' WHERE id = p_user_id;

  IF p_region_id IS NOT NULL THEN
    INSERT INTO public.admin_region_assignments (admin_id, region_id, scope, created_by)
    VALUES (p_user_id, p_region_id, p_scope, p_actor)
    ON CONFLICT (admin_id, region_id)
    DO UPDATE SET scope = EXCLUDED.scope, created_by = EXCLUDED.created_by;
  END IF;

  PERFORM public.write_audit(
    'ADMIN_CREATED', 'admin_management', p_user_id::text,
    jsonb_build_object('actor', p_actor::text, 'supervisor', v_supervisor::text,
                       'region_id', p_region_id, 'scope', p_scope));

  INSERT INTO public.notifications (user_id, title, body, type, data, deep_link, idempotency_key)
  VALUES (
    p_user_id,
    'Admin account created',
    'You now have admin access. Your supervisor is ' || v_supervisor::text || '.',
    'admin_management',
    jsonb_build_object('admin_id', p_user_id::text, 'supervisor_id', v_supervisor::text),
    '/admin/branches',
    'admin-create-' || p_user_id::text || '-' || gen_random_uuid()::text
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._admin_exec_deactivate(p_actor uuid, p_admin_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_target_role text;
BEGIN
  IF p_admin_id = p_actor THEN
    RAISE EXCEPTION 'Cannot deactivate yourself';
  END IF;
  IF NOT (public._is_owner_uid(p_actor) OR public.is_supervisor_of(p_actor, p_admin_id)) THEN
    RAISE EXCEPTION 'Not authorized for this admin';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.admin_management WHERE admin_id = p_admin_id AND is_active) THEN
    RAISE EXCEPTION 'Not an active admin';
  END IF;
  SELECT role INTO v_target_role FROM public.users WHERE id = p_admin_id;
  IF v_target_role = 'owner' THEN
    RAISE EXCEPTION 'Cannot deactivate the owner';
  END IF;

  UPDATE public.admin_management
    SET is_active = false, updated_at = now()
    WHERE admin_id = p_admin_id;

  -- defense-in-depth: demote so literal `role = 'admin'` checks also fail
  UPDATE public.users SET role = 'customer' WHERE id = p_admin_id;

  PERFORM public.write_audit(
    'ADMIN_DEACTIVATED', 'admin_management', p_admin_id::text,
    jsonb_build_object('actor', p_actor::text, 'reason', p_reason));

  INSERT INTO public.notifications (user_id, title, body, type, data, deep_link, idempotency_key)
  VALUES (
    p_admin_id,
    'Admin access removed',
    COALESCE(p_reason, 'Your admin access has been removed.'),
    'admin_management',
    jsonb_build_object('admin_id', p_admin_id::text),
    '/admin/branches',
    'admin-deactivate-' || p_admin_id::text || '-' || gen_random_uuid()::text
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._admin_exec_reactivate(p_actor uuid, p_admin_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.admin_management%ROWTYPE;
  v_role text;
  v_region_id uuid;
BEGIN
  IF p_admin_id = p_actor THEN
    RAISE EXCEPTION 'Cannot reactivate yourself';
  END IF;
  SELECT * INTO v_row FROM public.admin_management WHERE admin_id = p_admin_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Not an admin';
  END IF;
  -- authorization: owner, the direct supervisor, or a supervisor of the supervisor
  IF NOT (public._is_owner_uid(p_actor)
          OR v_row.supervisor_id = p_actor
          OR public.is_supervisor_of(p_actor, v_row.supervisor_id)) THEN
    RAISE EXCEPTION 'Not authorized for this admin';
  END IF;
  SELECT role INTO v_role FROM public.users WHERE id = p_admin_id;
  IF v_role = 'owner' THEN
    RAISE EXCEPTION 'Cannot reactivate the owner';
  END IF;
  -- region containment
  FOR v_region_id IN
    SELECT region_id FROM public.admin_region_assignments WHERE admin_id = p_admin_id
  LOOP
    IF NOT public._is_owner_uid(p_actor)
       AND NOT public._region_in_scope(p_actor, v_region_id) THEN
      RAISE EXCEPTION 'Region outside your scope';
    END IF;
  END LOOP;
  -- idempotent
  IF v_row.is_active THEN
    RETURN;
  END IF;

  UPDATE public.admin_management
    SET is_active = true, updated_at = now()
    WHERE admin_id = p_admin_id;

  UPDATE public.users SET role = 'admin' WHERE id = p_admin_id AND role <> 'admin';

  PERFORM public.write_audit(
    'ADMIN_REACTIVATED', 'admin_management', p_admin_id::text,
    jsonb_build_object('actor', p_actor::text, 'reason', p_reason));
END;
$function$
;
CREATE OR REPLACE FUNCTION public._admin_exec_region(p_actor uuid, p_admin_id uuid, p_region_id uuid, p_scope text DEFAULT 'descendants'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_admin_id = p_actor THEN
    RAISE EXCEPTION 'Cannot change your own scope';
  END IF;
  IF NOT (public._is_owner_uid(p_actor) OR public.is_supervisor_of(p_actor, p_admin_id)) THEN
    RAISE EXCEPTION 'Not authorized for this admin';
  END IF;
  IF p_scope NOT IN ('self','descendants') THEN
    RAISE EXCEPTION 'Invalid scope';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.regions WHERE id = p_region_id) THEN
    RAISE EXCEPTION 'Region not found';
  END IF;
  -- (b) region containment: the assigning actor must hold the region in scope
  IF NOT public._is_owner_uid(p_actor)
     AND NOT public._region_in_scope(p_actor, p_region_id) THEN
    RAISE EXCEPTION 'Region outside your scope';
  END IF;

  INSERT INTO public.admin_region_assignments (admin_id, region_id, scope, created_by)
  VALUES (p_admin_id, p_region_id, p_scope, p_actor)
  ON CONFLICT (admin_id, region_id)
  DO UPDATE SET scope = EXCLUDED.scope, created_by = EXCLUDED.created_by;

  PERFORM public.write_audit(
    'ADMIN_REGION_CHANGED', 'admin_region_assignments', p_admin_id::text,
    jsonb_build_object('actor', p_actor::text, 'region_id', p_region_id,
                       'scope', p_scope));
END;
$function$
;
CREATE OR REPLACE FUNCTION public._admin_exec_role(p_actor uuid, p_admin_id uuid, p_new_role text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_in_tree boolean;
  v_target_role text;
BEGIN
  IF p_admin_id = p_actor THEN
    RAISE EXCEPTION 'Cannot change your own role';
  END IF;
  IF NOT (public._is_owner_uid(p_actor) OR public.is_supervisor_of(p_actor, p_admin_id)) THEN
    RAISE EXCEPTION 'Not authorized for this admin';
  END IF;
  IF p_new_role NOT IN ('customer','merchant','driver','admin','owner','provider','delivery') THEN
    RAISE EXCEPTION 'Invalid role';
  END IF;
  IF p_new_role = 'owner' AND NOT public._is_owner_uid(p_actor) THEN
    RAISE EXCEPTION 'Only the owner can grant the owner role';
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.admin_management WHERE admin_id = p_admin_id)
    INTO v_in_tree;
  IF p_new_role = 'admin' AND NOT v_in_tree THEN
    RAISE EXCEPTION 'Use create_admin_account to create admins';
  END IF;
  -- role='admin' must stay aligned with an ACTIVE tree row (a deactivated admin
  -- cannot be silently re-armed without a proper reactivation flow)
  IF p_new_role = 'admin'
     AND NOT EXISTS (
       SELECT 1 FROM public.admin_management
       WHERE admin_id = p_admin_id AND is_active
     ) THEN
    RAISE EXCEPTION 'Admin is deactivated';
  END IF;
  SELECT role INTO v_target_role FROM public.users WHERE id = p_admin_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'User not found';
  END IF;
  IF v_target_role = 'owner' THEN
    RAISE EXCEPTION 'Cannot change the owner role';
  END IF;

  UPDATE public.users SET role = p_new_role WHERE id = p_admin_id;

  -- role and tree stay in sync: promoting to owner or demoting to a non-admin
  -- role removes the tree row (owner is implicit root; demoted admins lose all
  -- admin authority).
  IF p_new_role <> 'admin' THEN
    DELETE FROM public.admin_management WHERE admin_id = p_admin_id;
  END IF;

  PERFORM public.write_audit(
    'ADMIN_ROLE_CHANGED', 'admin_management', p_admin_id::text,
    jsonb_build_object('actor', p_actor::text, 'new_role', p_new_role,
                       'reason', p_reason));
END;
$function$
;
CREATE OR REPLACE FUNCTION public._admin_exec_supervisor(p_actor uuid, p_admin_id uuid, p_new_supervisor_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_region_id uuid;
BEGIN
  IF p_admin_id = p_actor THEN
    RAISE EXCEPTION 'Cannot change your own supervisor';
  END IF;
  IF NOT (public._is_owner_uid(p_actor) OR public.is_supervisor_of(p_actor, p_admin_id)) THEN
    RAISE EXCEPTION 'Not authorized for this admin';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.admin_management WHERE admin_id = p_admin_id AND is_active) THEN
    RAISE EXCEPTION 'Not an active admin';
  END IF;
  IF p_new_supervisor_id = p_admin_id THEN
    RAISE EXCEPTION 'Cannot be your own supervisor';
  END IF;
  IF NOT (public._is_owner_uid(p_new_supervisor_id) OR public._is_active_admin_uid(p_new_supervisor_id)) THEN
    RAISE EXCEPTION 'Invalid supervisor';
  END IF;
  -- new supervisor must be inside the actor's branch (unless actor is owner)
  IF NOT public._is_owner_uid(p_actor)
     AND p_new_supervisor_id <> p_actor
     AND NOT public.is_supervisor_of(p_actor, p_new_supervisor_id) THEN
    RAISE EXCEPTION 'New supervisor outside your branch';
  END IF;
  -- (a) no cycles: the new supervisor may not already be a subordinate of the
  -- moved admin (would make the subtree loop back onto itself)
  IF public.is_supervisor_of(p_admin_id, p_new_supervisor_id) THEN
    RAISE EXCEPTION 'Cannot create a supervision cycle';
  END IF;
  -- (b) the new supervisor's reachable scope must cover the admin's regions
  FOR v_region_id IN
    SELECT region_id FROM public.admin_region_assignments WHERE admin_id = p_admin_id
  LOOP
    IF NOT public._is_owner_uid(p_new_supervisor_id)
       AND NOT public._region_in_scope(p_new_supervisor_id, v_region_id) THEN
      RAISE EXCEPTION 'New supervisor scope does not cover target regions';
    END IF;
  END LOOP;

  UPDATE public.admin_management
    SET supervisor_id = p_new_supervisor_id, updated_at = now()
    WHERE admin_id = p_admin_id;

  PERFORM public.write_audit(
    'ADMIN_SUPERVISOR_CHANGED', 'admin_management', p_admin_id::text,
    jsonb_build_object('actor', p_actor::text, 'new_supervisor_id',
                       p_new_supervisor_id::text, 'reason', p_reason));
END;
$function$
;
CREATE OR REPLACE FUNCTION public._admin_scope_allows(p_region_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role text;
begin
  if not public.is_admin() then
    return false;
  end if;
  select role into v_role from public.users where id = auth.uid();
  if v_role = 'owner' then
    return true;
  end if;
  if not exists (select 1 from public.admin_region_assignments a where a.admin_id = auth.uid()) then
    return true;
  end if;
  if p_region_id is null then
    return false;
  end if;
  return public._admin_covers_region(auth.uid(), p_region_id);
end;
$function$
;
CREATE OR REPLACE FUNCTION public._appeals_admin_read_allowed(p_region_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role text;
begin
  if not public.is_admin() then
    return false;
  end if;
  select role into v_role from public.users where id = auth.uid();
  -- Owner sees all (final fallback of the duty chain).
  if v_role = 'owner' then
    return true;
  end if;
  -- Global admins (no region assignment rows) are the duty-chain fallback for
  -- every region, including NULL-region appeals.
  if not exists (
    select 1 from public.admin_region_assignments a where a.admin_id = auth.uid()
  ) then
    return true;
  end if;
  -- Region-assigned admins read only appeals inside their coverage; NULL-region
  -- appeals route to the fallbacks only, like _duty_admin_for_region does.
  if p_region_id is null then
    return false;
  end if;
  return public._admin_covers_region(auth.uid(), p_region_id);
end;
$function$
;
CREATE OR REPLACE FUNCTION public._approval_apply(p_request approval_requests, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_payload jsonb;
  v_campaign public.campaigns%ROWTYPE;
BEGIN
  v_payload := COALESCE(p_request.payload, '{}'::jsonb);

  CASE p_request.request_type
    WHEN 'campaign_approve' THEN
      SELECT * INTO v_campaign FROM public.campaigns c WHERE c.id = p_request.entity_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Campaign not found';
      END IF;
      IF v_campaign.status <> 'pending_review' THEN
        RAISE EXCEPTION 'Campaign is not pending review';
      END IF;
      IF NOT public.campaign_targets_authorized(v_campaign.id) THEN
        RAISE EXCEPTION 'Not authorized for this campaign region scope';
      END IF;
      UPDATE public.campaigns SET status = 'approved' WHERE id = v_campaign.id;
      INSERT INTO public.campaign_reviews
        (campaign_id, reviewer_id, action, previous_state, new_state, reason)
      VALUES (v_campaign.id, auth.uid(), 'approve', 'pending_review', 'approved', p_reason);

    WHEN 'admin_create' THEN
      PERFORM public._admin_exec_create(
        auth.uid(),
        (v_payload->>'user_id')::uuid,
        NULLIF(v_payload->>'supervisor_id', '')::uuid,
        NULLIF(v_payload->>'region_id', '')::uuid,
        COALESCE(v_payload->>'scope', 'descendants'));

    WHEN 'admin_role_change' THEN
      PERFORM public._admin_exec_role(
        auth.uid(),
        (v_payload->>'admin_id')::uuid,
        v_payload->>'new_role',
        COALESCE(p_reason, v_payload->>'reason'));

    WHEN 'admin_region_change' THEN
      PERFORM public._admin_exec_region(
        auth.uid(),
        (v_payload->>'admin_id')::uuid,
        (v_payload->>'region_id')::uuid,
        COALESCE(v_payload->>'scope', 'descendants'));

    WHEN 'admin_supervisor_change' THEN
      PERFORM public._admin_exec_supervisor(
        auth.uid(),
        (v_payload->>'admin_id')::uuid,
        (v_payload->>'new_supervisor_id')::uuid,
        COALESCE(p_reason, v_payload->>'reason'));

    WHEN 'admin_deactivate' THEN
      PERFORM public._admin_exec_deactivate(
        auth.uid(),
        (v_payload->>'admin_id')::uuid,
        COALESCE(p_reason, v_payload->>'reason'));

    WHEN 'member_ban' THEN
      PERFORM public._member_exec_sanction(
        auth.uid(),
        (v_payload->>'member_id')::uuid,
        v_payload->>'sanction_type',
        COALESCE(p_reason, v_payload->>'reason'),
        COALESCE((v_payload->>'duration_days')::int, 0),
        COALESCE((v_payload->>'amount')::numeric, 0),
        v_payload->>'evidence_url',
        true);

    WHEN 'member_delete' THEN
      PERFORM public._member_exec_delete(
        auth.uid(),
        (v_payload->>'member_id')::uuid,
        COALESCE(p_reason, v_payload->>'reason'));

    WHEN 'reward_config_change' THEN
      PERFORM public._reward_config_exec(
        auth.uid(),
        NULLIF(v_payload->>'region_id', '')::uuid,
        v_payload->>'reward_type',
        v_payload->'config',
        COALESCE(p_reason, v_payload->>'reason'));

    ELSE
      RAISE EXCEPTION 'Unsupported request type';
  END CASE;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._assign_chat_to_admin(p_room_id uuid, p_admin_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_customer_id uuid;
BEGIN
  UPDATE public.chat_rooms
     SET assigned_admin_id = p_admin_id,
         assigned_at = now(),
         status = p_status
   WHERE id = p_room_id;

  SELECT participant_ids[1] INTO v_customer_id
  FROM public.chat_rooms WHERE id = p_room_id;

  INSERT INTO public.notifications
    (user_id, title, body, type, data, deep_link, idempotency_key)
  VALUES (
    p_admin_id,
    CASE WHEN p_status = 'assigned' THEN 'New support chat assigned' ELSE 'Support chat escalated' END,
    'Room ' || p_room_id::text,
    CASE WHEN p_status = 'assigned' THEN 'chat_assigned' ELSE 'chat_escalated' END,
    jsonb_build_object('room_id', p_room_id::text),
    '/admin/support-chat/room/' || p_room_id::text,
    'chat-assign-' || p_room_id::text || '-' || p_admin_id::text
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._campaign_region_visible(p_campaign_id uuid, p_member_region uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1
      FROM public.campaign_targets t
     WHERE t.campaign_id = p_campaign_id
       AND (
         t.region_id IS NULL
         OR t.region_id = p_member_region
         OR t.region_id IN (
           WITH RECURSIVE region_chain AS (
             SELECT p_member_region AS region_id
             UNION ALL
             SELECT r.parent_region_id
               FROM public.regions r
               JOIN region_chain rc ON r.id = rc.region_id
              WHERE r.parent_region_id IS NOT NULL
           )
           SELECT region_id FROM region_chain
         )
       )
  );
$function$
;
CREATE OR REPLACE FUNCTION public._commission_bucket_amount(p_from timestamp with time zone, p_to timestamp with time zone, p_bucket text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rate numeric;
  v_key text;
BEGIN
  IF p_bucket = 'merchant' THEN
    v_key := 'merchant';
  ELSE
    v_key := 'provider';
  END IF;
  SELECT c.rate INTO v_rate
    FROM public.commission_rules c
   WHERE c.entity_type = 'account_type'
     AND c.entity_key = v_key
     AND c.effective_from <= CURRENT_DATE
     AND (c.effective_to IS NULL OR c.effective_to >= CURRENT_DATE)
   ORDER BY c.effective_from DESC, c.created_at DESC
   LIMIT 1;
  v_rate := COALESCE(v_rate, CASE WHEN p_bucket = 'merchant' THEN 3 ELSE 7 END);
  RETURN (SELECT COALESCE(SUM(pc.commission_amount), 0)
            FROM public.platform_commissions pc
           WHERE pc.commission_rate = v_rate
             AND pc.created_at >= p_from
             AND pc.created_at <= p_to);
END;
$function$
;
CREATE OR REPLACE FUNCTION public._dispatch_delivery_internal(p_ride_id uuid, p_radius_km numeric DEFAULT 10, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ride RECORD;
  v_driver RECORD;
  v_offered_count INTEGER := 0;
  v_found_any BOOLEAN := false;
  v_is_cash BOOLEAN := false;
  v_ceiling numeric;
BEGIN
  SELECT * INTO v_ride FROM public.rides WHERE id = p_ride_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'ride_not_found');
  END IF;
  IF v_ride.status != 'searching' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_searching');
  END IF;

  v_is_cash := lower(COALESCE(v_ride.payment_method, '')) = 'cash'
    OR EXISTS (
      SELECT 1 FROM public.orders o
       WHERE o.id = v_ride.order_id AND lower(COALESCE(o.payment_method,'')) = 'cash'
    );
  IF v_is_cash THEN
    SELECT settlement_driver_cash_ceiling INTO v_ceiling
      FROM public._settlement_settings();
    v_ceiling := COALESCE(v_ceiling, 1000);
  END IF;

  UPDATE public.ride_requests SET status='expired',responded_at=now()
    WHERE ride_id=p_ride_id AND status='offered' AND expires_at <= now();

  FOR v_driver IN
    SELECT d.id, d.user_id,
      haversine_km(v_ride.pickup_latitude, v_ride.pickup_longitude,
                   d.current_latitude, d.current_longitude) AS dist_km
    FROM drivers d
    WHERE d.status = 'online'
      AND d.location_updated_at > now() - interval '2 minutes'
      AND d.is_verified = true
      AND d.is_active = true
      -- Only active engagements exclude: an offer that EXPIRED unanswered may
      -- be re-offered (automatic retry); a rejected, accepted or cancelled
      -- one may not.
      AND NOT EXISTS (SELECT 1 FROM public.ride_requests previous WHERE previous.ride_id=p_ride_id AND previous.driver_id=d.id AND previous.status IN ('offered','accepted','rejected','cancelled'))
      AND NOT EXISTS (SELECT 1 FROM public.rides busy WHERE busy.driver_id=d.id AND busy.status IN ('matched','arrived','inTrip'))
      AND d.active_vehicle_id IS NOT NULL
      AND d.active_vehicle_id IN (
        SELECT v.id FROM vehicles v
        WHERE v.driver_id = d.id
          AND v.is_active = true
          AND (v.category = v_ride.ride_type OR v_ride.service_type != 'ride')
      )
      AND (d.accepts_deliveries = true OR v_ride.service_type = 'ride')
      AND d.current_latitude IS NOT NULL
      AND d.current_longitude IS NOT NULL
      AND haversine_km(v_ride.pickup_latitude, v_ride.pickup_longitude,
                       d.current_latitude, d.current_longitude) <= p_radius_km
      -- Settlement gate (cash only): no overdue open obligation and the
      -- weighted open total (open=1x, disputed=0.5x) stays within the ceiling.
      AND (
        NOT v_is_cash
        OR (
          NOT EXISTS (
            SELECT 1 FROM public.driver_obligations ob
             WHERE ob.driver_id = d.id AND ob.status = 'open' AND ob.due_at < now()
          )
          AND COALESCE((
            SELECT sum(CASE WHEN ob.status = 'open' THEN ob.amount ELSE ob.amount / 2 END)
              FROM public.driver_obligations ob
             WHERE ob.driver_id = d.id AND ob.status IN ('open','disputed')
          ), 0) <= v_ceiling
        )
      )
    ORDER BY dist_km ASC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 5), 30))
  LOOP
    -- The (ride_id, driver_id) uniqueness means a re-offer revives the
    -- expired row with a fresh window instead of inserting a twin.
    INSERT INTO ride_requests (ride_id, driver_id, status, distance_km, offered_at, expires_at)
    VALUES (
      p_ride_id, v_driver.id, 'offered', v_driver.dist_km,
      NOW(), NOW() + interval '20 seconds'
    )
    ON CONFLICT (ride_id, driver_id) DO UPDATE
      SET status = 'offered', distance_km = EXCLUDED.distance_km,
          offered_at = NOW(), expires_at = NOW() + interval '20 seconds',
          responded_at = NULL;
    v_offered_count := v_offered_count + 1;
    v_found_any := true;
  END LOOP;

  IF NOT v_found_any AND EXISTS (
    SELECT 1 FROM public.ride_requests WHERE ride_id=p_ride_id
      AND status='offered' AND expires_at > now()
  ) THEN
    RETURN jsonb_build_object('success', true, 'offered_to', 0, 'reason', 'offers_pending');
  END IF;
  IF NOT v_found_any THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_drivers_available');
  END IF;

  RETURN jsonb_build_object('success', true, 'offered_to', v_offered_count);
END;
$function$
;
CREATE OR REPLACE FUNCTION public._driver_delay_redispatch(p_ride_id uuid, p_reason text, p_reported_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ride public.rides%rowtype;
  v_driver_id uuid;
  v_driver_uid uuid;
  v_count int;
  v_within boolean;
  v_cfg public.platform_settings%rowtype;
  v_allowance int;
  v_apology numeric;
  v_dispatch jsonb;
  v_offered boolean;
  v_customer uuid;
  v_merchant_uid uuid;
  v_short text;
  v_prior_apologies int;
  v_reason text;
begin
  select * into v_ride from public.rides where id = p_ride_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'RIDE_NOT_FOUND');
  end if;
  -- Goods already picked up: custody path (report_delivery_incident), not delay.
  if v_ride.status not in ('matched', 'arrived') then
    return jsonb_build_object('ok', false, 'code', 'INVALID_STATE', 'status', v_ride.status);
  end if;
  if v_ride.driver_id is null then
    return jsonb_build_object('ok', false, 'code', 'NO_DRIVER');
  end if;
  v_driver_id := v_ride.driver_id;
  select user_id into v_driver_uid from public.drivers where id = v_driver_id;
  v_reason := coalesce(nullif(trim(p_reason), ''), 'عطل فني');
  v_short := right(coalesce(v_ride.order_id::text, p_ride_id::text), 6);

  select * into v_cfg from public._settlement_settings();
  v_allowance := greatest(coalesce(v_cfg.driver_delay_monthly_allowance, 3), 0);
  -- 188: the compensation is a GIFT of 7% of the order value (owner spec
  -- 2026-11-21), platform-funded, replacing the flat-EGP credit; the old
  -- delay_apology_discount_egp setting is deprecated and ignored.
  v_apology := round(coalesce((select o.total_amount from public.orders o
                                where o.id = v_ride.order_id), 0)
                     * greatest(coalesce(v_cfg.delay_apology_percent, 7), 0) / 100.0, 2);

  -- Monthly allowance (calendar month, UTC).
  select count(*) + 1 into v_count
    from public.driver_delay_events
   where driver_id = v_driver_id
     and created_at >= date_trunc('month', now() at time zone 'Africa/Cairo') at time zone 'Africa/Cairo';
  v_within := v_count <= v_allowance;

  -- Release the driver and re-offer (mirrors the 146 driver-cancel redispatch).
  update public.ride_requests set status = 'cancelled', responded_at = now()
   where ride_id = p_ride_id and driver_id = v_driver_id and status = 'accepted';
  update public.ride_requests set status = 'expired', responded_at = now()
   where ride_id = p_ride_id and status = 'offered';
  update public.driver_locations set ride_id = null where ride_id = p_ride_id;
  update public.rides
     set status = 'searching', driver_id = null,
         cancellation_reason = 'driver_delay: ' || v_reason,
         cancelled_by = 'driver'
   where id = p_ride_id;
  insert into public.trip_events (ride_id, event_type, actor)
  values (p_ride_id, 'driver_delay_redispatch', 'driver');

  v_dispatch := public._dispatch_delivery_internal(p_ride_id, 25.0, 15);
  v_offered := coalesce((v_dispatch->>'success')::boolean, false);

  update public.orders
     set driver_id = null,
         dispatch_status = case when v_offered then 'OFFERED' else 'PENDING_DISPATCH' end,
         updated_at = now()
   where id = v_ride.order_id
     and status not in ('cancelled', 'delivered');

  -- One apology credit per order, even across repeated delay events.
  select count(*) into v_prior_apologies
    from public.driver_delay_events
   where order_id is not null
     and order_id = v_ride.order_id
     and apology_amount > 0;

  insert into public.driver_delay_events
    (ride_id, order_id, driver_id, reported_by, reason,
     within_allowance, monthly_count, apology_amount)
  values
    (p_ride_id, v_ride.order_id, v_driver_id, p_reported_by, v_reason,
     v_within, v_count,
     case when v_prior_apologies = 0 then v_apology else 0 end);

  -- Customer apology: wallet credit funded from the platform ops share of
  -- the order (see header) + Egyptian-Arabic apology naming the breakdown.
  if v_ride.order_id is not null and v_prior_apologies = 0 then
    select user_id into v_customer from public.orders where id = v_ride.order_id;
    if v_customer is not null then
      if v_apology > 0 then
        perform public._wallet_credit(
          p_user_id := v_customer,
          p_amount := v_apology,
          p_description := 'Delay apology credit for order ' || v_ride.order_id::text,
          p_reference_type := 'delay_apology',
          p_reference_id := v_ride.order_id
        );
      end if;
      insert into public.notifications (user_id, title, body, type, data, send_push)
      values (v_customer,
              'نعتذر عن التأخير 🙏',
              'طلبك رقم ' || v_short || ' اتأخر بسبب عطل فني عند الكابتن السابق. المطعم ملوش أي ذنب، والموضوع مش مقصود مننا. كابتن تاني في الطريق لطلبك دلوقتي' ||
                case when v_apology > 0
                     then '، وأضفنا ' || trim(to_char(v_apology, 'FM999990.##')) || ' جنيه (٧٪ من قيمة طلبك) هدية مننا في محفظتك تقديرًا لصبرك وصبر المطعم 🎁'
                     else '.' end,
              'order',
              jsonb_build_object('order_id', v_ride.order_id, 'event', 'driver_delay_apology',
                                 'apology_amount', v_apology),
              true);
    end if;
  end if;

  -- The late driver is excused: no deduction either way. Beyond the monthly
  -- allowance the event is flagged for ops (no automatic penalty - owner to
  -- decide the consequence).
  if v_driver_uid is not null then
    insert into public.notifications (user_id, title, body, type, data, send_push)
    values (v_driver_uid,
            'تم إعفاؤك من الطلب',
            'سجلنا تأخيرك عن استلام الطلب رقم ' || v_short || ' (' || v_reason || '). تم إعفاؤك من الطلب بدون أي خصم' ||
              case when v_within
                   then ' - سماحية رقم ' || v_count || ' من ' || v_allowance || ' هذا الشهر.'
                   else '، لكن ده تأخيرك رقم ' || v_count || ' هذا الشهر وفوق السماحية (' || v_allowance || ')، وهيتراجع من فريق العمليات.' end,
            'order',
            jsonb_build_object('ride_id', p_ride_id, 'event', 'driver_delay_excused',
                               'within_allowance', v_within, 'monthly_count', v_count),
            true);
  end if;

  if not v_within then
    insert into public.complaints
      (order_id, ride_id, complainant_id, respondent_id, reporter_id,
       complaint_type, category, subject, description, status, priority)
    values
      (v_ride.order_id, p_ride_id, v_driver_uid, v_driver_uid, v_driver_uid,
       'driver', 'delay_allowance_exceeded',
       'تجاوز سماحية التأخير الشهرية',
       'الكابتن تجاوز سماحية التأخير الشهرية (' || v_count || ' من ' || v_allowance ||
         ') على الطلب رقم ' || v_short || '. السبب المسجل: ' || v_reason || '.',
       'pending', 'high');
  end if;

  -- Merchant heads-up: the order is moving to another captain.
  if v_ride.merchant_id is not null then
    select owner_user_id into v_merchant_uid from public.merchants where id = v_ride.merchant_id;
    if v_merchant_uid is not null then
      insert into public.notifications (user_id, title, body, type, data, send_push)
      values (v_merchant_uid,
              'إعادة توزيع الطلب على كابتن آخر',
              'الكابتن السابق اتأخر عن استلام الطلب رقم ' || v_short || ' (' || v_reason || ') وتم إعفاؤه. الطلب معروض دلوقتي على كباتن آخرين.',
              'order',
              jsonb_build_object('order_id', v_ride.order_id, 'event', 'driver_delay_redispatch'),
              true);
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'status', 'redispatching',
    'offered', v_offered,
    'within_allowance', v_within,
    'monthly_count', v_count,
    'apology_amount', case when v_prior_apologies = 0 then v_apology else 0 end);
end;
$function$
;
CREATE OR REPLACE FUNCTION public._driver_visible_to_ride_party(p_driver_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (select 1 from public.rides r
                  where r.driver_id = p_driver_id
                    and r.rider_id = auth.uid()
                    and r.status in ('matched', 'arrived', 'inTrip'));
$function$
;
CREATE OR REPLACE FUNCTION public._duty_admin_for_region(p_region_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_admin uuid;
begin
  if p_region_id is not null then
    with recursive chain as (
      select id, parent_region_id, 0 as depth from public.regions where id = p_region_id
      union all
      select r.id, r.parent_region_id, c.depth + 1
        from public.regions r join chain c on r.id = c.parent_region_id
    )
    select a.admin_id into v_admin
      from public.admin_region_assignments a
      join chain c on a.region_id = c.id
      join public.users u on u.id = a.admin_id and u.account_status = 'active'
      left join public.admin_availability av on av.admin_id = a.admin_id
     where (a.scope = 'descendants' or (a.scope = 'self' and c.depth = 0))
       and coalesce(av.is_available, true)
     order by c.depth asc, a.created_at asc
     limit 1;
    if v_admin is not null then
      return v_admin;
    end if;
  end if;

  -- Any available admin with no region rows (global scope).
  select u.id into v_admin
    from public.users u
    left join public.admin_availability av on av.admin_id = u.id
   where u.role = 'admin' and u.account_status = 'active'
     and not exists (select 1 from public.admin_region_assignments a where a.admin_id = u.id)
     and coalesce(av.is_available, true)
   order by u.created_at asc
   limit 1;
  if v_admin is not null then
    return v_admin;
  end if;

  select id into v_admin from public.users where role = 'owner' order by created_at asc limit 1;
  return v_admin;
end;
$function$
;
CREATE OR REPLACE FUNCTION public._enforce_member_status(p_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_best text := 'active';
  v_deactivated boolean;
  r record;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM public.users WHERE id = p_member_id AND account_status = 'deactivated'
  ) INTO v_deactivated;
  IF v_deactivated THEN
    RETURN;
  END IF;
  FOR r IN
    SELECT s.sanction_type
    FROM public.sanctions s
    WHERE s.target_user_id = p_member_id
      AND s.is_active
      AND s.action_status = 'active'
      AND (s.end_date IS NULL OR s.end_date >= now())
      AND public._valid_member_sanction_type(s.sanction_type)
  LOOP
    IF public._sanction_strictness(public._sanction_status_for(r.sanction_type))
       > public._sanction_strictness(v_best) THEN
      v_best := public._sanction_status_for(r.sanction_type);
    END IF;
  END LOOP;
  UPDATE public.users SET account_status = v_best WHERE id = p_member_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._enqueue_push(p_notification_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cfg public.notification_push_config%ROWTYPE;
BEGIN
  PERFORM set_config('app.notify_dispatch', 'true', true);

  SELECT * INTO v_cfg FROM public.notification_push_config WHERE id = 1;
  IF NOT FOUND OR NOT COALESCE(v_cfg.is_enabled, false)
     OR v_cfg.function_url IS NULL OR btrim(v_cfg.function_url) = ''
     OR v_cfg.auth_token IS NULL OR btrim(v_cfg.auth_token) = '' THEN
    UPDATE public.notifications
       SET push_status = 'unconfigured'
     WHERE id = p_notification_id AND push_status = 'pending';
    RETURN;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := v_cfg.function_url,
      body := jsonb_build_object('notification_id', p_notification_id),
      params := '{}'::jsonb,
      headers := jsonb_build_object(
        'Authorization', 'Bearer ' || v_cfg.auth_token,
        'Content-Type', 'application/json'
      ),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.notifications
       SET push_status = 'failed',
           push_error = 'pg_net_error'
     WHERE id = p_notification_id AND push_status = 'pending';
  END;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._ensure_wallet(p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF p_user_id IS NULL THEN RETURN NULL; END IF;
  SELECT id INTO v_id FROM public.wallets WHERE user_id = p_user_id;
  IF v_id IS NULL THEN
    INSERT INTO public.wallets (user_id, balance, currency) VALUES (p_user_id, 0, 'EGP') ON CONFLICT (user_id) DO NOTHING RETURNING id INTO v_id;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM public.wallets WHERE user_id = p_user_id; END IF;
  END IF;
  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._finalize_order_cancel(p_order_id uuid, p_actor text, p_reason text, p_restock boolean DEFAULT true, p_refund boolean DEFAULT true, p_release_coupon boolean DEFAULT true, p_ride_cancelled_by text DEFAULT 'system'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;
  if v_order.status in ('delivered','cancelled') then
    return; -- already closed: nothing to finalize
  end if;

  if p_restock and v_order.stock_decremented then
    update public.products p
       set stock_quantity = p.stock_quantity + s.qty
      from (select oi.product_id, sum(oi.quantity) as qty
              from public.order_items oi
             where oi.order_id = p_order_id
             group by oi.product_id) s
     where p.id = s.product_id
       and p.stock_quantity is not null;
  end if;

  if p_release_coupon and v_order.coupon_id is not null then
    delete from public.coupon_redemptions
     where coupon_id = v_order.coupon_id
       and user_id = v_order.user_id;
    if found then
      update public.coupons
         set used_count = greatest(used_count - 1, 0)
       where id = v_order.coupon_id;
    end if;
  end if;

  if p_refund and v_order.payment_status = 'paid' then
    perform public._wallet_credit(
      p_user_id := v_order.user_id,
      p_amount := v_order.total_amount,
      p_description := 'Refund for cancelled order ' || p_order_id::text,
      p_reference_type := 'refund',
      p_reference_id := p_order_id
    );
  end if;

  update public.orders
     set status = 'cancelled',
         cancelled_reason = p_reason,
         cancelled_by = p_actor,
         cancelled_at = now(),
         payment_status = case when p_refund and payment_status = 'paid' then 'refunded' else payment_status end,
         stock_decremented = false,
         driver_id = null,
         updated_at = now()
   where id = p_order_id;

  -- 196: release the driver and close open offers on every ride of the order.
  update public.driver_locations
     set ride_id = null
   where ride_id in (select id from public.rides where order_id = p_order_id);
  update public.ride_requests
     set status = 'expired', responded_at = now()
   where ride_id in (select id from public.rides where order_id = p_order_id)
     and status = 'offered';
  update public.ride_requests
     set status = 'cancelled', responded_at = now()
   where ride_id in (select id from public.rides where order_id = p_order_id)
     and status = 'accepted';

  update public.rides
     set status = 'cancelled',
         cancelled_at = now(),
         cancelled_by = p_ride_cancelled_by,
         cancellation_reason = p_reason
   where order_id = p_order_id
     and status not in ('completed', 'cancelled');
end;
$function$
;
CREATE OR REPLACE FUNCTION public._is_active_admin_uid(p_uid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = p_uid
      AND (
        u.role = 'owner'
        OR (
          u.role = 'admin'
          AND EXISTS (
            SELECT 1 FROM public.admin_management m
            WHERE m.admin_id = u.id AND m.is_active
          )
        )
      )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public._is_home_service_category(p_cat text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT lower(btrim(COALESCE(p_cat, ''))) IN (
    'service', 'home_services', 'homeservices', 'plumbing', 'electrical',
    'cleaning', 'handyman', 'carpentry', 'ac_maintenance', 'acmaintenance',
    'painting', 'pest_control', 'pestcontrol', 'appliance_repair',
    'appliancerepair', 'doctor', 'clinic'
  );
$function$
;
