 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.users
    WHERE id = p_uid AND role = 'owner'
  );
$function$
;
CREATE OR REPLACE FUNCTION public._issue_delivery_handoff()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF NEW.driver_id IS NOT NULL AND (TG_OP='INSERT' OR OLD.driver_id IS DISTINCT FROM NEW.driver_id) THEN
  INSERT INTO public.delivery_handoff_challenges(ride_id,stage,code)
   VALUES(NEW.id,'pickup',public._new_delivery_handoff_code()),(NEW.id,'dropoff',public._new_delivery_handoff_code())
   ON CONFLICT(ride_id,stage) DO UPDATE SET code=EXCLUDED.code,attempts=0,locked_until=NULL,verified_at=NULL,expires_at=now()+interval '24 hours';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public._lift_expired_member_sanctions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_count integer := 0;
begin
  for r in
    select distinct target_user_id
      from public.sanctions
     where is_active
       and action_status = 'active'
       and end_date is not null
       and end_date < now()
  loop
    perform public._enforce_member_status(r.target_user_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$
;
CREATE OR REPLACE FUNCTION public._lookup_caller_ip()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_headers text;
  v_parts text[];
begin
  v_headers := current_setting('request.headers', true);
  if v_headers is null then return 'unknown'; end if;
  v_parts := string_to_array(coalesce(v_headers::json ->> 'x-forwarded-for', ''), ',');
  -- The LAST entry is appended by the trusted edge; earlier ones are client input.
  return coalesce(nullif(btrim(v_parts[array_length(v_parts, 1)]), ''), 'unknown');
exception when others then
  return 'unknown';
end;
$function$
;
CREATE OR REPLACE FUNCTION public._lookup_rate_allow(p_k text, p_max integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_n int;
begin
  insert into public.identifier_lookup_attempts (k, window_start, n)
  values (p_k, now(), 1)
  on conflict (k) do update set
    n = case
          when identifier_lookup_attempts.window_start < now() - interval '1 hour'
          then 1 else identifier_lookup_attempts.n + 1 end,
    window_start = case
          when identifier_lookup_attempts.window_start < now() - interval '1 hour'
          then now() else identifier_lookup_attempts.window_start end
  returning n into v_n;
  return v_n <= p_max;
end;
$function$
;
CREATE OR REPLACE FUNCTION public._member_exec_delete(p_actor uuid, p_member_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_status text;
BEGIN
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required';
  END IF;
  SELECT account_status INTO v_status FROM public.users WHERE id = p_member_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;
  IF public._is_active_admin_uid(p_member_id) THEN
    RAISE EXCEPTION 'Admins are managed through the admin lifecycle';
  END IF;
  IF v_status = 'deactivated' THEN
    RAISE EXCEPTION 'Member account is already deactivated';
  END IF;

  -- 1. Soft-delete and anonymize user record
  UPDATE public.users SET
    account_status = 'deactivated',
    anonymized_at = now(),
    email = 'deleted-' || p_member_id::text || '@anonymized.invalid',
    full_name = NULL,
    phone = NULL,
    username = NULL,
    avatar_url = NULL,
    id_card_url = NULL,
    profile_photo_url = NULL,
    trade_license_url = NULL,
    driving_license_url = NULL
  WHERE id = p_member_id;

  -- 2. Cascade driver deactivation (if driver profile exists)
  IF EXISTS (SELECT 1 FROM public.drivers WHERE user_id = p_member_id) THEN
    UPDATE public.drivers SET
      is_online = false,
      is_active = false,
      status = 'suspended',
      updated_at = now()
    WHERE user_id = p_member_id;
  END IF;

  -- 3. Cascade merchant deactivation (if merchant profile exists)
  IF EXISTS (SELECT 1 FROM public.merchants WHERE owner_user_id = p_member_id) THEN
    UPDATE public.merchants SET
      is_open = false,
      status = 'suspended',
      updated_at = now()
    WHERE owner_user_id = p_member_id;
  END IF;

  -- 4. Deactivate all notification tokens for this user
  IF to_regclass('public.notification_tokens') IS NOT NULL THEN
    UPDATE public.notification_tokens SET
      is_active = false,
      updated_at = now()
    WHERE user_id = p_member_id;
  END IF;

  -- 5. Record timeline event & audit log
  INSERT INTO public.member_events (user_id, event_type, title, payload)
  VALUES (p_member_id, 'account_deactivated', 'Account deleted',
          jsonb_build_object('reason', p_reason));

  PERFORM public.write_audit(
    'MEMBER_DELETED', 'users', p_member_id::text,
    jsonb_build_object('actor', p_actor::text, 'reason', p_reason));
END;
$function$
;
CREATE OR REPLACE FUNCTION public._member_exec_revoke_sanction(p_actor uuid, p_sanction_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_member_id uuid;
BEGIN
  SELECT target_user_id INTO v_member_id FROM public.sanctions WHERE id = p_sanction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sanction not found';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sanctions WHERE id = p_sanction_id AND action_status = 'active'
  ) THEN
    RAISE EXCEPTION 'Sanction is not active';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required';
  END IF;

  UPDATE public.sanctions
    SET action_status = 'revoked', is_active = false, updated_at = now()
    WHERE id = p_sanction_id;

  PERFORM public._enforce_member_status(v_member_id);

  INSERT INTO public.member_events (user_id, event_type, title, payload)
  VALUES (v_member_id, 'moderation_action', 'Sanction lifted',
          jsonb_build_object('sanction_id', p_sanction_id::text, 'reason', p_reason));

  PERFORM public.write_audit(
    'SANCTION_REVOKED', 'sanctions', p_sanction_id::text,
    jsonb_build_object('actor', p_actor::text, 'member_id', v_member_id::text,
                       'reason', p_reason));

  INSERT INTO public.notifications (user_id, title, body, type, data, deep_link, idempotency_key)
  VALUES (
    v_member_id, 'Moderation', 'Your account status has been restored.', 'moderation',
    jsonb_build_object('sanction_id', p_sanction_id::text),
    '/profile',
    'sanction-revoke-' || p_sanction_id::text || '-' || gen_random_uuid()::text
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._member_exec_sanction(p_actor uuid, p_member_id uuid, p_sanction_type text, p_reason text, p_duration_days integer DEFAULT 0, p_amount numeric DEFAULT 0, p_evidence_url text DEFAULT NULL::text, p_via_approval boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_role text;
  v_status text;
  v_sanction_id uuid;
  v_event_type text;
  v_title text;
  v_body text;
BEGIN
  IF NOT public._valid_member_sanction_type(p_sanction_type) THEN
    RAISE EXCEPTION 'Invalid sanction type';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required';
  END IF;
  SELECT role, account_status INTO v_role, v_status
  FROM public.users WHERE id = p_member_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;
  IF public._is_active_admin_uid(p_member_id) THEN
    RAISE EXCEPTION 'Admins are managed through the admin lifecycle';
  END IF;
  IF v_status = 'deactivated' THEN
    RAISE EXCEPTION 'Member account is deactivated';
  END IF;
  IF p_sanction_type = 'permanent_ban'
     AND EXISTS (
       SELECT 1 FROM public.sanctions
       WHERE target_user_id = p_member_id
         AND sanction_type = 'permanent_ban'
         AND is_active
         AND action_status = 'active'
     ) THEN
    RAISE EXCEPTION 'Member already has an active permanent ban';
  END IF;

  INSERT INTO public.sanctions
    (target_user_id, target_role, sanction_type, reason, amount, duration_days,
     end_date, evidence_url, approving_admin_id, issued_by)
  VALUES (
    p_member_id, v_role, p_sanction_type, p_reason, p_amount, p_duration_days,
    CASE WHEN p_duration_days > 0
         THEN now() + (p_duration_days || ' days')::interval
         ELSE NULL END,
    p_evidence_url,
    CASE WHEN p_via_approval THEN p_actor ELSE NULL END,
    p_actor
  )
  RETURNING id INTO v_sanction_id;

  PERFORM public._enforce_member_status(p_member_id);

  v_event_type := CASE p_sanction_type
    WHEN 'suspension' THEN 'suspension'
    WHEN 'temporary_ban' THEN 'ban'
    WHEN 'permanent_ban' THEN 'ban'
    ELSE 'moderation_action'
  END;
  v_title := CASE p_sanction_type
    WHEN 'permanent_ban' THEN 'Account permanently banned'
    WHEN 'temporary_ban' THEN 'Account temporarily banned'
    WHEN 'suspension' THEN 'Account suspended'
    WHEN 'fine' THEN 'Account fined'
    ELSE 'Account restricted'
  END;
  v_body := CASE p_sanction_type
    WHEN 'permanent_ban' THEN 'Your account has been permanently banned.'
    WHEN 'temporary_ban' THEN 'Your account has been temporarily banned.'
    WHEN 'suspension' THEN 'Your account has been suspended.'
    WHEN 'fine' THEN 'A fine has been applied to your account.'
    ELSE 'Your account has been restricted.'
  END;

  INSERT INTO public.member_events (user_id, event_type, title, payload)
  VALUES (p_member_id, v_event_type, v_title,
          jsonb_build_object('sanction_id', v_sanction_id::text,
                             'sanction_type', p_sanction_type,
                             'reason', p_reason));

  PERFORM public.write_audit(
    'SANCTION_ISSUED', 'sanctions', v_sanction_id::text,
    jsonb_build_object('actor', p_actor::text, 'member_id', p_member_id::text,
                       'sanction_type', p_sanction_type, 'reason', p_reason,
                       'via_approval', p_via_approval));

  -- Member-facing notification carries NO admin identity (title is neutral).
  INSERT INTO public.notifications (user_id, title, body, type, data, deep_link, idempotency_key)
  VALUES (
    p_member_id, 'Moderation', v_body, 'moderation',
    jsonb_build_object('sanction_id', v_sanction_id::text,
                       'sanction_type', p_sanction_type),
    '/profile',
    'sanction-' || v_sanction_id::text
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  RETURN v_sanction_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._member_region_id(p_member_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT region_id FROM public.user_region_preferences
  WHERE user_id = p_member_id
  ORDER BY updated_at DESC
  LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public._new_delivery_handoff_code()
 RETURNS text
 LANGUAGE sql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
 SELECT lpad(((get_byte(b,0)::bigint*16777216+get_byte(b,1)::bigint*65536+get_byte(b,2)::bigint*256+get_byte(b,3)::bigint)%1000000)::text,6,'0') FROM (SELECT extensions.gen_random_bytes(4) b) q;
$function$
;
CREATE OR REPLACE FUNCTION public._normalize_egypt_phone(p_phone text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_digits text;
BEGIN
  IF p_phone IS NULL THEN
    RETURN '';
  END IF;
  v_digits := regexp_replace(btrim(p_phone), '[^0-9]', '', 'g');
  IF v_digits = '' THEN
    RETURN '';
  END IF;
  -- 00201xxxxxxxxx -> +201xxxxxxxxx
  IF v_digits LIKE '0020%' AND length(v_digits) = 14 THEN
    RETURN '+' || substring(v_digits FROM 3);
  END IF;
  -- 201xxxxxxxxx -> +201xxxxxxxxx
  IF v_digits LIKE '201%' AND length(v_digits) = 12 THEN
    RETURN '+' || v_digits;
  END IF;
  -- 01xxxxxxxxx (11 digits Egyptian mobile) -> +201xxxxxxxxx
  IF v_digits LIKE '01%' AND length(v_digits) = 11 THEN
    RETURN '+2' || v_digits;
  END IF;
  -- 1xxxxxxxxx (10 digits without leading 0) -> +201xxxxxxxxx
  IF v_digits LIKE '1%' AND length(v_digits) = 10 THEN
    RETURN '+20' || v_digits;
  END IF;
  RETURN '+' || v_digits;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._notification_audience_for(p_type text, p_deep_link text, p_data jsonb, p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_marker text;
  v_role text;
begin
  -- 1. explicit marker in the payload
  v_marker := lower(coalesce(
    p_data->>'target_app', p_data->>'target_role', p_data->>'audience', ''));
  if v_marker in ('customer','client','user') then return 'customer'; end if;
  if v_marker in ('driver','delivery','courier') then return 'driver'; end if;
  if v_marker in ('provider','merchant','vendor','partner') then return 'provider'; end if;
  if v_marker in ('admin','owner','super_admin','operational') then return 'admin'; end if;
  if v_marker in ('all','broadcast') then return 'all'; end if;

  -- 2. app-owned deep-link prefixes
  if p_deep_link is not null then
    if p_deep_link like '/admin%' then return 'admin'; end if;
    if p_deep_link like '/driver%' then return 'driver'; end if;
    if p_deep_link like '/provider%' or p_deep_link like '/merchant-dashboard%' then
      return 'provider';
    end if;
  end if;

  -- 3. unambiguous types. NOTE: 'appeal' is deliberately NOT here - the same
  -- type is used for admin-bound submissions AND member-bound receipts and
  -- decisions, so it must fall through to recipient-role derivation.
  if p_type in ('admin_management','approval',
                'emergency_alert','complaint_escalated','complaint_assigned',
                'chat_assigned','chat_escalated','topup_request_pending') then
    return 'admin';
  end if;
  if p_type in ('provider_profile','providerProfile') then
    return 'provider';
  end if;
  if p_type in ('promotion','reward') then
    return 'customer';
  end if;

  -- 4. recipient role
  select role into v_role from public.users where id = p_user_id;
  if v_role = 'customer' then return 'customer'; end if;
  if v_role = 'driver' then return 'driver'; end if;
  if v_role in ('merchant','provider') then return 'provider'; end if;
  if v_role in ('admin','owner','super_admin') then return 'admin'; end if;

  return 'all';
end;
$function$
;
CREATE OR REPLACE FUNCTION public._notifications_set_audience()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.audience is null or new.audience = 'all' then
    new.audience := public._notification_audience_for(
      new.type, new.deep_link, new.data, new.user_id);
  end if;
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public._provision_business_target(p_user_id uuid, p_category_type text, p_display_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user record;
  v_cat text := lower(btrim(COALESCE(p_category_type, 'restaurant')));
  v_name text;
  v_merchant_id uuid;
  v_sp_id uuid;
BEGIN
  SELECT id, full_name, email, phone, avatar_url, profile_photo_url
    INTO v_user
    FROM public.users
   WHERE id = p_user_id;

  v_name := COALESCE(
    NULLIF(btrim(p_display_name), ''),
    NULLIF(btrim(v_user.full_name), ''),
    'Delwaqty ' || initcap(v_cat)
  );

  IF public._is_home_service_category(v_cat) THEN
    SELECT id INTO v_sp_id
      FROM public.service_providers
     WHERE user_id = p_user_id
       AND lower(category_type) = CASE WHEN v_cat IN ('service', 'home_services', 'homeservices') THEN 'plumbing' ELSE v_cat END
     LIMIT 1;

    IF v_sp_id IS NULL THEN
      SELECT id INTO v_sp_id
        FROM public.service_providers
       WHERE user_id = p_user_id
       ORDER BY created_at ASC
       LIMIT 1;
    END IF;

    IF v_sp_id IS NULL THEN
      INSERT INTO public.service_providers (
        user_id, name, category_type, description, profile_image_url,
        rating, rating_count, is_verified, is_available, hourly_rate
      )
      VALUES (
        p_user_id,
        v_name,
        CASE WHEN v_cat IN ('service', 'home_services', 'homeservices') THEN 'plumbing' ELSE v_cat END,
        '',
        COALESCE(v_user.profile_photo_url, v_user.avatar_url),
        5.0,
        0,
        true,
        true,
        150
      )
      RETURNING id INTO v_sp_id;
    END IF;
  ELSE
    SELECT id INTO v_merchant_id
      FROM public.merchants
     WHERE owner_user_id = p_user_id AND lower(type) = v_cat
     ORDER BY created_at ASC
     LIMIT 1;

    IF v_merchant_id IS NULL THEN
      INSERT INTO public.merchants (
        owner_user_id, name, email, phone, type, status, is_open,
        delivery_fee, min_order, delivery_time_min, rating
      )
      VALUES (
        p_user_id,
        v_name,
        COALESCE(v_user.email, ''),
        v_user.phone,
        v_cat,
        'active',
        true,
        15,
        0,
        30,
        5.0
      )
      RETURNING id INTO v_merchant_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'merchant_id', v_merchant_id,
    'service_provider_id', v_sp_id
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public._record_delivery_earnings(p_ride_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r public.rides%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_driver_uid uuid;
  v_merchant_uid uuid;
  v_merchant_type text;
  v_merchant_model text;
  v_rate numeric;
  v_gross numeric;
  v_commission numeric;
  v_driver_commission numeric;
  v_currency text;
  v_due_hours integer;
  v_goods numeric;
  v_is_cash boolean;
BEGIN
  SELECT * INTO r FROM public.rides WHERE id = p_ride_id;
  IF NOT FOUND OR r.driver_id IS NULL THEN
    RETURN;
  END IF;
  -- Idempotent: one earning/commission pair per ride.
  IF EXISTS (SELECT 1 FROM public.driver_earnings WHERE ride_id = p_ride_id) THEN
    RETURN;
  END IF;

  -- Idempotent across paths: when the order-scoped accrual (172 trigger on
  -- orders.status -> delivered) already ran for the linked order, skip.
  -- complete_delivery updates orders.status BEFORE calling this function,
  -- so without this check both paths accrue (regression found in E2E).
  IF r.order_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.driver_earnings WHERE order_id = r.order_id) THEN
    RETURN;
  END IF;

  SELECT user_id INTO v_driver_uid FROM public.drivers WHERE id = r.driver_id;
  v_currency := COALESCE(NULLIF(r.currency, ''), 'EGP');
  v_is_cash := lower(COALESCE(r.payment_method, '')) = 'cash';

  -- Driver: earns the delivery fare minus the driver-rate commission.
  v_gross := COALESCE(r.fare, 0);
  v_rate := COALESCE(public.get_commission_rate('driver', NULL, v_driver_uid), 0);
  v_commission := public.calculate_commission(v_gross, v_rate);
  -- 188: driver-delay waiver - the platform takes NO commission from the
  -- replacement driver on an order that was redispatched for a delay.
  if r.order_id is not null and exists (
    select 1 from public.driver_delay_events de where de.order_id = r.order_id
  ) then
    v_commission := 0;
  end if;
  v_driver_commission := v_commission;

  INSERT INTO public.driver_earnings (driver_id, ride_id, type, amount, currency, description)
  VALUES (r.driver_id, p_ride_id, 'trip', v_gross - v_commission, v_currency,
          'Delivery fare ' || v_gross::text || ' less ' || v_rate::text || '% platform commission');

  INSERT INTO public.platform_commissions
    (member_id, reference_type, reference_id, gross_amount, commission_rate,
     commission_amount, net_amount, currency, status)
  VALUES (v_driver_uid, 'ride', p_ride_id, v_gross, v_rate, v_commission,
          v_gross - v_commission, v_currency, 'computed')
  ON CONFLICT (reference_type, reference_id) DO NOTHING;

  -- Merchant: commission on the goods subtotal for merchant orders.
  IF r.order_id IS NOT NULL THEN
    SELECT * INTO v_order FROM public.orders WHERE id = r.order_id;
    IF FOUND AND v_order.merchant_id IS NOT NULL THEN
      SELECT owner_user_id, type, settlement_model
        INTO v_merchant_uid, v_merchant_type, v_merchant_model
        FROM public.merchants WHERE id = v_order.merchant_id;
      IF v_merchant_uid IS NOT NULL THEN
        v_gross := COALESCE(v_order.subtotal, 0);
        v_rate := COALESCE(public.get_commission_rate('merchant', v_merchant_type, v_merchant_uid), 0);
        v_commission := public.calculate_commission(v_gross, v_rate);
        INSERT INTO public.platform_commissions
          (member_id, reference_type, reference_id, gross_amount, commission_rate,
           commission_amount, net_amount, currency, status)
        VALUES (v_merchant_uid, 'order', v_order.id, v_gross, v_rate, v_commission,
                v_gross - v_commission, v_currency, 'computed')
        ON CONFLICT (reference_type, reference_id) DO NOTHING;

        IF v_is_cash THEN
          SELECT settlement_remittance_due_hours INTO v_due_hours
            FROM public._settlement_settings();
          v_due_hours := COALESCE(v_due_hours, 24);

          -- Goods money: order value minus the delivery fee (driver keeps the
          -- fare side). Owed to the platform (model A) or the merchant (B).
          v_goods := GREATEST(
            COALESCE(v_order.total_amount, 0) - COALESCE(v_order.delivery_fee, 0), 0);
          IF v_goods > 0 THEN
            INSERT INTO public.driver_obligations
              (driver_id, ride_id, order_id, merchant_id, kind, amount, currency,
               owed_to, due_at)
            VALUES
              (r.driver_id, p_ride_id, v_order.id, v_order.merchant_id, 'goods',
               v_goods, v_currency,
               CASE WHEN v_merchant_model = 'direct' THEN 'merchant' ELSE 'platform' END,
               now() + make_interval(hours => v_due_hours))
            ON CONFLICT (ride_id, kind) WHERE ride_id IS NOT NULL DO NOTHING;

            INSERT INTO public.notifications
              (user_id, title, body, type, data, send_push)
            SELECT v_driver_uid,
                   'تسوية كاش مستحقة',
                   'قبضت ' || v_goods::text || ' ' || v_currency ||
                     ' من الطلب. التوريد مستحق خلال ' || v_due_hours::text || ' ساعة.',
                   'settlement',
                   jsonb_build_object('ride_id', p_ride_id, 'amount', v_goods),
                   true
            WHERE NOT EXISTS (
              SELECT 1 FROM public.notifications n
               WHERE n.user_id = v_driver_uid AND n.type = 'settlement'
                 AND n.data->>'ride_id' = p_ride_id::text
            );
          END IF;

          -- Model A: platform owes the merchant goods minus its commission.
          IF v_merchant_model IS DISTINCT FROM 'direct' THEN
            INSERT INTO public.merchant_ledger
              (merchant_id, order_id, entry_type, amount, currency, description)
            VALUES
              (v_order.merchant_id, v_order.id, 'credit',
               v_gross - v_commission, v_currency,
               'Order goods ' || v_gross::text || ' less ' || v_rate::text || '% platform commission')
            ON CONFLICT (order_id, entry_type)
              WHERE order_id IS NOT NULL AND entry_type = 'credit'
              DO NOTHING;
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;

  -- Cash rides of any kind: the platform's driver-side commission is debt
  -- until remitted (pure cash rides have no goods obligation).
  IF v_is_cash AND v_driver_commission > 0 THEN
    SELECT settlement_remittance_due_hours INTO v_due_hours
      FROM public._settlement_settings();
    INSERT INTO public.driver_obligations
      (driver_id, ride_id, order_id, merchant_id, kind, amount, currency,
       owed_to, due_at)
    VALUES
      (r.driver_id, p_ride_id, r.order_id, r.merchant_id, 'commission',
       v_driver_commission, v_currency, 'platform',
       now() + make_interval(hours => COALESCE(v_due_hours, 24)))
    ON CONFLICT (ride_id, kind) WHERE ride_id IS NOT NULL DO NOTHING;
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._record_order_settlement(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  o public.orders%ROWTYPE;
  v_driver_uid uuid;
  v_merchant_uid uuid;
  v_merchant_type text;
  v_merchant_model text;
  v_rate numeric;
  v_gross numeric;
  v_commission numeric;
  v_driver_commission numeric;
  v_currency text := 'EGP';
  v_due_hours integer;
  v_goods numeric;
  v_is_cash boolean;
BEGIN
  SELECT * INTO o FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND OR o.status <> 'delivered' OR o.driver_id IS NULL THEN
    RETURN;
  END IF;
  -- Idempotent: one accrual per order, regardless of path.
  IF EXISTS (SELECT 1 FROM public.driver_earnings WHERE order_id = p_order_id) THEN
    RETURN;
  END IF;
  -- A linked ride already accrued for this order (147/161 ride path).
  IF EXISTS (
    SELECT 1 FROM public.driver_earnings de
    JOIN public.rides r ON r.id = de.ride_id
    WHERE r.order_id = p_order_id
  ) THEN
    RETURN;
  END IF;

  SELECT user_id INTO v_driver_uid FROM public.drivers WHERE id = o.driver_id;
  v_is_cash := lower(COALESCE(o.payment_method, '')) = 'cash';

  -- Driver: earns the delivery fee minus the driver-rate commission.
  v_gross := COALESCE(o.delivery_fee, 0);
  v_rate := COALESCE(public.get_commission_rate('driver', NULL, v_driver_uid), 0);
  v_commission := public.calculate_commission(v_gross, v_rate);
  -- 188: driver-delay waiver - the platform takes NO commission from the
  -- replacement driver on an order that was redispatched for a delay.
  if p_order_id is not null and exists (
    select 1 from public.driver_delay_events de where de.order_id = p_order_id
  ) then
    v_commission := 0;
  end if;
  v_driver_commission := v_commission;

  INSERT INTO public.driver_earnings (driver_id, order_id, type, amount, currency, description)
  VALUES (o.driver_id, p_order_id, 'trip', v_gross - v_commission, v_currency,
          'Order delivery fee ' || v_gross::text || ' less ' || v_rate::text || '% platform commission');

  INSERT INTO public.platform_commissions
    (member_id, reference_type, reference_id, gross_amount, commission_rate,
     commission_amount, net_amount, currency, status)
  VALUES (v_driver_uid, 'order_driver', p_order_id, v_gross, v_rate, v_commission,
          v_gross - v_commission, v_currency, 'computed')
  ON CONFLICT (reference_type, reference_id) DO NOTHING;

  -- Merchant: commission on the goods subtotal.
  IF o.merchant_id IS NOT NULL THEN
    SELECT owner_user_id, type, settlement_model
      INTO v_merchant_uid, v_merchant_type, v_merchant_model
      FROM public.merchants WHERE id = o.merchant_id;
    IF v_merchant_uid IS NOT NULL THEN
      v_gross := COALESCE(o.subtotal, 0);
      v_rate := COALESCE(public.get_commission_rate('merchant', v_merchant_type, v_merchant_uid), 0);
      v_commission := public.calculate_commission(v_gross, v_rate);
      INSERT INTO public.platform_commissions
        (member_id, reference_type, reference_id, gross_amount, commission_rate,
         commission_amount, net_amount, currency, status)
      VALUES (v_merchant_uid, 'order', p_order_id, v_gross, v_rate, v_commission,
              v_gross - v_commission, v_currency, 'computed')
      ON CONFLICT (reference_type, reference_id) DO NOTHING;

      IF v_is_cash THEN
        SELECT settlement_remittance_due_hours INTO v_due_hours
          FROM public._settlement_settings();
        v_due_hours := COALESCE(v_due_hours, 24);

        -- Goods money owed by the driver (order value minus the delivery fee).
        v_goods := GREATEST(
          COALESCE(o.total_amount, 0) - COALESCE(o.delivery_fee, 0), 0);
        IF v_goods > 0 THEN
          INSERT INTO public.driver_obligations
            (driver_id, ride_id, order_id, merchant_id, kind, amount, currency,
             owed_to, due_at)
          VALUES
            (o.driver_id, NULL, p_order_id, o.merchant_id, 'goods',
             v_goods, v_currency,
             CASE WHEN v_merchant_model = 'direct' THEN 'merchant' ELSE 'platform' END,
             now() + make_interval(hours => v_due_hours))
          ON CONFLICT (order_id, kind) WHERE ride_id IS NULL AND order_id IS NOT NULL DO NOTHING;

          INSERT INTO public.notifications
            (user_id, title, body, type, data, send_push)
          SELECT v_driver_uid,
                 'تسوية كاش مستحقة',
                 'قبضت ' || v_goods::text || ' ' || v_currency ||
                   ' من الطلب. التوريد مستحق خلال ' || v_due_hours::text || ' ساعة.',
                 'settlement',
                 jsonb_build_object('order_id', p_order_id, 'amount', v_goods),
                 true
          WHERE NOT EXISTS (
            SELECT 1 FROM public.notifications n
             WHERE n.user_id = v_driver_uid AND n.type = 'settlement'
               AND n.data->>'order_id' = p_order_id::text
          );
        END IF;

        -- Platform model: platform owes the merchant goods minus commission.
        IF v_merchant_model IS DISTINCT FROM 'direct' THEN
          INSERT INTO public.merchant_ledger
            (merchant_id, order_id, entry_type, amount, currency, description)
          VALUES
            (o.merchant_id, p_order_id, 'credit',
             v_gross - v_commission, v_currency,
             'Order goods ' || v_gross::text || ' less ' || v_rate::text || '% platform commission')
          ON CONFLICT (order_id, entry_type)
            WHERE order_id IS NOT NULL AND entry_type = 'credit'
            DO NOTHING;
        END IF;
      END IF;
    END IF;
  END IF;

  -- Driver-side commission on cash orders is debt until remitted.
  IF v_is_cash AND v_driver_commission > 0 THEN
    SELECT settlement_remittance_due_hours INTO v_due_hours
      FROM public._settlement_settings();
    INSERT INTO public.driver_obligations
      (driver_id, ride_id, order_id, merchant_id, kind, amount, currency,
       owed_to, due_at)
    VALUES
      (o.driver_id, NULL, p_order_id, o.merchant_id, 'commission',
       v_driver_commission, v_currency, 'platform',
       now() + make_interval(hours => COALESCE(v_due_hours, 24)))
    ON CONFLICT (order_id, kind) WHERE ride_id IS NULL AND order_id IS NOT NULL DO NOTHING;
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._redact_delivery_handoff()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 NEW.pickup_otp:=NULL;
 IF NEW.driver_id IS NOT NULL THEN NEW.otp_required:=true; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public._region_in_scope(p_uid uuid, p_region_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_uid AND u.role = 'owner') THEN
    RETURN true;
  END IF;
  IF p_uid IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_uid AND u.role = 'admin')
     AND NOT EXISTS (
       SELECT 1 FROM public.admin_region_assignments
       WHERE admin_id = p_uid
     ) THEN
    RETURN true;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.admin_region_assignments a
    WHERE a.admin_id = p_uid
      AND (
        (a.scope = 'self' AND a.region_id = p_region_id)
        OR (a.scope = 'descendants' AND p_region_id IN (
          WITH RECURSIVE covered AS (
            SELECT id FROM public.regions WHERE id = a.region_id
            UNION ALL
            SELECT r.id FROM public.regions r
            JOIN covered c ON r.parent_region_id = c.id
          )
          SELECT id FROM covered
        ))
      )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public._region_label_path(p_region_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH RECURSIVE chain AS (
    SELECT r.id, r.parent_region_id,
           COALESCE(NULLIF(r.name_en, ''), NULLIF(r.name_ar, '')) AS nm,
           1 AS depth
      FROM public.regions r
     WHERE r.id = p_region_id
    UNION ALL
    SELECT r.id, r.parent_region_id,
           COALESCE(NULLIF(r.name_en, ''), NULLIF(r.name_ar, '')),
           c.depth + 1
      FROM public.regions r
      JOIN chain c ON r.id = c.parent_region_id
  )
  SELECT string_agg(nm, ' / ' ORDER BY depth DESC)
    FROM chain
   WHERE nm IS NOT NULL;
$function$
;
CREATE OR REPLACE FUNCTION public._reward_benefit_valid(p_benefit jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_kind text;
  v_free_delivery_enabled boolean;
BEGIN
  IF p_benefit IS NULL OR p_benefit = '{}'::jsonb THEN
    RETURN true;
  END IF;
  v_kind := p_benefit ->> 'kind';
  IF v_kind IS NULL OR v_kind NOT IN
     ('none','coupon','promo_code','offer','code_copy','free_delivery') THEN
    RETURN false;
  END IF;
  IF v_kind = 'free_delivery' THEN
    SELECT (to_jsonb(ps) #>> '{promotions,free_delivery_enabled}') = 'true'
      INTO v_free_delivery_enabled
      FROM public.platform_settings ps
      WHERE ps.id = 'default';
    RETURN COALESCE(v_free_delivery_enabled, false);
  END IF;
  RETURN true;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._reward_config(p_reward_type text, p_region_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(
    CASE WHEN p_region_id IS NOT NULL THEN
      (SELECT ps.rewards #> ARRAY['regions', p_region_id::text, p_reward_type]
       FROM public.platform_settings ps WHERE ps.id = 'default')
    END,
    (SELECT ps.rewards -> p_reward_type
     FROM public.platform_settings ps WHERE ps.id = 'default'),
    '{}'::jsonb);
$function$
;
CREATE OR REPLACE FUNCTION public._reward_config_exec(p_actor uuid, p_region_id uuid, p_reward_type text, p_config jsonb, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_enabled boolean;
  v_benefit jsonb;
  v_path text[];
BEGIN
  IF p_reward_type NOT IN ('birthday','anniversary') THEN
    RAISE EXCEPTION 'Invalid reward type';
  END IF;
  v_benefit := COALESCE(p_config -> 'benefit', '{"kind":"none"}'::jsonb);
  IF NOT public._reward_benefit_valid(v_benefit) THEN
    RAISE EXCEPTION 'Invalid reward benefit';
  END IF;
  v_enabled := COALESCE((p_config ->> 'enabled')::boolean, false);

  IF p_region_id IS NULL THEN
    IF NOT public._is_owner_uid(p_actor) THEN
      RAISE EXCEPTION 'Only owner can change global reward config';
    END IF;
    v_path := ARRAY[p_reward_type];
  ELSE
    IF NOT public._region_in_scope(p_actor, p_region_id) THEN
      RAISE EXCEPTION 'Not authorized for this region';
    END IF;
    v_path := ARRAY['regions', p_region_id::text, p_reward_type];
  END IF;

  UPDATE public.platform_settings
  SET rewards = jsonb_set(
        COALESCE(rewards, '{}'::jsonb),
        v_path,
        COALESCE(p_config, '{}'::jsonb),
        true),
      updated_at = now()
  WHERE id = 'default';

  PERFORM public.write_audit(
    'REWARD_CONFIG_CHANGED', 'platform_settings', 'default',
    jsonb_build_object('reward_type', p_reward_type,
                       'region_id', p_region_id,
                       'enabled', v_enabled,
                       'reason', p_reason));
END;
$function$
;
CREATE OR REPLACE FUNCTION public._sanction_requires_approval(p_type text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_type IN ('temporary_ban','permanent_ban');
$function$
;
CREATE OR REPLACE FUNCTION public._sanction_status_for(p_type text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE p_type
    WHEN 'warning' THEN 'restricted'
    WHEN 'fine' THEN 'restricted'
    WHEN 'suspension' THEN 'suspended'
    WHEN 'temporary_ban' THEN 'banned'
    WHEN 'permanent_ban' THEN 'banned'
    ELSE NULL
  END;
$function$
;
CREATE OR REPLACE FUNCTION public._sanction_strictness(p_status text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE p_status
    WHEN 'active' THEN 0
    WHEN 'restricted' THEN 1
    WHEN 'suspended' THEN 2
    WHEN 'banned' THEN 3
    WHEN 'deactivated' THEN 4
    ELSE -1
  END;
$function$
;
CREATE OR REPLACE FUNCTION public._settlement_escalation_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cfg public.platform_settings;
  ob RECORD;
  v_count integer := 0;
  v_driver RECORD;
  v_amount numeric;
  v_days integer;
BEGIN
  PERFORM set_config('app.escalation_rpc', 'true', true);
  SELECT * INTO v_cfg FROM public._settlement_settings();
  v_amount := COALESCE(v_cfg.settlement_suspension_amount, 1500);
  v_days := COALESCE(v_cfg.settlement_suspension_days, 5);

  -- 1) Overdue individual obligations -> ops complaint (unchanged behavior)
  FOR ob IN
    SELECT o.*, d.user_id AS driver_uid
      FROM public.driver_obligations o
      JOIN public.drivers d ON d.id = o.driver_id
     WHERE o.status = 'open'
       AND o.escalated_at IS NULL
       AND o.due_at + make_interval(hours => COALESCE(v_cfg.settlement_escalation_hours, 24)) < now()
  LOOP
    INSERT INTO public.complaints
      (order_id, ride_id, complainant_id, respondent_id, reporter_id,
       complaint_type, category, subject, description, status, priority)
    VALUES
      (ob.order_id, ob.ride_id, ob.driver_uid, ob.driver_uid, ob.driver_uid,
       'driver', 'settlement_overdue',
       'مديونية كاش متأخرة',
       'الكابتن متأخر عن توريد ' || ob.amount::text || ' ' || ob.currency ||
         ' (نوع: ' || ob.kind || '، مستحق لـ ' || ob.owed_to || ') منذ ' ||
         ob.due_at::date::text || '.',
       'pending', 'high');
    UPDATE public.driver_obligations SET escalated_at = now() WHERE id = ob.id;
    v_count := v_count + 1;
  END LOOP;

  -- 2) Outstanding > suspension amount -> auto-suspend 5 days
  FOR v_driver IN
    SELECT o.driver_id, d.user_id AS driver_uid,
           sum(o.amount) FILTER (WHERE o.status IN ('open','disputed')) AS outstanding
      FROM public.driver_obligations o
      JOIN public.drivers d ON d.id = o.driver_id
     WHERE o.status IN ('open','disputed')
     GROUP BY o.driver_id, d.user_id
    HAVING sum(o.amount) FILTER (WHERE o.status IN ('open','disputed')) > v_amount
  LOOP
    -- Skip if already suspended for settlement and still within the window
    IF EXISTS (
      SELECT 1 FROM public.drivers d
      WHERE d.id = v_driver.driver_id
        AND d.settlement_suspended_until IS NOT NULL
        AND d.settlement_suspended_until > now()
    ) THEN
      CONTINUE;
    END IF;

    UPDATE public.drivers
       SET settlement_suspended_until = now() + make_interval(days => v_days),
           is_online = false
     WHERE id = v_driver.driver_id;
    UPDATE public.users
       SET account_status = 'suspended'
     WHERE id = v_driver.driver_uid
       AND account_status = 'active';

    INSERT INTO public.notifications (user_id, title, body, type, data, priority)
    VALUES (
      v_driver.driver_uid,
      'إيقاف مؤقت لمدة ' || v_days || ' أيام',
      'تم إيقاف حسابك ' || v_days || ' أيام لأن المديونية غير الموردة تجاوزت ' ||
        v_amount::text || ' جنيه. الإجمالي القائم: ' ||
        COALESCE(v_driver.outstanding,0)::text || ' جنيه. قم بالتوريد لاستعادة حسابك.',
      'settlement_suspension',
      jsonb_build_object('driver_id', v_driver.driver_id,
                         'outstanding', v_driver.outstanding,
                         'suspended_days', v_days),
      'high');
    v_count := v_count + 1;

    -- Ops audit trail (kept from previous behavior)
    IF NOT EXISTS (
      SELECT 1 FROM public.complaints c
       WHERE c.respondent_id = v_driver.driver_uid
         AND c.category = 'settlement_suspension_review'
         AND c.status IN ('pending','investigating','escalated','open')
    ) THEN
      INSERT INTO public.complaints
        (complainant_id, respondent_id, reporter_id, complaint_type, category,
         subject, description, status, priority)
      VALUES
        (v_driver.driver_uid, v_driver.driver_uid, v_driver.driver_uid,
         'driver', 'settlement_suspension_review',
         'إيقاف كابتن لتجاوز حد التسوية',
         'تم إيقاف الكابتن ' || v_days || ' أيام: مديونية غير موردة ' ||
           COALESCE(v_driver.outstanding,0)::text || ' جنيه (الحد: ' || v_amount::text || ').',
         'pending', 'urgent');
      v_count := v_count + 1;
    END IF;
  END LOOP;

  -- 3) Reactivate drivers whose suspension expired and balance is back in limit.
  --    If still over the limit at expiry, extend the suspension another window.
  FOR v_driver IN
    SELECT d.id AS driver_id, d.user_id AS driver_uid, d.settlement_suspended_until,
           COALESCE((SELECT sum(o.amount) FROM public.driver_obligations o
                      WHERE o.driver_id = d.id AND o.status IN ('open','disputed')), 0) AS outstanding
      FROM public.drivers d
     WHERE d.settlement_suspended_until IS NOT NULL
       AND d.settlement_suspended_until <= now()
  LOOP
    IF v_driver.outstanding > v_amount THEN
      UPDATE public.drivers
         SET settlement_suspended_until = now() + make_interval(days => v_days)
       WHERE id = v_driver.driver_id;
      v_count := v_count + 1;
    ELSE
      UPDATE public.drivers SET settlement_suspended_until = NULL WHERE id = v_driver.driver_id;
      -- Do not revive a user suspended by ops for a different reason.
      UPDATE public.users
         SET account_status = 'active'
       WHERE id = v_driver.driver_uid
         AND account_status = 'suspended'
         AND NOT EXISTS (
           SELECT 1 FROM public.sanctions s
            WHERE s.target_user_id = v_driver.driver_uid
              AND s.is_active);
      INSERT INTO public.notifications (user_id, title, body, type, data, priority)
      VALUES (
        v_driver.driver_uid,
        'تمت استعادة حسابك',
        'انتهت فترة الإيقاف ومديونيتك الحالية ' || v_driver.outstanding::text ||
          ' جنيه ضمن الحد المسموح. يمكنك استقبال الطلبات من جديد.',
        'settlement_reactivation',
        jsonb_build_object('driver_id', v_driver.driver_id,
                           'outstanding', v_driver.outstanding),
        'high');
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public._settlement_settings()
 RETURNS platform_settings
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT * FROM public.platform_settings ORDER BY id LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public._sync_driver_rating()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ride uuid := COALESCE(NEW.ride_id, OLD.ride_id);
  v_driver uuid;
BEGIN
  SELECT r.driver_id INTO v_driver FROM public.rides r WHERE r.id = v_ride;
  IF v_driver IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  UPDATE public.drivers d
     SET rating = COALESCE((
           SELECT round(avg(x.stars)::numeric, 1)
             FROM public.ride_ratings x
             JOIN public.rides rr ON rr.id = x.ride_id
            WHERE rr.driver_id = v_driver
              AND x.ratee_role = 'driver'), 0)
   WHERE d.id = v_driver;
  RETURN COALESCE(NEW, OLD);
END;
$function$
;
CREATE OR REPLACE FUNCTION public._sync_merchant_rating()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_merchant uuid := COALESCE(NEW.merchant_id, OLD.merchant_id);
BEGIN
  UPDATE public.merchants m
     SET rating = COALESCE((
           SELECT round(avg(r.rating)::numeric, 1)
             FROM public.reviews r
            WHERE r.merchant_id = v_merchant), 0),
         total_reviews = (
           SELECT count(*) FROM public.reviews r
            WHERE r.merchant_id = v_merchant)
   WHERE m.id = v_merchant;
  RETURN COALESCE(NEW, OLD);
END;
$function$
;
CREATE OR REPLACE FUNCTION public._trg_order_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status = 'delivered' AND OLD.status IS DISTINCT FROM 'delivered' THEN
    PERFORM public._record_order_settlement(NEW.id);
  END IF;
  RETURN NEW;
END;
$function$
;
