 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN public.accept_ride_request(p_delivery_id, p_driver_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.accept_order(p_order_id uuid, p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order orders%ROWTYPE;
BEGIN
  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = p_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'FORBIDDEN');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_FOUND');
  END IF;
  IF v_order.dispatch_status <> 'PENDING_DISPATCH' OR v_order.driver_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'STALE', 'dispatch_status', v_order.dispatch_status);
  END IF;
  -- Non-owner callers may only accept an offer actually pending for their driver.
  IF NOT public._is_owner_uid(auth.uid()) AND NOT EXISTS (
    SELECT 1 FROM public.order_dispatch
     WHERE order_id = p_order_id
       AND candidate_driver_id = p_driver_id
       AND status IN ('pending', 'offered')
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NO_PENDING_OFFER');
  END IF;
  UPDATE public.orders
    SET driver_id = p_driver_id, dispatch_status = 'ASSIGNED', status = 'preparing'
    WHERE id = p_order_id;
  UPDATE public.order_dispatch
    SET status = 'accepted', candidate_driver_id = p_driver_id, updated_at = now()
    WHERE order_id = p_order_id;
  -- The driver app works off the delivery ride: hand it the same assignment.
  UPDATE public.rides
     SET driver_id = p_driver_id, status = 'matched', accepted_at = now()
   WHERE order_id = p_order_id
     AND ride_type = 'delivery'
     AND status = 'searching';
  PERFORM public.log_admin_action('DISPATCH_ACCEPT', 'order', p_order_id::text,
    NULL, jsonb_build_object('driver', p_driver_id), NULL, 'GLOBAL');
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.accept_ride_request(p_ride_id uuid, p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_owner UUID;
  v_status TEXT;
  v_req_status TEXT;
  v_expires timestamptz;
  v_otp TEXT;
  drv drivers%ROWTYPE;
  veh vehicles%ROWTYPE;
BEGIN
  SELECT * INTO drv FROM public.drivers WHERE id=p_driver_id FOR UPDATE;
  IF auth.uid() IS NULL OR drv.user_id IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;
  IF drv.location_updated_at IS NULL OR drv.location_updated_at <= now()-interval '2 minutes' THEN
    RETURN jsonb_build_object('success',false,'reason','stale_location');
  END IF;
  IF drv.is_verified IS DISTINCT FROM true OR drv.is_active IS DISTINCT FROM true
     OR drv.status IS DISTINCT FROM 'online' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'driver_ineligible');
  END IF;
  -- Serialize by ride before offer rows, so competing acceptances do not
  -- deadlock while expiring one another's offers.
  SELECT status INTO v_status FROM public.rides WHERE id=p_ride_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'ride_unavailable');
  END IF;
  IF EXISTS (SELECT 1 FROM rides WHERE driver_id = p_driver_id
             AND status IN ('matched','arrived','inTrip')) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'driver_busy');
  END IF;

  SELECT status, expires_at INTO v_req_status, v_expires FROM ride_requests
    WHERE ride_id = p_ride_id AND driver_id = p_driver_id FOR UPDATE;
  IF v_req_status IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_offer');
  END IF;
  IF v_req_status = 'offered' AND (v_expires IS NULL OR v_expires <= now()) THEN
    UPDATE public.ride_requests SET status='expired', responded_at=now()
      WHERE ride_id=p_ride_id AND driver_id=p_driver_id;
    RETURN jsonb_build_object('success', false, 'reason', 'offer_expired');
  END IF;
  IF v_req_status <> 'offered' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'offer_' || v_req_status);
  END IF;

  IF v_status IS DISTINCT FROM 'searching' THEN
    UPDATE ride_requests SET status = 'expired', responded_at = NOW()
      WHERE ride_id = p_ride_id AND driver_id = p_driver_id;
    RETURN jsonb_build_object('success', false, 'reason', 'ride_unavailable');
  END IF;

  SELECT * INTO drv FROM drivers WHERE id = p_driver_id;
  SELECT * INTO veh FROM vehicles
    WHERE id=drv.active_vehicle_id AND driver_id=p_driver_id AND is_active=true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_active_vehicle');
  END IF;
  v_otp := lpad((floor(random() * 10000))::INT::TEXT, 4, '0');

  UPDATE rides SET
    driver_id = p_driver_id,
    driver_name = drv.full_name,
    driver_phone = drv.phone,
    vehicle_type = COALESCE(veh.make || ' ' || veh.model, drv.vehicle_type),
    vehicle_plate = COALESCE(veh.plate_number, drv.vehicle_plate),
    vehicle_color = COALESCE(veh.color, drv.vehicle_color),
    driver_latitude = drv.current_latitude,
    driver_longitude = drv.current_longitude,
    status = 'matched',
    matched_at = NOW(),
    accepted_at = NOW(),
    pickup_otp = v_otp
  WHERE id = p_ride_id;

  UPDATE ride_requests SET status = 'accepted', responded_at = NOW()
    WHERE ride_id = p_ride_id AND driver_id = p_driver_id;
  UPDATE ride_requests SET status = 'expired', responded_at = NOW()
    WHERE ride_id = p_ride_id AND driver_id <> p_driver_id AND status = 'offered';

  INSERT INTO trip_events (ride_id, event_type, actor) VALUES (p_ride_id, 'accepted', 'driver');
  -- NOTE: OTP intentionally NOT included in the driver-facing return payload.
  RETURN jsonb_build_object('success', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.add_admin_note(p_complaint_id uuid, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_admin       uuid := auth.uid();
  v_complainant uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT complainant_id INTO v_complainant
    FROM public.complaints
   WHERE id = p_complaint_id;

  UPDATE complaints
  SET admin_notes = array_append(COALESCE(admin_notes, '{}'), p_note),
      updated_at = NOW()
  WHERE id = p_complaint_id;

  IF v_complainant IS NOT NULL THEN
    INSERT INTO public.notifications
      (user_id, title, body, type, data, deep_link, idempotency_key,
       sender_id, priority, send_push)
    VALUES
      (v_complainant,
       'Admin Note Added',
       'An administrator has added a note to your complaint.',
       'complaint_note',
       jsonb_build_object('entity_type', 'complaint', 'entity_id', p_complaint_id::text, 'action', 'admin_note'),
       '/my-complaints',
       'complaint-note-' || p_complaint_id::text || '-' || now()::text,
       v_admin, 'normal', true)
    ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

    INSERT INTO public.member_events (user_id, event_type, payload)
    VALUES (v_complainant, 'complaint_created',
            jsonb_build_object('complaint_id', p_complaint_id::text, 'action', 'admin_note'))
    ON CONFLICT DO NOTHING;
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.add_driver_vehicle(p_driver_id uuid, p_category text, p_make text, p_model text, p_year integer, p_color text, p_plate_number text, p_seats integer DEFAULT 4, p_photo_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id UUID;
BEGIN
  IF p_category IS NOT NULL AND p_category NOT IN ('motorcycle','tuk_tuk','tricycle','car') THEN
    RAISE EXCEPTION 'Invalid delivery vehicle type';
  END IF;
  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = p_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;
  INSERT INTO vehicles (driver_id, category, make, model, year, color, plate_number, seats, photo_url)
  VALUES (p_driver_id, p_category, p_make, p_model, p_year, p_color, p_plate_number, p_seats, p_photo_url)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('success', true, 'vehicle_id', v_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.add_order_items(p_order_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_order public.orders%rowtype;
  v_item jsonb;
  v_product public.products%rowtype;
  v_qty int;
  v_added numeric := 0;
  v_lines jsonb := '[]'::jsonb;
  v_stock_touched boolean := false;
  v_coupon public.coupons%rowtype;
  v_new_subtotal numeric;
  v_discount numeric := 0;
  v_total numeric;
  v_merchant_uid uuid;
begin
  if v_uid is null then
    raise exception 'UNAUTHENTICATED';
  end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;
  if v_order.user_id is distinct from v_uid and not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  if v_order.status not in ('pending','confirmed','preparing') then
    raise exception 'ORDER_NOT_EDITABLE %', v_order.status;
  end if;
  if v_order.payment_status = 'paid' then
    raise exception 'ORDER_ALREADY_PAID';
  end if;
  -- Monthly edit allowance (mig 185): 3 edits per calendar month (UTC).
  if v_uid = v_order.user_id and not public.is_admin() then
    if (select count(*) from public.order_edit_events
         where user_id = v_uid
           and created_at >= date_trunc('month', now() at time zone 'Africa/Cairo') at time zone 'Africa/Cairo') >= 3 then
      raise exception 'EDIT_ALLOWANCE_EXHAUSTED';
    end if;
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'EMPTY_ITEMS';
  end if;
  if jsonb_array_length(p_items) > 100 then
    raise exception 'TOO_MANY_ITEMS';
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_qty := coalesce((v_item->>'quantity')::int, 0);
    if v_qty < 1 or v_qty > 50 then
      raise exception 'INVALID_QUANTITY';
    end if;
    select * into v_product from public.products
     where id = (v_item->>'product_id')::uuid and merchant_id = v_order.merchant_id;
    if not found then
      raise exception 'PRODUCT_NOT_FOUND %', v_item->>'product_id';
    end if;
    if v_product.is_available is not true then
      raise exception 'PRODUCT_UNAVAILABLE %', coalesce(v_product.name_ar, v_product.name);
    end if;
    if v_product.stock_quantity is not null then
      update public.products set stock_quantity = stock_quantity - v_qty
       where id = v_product.id and stock_quantity >= v_qty;
      if not found then
        raise exception 'INSUFFICIENT_STOCK %', coalesce(v_product.name_ar, v_product.name);
      end if;
      v_stock_touched := true;
    end if;
    v_added := v_added + (v_product.price * v_qty);
    v_lines := v_lines || jsonb_build_object(
      'product_id', v_product.id,
      'product_name', coalesce(v_product.name_ar, v_product.name),
      'quantity', v_qty,
      'unit_price', v_product.price,
      'total_price', v_product.price * v_qty);
  end loop;

  v_new_subtotal := v_order.subtotal + v_added;

  if v_order.coupon_id is not null then
    select * into v_coupon from public.coupons where id = v_order.coupon_id;
    if found then
      if v_coupon.discount_type = 'percentage' then
        v_discount := round(v_new_subtotal * v_coupon.discount_value / 100.0, 2);
      else
        v_discount := v_coupon.discount_value;
      end if;
      if v_coupon.maximum_discount is not null then
        v_discount := least(v_discount, v_coupon.maximum_discount);
      end if;
      v_discount := least(v_discount, v_new_subtotal);
    else
      v_discount := v_order.discount;
    end if;
  else
    v_discount := coalesce(v_order.discount, 0);
  end if;

  v_total := greatest(v_new_subtotal + coalesce(v_order.delivery_fee,0) - v_discount, 0);

  insert into public.order_items (order_id, product_id, product_name, quantity, unit_price, total_price)
  select p_order_id, (l->>'product_id')::uuid, l->>'product_name',
         (l->>'quantity')::int, (l->>'unit_price')::numeric, (l->>'total_price')::numeric
    from jsonb_array_elements(v_lines) l;

  update public.orders
     set subtotal = v_new_subtotal,
         discount = v_discount,
         total_amount = v_total,
         items = coalesce(items, '[]'::jsonb) || v_lines,
         stock_decremented = stock_decremented or v_stock_touched,
         updated_at = now()
   where id = p_order_id;

  insert into public.order_edit_events (order_id, user_id, added_subtotal)
  values (p_order_id, v_order.user_id, v_added);

  select owner_user_id into v_merchant_uid from public.merchants where id = v_order.merchant_id;
  if v_merchant_uid is not null then
    insert into public.notifications (user_id, title, body, type, data, send_push)
    values (v_merchant_uid,
            'تعديل على طلب قيد التجهيز',
            'أضاف العميل منتجات إلى الطلب رقم ' || right(p_order_id::text, 6) ||
              '. الإجمالي الجديد: ' || v_total::text || ' جنيه.',
            'order',
            jsonb_build_object('order_id', p_order_id, 'event', 'items_added',
                               'added_subtotal', v_added, 'total_amount', v_total),
            true);
  end if;

  return jsonb_build_object(
    'ok', true, 'order_id', p_order_id,
    'added_subtotal', v_added,
    'subtotal', v_new_subtotal,
    'discount', v_discount,
    'total_amount', v_total);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_apply_role_template(p_admin_id uuid, p_role_key text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_before jsonb;
BEGIN
  IF NOT (public._is_owner_uid(auth.uid())
          OR public.has_permission('ADMIN_ROLE_ASSIGN', NULL)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  SELECT jsonb_build_object('role_key', role_key) INTO v_before FROM users WHERE id = p_admin_id;
  UPDATE users SET role_key = p_role_key WHERE id = p_admin_id;
  PERFORM public.log_admin_action('ADMIN_ROLE_CHANGE', 'admin', p_admin_id::text, v_before,
    jsonb_build_object('role_key', p_role_key), p_reason);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_assign_region_by_id(p_email text, p_region_id uuid, p_scope text DEFAULT 'descendants'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_admin_id uuid;
  v_region_name text;
BEGIN
  IF NOT (public.is_admin() OR public._is_owner_uid(auth.uid())) THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;

  IF p_scope NOT IN ('self', 'descendants') THEN
    RAISE EXCEPTION 'INVALID_SCOPE';
  END IF;

  SELECT id INTO v_admin_id
    FROM public.users
   WHERE lower(email) = lower(btrim(p_email))
      OR id::text = btrim(p_email)
      OR phone = btrim(p_email)
   LIMIT 1;

  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'ADMIN_NOT_FOUND';
  END IF;

  SELECT COALESCE(name_ar, name_en) INTO v_region_name
    FROM public.regions
   WHERE id = p_region_id;

  IF v_region_name IS NULL THEN
    RAISE EXCEPTION 'REGION_NOT_FOUND';
  END IF;

  INSERT INTO public.admin_region_assignments (
    admin_id, region_id, scope, created_by
  ) VALUES (
    v_admin_id, p_region_id, p_scope, auth.uid()
  )
  ON CONFLICT (admin_id, region_id) DO UPDATE
    SET scope = EXCLUDED.scope,
        created_by = EXCLUDED.created_by;

  UPDATE public.users
     SET region_id = p_region_id,
         updated_at = now()
   WHERE id = v_admin_id;

  INSERT INTO public.user_region_preferences (
    user_id, region_id, source, updated_at
  ) VALUES (
    v_admin_id, p_region_id, 'verified', now()
  )
  ON CONFLICT (user_id) DO UPDATE
    SET region_id = EXCLUDED.region_id,
        source = 'verified',
        updated_at = now();

  IF to_regclass('public.admin_users') IS NOT NULL THEN
    BEGIN
      UPDATE public.admin_users
         SET region_id = p_region_id,
             region_name = v_region_name,
             updated_at = now()
       WHERE user_id = v_admin_id OR lower(email) = lower(btrim(p_email));
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_broadcast_notification(p_title text, p_body text, p_type text DEFAULT 'info'::text, p_deep_link text DEFAULT NULL::text, p_target_role text DEFAULT NULL::text, p_target_user_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  matched_ids uuid[];
  device_count INTEGER;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT array_agg(u.id) INTO matched_ids
  FROM public.users u
  WHERE (p_target_user_id IS NULL OR u.id = p_target_user_id)
    AND (p_target_role IS NULL OR u.role = p_target_role);

  IF matched_ids IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, title, body, type, data, is_read)
    SELECT
      unnest(matched_ids),
      p_title,
      p_body,
      p_type,
      CASE
        WHEN p_deep_link IS NULL THEN NULL
        ELSE jsonb_build_object('deep_link', p_deep_link)
      END,
      false;
  END IF;

  SELECT COUNT(*) INTO device_count
  FROM public.notification_tokens t
  WHERE t.user_id = ANY(matched_ids);

  RETURN device_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_create_and_publish_banner(p_name_ar text, p_name_en text DEFAULT NULL::text, p_subtitle_ar text DEFAULT NULL::text, p_subtitle_en text DEFAULT NULL::text, p_region_id uuid DEFAULT NULL::uuid, p_image_path text DEFAULT NULL::text, p_starts_at timestamp with time zone DEFAULT now(), p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_campaign_id uuid;
  v_request_id uuid;
  v_code text;
  v_publish_status text;
  v_clean_image text := NULLIF(btrim(p_image_path), '');
BEGIN
  IF v_uid IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF NULLIF(btrim(p_name_ar), '') IS NULL THEN
    RAISE EXCEPTION 'Arabic title is required';
  END IF;

  IF p_ends_at IS NOT NULL AND p_starts_at IS NOT NULL AND p_ends_at <= p_starts_at THEN
    RAISE EXCEPTION 'ends_at must be after starts_at';
  END IF;

  IF NOT public.campaign_can_target_region(p_region_id) THEN
    RAISE EXCEPTION 'Not authorized for this target region';
  END IF;

  v_code := 'adm_banner_' || replace(gen_random_uuid()::text, '-', '');

  INSERT INTO public.campaigns (
    code,
    campaign_type,
    priority,
    name_ar,
    name_en,
    subtitle_ar,
    subtitle_en,
    status,
    starts_at,
    ends_at,
    proposed_by,
    created_by
  )
  VALUES (
    v_code,
    'promotion',
    'normal',
    btrim(p_name_ar),
    NULLIF(btrim(p_name_en), ''),
    NULLIF(btrim(p_subtitle_ar), ''),
    NULLIF(btrim(p_subtitle_en), ''),
    'draft',
    COALESCE(p_starts_at, now()),
    p_ends_at,
    v_uid,
    v_uid
  )
  RETURNING id INTO v_campaign_id;

  IF v_clean_image IS NOT NULL THEN
    INSERT INTO public.campaign_banners (
      campaign_id, placement, locale, image_path
    )
    VALUES
      (v_campaign_id, 'home_carousel', 'ar', v_clean_image),
      (v_campaign_id, 'home_carousel', 'en', v_clean_image);
  END IF;

  INSERT INTO public.campaign_targets (campaign_id, region_id, created_by)
  VALUES (v_campaign_id, p_region_id, v_uid);

  -- draft -> pending_review
  v_request_id := public.campaign_submit(v_campaign_id, 'admin_direct_publish');

  -- pending_review -> approved
  UPDATE public.approval_requests
  SET state = 'approved',
      decided_by = v_uid,
      decided_at = now(),
      reason = 'admin_direct_publish'
  WHERE id = v_request_id;

  INSERT INTO public.campaign_reviews
    (campaign_id, reviewer_id, action, previous_state, new_state, reason)
  VALUES (
    v_campaign_id, v_uid, 'approve',
    'pending_review', 'approved', 'admin_direct_publish'
  );

  UPDATE public.campaigns
  SET status = 'approved'
  WHERE id = v_campaign_id;

  -- approved -> published (or scheduled if starts_at > now())
  v_publish_status := public.campaign_publish(v_campaign_id);

  RETURN jsonb_build_object(
    'campaign_id', v_campaign_id,
    'request_id', v_request_id,
    'code', v_code,
    'status', v_publish_status
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_create_receiving_wallet(p_region_id uuid, p_method_type text, p_wallet_number text DEFAULT NULL::text, p_account_name text DEFAULT NULL::text, p_provider text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  IF NOT public.is_admin_for_region(p_region_id) THEN
    RAISE EXCEPTION 'Region forbidden';
  END IF;
  INSERT INTO public.admin_receiving_wallets
    (admin_id, region_id, method_type, wallet_number, account_name, provider)
  VALUES
    (auth.uid(), p_region_id, p_method_type, p_wallet_number, p_account_name, p_provider)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_create_settlement_code(p_obligation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ob public.driver_obligations%ROWTYPE;
  v_code text;
BEGIN
  IF auth.uid() IS NULL OR NOT (
    public.is_admin() OR EXISTS (
      SELECT 1 FROM public.admin_region_assignments WHERE admin_id = auth.uid())
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  SELECT * INTO v_ob FROM public.driver_obligations WHERE id = p_obligation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF v_ob.status <> 'open' OR v_ob.owed_to <> 'platform' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE');
  END IF;
  v_code := lpad(floor(random() * 10000)::int::text, 4, '0');
  UPDATE public.driver_obligations
     SET settlement_code = v_code, updated_at = now()
   WHERE id = p_obligation_id;
  RETURN jsonb_build_object('ok', true, 'code', v_code);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_delete_banner(p_campaign_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.campaigns WHERE id = p_campaign_id) THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;

  IF to_regclass('public.campaign_seen') IS NOT NULL THEN
    DELETE FROM public.campaign_seen WHERE campaign_id = p_campaign_id;
  END IF;
  IF to_regclass('public.campaign_banners') IS NOT NULL THEN
    DELETE FROM public.campaign_banners WHERE campaign_id = p_campaign_id;
  END IF;
  IF to_regclass('public.campaign_targets') IS NOT NULL THEN
    DELETE FROM public.campaign_targets WHERE campaign_id = p_campaign_id;
  END IF;
  IF to_regclass('public.campaign_media') IS NOT NULL THEN
    DELETE FROM public.campaign_media WHERE campaign_id = p_campaign_id;
  END IF;
  IF to_regclass('public.campaign_reviews') IS NOT NULL THEN
    DELETE FROM public.campaign_reviews WHERE campaign_id = p_campaign_id;
  END IF;
  IF to_regclass('public.approval_requests') IS NOT NULL THEN
    DELETE FROM public.approval_requests
     WHERE entity_id = p_campaign_id AND entity_type = 'campaign';
  END IF;

  DELETE FROM public.campaigns WHERE id = p_campaign_id;

  RETURN jsonb_build_object(
    'campaign_id', p_campaign_id,
    'deleted', true
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_delete_chat(p_room_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (SELECT role FROM public.users WHERE id = auth.uid()) = 'owner' OR EXISTS (SELECT 1 FROM public.chat_rooms cr WHERE cr.id = p_room_id AND auth.uid() = ANY(cr.participant_ids)) THEN
    DELETE FROM public.chat_messages WHERE room_id = p_room_id;
    DELETE FROM storage.objects WHERE bucket_id = 'chat_attachments' AND name LIKE (p_room_id::text || '/%');
    DELETE FROM public.chat_rooms WHERE id = p_room_id;
  ELSE
    RAISE EXCEPTION 'forbidden';
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_delete_merchant(p_merchant_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;
  DELETE FROM public.reviews WHERE merchant_id = p_merchant_id;
  UPDATE public.products
     SET is_available = false, updated_at = now()
   WHERE merchant_id = p_merchant_id
     AND id IN (SELECT product_id FROM public.order_items);
  DELETE FROM public.products
   WHERE merchant_id = p_merchant_id
     AND id NOT IN (SELECT product_id FROM public.order_items);
  DELETE FROM public.merchants WHERE id = p_merchant_id;
  RETURN FOUND;
END; $function$
;
CREATE OR REPLACE FUNCTION public.admin_delete_merchant_review(p_review_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;
  DELETE FROM public.reviews WHERE id = p_review_id;
  RETURN FOUND;
END; $function$
;
CREATE OR REPLACE FUNCTION public.admin_delete_product(p_product_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;
  DELETE FROM public.reviews WHERE product_id = p_product_id;
  BEGIN
    DELETE FROM public.products WHERE id = p_product_id;
    RETURN FOUND;
  EXCEPTION WHEN foreign_key_violation THEN
    UPDATE public.products
       SET is_available = false, updated_at = now()
     WHERE id = p_product_id;
    RETURN FOUND;
  END;
END; $function$
;
CREATE OR REPLACE FUNCTION public.admin_delete_service_review(p_review_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;
  DELETE FROM public.service_reviews WHERE id = p_review_id;
  -- trg_service_reviews_sync_provider (AFTER DELETE) recomputes the provider rating.
  RETURN FOUND;
END; $function$
;
CREATE OR REPLACE FUNCTION public.admin_direct_topup(p_account_type text, p_account_id uuid, p_amount numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller    uuid := auth.uid();
  v_wallet_id uuid;
  v_before    numeric;
  v_after     numeric;
  v_target    record;
  v_txn_id    uuid;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  -- OWNER ONLY. This removes the prior (owner OR TOPUP_APPROVE-admin) gate that
  -- let any region admin credit any wallet without a request + approval.
  IF NOT public._is_owner_uid(v_caller) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN_OWNER_ONLY');
  END IF;

  SELECT id INTO v_target FROM public.users WHERE id = p_account_id;
  IF v_target.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACCOUNT_NOT_FOUND');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_AMOUNT');
  END IF;

  v_wallet_id := public._ensure_wallet(p_account_id);
  SELECT balance INTO v_before FROM public.wallets WHERE id = v_wallet_id FOR UPDATE;
  v_after := COALESCE(v_before, 0) + p_amount;
  UPDATE public.wallets SET balance = v_after, updated_at = now()
   WHERE id = v_wallet_id;
  INSERT INTO public.wallet_transactions
    (wallet_id, type, amount, reference_type, reference_id, description, balance_after)
  VALUES
    (v_wallet_id, 'credit', p_amount, 'admin_topup', v_caller,
     'Owner direct top-up correction (' || coalesce(p_account_type, 'account') || ')', v_after)
  RETURNING id INTO v_txn_id;

  PERFORM public.write_audit('ADMIN_DIRECT_TOPUP', 'wallets', v_wallet_id::text,
    jsonb_build_object('actor', v_caller, 'actor_role', 'owner',
      'account_id', p_account_id, 'account_type', p_account_type,
      'amount', p_amount, 'balance_before', v_before, 'balance_after', v_after,
      'transaction_id', v_txn_id, 'note', p_note));

  INSERT INTO public.notifications (user_id, title, body, type, data)
  VALUES (p_account_id, 'Account funded',
    'Your wallet was credited with ' || p_amount::text, 'admin_topup',
    jsonb_build_object('account_id', p_account_id, 'account_type', p_account_type,
      'amount', p_amount, 'transaction_id', v_txn_id));

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'wallet_id', v_wallet_id,
    'transaction_id', v_txn_id, 'balance_before', v_before, 'balance_after', v_after,
    'amount', p_amount);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_effective_permissions(p_admin_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'role', (SELECT role_key FROM users WHERE id = p_admin_id),
    'role_permissions',
      (SELECT COALESCE(r.default_permissions, '[]'::jsonb)
         FROM public.admin_roles r WHERE r.role_key = (SELECT role_key FROM users WHERE id = p_admin_id)),
    'granted',
      (SELECT COALESCE(jsonb_agg(DISTINCT permission), '[]'::jsonb)
         FROM public.admin_permission_grants WHERE admin_id = p_admin_id),
    'regions',
      (SELECT COALESCE(jsonb_agg(DISTINCT region_id), '[]'::jsonb)
         FROM public.admin_region_assignments WHERE admin_id = p_admin_id)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.admin_promote_and_configure_member(p_member_id uuid, p_role text, p_region_id uuid DEFAULT NULL::uuid, p_permissions text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_perm text;
BEGIN
  IF NOT (public.is_admin() OR public._is_owner_uid(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  PERFORM public.assign_admin_role(p_member_id::text, p_role, 'Configured from Member Operations Center');

  IF p_region_id IS NOT NULL AND p_role NOT IN ('customer', 'driver', 'merchant', 'provider', 'delivery') THEN
    PERFORM public.admin_assign_region_by_id(p_member_id::text, p_region_id, 'descendants');
  END IF;

  IF p_permissions IS NOT NULL AND p_role NOT IN ('customer', 'driver', 'merchant', 'provider', 'delivery') THEN
    DELETE FROM public.admin_permission_grants
     WHERE admin_id = p_member_id
       AND NOT (permission = ANY(p_permissions));

    FOREACH v_perm IN ARRAY p_permissions LOOP
      IF public._valid_permission(v_perm) THEN
        INSERT INTO public.admin_permission_grants (admin_id, permission, granted_by)
        VALUES (p_member_id, v_perm, auth.uid())
        ON CONFLICT (admin_id, permission) DO NOTHING;
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'member_id', p_member_id,
    'role', p_role,
    'region_id', p_region_id
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_purge_expired_chats()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_expired integer;
DECLARE r RECORD;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admins only';
  END IF;

  SELECT count(*) INTO v_expired
    FROM public.chat_rooms
    WHERE auto_delete_at IS NOT NULL AND auto_delete_at <= now();

  FOR r IN
    SELECT id FROM public.chat_rooms
    WHERE auto_delete_at IS NOT NULL AND auto_delete_at <= now()
  LOOP
    DELETE FROM public.chat_messages WHERE room_id = r.id;
    DELETE FROM storage.objects
      WHERE bucket_id = 'chat_attachments'
        AND name LIKE r.id::text || '/%';
    DELETE FROM public.chat_rooms WHERE id = r.id;
  END LOOP;

  RETURN v_expired;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_review_payout(p_request_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_req public.merchant_payout_requests%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  SELECT * INTO v_req FROM public.merchant_payout_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_req.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE');
  END IF;
  UPDATE public.merchant_payout_requests
     SET status = CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,
         reviewed_by = auth.uid(), reviewed_at = now(), rejection_reason = p_reason
   WHERE id = p_request_id;
  IF p_approve THEN
    INSERT INTO public.merchant_ledger
      (merchant_id, entry_type, amount, currency, description, created_by)
    VALUES
      (v_req.merchant_id, 'debit', v_req.amount, v_req.currency,
       'Payout request ' || p_request_id::text, auth.uid());
  END IF;
  PERFORM public.log_admin_action(
    CASE WHEN p_approve THEN 'PAYOUT_APPROVED' ELSE 'PAYOUT_REJECTED' END,
    'merchant_payout_request', p_request_id::text, NULL,
    jsonb_build_object('amount', v_req.amount, 'reason', p_reason), p_reason, 'GLOBAL');
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_set_grace(p_user_id uuid, p_new_limit integer, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_region uuid;
  v_before integer;
  v_row    public.grace_accounts;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF p_new_limit < 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_LIMIT');
  END IF;
  SELECT region_id INTO v_region FROM public.user_region_preferences
   WHERE user_id = p_user_id LIMIT 1;
  IF v_region IS NOT NULL AND NOT public._region_in_scope(auth.uid(), v_region)
     AND NOT public._is_owner_uid(auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'REGION_FORBIDDEN');
  END IF;

  SELECT grace_limit INTO v_before FROM public.grace_accounts WHERE user_id = p_user_id;
  v_row := public.get_or_create_grace(p_user_id);
  v_before := COALESCE(v_before, 0);
  UPDATE public.grace_accounts SET grace_limit = p_new_limit, updated_at = now()
   WHERE user_id = p_user_id;

  INSERT INTO public.grace_audit_log
    (account_id, before, after, actor, reason, created_at)
  VALUES
    (p_user_id, v_before, p_new_limit, auth.uid(),
     COALESCE(p_reason, 'admin_adjustment'), now());

  PERFORM public.write_audit('GRACE_LIMIT_CHANGED', 'grace_accounts', p_user_id::text,
    jsonb_build_object('old', v_before, 'new', p_new_limit,
      'actor', auth.uid(), 'region', v_region, 'reason', p_reason));

  RETURN jsonb_build_object('ok', true, 'code', 'OK',
    'grace_limit', p_new_limit);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_set_user_role(p_user_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'Cannot change your own role';
  END IF;
  IF p_role NOT IN ('customer','merchant','driver','admin','owner','provider','delivery') THEN
    RAISE EXCEPTION 'Invalid role';
  END IF;
  IF p_role = 'owner' AND NOT public._is_owner_uid(auth.uid()) THEN
    RAISE EXCEPTION 'Only the owner can grant the owner role';
  END IF;
  IF p_role = 'admin'
     AND NOT EXISTS (
       SELECT 1 FROM public.admin_management
       WHERE admin_id = p_user_id AND is_active
     ) THEN
    RAISE EXCEPTION 'Use create_admin_account to create admins';
  END IF;
  -- managing an admin (or demoting one) requires supervision unless owner
  IF NOT public._is_owner_uid(auth.uid())
     AND (EXISTS (SELECT 1 FROM public.admin_management WHERE admin_id = p_user_id)
          OR p_role IN ('admin','owner'))
     AND NOT public.is_supervisor_of(auth.uid(), p_user_id) THEN
    RAISE EXCEPTION 'Not authorized for this user';
  END IF;

  PERFORM public._admin_exec_role(auth.uid(), p_user_id, p_role, NULL);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_update_banner(p_campaign_id uuid, p_name_ar text, p_name_en text DEFAULT NULL::text, p_subtitle_ar text DEFAULT NULL::text, p_subtitle_en text DEFAULT NULL::text, p_region_id uuid DEFAULT NULL::uuid, p_image_path text DEFAULT NULL::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_current_status text;
  v_existing_starts_at timestamptz;
  v_effective_starts_at timestamptz;
  v_new_status text;
  v_clean_image text := NULLIF(btrim(p_image_path), '');
BEGIN
  IF v_uid IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF NULLIF(btrim(p_name_ar), '') IS NULL THEN
    RAISE EXCEPTION 'Arabic title is required';
  END IF;

  IF NOT public.campaign_can_target_region(p_region_id) THEN
    RAISE EXCEPTION 'Not authorized for this target region';
  END IF;

  SELECT status, starts_at
    INTO v_current_status, v_existing_starts_at
    FROM public.campaigns
   WHERE id = p_campaign_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;

  v_effective_starts_at := COALESCE(p_starts_at, v_existing_starts_at, now());

  IF p_ends_at IS NOT NULL AND p_ends_at <= v_effective_starts_at THEN
    RAISE EXCEPTION 'ends_at must be after starts_at';
  END IF;

  IF v_current_status IN ('published', 'scheduled') THEN
    IF p_starts_at IS NOT NULL AND p_starts_at > now() THEN
      v_new_status := 'scheduled';
    ELSE
      v_new_status := 'published';
    END IF;
  ELSE
    v_new_status := v_current_status;
  END IF;

  UPDATE public.campaigns
     SET name_ar = btrim(p_name_ar),
         name_en = NULLIF(btrim(p_name_en), ''),
         subtitle_ar = NULLIF(btrim(p_subtitle_ar), ''),
         subtitle_en = NULLIF(btrim(p_subtitle_en), ''),
         starts_at = v_effective_starts_at,
         ends_at = p_ends_at,
         status = v_new_status,
         updated_at = now()
   WHERE id = p_campaign_id;

  DELETE FROM public.campaign_targets
   WHERE campaign_id = p_campaign_id;

  INSERT INTO public.campaign_targets (campaign_id, region_id, created_by)
  VALUES (p_campaign_id, p_region_id, v_uid);

  IF v_clean_image IS NOT NULL THEN
    INSERT INTO public.campaign_banners (
      campaign_id, placement, locale, image_path
    )
    VALUES
      (p_campaign_id, 'home_carousel', 'ar', v_clean_image),
      (p_campaign_id, 'home_carousel', 'en', v_clean_image)
    ON CONFLICT (campaign_id, placement, locale)
    DO UPDATE SET
      image_path = EXCLUDED.image_path,
      is_active = true,
      updated_at = now();
  END IF;

  RETURN jsonb_build_object(
    'campaign_id', p_campaign_id,
    'status', v_new_status
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_update_member_profile(p_member_id uuid, p_full_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_target_role text;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT role INTO v_target_role FROM public.users WHERE id = p_member_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;
  IF public._is_active_admin_uid(p_member_id) THEN
    RAISE EXCEPTION 'Admins are managed through the admin lifecycle';
  END IF;
  IF NOT public.has_permission('MEMBER_MODERATE', public._member_region_id(p_member_id)) THEN
    RAISE EXCEPTION 'Not authorized for this member';
  END IF;
  IF p_full_name IS NULL AND p_phone IS NULL THEN
    RAISE EXCEPTION 'Nothing to update';
  END IF;

  UPDATE public.users
     SET full_name = COALESCE(NULLIF(btrim(p_full_name), ''), full_name),
         phone = COALESCE(NULLIF(btrim(p_phone), ''), phone),
         updated_at = now()
   WHERE id = p_member_id;

  PERFORM public.write_audit(
    'MEMBER_PROFILE_UPDATED',
    'users',
    p_member_id::text,
    jsonb_build_object(
      'full_name', p_full_name,
      'phone', p_phone
    )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_upsert_product(p_id uuid, p_merchant_id uuid, p_name text, p_description text DEFAULT NULL::text, p_price numeric DEFAULT 0, p_compare_at_price numeric DEFAULT NULL::numeric, p_category text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_is_available boolean DEFAULT true, p_stock_quantity integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_product_id uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'insufficient_privilege';
  END IF;

  IF p_merchant_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.merchants WHERE id = p_merchant_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'merchant_not_found');
  END IF;

  IF p_name IS NULL OR trim(p_name) = '' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'name_required');
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE public.products
       SET name = p_name,
           description = p_description,
           price = COALESCE(p_price, 0),
           compare_at_price = p_compare_at_price,
           category = p_category,
           image_url = p_image_url,
           is_available = COALESCE(p_is_available, true),
           stock_quantity = COALESCE(p_stock_quantity, 0),
           updated_at = NOW()
     WHERE id = p_id AND merchant_id = p_merchant_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'reason', 'product_not_found');
    END IF;
    v_product_id := p_id;
  ELSE
    INSERT INTO public.products (
      merchant_id, name, description, price, compare_at_price,
      category, image_url, is_available, stock_quantity
    ) VALUES (
      p_merchant_id, p_name, p_description, COALESCE(p_price, 0),
      p_compare_at_price, p_category, p_image_url,
      COALESCE(p_is_available, true), COALESCE(p_stock_quantity, 0)
    )
    RETURNING id INTO v_product_id;
  END IF;

  INSERT INTO public.product_inventory (
    product_id, merchant_id, stock_quantity, is_in_stock, updated_at
  ) VALUES (
    v_product_id, p_merchant_id, COALESCE(p_stock_quantity, 0),
    COALESCE(p_stock_quantity, 0) > 0, NOW()
  )
  ON CONFLICT (product_id) DO UPDATE
    SET stock_quantity = EXCLUDED.stock_quantity,
        is_in_stock = EXCLUDED.stock_quantity > 0,
        updated_at = NOW();

  RETURN jsonb_build_object(
    'success', true,
    'product_id', v_product_id::text,
    'merchant_id', p_merchant_id::text
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_upsert_region(p_id uuid DEFAULT NULL::uuid, p_parent_region_id uuid DEFAULT NULL::uuid, p_type text DEFAULT 'village'::text, p_name_ar text DEFAULT ''::text, p_name_en text DEFAULT NULL::text, p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision, p_radius_km double precision DEFAULT 3.0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
  v_code text;
  v_level integer;
  v_radius_m double precision;
  v_meta jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;

  IF p_type NOT IN (
    'governorate', 'markaz', 'district', 'city', 'village', 'new_city', 'area'
  ) THEN
    RAISE EXCEPTION 'INVALID_REGION_TYPE';
  END IF;

  IF btrim(COALESCE(p_name_ar, '')) = '' THEN
    RAISE EXCEPTION 'NAME_AR_REQUIRED';
  END IF;

  v_radius_m := LEAST(GREATEST(COALESCE(p_radius_km, 3.0), 0.3), 50.0) * 1000.0;
  v_meta := jsonb_strip_nulls(jsonb_build_object(
    'lat', p_lat,
    'lon', p_lon,
    'radius_km', COALESCE(p_radius_km, 3.0),
    'source', 'admin_curated'
  ));

  IF p_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.regions WHERE id = p_id) THEN
    v_id := p_id;
    UPDATE public.regions
       SET parent_region_id = COALESCE(p_parent_region_id, parent_region_id),
           type = p_type,
           name_ar = btrim(p_name_ar),
           name_en = NULLIF(btrim(COALESCE(p_name_en, '')), ''),
           metadata = COALESCE(metadata, '{}'::jsonb) || v_meta,
           updated_at = now()
     WHERE id = v_id;
  ELSE
    v_id := COALESCE(p_id, gen_random_uuid());
    v_code := 'EG-CUSTOM-' || substr(replace(v_id::text, '-', ''), 1, 8);
    INSERT INTO public.regions (
      id, code, parent_region_id, country_code, type,
      name_ar, name_en, is_active, metadata
    ) VALUES (
      v_id,
      v_code,
      p_parent_region_id,
      'EG',
      p_type,
      btrim(p_name_ar),
      NULLIF(btrim(COALESCE(p_name_en, '')), ''),
      true,
      v_meta
    );
  END IF;

  IF p_lat IS NOT NULL AND p_lon IS NOT NULL THEN
    v_level := CASE p_type
      WHEN 'governorate' THEN 1
      WHEN 'markaz' THEN 2
      WHEN 'district' THEN 2
      WHEN 'city' THEN 3
      WHEN 'new_city' THEN 3
      WHEN 'village' THEN 3
      ELSE 4
    END;

    INSERT INTO public.geo_admin_boundaries (
      region_id, level, geometry, source, source_ref
    ) VALUES (
      v_id,
      v_level,
      ST_Multi(
        ST_Buffer(
          ST_SetSRID(ST_MakePoint(p_lon, p_lat), 4326)::geography,
          v_radius_m
        )::geometry
      ),
      'admin_curated',
      v_id::text
    )
    ON CONFLICT (region_id, source, source_ref) DO UPDATE
      SET level = EXCLUDED.level,
          geometry = EXCLUDED.geometry;
  END IF;

  RETURN jsonb_build_object('ok', true, 'id', v_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.admin_waive_obligation(p_obligation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  UPDATE public.driver_obligations
     SET status = 'waived', updated_at = now()
   WHERE id = p_obligation_id AND status IN ('open','disputed');
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE');
  END IF;
  PERFORM public.log_admin_action('OBLIGATION_WAIVED', 'driver_obligation',
    p_obligation_id::text, NULL, jsonb_build_object('reason', p_reason), p_reason, 'GLOBAL');
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.apply_coupon(p_code text, p_order_total numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE c public.coupons; v_discount numeric; BEGIN IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'UNAUTHENTICATED'); END IF; SELECT * INTO c FROM public.coupons WHERE code = p_code FOR UPDATE; IF c IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'NOT_FOUND'); END IF; IF NOT c.is_active THEN RETURN jsonb_build_object('ok', false, 'reason', 'INACTIVE'); END IF; IF c.expires_at IS NOT NULL AND c.expires_at < now() THEN RETURN jsonb_build_object('ok', false, 'reason', 'EXPIRED'); END IF; IF c.minimum_order IS NOT NULL AND p_order_total < c.minimum_order THEN RETURN jsonb_build_object('ok', false, 'reason', 'BELOW_MINIMUM'); END IF; IF c.usage_limit IS NOT NULL AND c.used_count >= c.usage_limit THEN RETURN jsonb_build_object('ok', false, 'reason', 'USAGE_EXHAUSTED'); END IF; IF c.discount_type = 'percentage' THEN v_discount := p_order_total * (c.discount_value / 100); IF c.maximum_discount IS NOT NULL AND v_discount > c.maximum_discount THEN v_discount := c.maximum_discount; END IF; ELSIF c.discount_type = 'fixed' THEN v_discount := c.discount_value; IF v_discount > p_order_total THEN v_discount := p_order_total; END IF; ELSE RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_DISCOUNT_TYPE'); END IF; UPDATE public.coupons SET used_count = used_count + 1 WHERE id = c.id; RETURN jsonb_build_object('ok', true, 'computed_discount', v_discount); END; $function$
;
CREATE OR REPLACE FUNCTION public.apply_retention_policies()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_policy record;
  v_cutoff timestamptz;
  v_count int;
  v_archived int;
  v_result jsonb := '{}'::jsonb;
  v_entry jsonb;
BEGIN
  FOR v_policy IN
    SELECT domain, retention_days FROM public.retention_policies
    WHERE enabled AND retention_days > 0
    ORDER BY domain
  LOOP
    v_cutoff := now() - make_interval(days => v_policy.retention_days);
    v_count := 0;
    v_archived := 0;

    CASE v_policy.domain
      WHEN 'location_updates' THEN
        IF to_regclass('public.location_updates') IS NOT NULL THEN
          DELETE FROM public.location_updates WHERE recorded_at < v_cutoff;
          GET DIAGNOSTICS v_count = ROW_COUNT;
        END IF;
      WHEN 'driver_locations' THEN
        IF to_regclass('public.driver_locations') IS NOT NULL THEN
          DELETE FROM public.driver_locations WHERE updated_at < v_cutoff;
          GET DIAGNOSTICS v_count = ROW_COUNT;
        END IF;
      WHEN 'member_events' THEN
        DELETE FROM public.member_events WHERE created_at < v_cutoff;
        GET DIAGNOSTICS v_count = ROW_COUNT;
      WHEN 'chat_messages' THEN
        DELETE FROM public.chat_messages WHERE created_at < v_cutoff;
        GET DIAGNOSTICS v_count = ROW_COUNT;
      WHEN 'notifications' THEN
        DELETE FROM public.notifications WHERE created_at < v_cutoff;
        GET DIAGNOSTICS v_count = ROW_COUNT;
      WHEN 'sanctions' THEN
        -- legal/evidence ledger: never purge ACTIVE rows, only closed ones.
        DELETE FROM public.sanctions
        WHERE created_at < v_cutoff AND action_status <> 'active';
        GET DIAGNOSTICS v_count = ROW_COUNT;
      WHEN 'emergency_audio_sessions' THEN
        -- metadata only; table optional (not live — 036 absorbed).
        IF to_regclass('public.emergency_audio_sessions') IS NOT NULL THEN
          DELETE FROM public.emergency_audio_sessions
          WHERE created_at < v_cutoff AND status IN ('ended','cancelled');
          GET DIAGNOSTICS v_count = ROW_COUNT;
        END IF;
      WHEN 'campaigns' THEN
        -- archived rows only; live campaigns are never purged.
        DELETE FROM public.campaigns
        WHERE archived_at IS NOT NULL AND archived_at < v_cutoff;
        GET DIAGNOSTICS v_count = ROW_COUNT;
      WHEN 'activity_logs' THEN
        -- archive-then-purge (audit rows survive, never silently destroyed).
        IF to_regclass('public.activity_logs_archive') IS NULL THEN
          CREATE TABLE public.activity_logs_archive (LIKE public.activity_logs);
          ALTER TABLE public.activity_logs_archive
            ADD COLUMN IF NOT EXISTS archived_at timestamptz DEFAULT now();
          ALTER TABLE public.activity_logs_archive ENABLE ROW LEVEL SECURITY;
          REVOKE ALL ON TABLE public.activity_logs_archive FROM PUBLIC;
          REVOKE ALL ON TABLE public.activity_logs_archive FROM anon;
          REVOKE ALL ON TABLE public.activity_logs_archive FROM authenticated;
          GRANT ALL ON TABLE public.activity_logs_archive TO service_role;
          DROP POLICY IF EXISTS activity_logs_archive_admin_select
            ON public.activity_logs_archive;
          CREATE POLICY activity_logs_archive_admin_select
            ON public.activity_logs_archive
            FOR SELECT TO authenticated
            USING (public.is_admin());
        END IF;
        INSERT INTO public.activity_logs_archive
          (id, user_id, action, resource, resource_id, details, ip_address,
           user_agent, timestamp, archived_at)
        SELECT id, user_id, action, resource, resource_id, details, ip_address,
               user_agent, timestamp, now()
        FROM public.activity_logs
        WHERE timestamp < v_cutoff;
        GET DIAGNOSTICS v_archived = ROW_COUNT;
        DELETE FROM public.activity_logs WHERE timestamp < v_cutoff;
        GET DIAGNOSTICS v_count = ROW_COUNT;
      ELSE
        CONTINUE;
    END CASE;

    IF v_count > 0 OR v_archived > 0 THEN
      PERFORM public.write_audit(
        'RETENTION_PURGED', v_policy.domain, NULL,
        jsonb_build_object('domain', v_policy.domain, 'purged', v_count,
                           'archived', v_archived));
      v_entry := jsonb_build_object('purged', v_count, 'archived', v_archived);
      v_result := v_result || jsonb_build_object(v_policy.domain, v_entry);
    END IF;
  END LOOP;
  RETURN v_result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.approve_member_deletion(p_deletion_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_reason text;
BEGIN
  SELECT reason INTO v_reason
    FROM public.approval_requests
   WHERE id = p_deletion_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Deletion request not found';
  END IF;
  PERFORM public.decide_approval_request(
    p_deletion_id, 'approve', COALESCE(v_reason, 'Approved by admin')
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.approve_settlement_request(p_settlement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  s public.platform_settlements;
BEGIN
  IF auth.uid() IS NULL OR NOT public._is_owner_uid(auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  SELECT * INTO s FROM public.platform_settlements
   WHERE id = p_settlement_id FOR UPDATE;
  IF s IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF s.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ALREADY_PROCESSED', 'status', s.status);
  END IF;
  IF s.admin_id = auth.uid() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SELF_APPROVAL');
  END IF;
  UPDATE public.platform_settlements
     SET status = 'approved', reviewed_at = now(), reviewed_by = auth.uid()
   WHERE id = s.id;
  UPDATE public.regional_collections
     SET status = 'settled', settlement_id = s.id
   WHERE admin_id = s.admin_id AND status = 'collected'
     AND (s.region_id IS NULL OR region_id = s.region_id);
  PERFORM public.write_audit('SETTLEMENT_APPROVED', 'platform_settlements', s.id::text,
    jsonb_build_object('admin', s.admin_id, 'amount', s.amount, 'region', s.region_id));
  RETURN jsonb_build_object('ok', true, 'code', 'OK');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.approve_topup_request(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r          public.topup_requests;
  v_wallet_id uuid;
  v_balance  numeric;
  v_after    numeric;
  v_coll_id  uuid;
BEGIN
  -- Sensitive financial approval is OWNER-only. A normal admin is never a
  -- substitute unless an explicit, separately-protected financial role exists.
  IF auth.uid() IS NULL OR NOT public._is_owner_uid(auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN_OWNER_ONLY');
  END IF;

  SELECT * INTO r FROM public.topup_requests
   WHERE id = p_request_id FOR UPDATE;
  IF r IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF r.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ALREADY_PROCESSED', 'status', r.status);
  END IF;
  -- Owner cannot approve their own request (an Owner account filing for itself).
  IF r.account_id = auth.uid() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SELF_APPROVAL');
  END IF;

  -- Hard idempotency: the ledger row is the single source of truth. If a credit
  -- already exists for this request, never credit again (double-approval blocked).
  IF EXISTS (SELECT 1 FROM public.regional_collections WHERE topup_request_id = r.id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ALREADY_CREDITED');
  END IF;

  -- Atomic credit: lock the wallet row, compute, write, ledger.
  v_wallet_id := public._ensure_wallet(r.account_id);
  SELECT balance INTO v_balance FROM public.wallets WHERE id = v_wallet_id FOR UPDATE;
  v_after := COALESCE(v_balance, 0) + r.amount;
  UPDATE public.wallets SET balance = v_after, updated_at = now()
   WHERE id = v_wallet_id;
  INSERT INTO public.wallet_transactions
    (wallet_id, type, amount, reference_type, reference_id, description, balance_after)
  VALUES
    (v_wallet_id, 'credit', r.amount, 'topup', r.id,
     'Wallet top-up approved (request ' || r.id::text || ')', v_after);

  -- Immutable collection/credit ledger (UNIQUE topup_request_id = idempotency).
  INSERT INTO public.regional_collections
    (admin_id, region_id, account_id, topup_request_id, amount, currency, reference)
  VALUES
    (auth.uid(), r.region_id, r.account_id, r.id, r.amount, r.currency, r.transfer_reference)
  RETURNING id INTO v_coll_id;

  UPDATE public.topup_requests
     SET status = 'approved', reviewed_at = now(), reviewed_by = auth.uid()
   WHERE id = r.id;

  -- Full audit with balance before/after (write_audit is safe for all actors).
  PERFORM public.write_audit('TOPUP_APPROVED', 'topup_requests', r.id::text,
    jsonb_build_object('account', r.account_id, 'amount', r.amount,
      'method', r.payment_method, 'reference', r.transfer_reference,
      'reviewed_by', auth.uid(), 'collection', v_coll_id,
      'balance_before', v_balance, 'balance_after', v_after));

  INSERT INTO public.notifications (user_id, title, body, type, data)
  VALUES
    (r.account_id, 'Top-up approved', 'Your wallet was credited with ' ||
       r.amount::text || ' ' || coalesce(r.currency, 'EGP'), 'topup_approved',
     jsonb_build_object('topup_request_id', r.id, 'amount', r.amount,
       'wallet_transaction_balance', v_after, 'deep_link', '/wallet'));

  RETURN jsonb_build_object('ok', true, 'code', 'OK',
    'wallet_balance', v_after, 'collection_id', v_coll_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.approve_wallet_funding_request(p_funding_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request RECORD;
  v_wallet_id UUID;
  v_new_balance NUMERIC;
  v_approved_by UUID := auth.uid();
BEGIN
  -- Authorization: only financial admins/Owner can approve
  IF NOT public.has_financial_permission(v_approved_by, 'approve_wallet_funding') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF p_funding_request_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_REQUEST_ID');
  END IF;
  IF v_approved_by IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_APPROVER');
  END IF;

  -- Lock the funding request row
  SELECT * INTO STRICT v_request
  FROM public.wallet_funding_requests
  WHERE id = p_funding_request_id
  FOR UPDATE;

  IF v_request.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATUS', 'current_status', v_request.status);
  END IF;

  -- Ensure wallet exists
  v_wallet_id := public._ensure_wallet(v_request.user_id);

  -- Credit the wallet atomically
  UPDATE public.wallets
  SET balance = balance + v_request.amount,
      updated_at = now()
  WHERE id = v_wallet_id
  RETURNING balance INTO v_new_balance;

  -- Record the wallet transaction
  INSERT INTO public.wallet_transactions (
    wallet_id,
    type,
    amount,
    description,
    reference_type,
    reference_id,
    created_by
  ) VALUES (
    v_wallet_id,
    'credit',
    v_request.amount,
    'Funding request approved: ' || v_request.reference,
    'funding_approval',
    v_request.id,
    v_approved_by
  );

  -- Update funding request status
  UPDATE public.wallet_funding_requests
  SET status = 'approved',
      approved_by = v_approved_by,
      approved_at = now(),
      updated_at = now()
  WHERE id = p_funding_request_id;

  RETURN jsonb_build_object(
    'ok', true,
    'transaction_id', (SELECT id FROM public.wallet_transactions WHERE reference_id = v_request.id AND type = 'credit' ORDER BY created_at DESC LIMIT 1),
    'new_balance', v_new_balance,
    'amount', v_request.amount
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.assign_complaint(p_complaint_id uuid, p_admin_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_complaint public.complaints%ROWTYPE;
  v_region uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Prove server-origin to complaints_fixup_update (RPC path marker).
  PERFORM set_config('app.escalation_rpc', 'true', true);

  SELECT * INTO v_complaint
    FROM public.complaints WHERE id = p_complaint_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Complaint not found';
  END IF;
  IF v_complaint.status IN ('resolved','rejected','dismissed') THEN
    RAISE EXCEPTION 'Complaint is already closed';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.users
    WHERE id = p_admin_id AND role IN ('admin','owner')
  ) THEN
    RAISE EXCEPTION 'Assignee must be an admin';
  END IF;

  v_region := public._member_region_id(v_complaint.complainant_id);
  IF NOT public.has_permission('MEMBER_VIEW_COMPLAINTS', v_region) THEN
    RAISE EXCEPTION 'Not authorized for this complaint region';
  END IF;
  IF p_admin_id <> auth.uid()
     AND NOT public.is_admin_for_region(v_region) THEN
    RAISE EXCEPTION 'Assignee must be in scope for the complaint region';
  END IF;

  UPDATE public.complaints
     SET status = 'escalated',
         assigned_admin_id = p_admin_id,
         escalated_at = now(),
         escalated_from_admin_id = auth.uid(),
         updated_at = now()
   WHERE id = p_complaint_id;

  INSERT INTO public.escalation_events
    (entity_type, entity_id, from_admin_id, to_admin_id, actor_id, reason,
     previous_scope, new_scope)
  VALUES ('complaint', p_complaint_id,
          v_complaint.assigned_admin_id, p_admin_id, auth.uid(),
          'Assigned to admin',
          CASE WHEN v_complaint.assigned_admin_id IS NULL THEN 'unassigned'
               ELSE 'assigned' END,
          CASE WHEN EXISTS (SELECT 1 FROM public.users
                            WHERE id = p_admin_id AND role = 'owner')
               THEN 'owner' ELSE 'scoped' END);

  INSERT INTO public.member_events (user_id, event_type, payload)
  VALUES (v_complaint.complainant_id, 'complaint_assigned',
          jsonb_build_object('complaint_id', p_complaint_id::text,
                             'assigned_to', p_admin_id::text))
  ON CONFLICT DO NOTHING;

  INSERT INTO public.notifications
    (user_id, title, body, type, data, deep_link, idempotency_key,
     sender_id, priority, send_push)
  VALUES (
    p_admin_id,
    'Complaint assigned to you',
    'A complaint has been assigned to you for review.',
    'complaint_assigned',
    jsonb_build_object('entity_type', 'complaint',
                       'entity_id', p_complaint_id::text,
                       'action', 'assigned'),
    '/admin/complaints',
    'complaint-assigned-' || p_complaint_id::text || '-' || p_admin_id::text,
    auth.uid(), 'high', true
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  PERFORM public.write_audit(
    'COMPLAINT_ASSIGNED', 'complaints', p_complaint_id::text,
    jsonb_build_object('from_admin_id', auth.uid(),
                       'to_admin_id', p_admin_id)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.assign_order_manual(p_order_id uuid, p_driver_id uuid, p_admin_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order orders%ROWTYPE;
BEGIN
  IF NOT (public._is_owner_uid(auth.uid())
          OR public.admin_has_permission('DISPATCH_MANUAL', NULL)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_FOUND');
  END IF;
  IF v_order.dispatch_status <> 'PENDING_DISPATCH' OR v_order.driver_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'STALE');
  END IF;
  UPDATE public.orders
    SET driver_id = p_driver_id, dispatch_status = 'ASSIGNED', status = 'preparing'
    WHERE id = p_order_id;
  UPDATE public.order_dispatch
    SET status = 'accepted', candidate_driver_id = p_driver_id, assigned_by = p_admin_id, updated_at = now()
    WHERE order_id = p_order_id;
  PERFORM public.log_admin_action('DISPATCH_MANUAL', 'order', p_order_id::text,
    NULL, jsonb_build_object('driver', p_driver_id), p_reason, 'GLOBAL');
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.assign_support_chat(p_room_id uuid, p_admin_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_room public.chat_rooms%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT * INTO v_room FROM public.chat_rooms WHERE id = p_room_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Room not found';
  END IF;
  IF v_room.status = 'closed' THEN
    RAISE EXCEPTION 'Room is closed';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.users WHERE id = p_admin_id AND role IN ('admin','owner')
  ) THEN
    RAISE EXCEPTION 'Assignee must be an admin';
  END IF;

  PERFORM public._assign_chat_to_admin(p_room_id, p_admin_id, 'assigned');
  PERFORM public.write_audit(
    'SUPPORT_ASSIGNED', 'chat_rooms', p_room_id::text,
    jsonb_build_object(
      'admin_id', p_admin_id,
      'from_admin_id', auth.uid(),
      'manual', true,
      'priority', v_room.priority
    )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.auto_sync_product_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.merchant_id IS NOT NULL THEN
    INSERT INTO public.product_inventory (
      product_id,
      merchant_id,
      stock_quantity,
      reserved_quantity,
      low_stock_threshold,
      is_in_stock,
      updated_at
    )
    VALUES (
      NEW.id,
      NEW.merchant_id,
      COALESCE(NEW.stock_quantity, 50),
      0,
      5,
      COALESCE(NEW.is_available, true),
      now()
    )
    ON CONFLICT (product_id) DO UPDATE
      SET is_in_stock = COALESCE(NEW.is_available, true),
          updated_at = now();
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.calculate_commission(p_amount numeric, p_rate numeric)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT ROUND(COALESCE(p_amount, 0) * COALESCE(p_rate, 0) / 100.0, 2);
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_archive(p_campaign_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_campaign public.campaigns%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT * INTO v_campaign FROM public.campaigns c WHERE c.id = p_campaign_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;
  IF NOT public.campaign_targets_authorized(p_campaign_id) THEN
    RAISE EXCEPTION 'Not authorized for this campaign region scope';
  END IF;
  IF v_campaign.status NOT IN ('published','paused','expired','cancelled','rejected') THEN
    RAISE EXCEPTION 'Campaign cannot be archived from current state';
  END IF;
  UPDATE public.campaigns SET status = 'archived', archived_at = now()
  WHERE id = p_campaign_id;
  INSERT INTO public.campaign_reviews
    (campaign_id, reviewer_id, action, previous_state, new_state, reason)
  VALUES (p_campaign_id, auth.uid(), 'archive', v_campaign.status, 'archived', p_reason);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_cancel(p_campaign_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_campaign public.campaigns%ROWTYPE;
  v_is_creator boolean;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT * INTO v_campaign FROM public.campaigns c WHERE c.id = p_campaign_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;
  SELECT (v_campaign.proposed_by = auth.uid()) INTO v_is_creator;
  IF NOT v_is_creator AND NOT public.campaign_targets_authorized(p_campaign_id) THEN
    RAISE EXCEPTION 'Not authorized for this campaign';
  END IF;
  IF v_campaign.status NOT IN ('draft','pending_review','approved','scheduled') THEN
    RAISE EXCEPTION 'Campaign cannot be cancelled from current state';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'Cancellation requires a reason';
  END IF;
  UPDATE public.campaigns SET status = 'cancelled' WHERE id = p_campaign_id;
  INSERT INTO public.campaign_reviews
    (campaign_id, reviewer_id, action, previous_state, new_state, reason)
  VALUES (p_campaign_id, auth.uid(), 'cancel', v_campaign.status, 'cancelled', p_reason);
  UPDATE public.approval_requests
    SET state = 'cancelled', reason = COALESCE(reason, p_reason), decided_at = now()
  WHERE request_type = 'campaign_approve' AND entity_id = p_campaign_id AND state = 'pending';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_id_from_storage_path(p_name text)
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN (storage.foldername(p_name))[2] ~
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    THEN (storage.foldername(p_name))[2]::uuid
    ELSE NULL
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_pause(p_campaign_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_campaign public.campaigns%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT * INTO v_campaign FROM public.campaigns c WHERE c.id = p_campaign_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;
  IF NOT public.campaign_targets_authorized(p_campaign_id) THEN
    RAISE EXCEPTION 'Not authorized for this campaign region scope';
  END IF;
  IF v_campaign.status <> 'published' THEN
    RAISE EXCEPTION 'Only published campaigns can be paused';
  END IF;
  UPDATE public.campaigns SET status = 'paused' WHERE id = p_campaign_id;
  INSERT INTO public.campaign_reviews
    (campaign_id, reviewer_id, action, previous_state, new_state, reason)
  VALUES (p_campaign_id, auth.uid(), 'pause', 'published', 'paused', p_reason);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_publish(p_campaign_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_campaign public.campaigns%ROWTYPE;
  v_has_national boolean;
  v_is_owner boolean;
  v_scoped boolean;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT * INTO v_campaign FROM public.campaigns c WHERE c.id = p_campaign_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;
  IF NOT public.campaign_targets_authorized(p_campaign_id) THEN
    RAISE EXCEPTION 'Not authorized for this campaign region scope';
  END IF;
  IF v_campaign.status NOT IN ('approved','scheduled') THEN
    RAISE EXCEPTION 'Campaign must be approved or scheduled to publish';
  END IF;
  IF v_campaign.ends_at IS NOT NULL AND v_campaign.ends_at <= now() THEN
    RAISE EXCEPTION 'Campaign window has expired';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.campaign_targets t
    WHERE t.campaign_id = p_campaign_id AND t.region_id IS NULL
  ) INTO v_has_national;

  IF v_has_national THEN
    SELECT EXISTS (SELECT 1 FROM public.users u WHERE u.id = auth.uid() AND u.role = 'owner')
      INTO v_is_owner;
    SELECT EXISTS (
      SELECT 1 FROM public.admin_region_assignments a WHERE a.admin_id = auth.uid()
    ) INTO v_scoped;
    IF NOT v_is_owner AND v_scoped THEN
      RAISE EXCEPTION 'Only global authority can publish a national campaign';
    END IF;
  END IF;

  IF v_campaign.starts_at IS NOT NULL AND v_campaign.starts_at > now() THEN
    UPDATE public.campaigns SET status = 'scheduled' WHERE id = p_campaign_id;
    INSERT INTO public.campaign_reviews
      (campaign_id, reviewer_id, action, previous_state, new_state, reason)
    VALUES (p_campaign_id, auth.uid(), 'publish', v_campaign.status, 'scheduled', NULL);
    RETURN 'scheduled';
  ELSE
    UPDATE public.campaigns SET status = 'published', published_at = now()
    WHERE id = p_campaign_id;
    INSERT INTO public.campaign_reviews
      (campaign_id, reviewer_id, action, previous_state, new_state, reason)
    VALUES (p_campaign_id, auth.uid(), 'publish', v_campaign.status, 'published', NULL);
    RETURN 'published';
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_purge_media(p_campaign_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.campaigns c
    WHERE c.id = p_campaign_id
      AND c.status IN ('archived','cancelled','rejected')
  ) THEN
    RAISE EXCEPTION 'Campaign must be in a terminal state to purge media';
  END IF;
  -- storage.protect_delete() blocks direct SQL DELETE unless the GUC is set.
  PERFORM set_config('storage.allow_delete_query', 'true', true);
  DELETE FROM storage.objects
  WHERE bucket_id = 'campaign-media'
    AND public.campaign_id_from_storage_path(name) = p_campaign_id;
  PERFORM set_config('storage.allow_delete_query', 'false', true);
  UPDATE public.campaign_media SET is_active = false WHERE campaign_id = p_campaign_id;
  UPDATE public.campaign_banners SET is_active = false WHERE campaign_id = p_campaign_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_resume(p_campaign_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_campaign public.campaigns%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT * INTO v_campaign FROM public.campaigns c WHERE c.id = p_campaign_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;
  IF NOT public.campaign_targets_authorized(p_campaign_id) THEN
    RAISE EXCEPTION 'Not authorized for this campaign region scope';
  END IF;
  IF v_campaign.status <> 'paused' THEN
    RAISE EXCEPTION 'Only paused campaigns can be resumed';
  END IF;
  IF v_campaign.ends_at IS NOT NULL AND v_campaign.ends_at <= now() THEN
    RAISE EXCEPTION 'Campaign window has expired';
  END IF;
  UPDATE public.campaigns SET status = 'published', published_at = now()
  WHERE id = p_campaign_id;
  INSERT INTO public.campaign_reviews
    (campaign_id, reviewer_id, action, previous_state, new_state, reason)
  VALUES (p_campaign_id, auth.uid(), 'resume', 'paused', 'published', NULL);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_submit(p_campaign_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_campaign public.campaigns%ROWTYPE;
  v_request_id uuid;
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_owner_provider boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_campaign FROM public.campaigns c WHERE c.id = p_campaign_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;

  v_is_admin := public.is_admin();
  v_is_owner_provider := (
    v_campaign.created_by = v_uid
    AND (
      EXISTS (SELECT 1 FROM public.merchants m WHERE m.owner_user_id = v_uid)
      OR EXISTS (SELECT 1 FROM public.merchant_profiles mp WHERE mp.user_id = v_uid)
      OR EXISTS (SELECT 1 FROM public.service_providers sp WHERE sp.user_id = v_uid)
    )
  );

  IF NOT v_is_admin AND NOT v_is_owner_provider THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF v_is_admin AND NOT public.campaign_targets_authorized(p_campaign_id) THEN
    RAISE EXCEPTION 'Not authorized for this campaign region scope';
  END IF;

  IF v_campaign.status NOT IN ('draft','rejected') THEN
    RAISE EXCEPTION 'Only draft or rejected campaigns can be submitted';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.campaign_targets t WHERE t.campaign_id = p_campaign_id
  ) THEN
    RAISE EXCEPTION 'Campaign must have at least one targeting region';
  END IF;

  IF NOT public.campaign_validate_benefit(v_campaign.benefit) THEN
    RAISE EXCEPTION 'Invalid campaign benefit';
  END IF;

  IF NOT public.campaign_validate_target_roles(v_campaign.target_roles) THEN
    RAISE EXCEPTION 'Invalid campaign audience roles';
  END IF;

  IF v_campaign.status = 'rejected' THEN
    UPDATE public.campaigns SET status = 'draft' WHERE id = p_campaign_id;
  END IF;

  INSERT INTO public.campaign_reviews
    (campaign_id, reviewer_id, action, previous_state, new_state, reason)
  VALUES (
    p_campaign_id, v_uid, 'submit',
    v_campaign.status, 'pending_review', p_reason
  );

  UPDATE public.campaigns SET status = 'pending_review' WHERE id = p_campaign_id;

  INSERT INTO public.approval_requests
    (request_type, entity_type, entity_id, payload, requested_by, required_approver)
  VALUES (
    'campaign_approve', 'campaign', p_campaign_id,
    jsonb_build_object(
      'campaign_id', p_campaign_id,
      'code', v_campaign.code,
      'name_ar', v_campaign.name_ar,
      'name_en', v_campaign.name_en,
      'campaign_type', v_campaign.campaign_type,
      'priority', v_campaign.priority,
      'reason', p_reason,
      'targets', COALESCE((
        SELECT jsonb_agg(t.region_id ORDER BY t.created_at)
        FROM public.campaign_targets t WHERE t.campaign_id = p_campaign_id
      ), '[]'::jsonb)
    ),
    v_uid,
    NULL
  )
  RETURNING id INTO v_request_id;

  RETURN v_request_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_validate_benefit(p_benefit jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_kind text;
  v_code text;
  v_coupon_id uuid;
  v_promo_code_id uuid;
  v_offer_id uuid;
  v_free_delivery_enabled boolean;
BEGIN
  IF p_benefit IS NULL THEN
    RETURN true;
  END IF;
  v_kind := p_benefit ->> 'kind';
  IF v_kind IS NULL OR v_kind NOT IN
       ('none','coupon','promo_code','offer','code_copy','free_delivery') THEN
    RETURN false;
  END IF;
  IF v_kind = 'none' THEN
    RETURN true;
  END IF;
  IF v_kind = 'coupon' THEN
    BEGIN
      v_coupon_id := (p_benefit ->> 'coupon_id')::uuid;
    EXCEPTION WHEN others THEN
      RETURN false;
    END;
    RETURN EXISTS (SELECT 1 FROM public.coupons c WHERE c.id = v_coupon_id);
  END IF;
  IF v_kind = 'promo_code' THEN
    BEGIN
      v_promo_code_id := (p_benefit ->> 'promo_code_id')::uuid;
    EXCEPTION WHEN others THEN
      RETURN false;
    END;
    RETURN EXISTS (SELECT 1 FROM public.promo_codes p WHERE p.id = v_promo_code_id);
  END IF;
  IF v_kind = 'offer' THEN
    BEGIN
      v_offer_id := (p_benefit ->> 'offer_id')::uuid;
    EXCEPTION WHEN others THEN
      RETURN false;
    END;
    RETURN EXISTS (SELECT 1 FROM public.offers o WHERE o.id = v_offer_id);
  END IF;
  IF v_kind = 'code_copy' THEN
    v_code := p_benefit ->> 'code';
    RETURN v_code IS NOT NULL AND v_code ~ '^[A-Za-z0-9_-]{1,64}$';
  END IF;
  IF v_kind = 'free_delivery' THEN
    SELECT (to_jsonb(ps) #>> '{promotions,free_delivery_enabled}') = 'true'
      INTO v_free_delivery_enabled
      FROM public.platform_settings ps
      WHERE ps.id = 'default';
    RETURN COALESCE(v_free_delivery_enabled, false);
  END IF;
  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_validate_cta(p_cta jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_type text;
  v_route text;
  v_entity_type text;
  v_entity_id text;
  v_url text;
  v_code text;
BEGIN
  IF p_cta IS NULL THEN
    RETURN true;
  END IF;
  v_type := p_cta ->> 'type';
  IF v_type IS NULL OR v_type NOT IN
       ('none','internal_route','entity','external_url','copy_code') THEN
    RETURN false;
  END IF;
  IF v_type = 'none' THEN
    RETURN true;
  END IF;
  v_route := p_cta ->> 'route';
  v_entity_type := p_cta ->> 'entity_type';
  v_entity_id := p_cta ->> 'entity_id';
  v_url := p_cta ->> 'url';
  v_code := p_cta ->> 'code';
  IF v_type = 'internal_route' THEN
    RETURN v_route IS NOT NULL
      AND EXISTS (SELECT 1 FROM public.campaign_cta_routes r
                  WHERE r.route = v_route);
  END IF;
  IF v_type = 'entity' THEN
    RETURN v_entity_type IN ('merchant','product','service','category','campaign')
      AND v_entity_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  END IF;
  IF v_type = 'external_url' THEN
    RETURN v_url IS NOT NULL
      AND (v_url ~* '^https?://[A-Za-z0-9._-]+')
      AND v_url !~* '(^|[^A-Za-z0-9])javascript:|(^|[^A-Za-z0-9])data:|(^|[^A-Za-z0-9])file:|vbscript:'
      AND v_url !~ '[[:space:]]';
  END IF;
  IF v_type = 'copy_code' THEN
    RETURN v_code IS NOT NULL
      AND v_code ~ '^[A-Za-z0-9_-]{1,64}$';
  END IF;
  RETURN false;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_validate_priority(p_campaign_type text, p_priority text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN p_campaign_type IN ('emergency_notice','safety_notice')
      THEN p_priority = 'critical'
    ELSE p_priority IN ('normal','important','critical')
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_validate_target_roles(p_roles text[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_roles IS NULL OR p_roles <@
         ARRAY['customer','merchant','driver','admin','owner','provider','delivery']::text[];
$function$
;
CREATE OR REPLACE FUNCTION public.campaigns_guard_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
      IF NOT (
        OLD.created_by = auth.uid()
        AND OLD.status IN ('draft','rejected')
        AND NEW.status IN ('draft','pending_review')
        AND (
          EXISTS (SELECT 1 FROM public.merchants m WHERE m.owner_user_id = auth.uid())
          OR EXISTS (SELECT 1 FROM public.merchant_profiles mp WHERE mp.user_id = auth.uid())
          OR EXISTS (SELECT 1 FROM public.service_providers sp WHERE sp.user_id = auth.uid())
        )
      ) THEN
        RAISE EXCEPTION 'Not authorized';
      END IF;
    END IF;
    IF NOT (OLD.status, NEW.status) IN (
      ('draft','pending_review'),('draft','cancelled'),('draft','archived'),
      ('pending_review','approved'),('pending_review','rejected'),
      ('pending_review','cancelled'),
      ('approved','scheduled'),('approved','published'),('approved','cancelled'),
      ('rejected','draft'),('rejected','archived'),
      ('scheduled','published'),('scheduled','cancelled'),
      ('published','paused'),('published','expired'),('published','archived'),
      ('paused','published'),('paused','archived'),
      ('expired','archived'),
      ('cancelled','draft'),('cancelled','archived')
    ) THEN
      RAISE EXCEPTION 'Invalid campaign status transition % -> %',
        OLD.status, NEW.status;
    END IF;
    IF NEW.status = 'published' AND NEW.published_at IS NULL THEN
      NEW.published_at := now();
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.campaigns_set_creator()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.status := 'draft';
    NEW.created_by := COALESCE(NEW.created_by, auth.uid());
    NEW.proposed_by := COALESCE(NEW.proposed_by, auth.uid());
  ELSE
    IF auth.uid() IS NOT NULL THEN
      NEW.updated_by := auth.uid();
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.cancel_delivery(p_delivery_id uuid, p_reason text DEFAULT NULL::text, p_actor_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN public.cancel_ride_lifecycle(p_delivery_id, p_actor_role, p_reason);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.cancel_order(p_order_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_uid uuid := auth.uid();
  v_suspend_after boolean := false;
  v_refunded boolean := false;
  v_actor uuid;
  v_driver_uid uuid;
  v_merchant_uid uuid;
  v_short text;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.id is null then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  end if;

  if v_order.user_id is distinct from v_uid and not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;

  if v_order.status in ('delivered', 'cancelled') then
    return jsonb_build_object('ok', false, 'code', 'NOT_CANCELLABLE', 'status', v_order.status);
  end if;

  -- Customer self-cancel policy (owner-confirmed 2026-11-21, mig 185):
  -- no solo-cancel once the order is out for delivery, and a MONTHLY
  -- allowance of 2 customer cancels (calendar month, UTC; further cancels
  -- go through merchant/support).
  if v_uid = v_order.user_id and not public.is_admin() then
    if v_order.status = 'delivering' then
      return jsonb_build_object('ok', false, 'code', 'OUT_FOR_DELIVERY', 'status', v_order.status);
    end if;
    -- 188: the 3rd monthly cancel EXECUTES and triggers a 5-day suspension
    -- (appealable); it is no longer blocked.
    if (select count(*) from public.orders
         where user_id = v_uid and cancelled_by = 'customer'
           and cancelled_at >= date_trunc('month', now() at time zone 'Africa/Cairo') at time zone 'Africa/Cairo') >= 2 then
      v_suspend_after := true;
    end if;
  end if;

  -- 194: shared finalizer owns stock/coupon/refund/order+ride cancellation.
  v_refunded := v_order.payment_status = 'paid';
  perform public._finalize_order_cancel(
    p_order_id,
    case when v_uid = v_order.user_id then 'customer' else 'admin' end,
    coalesce(p_reason, v_order.cancelled_reason, 'Order cancelled'),
    true, true, true,
    case when v_uid is distinct from v_order.user_id then 'system' else 'rider' end);

  -- Notify the assigned driver: stop heading to pickup.
  if v_order.driver_id is not null then
    select user_id into v_driver_uid from public.drivers where id = v_order.driver_id;
    if v_driver_uid is not null then
      insert into public.notifications (user_id, title, body, type, data, send_push)
      values (v_driver_uid,
              'تم إلغاء الطلب',
              'ألغى العميل الطلب. لا تتوجه للاستلام.',
              'order',
              jsonb_build_object('order_id', v_order.id, 'status', 'cancelled',
                                 'reason', p_reason),
              true);
    end if;
  end if;

  -- Notify the merchant owner.
  if v_order.merchant_id is not null then
    select owner_user_id into v_merchant_uid from public.merchants where id = v_order.merchant_id;
    if v_merchant_uid is not null then
      v_short := right(v_order.id::text, 6);
      insert into public.notifications (user_id, title, body, type, data, send_push)
      values (v_merchant_uid,
              'تم إلغاء طلب',
              'ألغى العميل الطلب رقم ' || v_short || '.',
              'order',
              jsonb_build_object('order_id', v_order.id, 'status', 'cancelled',
                                 'reason', p_reason),
              true);
    end if;
  end if;

  -- 188: suspension after the 3rd monthly cancel (moderation engine owns
  -- account_status; appeal via submit_appeal routes to the region duty admin).
  if v_suspend_after then
    v_actor := coalesce(
      (select id from public.users where role = 'owner' order by created_at limit 1),
      v_order.user_id);
    perform public._member_exec_sanction(
      v_actor, v_order.user_id, 'suspension',
      'تجاوز سماحية الإلغاء الشهرية (إلغاء ثالث خلال شهر واحد)', 5);
    insert into public.notifications (user_id, title, body, type, data, send_push)
    values (v_order.user_id,
            'تم إيقاف حسابك 5 أيام',
            'تم تنفيذ إلغاء الطلب، لكن ده ثالث إلغاء ليك هذا الشهر (السماحية: 2). اتوقف حسابك 5 أيام. لو عندك ظرف، قدّم التماس من التطبيق والمسؤول عن منطقتك هيراجعه.',
            'account',
            jsonb_build_object('event', 'cancel_suspension', 'order_id', v_order.id,
                               'duration_days', 5),
            true);
    return jsonb_build_object('ok', true, 'code', 'OK', 'status', 'cancelled',
                              'refunded', v_refunded, 'suspended', true,
                              'suspension_days', 5);
  end if;

  return jsonb_build_object('ok', true, 'code', 'OK', 'status', 'cancelled', 'refunded', v_refunded);
end;


$function$
;
CREATE OR REPLACE FUNCTION public.cancel_ride_lifecycle(p_ride_id uuid, p_by text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r rides%ROWTYPE;
  v_is_rider BOOLEAN;
  v_is_driver BOOLEAN;
  v_driver_id uuid;
  v_dispatch jsonb;
  v_offered boolean;
  v_cancel jsonb;
BEGIN
  SELECT * INTO r FROM rides WHERE id = p_ride_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_found');
  END IF;
  v_is_rider := (r.rider_id = auth.uid());
  SELECT id INTO v_driver_id FROM drivers WHERE user_id = auth.uid() AND id = r.driver_id;
  v_is_driver := (v_driver_id IS NOT NULL);
  IF auth.uid() IS NULL OR NOT (COALESCE(v_is_rider,false) OR COALESCE(v_is_driver,false)) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;
  IF r.status IN ('completed','cancelled') THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invalid_transition');
  END IF;

  -- Goods are physically with the driver: a plain cancellation would erase
  -- custody. This is an incident, not a cancel.
  IF r.status = 'inTrip' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'in_custody');
  END IF;

  -- Driver backs out before pickup: keep the customer's delivery alive and
  -- re-offer it to other drivers automatically.
  IF v_is_driver AND r.status IN ('matched','arrived') THEN
    UPDATE ride_requests SET status = 'cancelled', responded_at = NOW()
      WHERE ride_id = p_ride_id AND driver_id = v_driver_id AND status = 'accepted';
    UPDATE ride_requests SET status = 'expired', responded_at = NOW()
      WHERE ride_id = p_ride_id AND status = 'offered';
    UPDATE driver_locations SET ride_id = NULL WHERE ride_id = p_ride_id;
    UPDATE rides SET status = 'searching', driver_id = NULL,
      cancellation_reason = p_reason, cancelled_by = 'driver'
      WHERE id = p_ride_id;
    INSERT INTO trip_events (ride_id, event_type, actor)
      VALUES (p_ride_id, 'driver_cancelled_redispatch', 'driver');

    v_dispatch := public._dispatch_delivery_internal(p_ride_id, 25.0, 15);
    v_offered := COALESCE((v_dispatch->>'success')::boolean, false);

    UPDATE public.orders
       SET driver_id = NULL,
           dispatch_status = CASE WHEN v_offered THEN 'OFFERED' ELSE 'PENDING_DISPATCH' END,
           updated_at = now()
     WHERE id = r.order_id
       AND status NOT IN ('cancelled','delivered');

    RETURN jsonb_build_object('success', true, 'status', 'redispatching',
      'offered', v_offered,
      'dispatch_reason', v_dispatch->>'reason');
  END IF;

  -- 194: a customer (rider) cancel with a linked order goes through
  -- cancel_order so the monthly ladder, finalization and notifications all
  -- fire exactly as on the orders screen. cancel_order's finalizer also
  -- cancels this ride (same order_id), so only the peripheral cleanup stays.
  IF v_is_rider AND r.order_id IS NOT NULL THEN
    v_cancel := public.cancel_order(r.order_id, p_reason);
    IF NOT COALESCE((v_cancel->>'ok')::boolean, false) THEN
      RETURN jsonb_build_object('success', false,
        'reason', lower(coalesce(v_cancel->>'code', 'cancel_failed')),
        'detail', v_cancel);
    END IF;
    UPDATE ride_requests SET status = 'expired', responded_at = NOW()
      WHERE ride_id = p_ride_id AND status = 'offered';
    UPDATE driver_locations SET ride_id = NULL WHERE ride_id = p_ride_id;
    INSERT INTO trip_events (ride_id, event_type, actor)
      VALUES (p_ride_id, 'cancelled', 'rider');
    RETURN jsonb_build_object('success', true, 'status', 'cancelled');
  END IF;

  UPDATE rides SET status = 'cancelled', cancelled_at = NOW(),
    cancellation_reason = p_reason,
    cancelled_by = CASE WHEN v_is_driver THEN 'driver' ELSE 'rider' END
  WHERE id = p_ride_id;

  UPDATE ride_requests SET status = 'expired', responded_at = NOW()
    WHERE ride_id = p_ride_id AND status = 'offered';
  UPDATE driver_locations SET ride_id = NULL WHERE ride_id = p_ride_id;

  INSERT INTO trip_events (ride_id, event_type, actor)
    VALUES (p_ride_id, 'cancelled', CASE WHEN v_is_driver THEN 'driver' ELSE 'rider' END);
  RETURN jsonb_build_object('success', true, 'status', 'cancelled');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.chat_ensure_room_active()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_active boolean;
BEGIN
  SELECT is_active INTO v_active
    FROM public.chat_rooms
   WHERE id = NEW.room_id;
  IF v_active IS FALSE THEN
    RAISE EXCEPTION 'chat room is closed';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.chat_room_origin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_role text;
  v_label text;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    v_uid := NEW.participant_ids[1];
  END IF;

  SELECT role INTO v_role FROM public.users WHERE id = v_uid;

  CASE
    WHEN v_role IN ('admin', 'owner') THEN NEW.origin_type := 'admin';
    WHEN v_role IN ('driver', 'delivery') THEN NEW.origin_type := 'driver';
    WHEN v_role IN ('provider', 'merchant') THEN NEW.origin_type := 'provider';
    ELSE NEW.origin_type := 'customer';
  END CASE;

  IF NEW.origin_type = 'provider' THEN
    v_label := NULL;
    SELECT category_type INTO v_label
      FROM public.service_providers
      WHERE user_id = v_uid
      ORDER BY created_at
      LIMIT 1;
    IF v_label IS NULL THEN
      SELECT type INTO v_label
        FROM public.merchants
        WHERE owner_user_id = v_uid
        ORDER BY created_at
        LIMIT 1;
    END IF;
    NEW.origin_label := v_label;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.chat_rooms_auto_route()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_admin_id uuid;
BEGIN
  IF NEW.priority = 'emergency' OR NEW.status = 'closed' THEN
    RETURN NEW;
  END IF;
  IF NEW.assigned_admin_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  v_admin_id := public.resolve_support_admin(NEW.region_id, true);
  IF v_admin_id IS NOT NULL THEN
    PERFORM public._assign_chat_to_admin(NEW.id, v_admin_id, 'assigned');
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.chat_rooms_fixup_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- SECURITY DEFINER RPC context (current_user = owner, session_user = caller)
  -- is trusted: RPCs validate server-side. Direct client writes by non-admins
  -- are forced to the safe default contract.
  IF current_user IS DISTINCT FROM session_user THEN
    RETURN NEW;
  END IF;
  IF NOT public.is_admin() THEN
    NEW.priority := 'low';
    NEW.status := 'open';
    NEW.assigned_admin_id := NULL;
    NEW.assigned_at := NULL;
    NEW.escalated_at := NULL;
    NEW.escalated_from_admin_id := NULL;
    NEW.closed_at := NULL;
  END IF;
  IF NEW.region_id IS NULL THEN
    SELECT region_id INTO NEW.region_id
    FROM public.user_region_preferences
    WHERE user_id = auth.uid()
    ORDER BY updated_at DESC
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.chat_rooms_fixup_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_user IS DISTINCT FROM session_user THEN
    RETURN NEW;
  END IF;
  IF NOT public.is_admin() THEN
    NEW.priority := OLD.priority;
    NEW.status := OLD.status;
    NEW.assigned_admin_id := OLD.assigned_admin_id;
    NEW.assigned_at := OLD.assigned_at;
    NEW.escalated_at := OLD.escalated_at;
    NEW.escalated_from_admin_id := OLD.escalated_from_admin_id;
    NEW.closed_at := OLD.closed_at;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.chat_set_call_status(p_message_id uuid, p_status text, p_responder_id uuid DEFAULT NULL::uuid, p_responder_type text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_room_id uuid;
  v_participants uuid[];
BEGIN
  SELECT room_id, (SELECT cr.participant_ids FROM public.chat_rooms cr WHERE cr.id = m.room_id)
    INTO v_room_id, v_participants
  FROM public.chat_messages m
  WHERE m.id = p_message_id;

  IF v_room_id IS NULL THEN
    RAISE EXCEPTION 'message not found';
  END IF;

  -- Caller must be a participant of the room (or an admin/owner).
  IF NOT (p_responder_id IS NOT NULL
          AND (auth.uid() = ANY(v_participants)
               OR (SELECT role FROM public.users WHERE id = auth.uid()) IN ('admin', 'owner'))) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE public.chat_messages
  SET meta_data = COALESCE(meta_data, '{}'::jsonb)
                  || jsonb_build_object(
                       'status', p_status,
                       'responder_id', p_responder_id,
                       'responder_type', p_responder_type,
                       'responded_at', now()::text
                     )
  WHERE id = p_message_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.cleanup_invalid_token(p_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_user NOT IN ('service_role','postgres') THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_token IS NULL OR btrim(p_token) = '' THEN
    RETURN;
  END IF;

  UPDATE public.notification_tokens
     SET is_active = false,
         last_seen_at = now(),
         updated_at = now()
   WHERE token = p_token;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.close_support_chat(p_room_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_admin    uuid := auth.uid();
  v_customer uuid;
  v_room     public.chat_rooms%ROWTYPE;
BEGIN
  SELECT * INTO v_room FROM public.chat_rooms WHERE id = p_room_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Room not found';
  END IF;

  IF NOT (public.is_admin()
          OR v_admin = ANY (v_room.participant_ids)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT cp.user_id INTO v_customer
    FROM public.chat_participants cp
   WHERE cp.room_id = p_room_id
     AND cp.user_id != v_admin
     AND cp.role = 'customer'
   LIMIT 1;

  UPDATE public.chat_rooms
     SET status = 'closed', closed_at = now(), is_active = false
   WHERE id = p_room_id;

  PERFORM public.write_audit(
    'SUPPORT_CLOSED', 'chat_rooms', p_room_id::text,
    jsonb_build_object('priority', v_room.priority, 'assigned_admin_id', v_room.assigned_admin_id)
  );

  IF v_customer IS NOT NULL THEN
    INSERT INTO public.notifications
      (user_id, title, body, type, data, deep_link, idempotency_key,
       sender_id, priority, send_push)
    VALUES
      (v_customer,
       'Chat Closed',
       'Your support chat has been closed. If you need further help, open a new chat.',
       'chat_closed',
       jsonb_build_object('entity_type', 'chat_room', 'entity_id', p_room_id::text, 'action', 'closed'),
       '/support/room/' || p_room_id::text,
       'chat-closed-' || p_room_id::text || '-' || v_customer::text,
       v_admin, 'normal', true)
    ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

    INSERT INTO public.member_events (user_id, event_type, payload)
    VALUES (v_customer, 'support_resolved',
            jsonb_build_object('room_id', p_room_id::text, 'closed_by', 'admin'))
    ON CONFLICT DO NOTHING;
  END IF;

  INSERT INTO public.member_events (user_id, event_type, payload)
  VALUES (v_admin, 'support_resolved',
          jsonb_build_object('room_id', p_room_id::text, 'customer_id', v_customer::text))
  ON CONFLICT DO NOTHING;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaints_fixup_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Server-origin proof: admins, no-JWT calls (service_role/cron), or the
  -- escalation-RPC marker set by the SECURITY DEFINER engine RPCs.
  -- IMPORTANT: do NOT use `current_user IS DISTINCT FROM session_user` here.
  -- Supabase's PostgREST pooler always runs with session_user='authenticator'
  -- and SET LOCAL ROLE, so that test is TRUE for every client write and would
  -- trust forged inserts/updates (verified live). The marker is transaction-
  -- local and set ONLY by escalate_complaint/assign_complaint -> unspoofable.
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  IF current_setting('app.escalation_rpc', true) = 'true' THEN
    RETURN NEW;
  END IF;
  NEW.status := 'pending';
  NEW.priority := 'medium';
  NEW.assigned_admin_id := NULL;
  NEW.escalated_at := NULL;
  NEW.escalated_from_admin_id := NULL;
  NEW.resolved_at := NULL;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaints_fixup_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- See complaints_fixup_insert for why the marker (not the session-role
  -- discriminator) is the correct server-origin proof under PostgREST.
  -- RPC-origin marker: set_config('app.escalation_rpc','true',true) inside the
  -- SECURITY DEFINER engine RPCs (escalate/assign). PostgREST clients cannot
  -- set this via table CRUD, so it is unspoofable proof of RPC origin.
  IF current_setting('app.escalation_rpc', true) = 'true' THEN
    RETURN NEW;
  END IF;
  -- No-JWT server calls (service_role / cron / edge worker / operational tooling).
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  IF NOT public.is_admin() THEN
    NEW.status := OLD.status;
    NEW.priority := OLD.priority;
    NEW.assigned_admin_id := OLD.assigned_admin_id;
    NEW.escalated_at := OLD.escalated_at;
    NEW.escalated_from_admin_id := OLD.escalated_from_admin_id;
    NEW.resolved_at := OLD.resolved_at;
    RETURN NEW;
  END IF;

  -- Admin direct client writes: any status transition is allowed EXCEPT the
  -- RPC-only ones (escalated status / assignment fields).
  IF NEW.status = 'escalated' AND NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'Complaint must be escalated via escalate_complaint()';
  END IF;
  IF NEW.assigned_admin_id IS DISTINCT FROM OLD.assigned_admin_id
     OR NEW.escalated_at IS DISTINCT FROM OLD.escalated_at
     OR NEW.escalated_from_admin_id IS DISTINCT FROM OLD.escalated_from_admin_id THEN
    RAISE EXCEPTION 'Complaint assignment fields are managed by the escalation RPCs';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complaints_guard_admin_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status
     OR NEW.priority IS DISTINCT FROM OLD.priority
     OR NEW.admin_notes IS DISTINCT FROM OLD.admin_notes
     OR NEW.resolution_note IS DISTINCT FROM OLD.resolution_note
     OR NEW.resolved_at IS DISTINCT FROM OLD.resolved_at
     OR NEW.assigned_admin_id IS DISTINCT FROM OLD.assigned_admin_id
     OR NEW.escalated_at IS DISTINCT FROM OLD.escalated_at
     OR NEW.escalated_from_admin_id IS DISTINCT FROM OLD.escalated_from_admin_id
     OR NEW.complainant_id IS DISTINCT FROM OLD.complainant_id
     OR NEW.respondent_id IS DISTINCT FROM OLD.respondent_id
     OR NEW.reporter_id IS DISTINCT FROM OLD.reporter_id
     OR NEW.order_id IS DISTINCT FROM OLD.order_id
     OR NEW.ride_id IS DISTINCT FROM OLD.ride_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'complaint handling fields are managed by the admin team';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complete_delivery(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$

DECLARE
  v_uid     uuid := auth.uid();
  v_order   orders%ROWTYPE;
  v_is_driver boolean;
  v_driver_uid uuid;
  v_rate      numeric;
  v_commission numeric;
  v_net       numeric;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL OR v_order.driver_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_ASSIGNED');
  END IF;
  IF v_order.status = 'delivered' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'ALREADY_DONE');
  END IF;

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'UNAUTHENTICATED');
  END IF;

  v_is_driver := EXISTS (
    SELECT 1 FROM public.drivers d
     WHERE d.user_id = v_uid AND d.id = v_order.driver_id
  );

  IF NOT v_is_driver AND NOT public._is_owner_uid(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'FORBIDDEN');
  END IF;

  IF EXISTS(SELECT 1 FROM public.rides WHERE order_id=p_order_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','USE_ASSIGNED_DELIVERY_FLOW');
  END IF;

  -- Retired surface: the old split below credits the driver with the goods
  -- money and records nothing for the merchant. Only the owner may still run
  -- it, pending removal once no-ride assignments are gone.
  IF NOT public._is_owner_uid(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'LEGACY_RETIRED');
  END IF;

  -- Canonical identity mapping: driver_earnings.driver_id -> drivers.id;
  -- platform_commissions.member_id -> users.id (drivers.user_id).
  SELECT user_id INTO v_driver_uid
    FROM public.drivers WHERE id = v_order.driver_id;

  SELECT COALESCE(public.get_commission_rate('driver'::text, NULL::text, v_driver_uid), 0)
    INTO v_rate;
  v_rate := COALESCE(v_rate, 0);
  v_commission := (COALESCE(v_order.total_amount, 0) * v_rate / 100.0);
  v_net := COALESCE(v_order.total_amount, 0) - v_commission;

  INSERT INTO public.driver_earnings (driver_id, ride_id, type, amount, currency, description)
  VALUES (v_order.driver_id, NULL, 'trip', v_net, 'EGP', 'Order ' || p_order_id::text || ' delivery earning');

  INSERT INTO public.platform_commissions (member_id, reference_type, reference_id, gross_amount, commission_rate, commission_amount, net_amount, currency, status)
  VALUES (v_driver_uid, 'order', p_order_id, v_order.total_amount, v_rate, v_commission, v_net, 'EGP', 'computed');

  UPDATE public.orders SET status = 'delivered', dispatch_status = 'ACCEPTED'
    WHERE id = p_order_id;

  PERFORM public.log_admin_action('DELIVERY_COMPLETE', 'order', p_order_id::text,
    NULL, jsonb_build_object('commission', v_commission, 'rate', v_rate), NULL, 'GLOBAL');
  RETURN jsonb_build_object('ok', true, 'commission', v_commission, 'rate', v_rate);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complete_delivery(p_ride_id uuid, p_driver_id uuid, p_proof_url text DEFAULT NULL::text, p_final_distance numeric DEFAULT NULL::numeric, p_recipient_otp text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.rides%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.drivers WHERE id=p_driver_id AND user_id=auth.uid()) THEN
   RETURN jsonb_build_object('success',false,'reason','forbidden');
 END IF;
 SELECT * INTO r FROM public.rides WHERE id=p_ride_id FOR UPDATE;
 IF NOT FOUND OR r.driver_id IS DISTINCT FROM p_driver_id THEN
   RETURN jsonb_build_object('success',false,'reason','not_your_delivery');
 END IF;
 IF r.service_type='ride' OR r.status IS DISTINCT FROM 'inTrip' THEN
   RETURN jsonb_build_object('success',false,'reason','invalid_transition');
 END IF;
 IF NOT public._verify_delivery_handoff(p_ride_id,'dropoff',p_recipient_otp) THEN
   RETURN jsonb_build_object('success',false,'reason','INVALID_OR_LOCKED_RECIPIENT_CODE');
 END IF;
 UPDATE public.rides SET status='completed',completed_at=now(),delivered_at=now(),
   delivery_proof_url=COALESCE(p_proof_url,delivery_proof_url) WHERE id=p_ride_id;
 UPDATE public.driver_locations SET ride_id=NULL WHERE driver_id=p_driver_id AND ride_id=p_ride_id;
 INSERT INTO public.trip_events(ride_id,event_type,actor) VALUES(p_ride_id,'delivered','driver');
 PERFORM public._record_delivery_earnings(p_ride_id);
 RETURN jsonb_build_object('success',true,'ride_id',p_ride_id,'fare',r.fare);
END; $function$
;
CREATE OR REPLACE FUNCTION public.complete_delivery_for_driver(p_delivery_id uuid, p_driver_id uuid, p_proof_url text DEFAULT NULL::text, p_final_distance numeric DEFAULT NULL::numeric, p_recipient_otp text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN public.complete_delivery(p_delivery_id, p_driver_id, p_proof_url, p_final_distance, p_recipient_otp);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.complete_driver_onboarding(p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d public.drivers%ROWTYPE;
BEGIN
 SELECT * INTO d FROM public.drivers WHERE id=p_driver_id FOR UPDATE;
 IF auth.uid() IS NULL OR d.user_id IS DISTINCT FROM auth.uid() THEN
  RETURN jsonb_build_object('success',false,'reason','FORBIDDEN');
 END IF;
 IF NOT public.driver_application_documents_ready(p_driver_id) THEN
  RETURN jsonb_build_object('success',false,'reason','REQUIRED_DOCUMENTS_MISSING');
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.vehicles WHERE driver_id=p_driver_id AND is_active=true) THEN
  RETURN jsonb_build_object('success',false,'reason','ACTIVE_VEHICLE_REQUIRED');
 END IF;
 UPDATE public.drivers SET onboarding_completed=true,onboarding_step=5,
   verification_status=CASE WHEN is_verified THEN verification_status ELSE 'pending' END,
   updated_at=now() WHERE id=p_driver_id;
 RETURN jsonb_build_object('success',true);
END; $function$
;
CREATE OR REPLACE FUNCTION public.confirm_cash_collection(p_reference_type cash_ref_type, p_reference_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  DECLARE
  v_uid uuid := auth.uid();
  v_is_owner boolean;
  v_is_driver boolean;
  v_is_provider uuid;
  v_provider_user uuid;
  v_status text;
  v_pay_status text;
  v_pay_method text;
  v_amount numeric;
  v_driver_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  IF p_reference_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_REFERENCE');
  END IF;

  v_is_owner := public._is_owner_uid(v_uid);

  -- ── ORDER (commerce) ────────────────────────────────────────────
  IF p_reference_type = 'order'::public.cash_ref_type THEN
    SELECT status, payment_status, payment_method, driver_id
      INTO v_status, v_pay_status, v_pay_method, v_driver_id
      FROM public.orders
     WHERE id = p_reference_id
     FOR UPDATE;
    IF v_status IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
    END IF;

    IF v_pay_status = 'paid' THEN
      RETURN jsonb_build_object('ok', true, 'code', 'ALREADY_COLLECTED', 'reference_id', p_reference_id);
    END IF;
    IF v_pay_status NOT IN ('unpaid', 'pending') THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATUS', 'current_status', v_pay_status);
    END IF;
    IF v_pay_method <> 'cash' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NOT_CASH');
    END IF;

    IF NOT v_is_owner AND v_status NOT IN ('delivering', 'delivered') THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_LIFECYCLE', 'current_status', v_status);
    END IF;

    -- Authorization: the physically assigned driver (their driver ROW matches
    -- the order's driver_id) OR the Owner. An UNASSIGNED order (driver_id NULL)
    -- cannot be confirmed by a driver; only the Owner may reconcile it.
    -- Use COALESCE to keep the boolean logic strict (never NULL).
    v_is_driver := COALESCE(
      v_driver_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.user_id = v_uid AND d.id = v_driver_id
      ),
      FALSE
    );
    IF NOT v_is_driver AND NOT v_is_owner THEN
      RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
    END IF;

    UPDATE public.orders
       SET payment_status = 'paid',
           cash_collected_at = now(),
           cash_collected_by = v_uid,
           updated_at = now()
     WHERE id = p_reference_id;

    SELECT total_amount INTO v_amount FROM public.orders WHERE id = p_reference_id;
    RETURN jsonb_build_object('ok', true, 'code', 'COLLECTED', 'reference_id', p_reference_id, 'amount', v_amount);
  END IF;

  -- ── RIDE (direct delivery) ──────────────────────────────────────
  IF p_reference_type = 'ride'::public.cash_ref_type THEN
    SELECT status, payment_status, payment_method, driver_id
      INTO v_status, v_pay_status, v_pay_method, v_driver_id
      FROM public.rides
     WHERE id = p_reference_id
     FOR UPDATE;
    IF v_status IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
    END IF;

    IF v_pay_status = 'paid' THEN
      RETURN jsonb_build_object('ok', true, 'code', 'ALREADY_COLLECTED', 'reference_id', p_reference_id);
    END IF;
    IF v_pay_status NOT IN ('pending', 'unpaid') THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATUS', 'current_status', v_pay_status);
    END IF;
    IF v_pay_method <> 'cash' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NOT_CASH');
    END IF;
    IF NOT v_is_owner AND v_status <> 'completed' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_LIFECYCLE', 'current_status', v_status);
    END IF;

    v_is_driver := COALESCE(
      v_driver_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.user_id = v_uid AND d.id = v_driver_id
      ),
      FALSE
    );
    IF NOT v_is_driver AND NOT v_is_owner THEN
      RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
    END IF;

    UPDATE public.rides
       SET payment_status = 'paid',
           cash_collected_at = now(),
           cash_collected_by = v_uid
     WHERE id = p_reference_id;

    SELECT fare INTO v_amount FROM public.rides WHERE id = p_reference_id;
    RETURN jsonb_build_object('ok', true, 'code', 'COLLECTED', 'reference_id', p_reference_id, 'amount', v_amount);
  END IF;

  -- ── SERVICE BOOKING (provider) ──────────────────────────────────
  IF p_reference_type = 'service_booking'::public.cash_ref_type THEN
    SELECT b.status, b.payment_status, b.payment_method,
           p.user_id::uuid
      INTO v_status, v_pay_status, v_pay_method, v_provider_user
      FROM public.service_bookings b
      JOIN public.service_providers p ON p.id = b.provider_id
     WHERE b.id = p_reference_id
     FOR UPDATE OF b;
    IF v_status IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
    END IF;

    IF v_pay_status = 'paid' THEN
      RETURN jsonb_build_object('ok', true, 'code', 'ALREADY_COLLECTED', 'reference_id', p_reference_id);
    END IF;

    v_is_provider := v_provider_user;
    IF (v_is_provider IS DISTINCT FROM v_uid) AND NOT v_is_owner THEN
      RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
    END IF;
    IF v_pay_method <> 'cash' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NOT_CASH');
    END IF;
    IF NOT v_is_owner AND v_status <> 'completed' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_LIFECYCLE', 'current_status', v_status);
    END IF;

    UPDATE public.service_bookings
       SET payment_status = 'paid',
           cash_collected_at = now(),
           cash_collected_by = v_uid,
           updated_at = now()
     WHERE id = p_reference_id
     RETURNING COALESCE(final_price, estimated_price) INTO v_amount;

    RETURN jsonb_build_object('ok', true, 'code', 'COLLECTED', 'reference_id', p_reference_id, 'amount', v_amount);
  END IF;

  RETURN jsonb_build_object('ok', false, 'code', 'INVALID_REFERENCE_TYPE');
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reference_type', p_reference_type::text);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.consume_grace(p_order_id uuid, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_grace   public.grace_accounts;
  v_before  integer;
  v_after   integer;
BEGIN
  SELECT * INTO v_grace FROM public.grace_accounts
   WHERE user_id = auth.uid() FOR UPDATE;
  IF v_grace IS NULL THEN
    v_grace := public.get_or_create_grace(auth.uid());
    SELECT * INTO v_grace FROM public.grace_accounts
     WHERE user_id = auth.uid() FOR UPDATE;
  END IF;
  v_before := v_grace.grace_used;
  IF (v_grace.grace_limit - v_grace.grace_used) <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'GRACE_EXHAUSTED',
      'grace_remaining', 0);
  END IF;
  v_after := v_grace.grace_used + 1;
  UPDATE public.grace_accounts
     SET grace_used = v_after, updated_at = now()
   WHERE user_id = auth.uid();
  INSERT INTO public.grace_audit_log
    (account_id, order_id, before, after, actor, reason, created_at)
  VALUES
    (auth.uid(), p_order_id, v_before, v_after, auth.uid(),
     'grace_consumed', now());
  RETURN jsonb_build_object('ok', true, 'code', 'OK',
    'grace_used', v_after,
    'grace_remaining', GREATEST(0, v_grace.grace_limit - v_after),
    'amount', p_amount);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.count_table_rows(table_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  row_count integer;
BEGIN
  IF NOT public._is_active_admin_uid(auth.uid()) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  -- Whitelist: never interpolate an arbitrary identifier into SQL.
  IF table_name NOT IN (
    'users', 'orders', 'merchants', 'products', 'drivers', 'rides',
    'service_providers', 'service_bookings', 'reviews', 'wallets',
    'categories', 'catalog_categories', 'complaints', 'chat_rooms',
    'notifications', 'driver_locations'
  ) THEN
    RAISE EXCEPTION 'unknown table %', table_name;
  END IF;

  EXECUTE format('SELECT count(*) FROM public.%I', table_name) INTO row_count;
  RETURN row_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_order(p_merchant_id uuid, p_items jsonb, p_delivery_address text DEFAULT NULL::text, p_delivery_latitude numeric DEFAULT NULL::numeric, p_delivery_longitude numeric DEFAULT NULL::numeric, p_payment_method text DEFAULT 'cash'::text, p_coupon_code text DEFAULT NULL::text, p_special_instructions text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_merchant public.merchants%rowtype;
  v_item jsonb;
  v_product public.products%rowtype;
  v_qty int;
  v_subtotal numeric := 0;
  v_delivery_fee numeric := 0;
  v_discount numeric := 0;
  v_total numeric;
  v_order_id uuid;
  v_coupon jsonb;
  v_coupon_id uuid;
  v_lines jsonb := '[]'::jsonb;
  v_existing uuid;
  v_stock_touched boolean := false;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;
  -- 188: a suspended/banned customer cannot place orders (the 5-day policy
  -- suspensions would otherwise be cosmetic).
  if (select u.account_status from public.users u where u.id = v_uid) in ('suspended', 'banned') then
    raise exception 'ACCOUNT_SUSPENDED';
  end if;

  if p_payment_method not in ('cash', 'instapay', 'vodafone_cash') then
    raise exception 'INVALID_PAYMENT_METHOD';
  end if;

  if p_idempotency_key is not null then
    select id into v_existing from public.orders
    where user_id = v_uid and idempotency_key = p_idempotency_key;
    if v_existing is not null then
      return jsonb_build_object(
        'ok', true, 'order_id', v_existing, 'idempotent_replay', true
      );
    end if;
  end if;

  select * into v_merchant from public.merchants where id = p_merchant_id;
  if not found then
    raise exception 'MERCHANT_NOT_FOUND';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'EMPTY_CART';
  end if;
  if jsonb_array_length(p_items) > 100 then
    raise exception 'TOO_MANY_ITEMS';
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_qty := coalesce((v_item->>'quantity')::int, 0);
    if v_qty < 1 or v_qty > 50 then
      raise exception 'INVALID_QUANTITY';
    end if;

    select * into v_product
    from public.products
    where id = (v_item->>'product_id')::uuid
      and merchant_id = p_merchant_id;
    if not found then
      raise exception 'PRODUCT_NOT_FOUND %', v_item->>'product_id';
    end if;
    if v_product.is_available is not true then
      raise exception 'PRODUCT_UNAVAILABLE %', coalesce(v_product.name_ar, v_product.name);
    end if;

    -- Atomic stock check + decrement (NULL stock = unlimited)
    if v_product.stock_quantity is not null then
      update public.products
         set stock_quantity = stock_quantity - v_qty
       where id = v_product.id
         and stock_quantity >= v_qty;
      if not found then
        raise exception 'INSUFFICIENT_STOCK %', coalesce(v_product.name_ar, v_product.name);
      end if;
      v_stock_touched := true;
    end if;

    v_subtotal := v_subtotal + (v_product.price * v_qty);
    v_lines := v_lines || jsonb_build_object(
      'product_id', v_product.id,
      'product_name', coalesce(v_product.name_ar, v_product.name),
      'quantity', v_qty,
      'unit_price', v_product.price,
      'total_price', v_product.price * v_qty
    );
  end loop;

  v_delivery_fee := coalesce(v_merchant.delivery_fee, 0);

  if v_merchant.min_order is not null and v_subtotal < v_merchant.min_order then
    raise exception 'BELOW_MIN_ORDER %', v_merchant.min_order;
  end if;

  if p_coupon_code is not null and btrim(p_coupon_code) <> '' then
    v_coupon := public.redeem_coupon(p_coupon_code, v_uid);
    if not (v_coupon->>'success')::boolean then
      raise exception 'COUPON_%', upper(v_coupon->>'reason');
    end if;
    if (v_coupon->>'merchant_id') is not null
       and (v_coupon->>'merchant_id')::uuid <> p_merchant_id then
      raise exception 'COUPON_WRONG_MERCHANT';
    end if;
    if (v_coupon->>'minimum_order') is not null
       and v_subtotal < (v_coupon->>'minimum_order')::numeric then
      raise exception 'COUPON_MIN_ORDER_NOT_MET';
    end if;
    v_coupon_id := (v_coupon->>'coupon_id')::uuid;
    if v_coupon->>'discount_type' = 'percentage' then
      v_discount := round(v_subtotal * (v_coupon->>'discount_value')::numeric / 100.0, 2);
    else
      v_discount := (v_coupon->>'discount_value')::numeric;
    end if;
    if (v_coupon->>'maximum_discount') is not null then
      v_discount := least(v_discount, (v_coupon->>'maximum_discount')::numeric);
    end if;
    v_discount := least(v_discount, v_subtotal);
  end if;

  v_total := v_subtotal + v_delivery_fee - v_discount;
  if v_total < 0 then
    v_total := 0;
  end if;

  insert into public.orders (
    user_id, merchant_id, merchant_name, status, payment_status,
    payment_method, subtotal, delivery_fee, discount, tax, total_amount,
    coupon_id, delivery_address, delivery_latitude, delivery_longitude,
    special_instructions, items, idempotency_key, dispatch_status,
    stock_decremented
  ) values (
    v_uid, p_merchant_id, v_merchant.name, 'pending', 'pending',
    p_payment_method, v_subtotal, v_delivery_fee, v_discount, 0, v_total,
    v_coupon_id, p_delivery_address, p_delivery_latitude, p_delivery_longitude,
    p_special_instructions, v_lines, p_idempotency_key, 'PENDING_DISPATCH',
    v_stock_touched
  )
  returning id into v_order_id;

  insert into public.order_items (order_id, product_id, product_name, quantity, unit_price, total_price)
  select v_order_id,
         (l->>'product_id')::uuid,
         l->>'product_name',
         (l->>'quantity')::int,
         (l->>'unit_price')::numeric,
         (l->>'total_price')::numeric
  from jsonb_array_elements(v_lines) l;

  return jsonb_build_object(
    'ok', true,
    'order_id', v_order_id,
    'subtotal', v_subtotal,
    'delivery_fee', v_delivery_fee,
    'discount', v_discount,
    'total_amount', v_total,
    'status', 'pending',
    'idempotent_replay', false
  );
end;
$function$
;
CREATE OR REPLACE FUNCTION public.create_order_idempotent(p_idempotency_key text, p_merchant_id uuid, p_merchant_name text, p_items jsonb, p_subtotal numeric, p_delivery_fee numeric, p_discount numeric, p_total numeric, p_delivery_address text, p_payment_method text, p_payment_status text, p_payment_provider text, p_payment_provider_order_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_order_id uuid;
  v_existing_order uuid;
  v_coupon_id uuid;
  v_items jsonb;
  v_quantity int;
  v_unit_price numeric;
  v_total_price numeric;
  v_subtotal numeric;
  v_delivery_fee numeric;
  v_discount numeric;
  v_total numeric;
  v_is_service boolean;
  v_status text;
  v_item record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  IF p_idempotency_key IS NULL OR p_idempotency_key = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MISSING_IDEMPOTENCY_KEY');
  END IF;
  v_is_service := (current_user = 'service_role' OR current_setting('request.jwt.claims', true) LIKE '%"role":"service_role"%');
  v_subtotal := COALESCE(p_subtotal, 0);
  v_delivery_fee := COALESCE(p_delivery_fee, 0);
  v_discount := COALESCE(p_discount, 0);
  IF v_subtotal < 0 OR v_delivery_fee < 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_AMOUNTS');
  END IF;
  v_discount := LEAST(v_discount, v_subtotal + v_delivery_fee);
  IF v_discount < 0 THEN
    v_discount := 0;
  END IF;
  v_total := ROUND(v_subtotal + v_delivery_fee - v_discount, 2);
  IF v_total < 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_TOTAL');
  END IF;
  IF v_is_service THEN
    v_status := p_payment_status;
  ELSIF p_payment_status IN ('paid','refunded','failed') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'PAYMENT_STATUS_FORBIDDEN');
  ELSE
    v_status := COALESCE(NULLIF(p_payment_status, ''), 'pending');
  END IF;

  -- Tolerant items: accept either a JSON array (direct callers) or a
  -- string-encoded array (the app's jsonEncode() call), then normalize keys.
  IF jsonb_typeof(p_items) = 'string' THEN
    BEGIN
      v_items := (p_items #>> '{}')::jsonb;
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ITEMS');
    END;
  ELSE
    v_items := p_items;
  END IF;
  IF v_items IS NULL OR jsonb_typeof(v_items) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ITEMS');
  END IF;

  SELECT id INTO v_existing_order
    FROM public.orders
   WHERE idempotency_key = p_idempotency_key;
  IF v_existing_order IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'code', 'ALREADY_EXISTS', 'order_id', v_existing_order);
  END IF;

  v_coupon_id := NULLIF(COALESCE(v_items -> 0 ->> 'coupon_id', v_items -> 0 ->> 'couponId'), '')::uuid;

  -- Validate every line resolves a product + both prices (snake_case OR camelCase).
  FOR v_item IN SELECT * FROM jsonb_array_elements(v_items) AS e(item) LOOP
    v_quantity := COALESCE((v_item.item ->> 'quantity')::int, 1);
    v_unit_price := COALESCE((v_item.item ->> 'unit_price')::numeric, (v_item.item ->> 'unitPrice')::numeric);
    v_total_price := COALESCE((v_item.item ->> 'total_price')::numeric, (v_item.item ->> 'totalPrice')::numeric);
    IF COALESCE(v_item.item ->> 'product_id', v_item.item ->> 'productId') IS NULL
       OR v_quantity <= 0 OR v_unit_price IS NULL OR v_total_price IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ITEMS');
    END IF;
  END LOOP;

  BEGIN
    INSERT INTO public.orders (
      user_id, merchant_id, merchant_name, items, subtotal, delivery_fee,
      discount, total_amount, delivery_address, payment_method,
      payment_status, payment_provider, payment_provider_order_id,
      idempotency_key, coupon_id
    ) VALUES (
      v_uid, p_merchant_id, p_merchant_name, v_items, v_subtotal, v_delivery_fee,
      v_discount, v_total, p_delivery_address, p_payment_method,
      v_status, p_payment_provider, p_payment_provider_order_id,
      p_idempotency_key, v_coupon_id
    ) RETURNING id INTO v_order_id;
  EXCEPTION
    WHEN unique_violation THEN
      SELECT id INTO v_existing_order
        FROM public.orders WHERE idempotency_key = p_idempotency_key;
      IF v_existing_order IS NOT NULL THEN
        RETURN jsonb_build_object('ok', true, 'code', 'ALREADY_EXISTS', 'order_id', v_existing_order);
      END IF;
      RETURN jsonb_build_object('ok', false, 'code', 'CONFLICT');
  END;

  INSERT INTO public.order_items (order_id, product_id, quantity, unit_price, total_price, modifiers)
  SELECT
    v_order_id,
    COALESCE((item ->> 'product_id')::uuid, (item ->> 'productId')::uuid),
    COALESCE((item ->> 'quantity')::int, 1),
    COALESCE((item ->> 'unit_price')::numeric, (item ->> 'unitPrice')::numeric),
    COALESCE((item ->> 'total_price')::numeric, (item ->> 'totalPrice')::numeric),
    COALESCE(item -> 'modifiers', '[]'::jsonb)
  FROM jsonb_array_elements(v_items) AS item;

  RETURN jsonb_build_object('ok', true, 'code', 'CREATED', 'order_id', v_order_id, 'total_amount', v_total);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_receiving_account(p_method text, p_display_name text, p_account_identifier text, p_instructions text DEFAULT NULL::text, p_is_active boolean DEFAULT true, p_display_order integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.has_financial_permission(auth.uid(), 'manage_receiving_accounts') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  IF p_method IS NULL OR p_method NOT IN ('instapay', 'vodafone_cash', 'bank_transfer', 'other') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_METHOD');
  END IF;

  IF p_display_name IS NULL OR p_display_name = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_DISPLAY_NAME');
  END IF;

  IF p_account_identifier IS NULL OR p_account_identifier = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ACCOUNT_IDENTIFIER');
  END IF;

  INSERT INTO public.financial_receiving_accounts (
    method, display_name, account_identifier, instructions, is_active, display_order
  ) VALUES (
    p_method, p_display_name, p_account_identifier, p_instructions, p_is_active, p_display_order
  ) ON CONFLICT (method) DO UPDATE SET
    display_name = EXCLUDED.display_name,
    account_identifier = EXCLUDED.account_identifier,
    instructions = EXCLUDED.instructions,
    is_active = EXCLUDED.is_active,
    display_order = EXCLUDED.display_order,
    updated_at = now();

  RETURN jsonb_build_object('ok', true, 'code', 'OK');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_service_booking(p_provider_id uuid, p_provider_name text, p_category_type text, p_scheduled_date date, p_scheduled_time text, p_address text, p_address_latitude double precision, p_address_longitude double precision, p_estimated_price numeric, p_description text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_price numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'UNAUTHENTICATED');
  END IF;
  IF p_category_type IS NULL OR p_scheduled_date IS NULL OR p_provider_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_INPUT');
  END IF;
  v_price := GREATEST(COALESCE(p_estimated_price, 0), 0);

  INSERT INTO public.service_bookings (
    user_id, provider_id, provider_name, category_type, status,
    description, scheduled_date, scheduled_time, address,
    address_latitude, address_longitude, estimated_price, notes
  ) VALUES (
    v_uid, p_provider_id, p_provider_name, p_category_type, 'pending',
    p_description, p_scheduled_date, p_scheduled_time, p_address,
    p_address_latitude, p_address_longitude, v_price, p_notes
  ) RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'booking_id', v_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_topup_request(p_amount numeric, p_payment_method text DEFAULT 'instapay'::text, p_transfer_reference text DEFAULT NULL::text, p_proof_path text DEFAULT NULL::text, p_message text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_region uuid;
  v_snap   jsonb;
  v_id     uuid;
  v_existing uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_AMOUNT');
  END IF;
  IF p_payment_method NOT IN ('instapay','vodafone_cash','bank_transfer','cash','other') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_METHOD');
  END IF;

  -- Proof-path ownership: a requester may only reference a proof object in their
  -- OWN folder (first path segment == auth.uid()). This prevents attaching
  -- another user's (or a non-existent) transfer proof to your own request and
  -- presenting it to the Owner as evidence of YOUR deposit.
  IF p_proof_path IS NOT NULL AND p_proof_path <> ''
     AND split_part(p_proof_path, '/', 1) IS DISTINCT FROM v_uid::text THEN
    RETURN jsonb_build_object('ok', false, 'code', 'PROOF_PATH_FORBIDDEN');
  END IF;

  -- Idempotency: reuse an existing pending request with the same key instead of
  -- creating a duplicate (protects against double-tap / client retry).
  IF p_idempotency_key IS NOT NULL AND p_idempotency_key <> '' THEN
    SELECT id INTO v_existing
      FROM public.topup_requests
     WHERE account_id = v_uid AND idempotency_key = p_idempotency_key
       AND status = 'pending'
     LIMIT 1;
    IF v_existing IS NOT NULL THEN
      RETURN jsonb_build_object('ok', true, 'code', 'ALREADY_EXISTS', 'id', v_existing, 'status', 'pending');
    END IF;
  END IF;

  SELECT region_id INTO v_region FROM public.user_region_preferences
   WHERE user_id = v_uid LIMIT 1;

  -- Snapshot the Owner-managed platform receivers as the where-to-send
  -- reference on the request.
  SELECT receiver_data INTO v_snap FROM (
    SELECT jsonb_build_object('source', 'platform', 'receivers',
      COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'method_type', a.method_type, 'display_name', a.display_name,
        'account_name', a.account_name, 'account_number', a.account_number,
        'wallet_number', a.wallet_number)) FROM public.platform_receiving_accounts a
        WHERE a.is_active), '[]'::jsonb)) AS receiver_data
  ) sub;

  INSERT INTO public.topup_requests
    (account_id, region_id, amount, currency, receiver_admin_id,
     receiver_wallet_snapshot, payment_method, transfer_reference, proof_path, message,
     idempotency_key)
  VALUES
    (v_uid, v_region, p_amount, 'EGP', NULL, v_snap,
     p_payment_method, p_transfer_reference, p_proof_path, p_message,
     p_idempotency_key)
  RETURNING id INTO v_id;

  -- Notify every Owner that a new top-up request is pending approval (the Owner
  -- is the only actor who can approve). Without this the Owner would only learn
  -- of new requests by manually refreshing an admin page.
  INSERT INTO public.notifications (user_id, title, body, type, data)
  SELECT u.id, 'New top-up request', 'A top-up request for ' || p_amount::text
           || ' ' || 'EGP' || ' is pending your approval.',
         'topup_request_pending',
         jsonb_build_object('topup_request_id', v_id, 'amount', p_amount,
           'account_id', v_uid, 'deep_link', '/admin/wallet/topups')
    FROM public.users u
   WHERE u.role = 'owner';

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'id', v_id, 'status', 'pending');
EXCEPTION
  WHEN unique_violation THEN
    -- A concurrent identical submission won the race. Reuse the existing row
    -- instead of failing — atomic dedup (double-tap / concurrent retry).
    IF p_idempotency_key IS NOT NULL AND p_idempotency_key <> '' THEN
      SELECT id INTO v_existing
        FROM public.topup_requests
       WHERE account_id = v_uid AND idempotency_key = p_idempotency_key
       ORDER BY created_at ASC
       LIMIT 1;
      IF v_existing IS NOT NULL THEN
        RETURN jsonb_build_object('ok', true, 'code', 'ALREADY_EXISTS',
          'id', v_existing, 'status', 'pending');
      END IF;
    END IF;
    RAISE;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.create_wallet_funding_request(p_user_id uuid, p_amount numeric, p_method text, p_reference text, p_proof_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_funding_request_id UUID;
BEGIN
  IF auth.uid() IS NOT NULL AND p_user_id IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_USER');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_AMOUNT');
  END IF;
  IF p_method IS NULL OR p_method NOT IN ('instapay', 'vodafone_cash', 'bank_transfer') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_METHOD');
  END IF;
  IF p_reference IS NULL OR p_reference = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_REFERENCE');
  END IF;

  INSERT INTO public.wallet_funding_requests (
    user_id, amount, method, reference, proof_url, status
  ) VALUES (
    p_user_id, p_amount, p_method, p_reference, p_proof_url, 'pending'
  ) RETURNING id INTO v_funding_request_id;

  RETURN jsonb_build_object(
    'ok', true,
    'funding_request_id', v_funding_request_id,
    'amount', p_amount,
    'method', p_method
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.deactivate_device_tokens(p_device_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_affected integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE public.notification_tokens
     SET is_active = false,
         updated_at = now()
   WHERE user_id = v_uid
     AND (p_device_id IS NULL OR btrim(p_device_id) = '' OR device_id = p_device_id)
     AND is_active = true;

  GET DIAGNOSTICS v_affected = ROW_COUNT;
  RETURN v_affected;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.deactivate_device_tokens(p_device_id text, p_app text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;
  update public.notification_tokens
     set is_active = false, updated_at = now()
   where user_id = v_uid
     and device_id = p_device_id
     and (p_app is null or app = p_app or app is null);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.deactivate_stale_tokens(stale_interval interval DEFAULT '30 days'::interval)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_affected integer;
BEGIN
  IF current_user NOT IN ('service_role','postgres') THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  UPDATE public.notification_tokens
     SET is_active = false,
         updated_at = now()
   WHERE is_active = true
     AND last_seen_at < now() - stale_interval;

  GET DIAGNOSTICS v_affected = ROW_COUNT;
  RETURN v_affected;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.decide_appeal(p_appeal_id uuid, p_approve boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_appeal public.appeals%rowtype;
  v_duty uuid;
  v_is_owner boolean;
begin
  if v_uid is null or not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  select * into v_appeal from public.appeals where id = p_appeal_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  end if;
  if v_appeal.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_DECIDED');
  end if;
  v_duty := public._duty_admin_for_region(v_appeal.region_id);
  select exists (select 1 from public.users where id = v_uid and role = 'owner') into v_is_owner;
  if not (v_is_owner or v_uid is not distinct from v_duty) then
    return jsonb_build_object('ok', false, 'code', 'NOT_DUTY_ADMIN');
  end if;
  if p_approve then
    perform public._member_exec_revoke_sanction(v_uid, v_appeal.sanction_id,
      coalesce(nullif(btrim(p_note), ''), 'قبول الالتماس'));
    update public.appeals
       set status = 'approved', decided_by = v_uid, decided_at = now(), decision_note = p_note
     where id = p_appeal_id;
    insert into public.notifications (user_id, title, body, type, data, send_push)
    values (v_appeal.user_id,
            'تم قبول الالتماس 🎉',
            'راجع المسؤول التماسك واتفعل حسابك من جديد. أهلًا بعودتك.',
            'appeal',
            jsonb_build_object('appeal_id', p_appeal_id, 'status', 'approved'),
            true);
  else
    update public.appeals
       set status = 'rejected', decided_by = v_uid, decided_at = now(), decision_note = p_note
     where id = p_appeal_id;
    insert into public.notifications (user_id, title, body, type, data, send_push)
    values (v_appeal.user_id,
            'تم رفض الالتماس',
            'راجع المسؤول التماسك وقرر استمرار الإيقاف.' ||
              case when p_note is not null and btrim(p_note) <> '' then ' السبب: ' || p_note else '' end,
            'appeal',
            jsonb_build_object('appeal_id', p_appeal_id, 'status', 'rejected'),
            true);
  end if;
  return jsonb_build_object('ok', true, 'status', case when p_approve then 'approved' else 'rejected' end);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.decide_approval_request(p_request_id uuid, p_decision text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request public.approval_requests%ROWTYPE;
  v_is_owner boolean;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_decision NOT IN ('approve','reject') THEN
    RAISE EXCEPTION 'Invalid decision';
  END IF;
  SELECT * INTO v_request FROM public.approval_requests a WHERE a.id = p_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Approval request not found';
  END IF;
  IF v_request.state <> 'pending' THEN
    RAISE EXCEPTION 'Approval request already decided';
  END IF;
  IF v_request.request_type <> 'campaign_approve'
     AND NOT public._valid_approval_type(v_request.request_type) THEN
    RAISE EXCEPTION 'Unsupported request type';
  END IF;

  SELECT public._is_owner_uid(auth.uid()) INTO v_is_owner;

  IF v_request.requested_by = auth.uid() AND NOT v_is_owner THEN
    RAISE EXCEPTION 'Cannot decide your own request';
  END IF;

  IF NOT v_is_owner THEN
    IF v_request.required_approver IS NULL THEN
      RAISE EXCEPTION 'Not authorized to decide this request';
    END IF;
    IF v_request.required_approver <> auth.uid()
       AND NOT public.is_supervisor_of(auth.uid(), v_request.requested_by) THEN
      RAISE EXCEPTION 'Not authorized to decide this request';
    END IF;
  END IF;

  IF p_decision = 'reject'
     AND (p_reason IS NULL OR btrim(p_reason) = '') THEN
    RAISE EXCEPTION 'Rejection requires a reason';
  END IF;

  IF p_decision = 'approve' THEN
    PERFORM public._approval_apply(v_request, p_reason);
    UPDATE public.approval_requests
      SET state = 'approved', reason = p_reason,
          decided_by = auth.uid(), decided_at = now()
      WHERE id = p_request_id;
  ELSE
    UPDATE public.approval_requests
      SET state = 'rejected', reason = p_reason,
          decided_by = auth.uid(), decided_at = now()
      WHERE id = p_request_id;
  END IF;

  INSERT INTO public.notifications (user_id, title, body, type, data, deep_link, idempotency_key)
  VALUES (
    v_request.requested_by,
    CASE WHEN p_decision = 'approve' THEN 'Approval granted' ELSE 'Approval rejected' END,
    v_request.request_type || ' — ' || COALESCE(p_reason, ''),
    'approval',
    jsonb_build_object('request_id', p_request_id::text,
                       'decision', p_decision,
                       'request_type', v_request.request_type),
    '/admin/approvals',
    'approval-decide-' || p_request_id::text
  );

  PERFORM public.write_audit(
    'APPROVAL_DECIDED', 'approval_requests', p_request_id::text,
    jsonb_build_object('decision', p_decision,
                       'request_type', v_request.request_type,
                       'reason', p_reason));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.decide_provider_profile_request(p_profile_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_req public.provider_business_profiles%ROWTYPE;
  v_dec text := lower(btrim(COALESCE(p_decision, '')));
  v_target jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF v_dec NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Decision must be approved or rejected';
  END IF;

  SELECT * INTO v_req FROM public.provider_business_profiles WHERE id = p_profile_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profile request not found';
  END IF;

  IF v_dec = 'approved' THEN
    v_target := public._provision_business_target(v_req.user_id, v_req.category_type, v_req.display_name);
    UPDATE public.provider_business_profiles
       SET status = 'approved',
           merchant_id = COALESCE((v_target->>'merchant_id')::uuid, merchant_id),
           service_provider_id = COALESCE((v_target->>'service_provider_id')::uuid, service_provider_id),
           rejection_reason = NULL,
           reviewed_by = v_actor,
           reviewed_at = now(),
           updated_at = now()
     WHERE id = p_profile_id;
  ELSE
    UPDATE public.provider_business_profiles
       SET status = 'rejected',
           rejection_reason = NULLIF(btrim(COALESCE(p_reason, '')), ''),
           reviewed_by = v_actor,
           reviewed_at = now(),
           updated_at = now()
     WHERE id = p_profile_id;
  END IF;

  INSERT INTO public.notifications (user_id, title, body, type, data)
  VALUES (
    v_req.user_id,
    CASE WHEN v_dec = 'approved' THEN 'Service Line Approved' ELSE 'Service Line Update' END,
    CASE
      WHEN v_dec = 'approved' THEN 'Your additional service line (' || v_req.category_type || ') is now active!'
      ELSE COALESCE(p_reason, 'Your additional service line request was rejected.')
    END,
    'provider_profile',
    jsonb_build_object('profile_id', p_profile_id, 'category_type', v_req.category_type, 'status', v_dec)
  );

  RETURN jsonb_build_object('ok', true, 'status', v_dec);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.decide_user_verification(p_user_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_current text;
  v_new text;
  v_has_docs boolean;
  v_target_regid uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_decision NOT IN ('approve', 'reject') THEN
    RAISE EXCEPTION 'Invalid decision';
  END IF;
  IF p_decision = 'reject'
     AND btrim(COALESCE(p_reason, '')) = '' THEN
    RAISE EXCEPTION 'Rejection requires a reason';
  END IF;

  SELECT region_id INTO v_target_regid
    FROM public.user_region_preferences
   WHERE user_id = p_user_id
   ORDER BY updated_at DESC
   LIMIT 1;

  IF NOT (public._is_owner_uid(auth.uid())
          OR (v_target_regid IS NOT NULL
              AND public.has_permission('MEMBER_MODERATE', v_target_regid))) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT verification_status,
         id_card_url IS NOT NULL AND profile_photo_url IS NOT NULL
    INTO v_current, v_has_docs
    FROM public.users WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;

  IF v_current NOT IN ('pending', 'rejected') THEN
    RAISE EXCEPTION 'Verification already decided';
  END IF;

  v_new := CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END;

  UPDATE public.users
    SET verification_status = v_new,
        rejection_reason = CASE
          WHEN p_decision = 'reject' THEN btrim(p_reason)
          ELSE NULL
        END,
        rejection_reason_at = CASE
          WHEN p_decision = 'reject' THEN now()
          ELSE NULL
        END,
        updated_at = now()
    WHERE id = p_user_id;

  INSERT INTO public.notifications
    (user_id, title, body, type, data, deep_link, idempotency_key)
  VALUES (
    p_user_id,
    CASE WHEN p_decision = 'approve' THEN 'Verification approved'
         ELSE 'Verification rejected' END,
    CASE WHEN p_decision = 'approve'
         THEN 'You can now use the platform.'
         ELSE COALESCE(btrim(p_reason), 'Please review your documents.') END,
    'verification',
    jsonb_build_object(
      'status', v_new,
      'reason', p_reason
    ),
    CASE WHEN p_decision = 'approve' THEN '/profile' ELSE '/pending-verification' END,
    'verification-decide-' || p_user_id::text || '-' || gen_random_uuid()::text
  );

  PERFORM public.write_audit(
    'VERIFICATION_DECIDED',
    'users',
    p_user_id::text,
    jsonb_build_object(
      'decision', p_decision,
      'reason', p_reason,
      'had_documents', v_has_docs
    )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.decline_order(p_order_id uuid, p_driver_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = p_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'FORBIDDEN');
  END IF;

  UPDATE public.order_dispatch
    SET status = 'declined', updated_at = now()
    WHERE order_id = p_order_id AND candidate_driver_id = p_driver_id;
  UPDATE public.orders SET dispatch_status = 'PENDING_DISPATCH', driver_id = NULL
    WHERE id = p_order_id AND driver_id = p_driver_id;
  PERFORM public.log_admin_action('DISPATCH_DECLINE', 'order', p_order_id::text,
    jsonb_build_object('driver', p_driver_id), NULL, p_reason, 'GLOBAL');
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.delete_member_account(p_member_id uuid, p_confirmation_token text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE v_status text; v_email text; v_expected_token text; v_request_id uuid; BEGIN SELECT account_status, email INTO v_status, v_email FROM public.users WHERE id = p_member_id; IF NOT FOUND THEN RAISE EXCEPTION 'Member not found'; END IF; IF public._is_active_admin_uid(p_member_id) THEN RAISE EXCEPTION 'Admins are managed through the admin lifecycle'; END IF; IF v_status = 'deactivated' THEN RAISE EXCEPTION 'Member account is already deactivated'; END IF; IF NOT public.has_permission('MEMBER_DELETE', public._member_region_id(p_member_id)) AND NOT public._is_owner_uid(auth.uid()) THEN RAISE EXCEPTION 'Not authorized for this member'; END IF; IF v_email IS NOT NULL AND btrim(v_email) <> '' THEN v_expected_token := 'DELETE-' || encode(sha256(lower(btrim(v_email))::bytea), 'hex'); ELSE v_expected_token := 'DELETE-' || encode(sha256(p_member_id::text::bytea), 'hex'); END IF; IF p_confirmation_token IS NULL OR p_confirmation_token <> v_expected_token THEN RAISE EXCEPTION 'Invalid confirmation token'; END IF; v_request_id := public.submit_approval_request('member_delete', 'member', p_member_id, jsonb_build_object('member_id', p_member_id::text, 'reason', p_reason), p_reason); RETURN v_request_id; END; $function$
;
CREATE OR REPLACE FUNCTION public.delete_my_account(p_reason text DEFAULT 'user_requested'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  PERFORM public.delete_user_data(v_uid, p_reason);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.delete_receiving_account(p_method text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.has_financial_permission(auth.uid(), 'manage_receiving_accounts') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  IF p_method IS NULL OR p_method = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_METHOD');
  END IF;

  DELETE FROM public.financial_receiving_accounts WHERE method = p_method;

  RETURN jsonb_build_object('ok', true, 'code', 'OK');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.delete_trusted_contact(p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  DELETE FROM trusted_contacts
  WHERE id = p_contact_id AND user_id = v_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'contact_not_found');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.delete_user_data(p_uid uuid, p_reason text DEFAULT 'user_requested'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_room_ids uuid[];
  v_driver_ids uuid[];
  v_merchant_ids uuid[];
BEGIN
  IF p_uid IS NULL THEN
    RAISE EXCEPTION 'User id is required';
  END IF;
  IF public._is_active_admin_uid(p_uid) THEN
    RAISE EXCEPTION 'Admins are managed through the admin lifecycle';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_uid) THEN
    RAISE EXCEPTION 'Member not found';
  END IF;

  -- 1. Conversations: every room the user participates in goes (messages,
  --    typing and escalations cascade from the room). Attachments are
  --    purged by the edge function through the Storage API first. Any
  --    message the user sent in another room goes too.
  SELECT array_agg(id) INTO v_room_ids
  FROM public.chat_rooms
  WHERE participant_ids @> ARRAY[p_uid]::uuid[];
  IF v_room_ids IS NOT NULL THEN
    DELETE FROM public.chat_rooms WHERE id = ANY (v_room_ids);
  END IF;
  DELETE FROM public.chat_messages WHERE sender_id = p_uid;

  -- 2. Audio recording rows (objects purged via Storage API first).
  DELETE FROM public.service_audio_logs WHERE user_id = p_uid;

  -- 3. Personal document rows (objects purged via Storage API first; the
  --    users-row URL columns are nulled by the engine below).
  DELETE FROM public.provider_documents WHERE provider_id = p_uid;
  DELETE FROM public.verification_attempts WHERE user_id = p_uid;

  -- 4. Wallet top-up proof references (the financial rows stay; the
  --    personal transfer receipts go).
  UPDATE public.wallet_funding_requests SET proof_url = NULL WHERE user_id = p_uid;
  UPDATE public.topup_requests SET proof_path = NULL WHERE account_id = p_uid;

  -- 5. Captain profile, if any: detach historical deliveries (driver_id is
  --    nullable on orders/rides), then delete the driver row; its documents,
  --    earnings, locations, vehicles and withdrawal requests cascade.
  SELECT array_agg(id) INTO v_driver_ids FROM public.drivers WHERE user_id = p_uid;
  IF v_driver_ids IS NOT NULL THEN
    UPDATE public.drivers SET current_delivery_id = NULL WHERE id = ANY (v_driver_ids);
    UPDATE public.orders SET driver_id = NULL WHERE driver_id = ANY (v_driver_ids);
    UPDATE public.rides SET driver_id = NULL WHERE driver_id = ANY (v_driver_ids);
    DELETE FROM public.order_dispatch WHERE candidate_driver_id = ANY (v_driver_ids);
    DELETE FROM public.drivers WHERE id = ANY (v_driver_ids);
  END IF;

  -- 6. Merchant profile, if any: detach historical orders/rides, then delete
  --    the store; its products, branches, favorites and profile rows cascade.
  SELECT array_agg(id) INTO v_merchant_ids FROM public.merchants WHERE owner_user_id = p_uid;
  IF v_merchant_ids IS NOT NULL THEN
    UPDATE public.orders SET merchant_id = NULL WHERE merchant_id = ANY (v_merchant_ids);
    UPDATE public.rides SET merchant_id = NULL WHERE merchant_id = ANY (v_merchant_ids);
    UPDATE public.coupons SET merchant_id = NULL WHERE merchant_id = ANY (v_merchant_ids);
    UPDATE public.reviews SET merchant_id = NULL WHERE merchant_id = ANY (v_merchant_ids);
    DELETE FROM public.merchants WHERE id = ANY (v_merchant_ids);
  END IF;
  DELETE FROM public.merchant_profiles WHERE user_id = p_uid;

  -- 7. Personal content rows.
  DELETE FROM public.user_addresses WHERE user_id = p_uid;
  DELETE FROM public.trusted_contacts WHERE user_id = p_uid;
  DELETE FROM public.saved_places WHERE user_id = p_uid;
  DELETE FROM public.favorites WHERE user_id = p_uid;
  DELETE FROM public.favorite_drivers WHERE user_id = p_uid;
  DELETE FROM public.notification_tokens WHERE user_id = p_uid;
  DELETE FROM public.notifications WHERE user_id = p_uid;
  DELETE FROM public.live_share_sessions WHERE user_id = p_uid;
  DELETE FROM public.location_updates WHERE user_id = p_uid;
  DELETE FROM public.user_region_preferences WHERE user_id = p_uid;
  DELETE FROM public.campaign_seen WHERE user_id = p_uid;
  DELETE FROM public.promo_redemptions WHERE user_id = p_uid;
  DELETE FROM public.sos_alerts WHERE user_id = p_uid;
  DELETE FROM public.reviews WHERE user_id = p_uid;
  DELETE FROM public.ride_ratings WHERE rater_id = p_uid;
  DELETE FROM public.service_reviews WHERE user_id = p_uid;
  DELETE FROM public.member_rewards WHERE user_id = p_uid;
  DELETE FROM public.grace_accounts WHERE user_id = p_uid;
  DELETE FROM public.chat_typing WHERE user_id = p_uid;
  DELETE FROM public.provider_business_profiles WHERE user_id = p_uid;

  -- 8. The engine's audit row references auth.users(actor) with NO ACTION;
  --    detach the member's actor rows so the auth delete below cannot fail.
  UPDATE public.audit_log SET actor = NULL WHERE actor = p_uid;

  -- 9. Anonymize the account row (D4 semantics, FK-safe) via the existing
  --    moderation engine, then revoke the login by removing the auth row.
  PERFORM public._member_exec_delete(
    p_uid, p_uid, COALESCE(NULLIF(btrim(p_reason), ''), 'user_requested'));

  DELETE FROM auth.users WHERE id = p_uid;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.deliveries_view_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_driver uuid;
  v_ride_status text;
  v_delivery_status public.delivery_status;
BEGIN
  SELECT id INTO v_driver FROM public.drivers WHERE user_id = auth.uid() LIMIT 1;
  IF v_driver IS NULL THEN RAISE EXCEPTION 'Not a driver'; END IF;

  IF NEW.status = 'rejected' THEN
    UPDATE public.rides
       SET driver_id = NULL, status = 'searching', delivery_status = 'searching',
           accepted_at = NULL
     WHERE id = OLD.id AND driver_id = v_driver;
    RETURN NEW;
  END IF;

  v_ride_status := CASE NEW.status
    WHEN 'accepted' THEN 'matched'
    WHEN 'arrived' THEN 'arrived'
    WHEN 'picked_up' THEN 'inTrip'
    WHEN 'delivered' THEN 'completed'
    WHEN 'cancelled' THEN 'cancelled'
    ELSE NULL END;
  v_delivery_status := CASE NEW.status
    WHEN 'accepted' THEN 'matched'::public.delivery_status
    WHEN 'arrived' THEN 'arrived'::public.delivery_status
    WHEN 'picked_up' THEN 'picked_up'::public.delivery_status
    WHEN 'delivered' THEN 'delivered'::public.delivery_status
    WHEN 'cancelled' THEN 'cancelled'::public.delivery_status
    ELSE NULL END;

  UPDATE public.rides
     SET status = COALESCE(v_ride_status, status),
         delivery_status = COALESCE(v_delivery_status, delivery_status),
         driver_id = CASE WHEN NEW.status = 'accepted' THEN v_driver ELSE driver_id END,
         accepted_at = COALESCE(NEW.accepted_at, accepted_at),
         picked_up_at = CASE WHEN v_ride_status = 'inTrip' THEN COALESCE(NEW.picked_up_at, now()) ELSE COALESCE(NEW.picked_up_at, picked_up_at) END,
         delivered_at = CASE WHEN v_ride_status = 'completed' THEN COALESCE(NEW.delivered_at, now()) ELSE COALESCE(NEW.delivered_at, delivered_at) END
   WHERE id = OLD.id
     AND (driver_id IS NULL OR driver_id = v_driver);

  IF NOT FOUND THEN RAISE EXCEPTION 'Delivery unavailable or assigned to another driver'; END IF;

  IF v_ride_status = 'matched' AND OLD.order_id IS NOT NULL THEN
    UPDATE public.orders SET dispatch_status = 'ASSIGNED', updated_at = now() WHERE id = OLD.order_id;
  ELSIF v_ride_status = 'inTrip' AND OLD.order_id IS NOT NULL THEN
    UPDATE public.orders SET status = 'delivering', dispatch_status = 'ACCEPTED', updated_at = now() WHERE id = OLD.order_id;
  ELSIF v_ride_status = 'completed' AND OLD.order_id IS NOT NULL THEN
    UPDATE public.orders SET status = 'delivered', dispatch_status = 'ACCEPTED', updated_at = now() WHERE id = OLD.order_id;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.delivery_handoff_code(p_stage text, p_ride_id uuid DEFAULT NULL::uuid, p_order_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r rides%ROWTYPE; c delivery_handoff_challenges%ROWTYPE;
BEGIN
 SELECT * INTO r FROM rides WHERE (p_ride_id IS NOT NULL AND id=p_ride_id) OR (p_order_id IS NOT NULL AND order_id=p_order_id) ORDER BY created_at DESC LIMIT 1;
 IF NOT FOUND OR auth.uid() IS NULL OR p_stage NOT IN ('pickup','dropoff') THEN RETURN jsonb_build_object('ok',false,'reason','HANDOFF_UNAVAILABLE'); END IF;
 -- Merchant hands goods over at pickup; the customer/recipient controls dropoff.
 IF (p_stage='pickup' AND NOT ((r.merchant_id IS NOT NULL AND is_merchant_owner(r.merchant_id)) OR (r.merchant_id IS NULL AND r.rider_id=auth.uid())))
    OR (p_stage='dropoff' AND r.rider_id IS DISTINCT FROM auth.uid())
    OR EXISTS(SELECT 1 FROM drivers WHERE id=r.driver_id AND user_id=auth.uid()) THEN
   RETURN jsonb_build_object('ok',false,'reason','FORBIDDEN');
 END IF;
 IF r.status NOT IN ('matched','arrived','inTrip') THEN RETURN jsonb_build_object('ok',false,'reason','HANDOFF_UNAVAILABLE'); END IF;
 SELECT * INTO c FROM delivery_handoff_challenges WHERE ride_id=r.id AND stage=p_stage FOR UPDATE;
 IF NOT FOUND OR c.verified_at IS NOT NULL THEN RETURN jsonb_build_object('ok',false,'reason','HANDOFF_UNAVAILABLE'); END IF;
 IF c.expires_at<=now() THEN
  UPDATE delivery_handoff_challenges SET code=public._new_delivery_handoff_code(),expires_at=now()+interval '24 hours',attempts=0,locked_until=NULL WHERE ride_id=r.id AND stage=p_stage RETURNING * INTO c;
 END IF;
 RETURN jsonb_build_object('ok',true,'code',c.code,'stage',p_stage,'locked_until',c.locked_until);
END; $function$
;
CREATE OR REPLACE FUNCTION public.dispatch_delivery(p_ride_id uuid, p_radius_km numeric DEFAULT 10, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ride RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;
  SELECT * INTO v_ride FROM public.rides WHERE id = p_ride_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'ride_not_found');
  END IF;
  IF NOT (public.is_admin() OR COALESCE(v_ride.rider_id = auth.uid(),false)
      OR (v_ride.merchant_id IS NOT NULL AND public.is_merchant_owner(v_ride.merchant_id))) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;
  RETURN public._dispatch_delivery_internal(p_ride_id, p_radius_km, p_limit);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.dispatch_order(p_order_id uuid, p_region_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order orders%ROWTYPE;
  v_best uuid;
  v_score numeric;
  v_cfg dispatch_config%ROWTYPE;
  v_cat text;
BEGIN
  -- Authorization FIRST: only owner or admin can manually trigger dispatch
  -- (service_role with NULL auth.uid() is allowed for cron jobs)
  IF auth.uid() IS NOT NULL
     AND NOT (public._is_owner_uid(auth.uid()) OR public.is_admin()) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'FORBIDDEN');
  END IF;

  SELECT * INTO v_cfg FROM public.dispatch_config WHERE region_id IS NOT DISTINCT FROM p_region_id;
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_FOUND');
  END IF;
  IF v_order.dispatch_status <> 'PENDING_DISPATCH' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_PENDING', 'dispatch_status', v_order.dispatch_status);
  END IF;
   v_cat := 'food';

  SELECT driver_id, score INTO v_best, v_score
  FROM (
    SELECT d.id AS driver_id,
      (1.0 / (1.0 + public.driver_distance_km(
        v_order.delivery_latitude, v_order.delivery_longitude,
        dl.latitude, dl.longitude))) AS score
    FROM public.drivers d
    JOIN public.driver_locations dl ON dl.driver_id = d.id
    WHERE d.is_online
      AND d.is_verified
      AND d.accepts_deliveries
      AND (d.max_delivery_distance_km IS NULL OR
           public.driver_distance_km(v_order.delivery_latitude, v_order.delivery_longitude, dl.latitude, dl.longitude)
            <= d.max_delivery_distance_km)
      AND (d.service_types IS NULL OR d.service_types && ARRAY[v_cat])
    ORDER BY score DESC
    LIMIT 1
  ) ranked;

  IF v_best IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NO_AVAILABLE_DRIVER');
  END IF;

  INSERT INTO public.order_dispatch (order_id, candidate_driver_id, score, status, region_id)
  VALUES (p_order_id, v_best, v_score, 'pending', p_region_id)
  ON CONFLICT (order_id) DO UPDATE
    SET candidate_driver_id = EXCLUDED.candidate_driver_id,
        score = EXCLUDED.score,
        status = 'pending',
        region_id = EXCLUDED.region_id,
        updated_at = now();

  PERFORM public.log_admin_action('DISPATCH_AUTO', 'order', p_order_id::text,
    NULL, jsonb_build_object('driver', v_best, 'score', v_score), NULL, 'GLOBAL');

  RETURN jsonb_build_object('ok', true, 'driver_id', v_best, 'score', v_score);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.dispatch_push(p_notification_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.notifications%ROWTYPE;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  PERFORM set_config('app.notify_dispatch', 'true', true);

  SELECT * INTO v_row FROM public.notifications WHERE id = p_notification_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  -- Idempotent: never re-send an already-sent notification.
  IF v_row.push_status = 'sent' THEN
    RETURN;
  END IF;

  UPDATE public.notifications
     SET push_status = 'pending', push_error = NULL
   WHERE id = p_notification_id;
  PERFORM public._enqueue_push(p_notification_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.dispute_obligation(p_obligation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ob public.driver_obligations%ROWTYPE;
BEGIN
  SELECT * INTO v_ob FROM public.driver_obligations WHERE id = p_obligation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.drivers d WHERE d.id = v_ob.driver_id AND d.user_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF v_ob.status <> 'open' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE');
  END IF;
  UPDATE public.driver_obligations
     SET status = 'disputed', dispute_reason = p_reason, updated_at = now()
   WHERE id = p_obligation_id;
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.driver_application_documents_ready(p_driver_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
 SELECT NOT EXISTS (
  SELECT 1 FROM (VALUES('driving_license'),('vehicle_registration')) required(doc_type)
  WHERE NOT EXISTS(SELECT 1 FROM public.driver_documents doc
    JOIN storage.objects obj ON obj.bucket_id='driver-documents' AND obj.name=doc.file_url
    WHERE doc.driver_id=p_driver_id AND doc.doc_type=required.doc_type
    AND doc.status IN ('pending','verified')
    AND (doc.expires_at IS NULL OR doc.expires_at >= current_date)));
$function$
;
CREATE OR REPLACE FUNCTION public.driver_arrive(p_ride_id uuid, p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r rides%ROWTYPE;
  v_owner UUID;
BEGIN
  SELECT user_id INTO v_owner FROM drivers WHERE id = p_driver_id;
  IF v_owner IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;
  SELECT * INTO r FROM rides WHERE id = p_ride_id FOR UPDATE;
  IF r.driver_id IS DISTINCT FROM p_driver_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_your_ride');
  END IF;
  IF r.status <> 'matched' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invalid_transition');
  END IF;
  UPDATE rides SET status = 'arrived', arrived_at = NOW(),
    driver_arrived_confirmed = true WHERE id = p_ride_id;
  INSERT INTO trip_events (ride_id, event_type, actor) VALUES (p_ride_id, 'driver_arrived', 'driver');
  RETURN jsonb_build_object('success', true, 'status', 'arrived');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.driver_arrived_at_pickup(p_delivery_id uuid, p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN public.driver_arrive(p_delivery_id, p_driver_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.driver_complete_registration(p_full_name text, p_phone text DEFAULT NULL::text, p_vehicle_type text DEFAULT NULL::text, p_vehicle_plate text DEFAULT NULL::text, p_vehicle_color text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_driver uuid;
  v_vehicle uuid;
BEGIN
  IF p_vehicle_type IS NOT NULL AND p_vehicle_type NOT IN ('motorcycle','tuk_tuk','tricycle','car') THEN
    RAISE EXCEPTION 'Invalid delivery vehicle type';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_full_name IS NULL OR btrim(p_full_name) = '' THEN
    RAISE EXCEPTION 'Full name is required';
  END IF;

  SELECT id INTO v_driver FROM public.drivers WHERE user_id = v_uid LIMIT 1;

  IF v_driver IS NULL THEN
    INSERT INTO public.drivers
      (user_id, full_name, phone, vehicle_type, vehicle_plate,
       vehicle_color, status, is_online, is_active, is_verified,
       verification_status, onboarding_step, created_at, updated_at)
    VALUES
      (v_uid, btrim(p_full_name), p_phone, p_vehicle_type, p_vehicle_plate,
       p_vehicle_color, 'offline', false, true, false, 'pending', 1,
       now(), now())
    RETURNING id INTO v_driver;
  ELSE
    UPDATE public.drivers
       SET full_name = btrim(p_full_name),
           phone = COALESCE(p_phone, phone),
           vehicle_type = COALESCE(p_vehicle_type, vehicle_type),
           vehicle_plate = COALESCE(p_vehicle_plate, vehicle_plate),
           vehicle_color = COALESCE(p_vehicle_color, vehicle_color),
           updated_at = now()
     WHERE id = v_driver
      RETURNING id INTO v_driver;
  END IF;

  -- A driver with no vehicle can never satisfy the dispatch filter.
  IF p_vehicle_type IS NOT NULL AND btrim(COALESCE(p_vehicle_plate,'')) <> '' THEN
    SELECT id INTO v_vehicle
      FROM public.vehicles
     WHERE driver_id = v_driver
       AND category = p_vehicle_type
     LIMIT 1;

    IF v_vehicle IS NULL THEN
      -- The live vehicles table uses `category` (not vehicle_type),
      -- `plate_number` (not vehicle_plate) and `color` (not
      -- vehicle_color).
      INSERT INTO public.vehicles
        (driver_id, category, plate_number, color, is_active, is_verified, created_at)
      VALUES
        (v_driver, p_vehicle_type, p_vehicle_plate, p_vehicle_color, true, false, now())
      RETURNING id INTO v_vehicle;
    ELSE
      UPDATE public.vehicles
         SET is_active = true,
             plate_number = COALESCE(p_vehicle_plate, plate_number),
             color = COALESCE(p_vehicle_color, color)
       WHERE id = v_vehicle;
    END IF;

    UPDATE public.drivers SET active_vehicle_id = v_vehicle WHERE id = v_driver;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'driver_id', v_driver, 'vehicle_id', v_vehicle
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.driver_confirm_settlement(p_obligation_id uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ob public.driver_obligations%ROWTYPE;
BEGIN
  SELECT * INTO v_ob FROM public.driver_obligations WHERE id = p_obligation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.drivers d WHERE d.id = v_ob.driver_id AND d.user_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF v_ob.status <> 'open' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE');
  END IF;
  IF v_ob.settlement_code IS NULL OR v_ob.settlement_code <> p_code THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CODE');
  END IF;
  UPDATE public.driver_obligations
     SET status = 'settled', settled_at = now(), settled_via = 'admin_code',
         settlement_code = NULL, updated_at = now()
   WHERE id = p_obligation_id;
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.driver_dashboard_stats(p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_owner UUID;
  v_today_rides INTEGER;
  v_today_earnings DECIMAL(10,2);
  v_week_earnings DECIMAL(10,2);
  v_balance DECIMAL(10,2);
  v_pending_withdrawals DECIMAL(10,2);
  v_total_trips INTEGER;
  v_rating DECIMAL(3,2);
  v_acceptance NUMERIC;
BEGIN
  SELECT user_id INTO v_owner FROM drivers WHERE id = p_driver_id;
  IF v_owner IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;

  SELECT COUNT(*) INTO v_today_rides FROM rides
    WHERE driver_id = p_driver_id AND status = 'completed'
      AND completed_at >= date_trunc('day', NOW());

  SELECT COALESCE(SUM(amount), 0) INTO v_today_earnings FROM driver_earnings
    WHERE driver_id = p_driver_id AND type IN ('trip','bonus','tip')
      AND created_at >= date_trunc('day', NOW());

  SELECT COALESCE(SUM(amount), 0) INTO v_week_earnings FROM driver_earnings
    WHERE driver_id = p_driver_id AND type IN ('trip','bonus','tip')
      AND created_at >= date_trunc('week', NOW());

  SELECT COALESCE(earnings_balance, 0), COALESCE(total_trips, 0), COALESCE(rating, 0)
    INTO v_balance, v_total_trips, v_rating FROM drivers WHERE id = p_driver_id;

  SELECT COALESCE(SUM(amount), 0) INTO v_pending_withdrawals FROM withdrawal_requests
    WHERE driver_id = p_driver_id AND status IN ('pending','approved');

  SELECT CASE WHEN COUNT(*) = 0 THEN 100
              ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'accepted') / COUNT(*), 0)
         END INTO v_acceptance
    FROM ride_requests WHERE driver_id = p_driver_id
      AND status IN ('accepted','rejected','expired');

  RETURN jsonb_build_object(
    'success', true,
    'today_rides', v_today_rides,
    'today_earnings', v_today_earnings,
    'week_earnings', v_week_earnings,
    'balance', v_balance,
    'pending_withdrawals', v_pending_withdrawals,
    'total_trips', v_total_trips,
    'rating', v_rating,
    'acceptance_rate', v_acceptance
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.driver_distance_km(p_pickup_lat double precision, p_pickup_lng double precision, p_driver_lat double precision, p_driver_lng double precision)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT 6371 * acos(
    least(1.0, greatest(-1.0,
      cos(radians(p_pickup_lat)) * cos(radians(p_driver_lat)) *
      cos(radians(p_driver_lng) - radians(p_pickup_lng)) +
      sin(radians(p_pickup_lat)) * sin(radians(p_driver_lat))
    ))
  );
$function$
;
CREATE OR REPLACE FUNCTION public.driver_presence(p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d drivers%ROWTYPE;
BEGIN
 SELECT * INTO d FROM drivers WHERE id=p_driver_id AND user_id=auth.uid();
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','FORBIDDEN'); END IF;
 RETURN jsonb_build_object('ok',true,'online',COALESCE(d.is_online,false),
   'fresh',COALESCE(d.location_updated_at > now()-interval '2 minutes',false));
END; $function$
;
CREATE OR REPLACE FUNCTION public.driver_set_online(p_driver_id uuid, p_online boolean, p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_owner UUID;
BEGIN
  SELECT user_id INTO v_owner FROM drivers WHERE id = p_driver_id;
  IF v_owner IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;

  UPDATE drivers SET
    is_online = p_online,
    current_latitude = COALESCE(p_lat, current_latitude),
    current_longitude = COALESCE(p_lon, current_longitude),
    location_updated_at = NOW()
  WHERE id = p_driver_id;

  IF p_online AND p_lat IS NOT NULL AND p_lon IS NOT NULL THEN
    INSERT INTO driver_locations (driver_id, latitude, longitude, updated_at)
      VALUES (p_driver_id, p_lat, p_lon, NOW())
    ON CONFLICT (driver_id) DO UPDATE
      SET latitude = EXCLUDED.latitude,
          longitude = EXCLUDED.longitude,
          updated_at = NOW();
  END IF;

  RETURN jsonb_build_object('success', true, 'online', p_online);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.driver_set_online_state(p_online boolean, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_driver_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_driver uuid;
  v_vehicle uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id INTO v_driver
    FROM public.drivers
   WHERE user_id = v_uid
   ORDER BY created_at
   LIMIT 1
   FOR UPDATE;

  IF v_driver IS NULL THEN
    RAISE EXCEPTION 'Driver profile not found';
  END IF;

  IF p_driver_id IS NOT NULL AND p_driver_id <> v_driver THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  IF p_online THEN
    IF p_lat IS NULL OR p_lng IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 THEN
      RETURN jsonb_build_object('ok',false,'reason','FRESH_LOCATION_REQUIRED');
    END IF;
    IF NOT EXISTS(SELECT 1 FROM drivers WHERE id=v_driver AND is_verified AND is_active) THEN
      RETURN jsonb_build_object('ok',false,'reason','DRIVER_NOT_VERIFIED');
    END IF;
    IF NOT EXISTS(SELECT 1 FROM vehicles WHERE driver_id=v_driver AND is_active) THEN
      RETURN jsonb_build_object('ok',false,'reason','ACTIVE_VEHICLE_REQUIRED');
    END IF;
  END IF;
  -- Adopt the driver's active vehicle so dispatch_delivery's
  -- `active_vehicle_id IS NOT NULL` precondition can be satisfied.
  SELECT id INTO v_vehicle
    FROM public.vehicles
   WHERE driver_id = v_driver
     AND is_active = true
   ORDER BY created_at
   LIMIT 1;

  UPDATE public.drivers
     SET is_online = p_online,
         -- status and is_online are two views of the same fact; the
         -- dispatch filter reads `status`, so both must move together.
         status = CASE WHEN p_online THEN 'online' ELSE 'offline' END,
         active_vehicle_id = COALESCE(active_vehicle_id, v_vehicle),
         current_latitude = COALESCE(p_lat, current_latitude),
         current_longitude = COALESCE(p_lng, current_longitude),
         location_updated_at = CASE
           WHEN p_lat IS NOT NULL THEN now() ELSE location_updated_at END,
         updated_at = now()
   WHERE id = v_driver;

  IF p_online AND p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    INSERT INTO public.driver_locations (driver_id, latitude, longitude, updated_at)
         VALUES (v_driver, p_lat, p_lng, now())
    ON CONFLICT (driver_id) DO UPDATE
      SET latitude = EXCLUDED.latitude,
          longitude = EXCLUDED.longitude,
          updated_at = EXCLUDED.updated_at;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'driver_id', v_driver,
    'status', CASE WHEN p_online THEN 'online' ELSE 'offline' END,
    'active_vehicle_id', COALESCE(
      (SELECT active_vehicle_id FROM public.drivers WHERE id = v_driver),
      NULL
    )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.driver_sync_active_vehicle(p_driver_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_driver uuid;
BEGIN
  SELECT id INTO v_driver FROM public.drivers WHERE user_id = v_uid LIMIT 1;
  IF v_driver IS NULL THEN
    RETURN false;
  END IF;
  IF p_driver_id IS NOT NULL AND p_driver_id <> v_driver THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  -- Promote the requested vehicle when it belongs to this driver,
  -- otherwise fall back to any active vehicle.
  IF p_vehicle_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.vehicles
                  WHERE id = p_vehicle_id
                    AND driver_id = v_driver
                    AND is_active = true) THEN
    UPDATE public.drivers SET active_vehicle_id = p_vehicle_id WHERE id = v_driver;
    RETURN true;
  END IF;

  UPDATE public.drivers
     SET active_vehicle_id = (
       SELECT id FROM public.vehicles
        WHERE driver_id = v_driver AND is_active = true
        ORDER BY created_at LIMIT 1
     )
   WHERE id = v_driver;

  RETURN true;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.driver_update_location(p_driver_id uuid, p_lat double precision, p_lon double precision, p_heading double precision DEFAULT NULL::double precision, p_speed double precision DEFAULT NULL::double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_owner UUID;
  v_ride UUID;
BEGIN
  IF auth.uid() IS NULL OR p_lat IS NULL OR p_lon IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lon NOT BETWEEN -180 AND 180 THEN
    RETURN jsonb_build_object('success',false,'reason','invalid_location');
  END IF;
  SELECT user_id INTO v_owner FROM drivers WHERE id = p_driver_id;
  IF v_owner IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;

  SELECT id INTO v_ride FROM rides
    WHERE driver_id = p_driver_id
      AND status IN ('matched','arrived','inTrip')
    ORDER BY created_at DESC LIMIT 1;

  INSERT INTO driver_locations (driver_id, latitude, longitude, heading, speed, ride_id, updated_at)
    VALUES (p_driver_id, p_lat, p_lon, p_heading, p_speed, v_ride, NOW())
  ON CONFLICT (driver_id) DO UPDATE
    SET latitude = EXCLUDED.latitude,
        longitude = EXCLUDED.longitude,
        heading = EXCLUDED.heading,
        speed = EXCLUDED.speed,
        ride_id = EXCLUDED.ride_id,
        updated_at = NOW();

  UPDATE drivers SET
    current_latitude = p_lat,
    current_longitude = p_lon,
    location_updated_at = NOW()
  WHERE id = p_driver_id;

  IF v_ride IS NOT NULL THEN
    UPDATE rides SET
      driver_latitude = p_lat,
      driver_longitude = p_lon,
      driver_heading = p_heading
    WHERE id = v_ride;
  END IF;

  RETURN jsonb_build_object('success', true, 'ride_id', v_ride);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.drivers_guard_sensitive_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_user IN ('authenticated', 'anon') AND NOT public.is_admin() THEN
    IF NEW.earnings_balance IS DISTINCT FROM OLD.earnings_balance THEN
      RAISE EXCEPTION 'earnings_balance is managed by the earnings RPCs';
    END IF;
    IF NEW.is_verified IS DISTINCT FROM OLD.is_verified THEN
      RAISE EXCEPTION 'is_verified is managed by the admin verification RPCs';
    END IF;
    IF NEW.verification_status IS DISTINCT FROM OLD.verification_status THEN
      RAISE EXCEPTION 'verification_status is managed by the admin verification RPCs';
    END IF;
    IF NEW.background_check_status IS DISTINCT FROM OLD.background_check_status THEN
      RAISE EXCEPTION 'background_check_status is managed by the admin RPCs';
    END IF;
    IF NEW.rating IS DISTINCT FROM OLD.rating THEN
      RAISE EXCEPTION 'rating is managed by the rating engine';
    END IF;
    IF NEW.total_deliveries IS DISTINCT FROM OLD.total_deliveries THEN
      RAISE EXCEPTION 'total_deliveries is managed by the delivery engine';
    END IF;
    IF NEW.total_trips IS DISTINCT FROM OLD.total_trips THEN
      RAISE EXCEPTION 'total_trips is managed by the trip engine';
    END IF;
    IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
      RAISE EXCEPTION 'user_id is immutable';
    END IF;
    IF NEW.active_vehicle_id IS DISTINCT FROM OLD.active_vehicle_id THEN
      RAISE EXCEPTION 'active_vehicle_id is managed by the vehicle RPCs';
    END IF;
    IF NEW.national_id_number IS DISTINCT FROM OLD.national_id_number THEN
      RAISE EXCEPTION 'national_id_number is managed by the onboarding RPCs';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.ensure_owner_operational_contexts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_result jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;
  SELECT role INTO v_role FROM users WHERE id = v_uid;
  IF v_role <> 'owner' THEN
    RAISE EXCEPTION 'forbidden: only the platform owner may provision owner contexts';
  END IF;

  -- Delivery operational identity (owner-operated).
  IF NOT EXISTS (SELECT 1 FROM drivers WHERE user_id = v_uid) THEN
    INSERT INTO public.drivers (user_id, full_name, status, onboarding_completed, verification_status, rating, total_deliveries)
    VALUES (v_uid, COALESCE((SELECT full_name FROM users WHERE id = v_uid), 'Owner'), 'online', true, 'verified', 5.0, 0);
    v_result := v_result || jsonb_build_object('delivery', 'created');
  ELSE
    v_result := v_result || jsonb_build_object('delivery', 'exists');
  END IF;

  -- Provider operational identity (owner-operated).
  IF NOT EXISTS (SELECT 1 FROM service_providers WHERE user_id = v_uid) THEN
    INSERT INTO public.service_providers (user_id, name, category_type, is_verified)
    VALUES (v_uid, COALESCE((SELECT full_name FROM users WHERE id = v_uid), 'Owner'), 'home_services', true);
    v_result := v_result || jsonb_build_object('provider', 'created');
  ELSE
    v_result := v_result || jsonb_build_object('provider', 'exists');
  END IF;

  PERFORM public.log_admin_action('OWNER_CONTEXT_PROVISION', 'owner', v_uid::text,
    NULL, v_result, 'Idempotent owner operational context provisioning', 'GLOBAL');

  RETURN v_result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalate_complaint(p_complaint_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_complaint public.complaints%ROWTYPE;
  v_region uuid;
  v_current uuid;
  v_next uuid;
  v_prev_scope text;
  v_new_scope text;
  v_assignee uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'Escalation requires a reason';
  END IF;

  -- Prove server-origin to complaints_fixup_update (RPC path marker).
  PERFORM set_config('app.escalation_rpc', 'true', true);

  SELECT * INTO v_complaint
    FROM public.complaints WHERE id = p_complaint_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Complaint not found';
  END IF;
  IF v_complaint.status IN ('resolved','rejected','dismissed') THEN
    RAISE EXCEPTION 'Complaint is already closed';
  END IF;

  v_region := public._member_region_id(v_complaint.complainant_id);
  IF NOT public.has_permission('MEMBER_VIEW_COMPLAINTS', v_region) THEN
    RAISE EXCEPTION 'Not authorized for this complaint region';
  END IF;

  v_current := v_complaint.assigned_admin_id;
  v_prev_scope := CASE
    WHEN v_current IS NULL THEN 'unassigned'
    WHEN EXISTS (SELECT 1 FROM public.users WHERE id = v_current AND role = 'owner') THEN 'owner'
    WHEN EXISTS (SELECT 1 FROM public.admin_region_assignments WHERE admin_id = v_current) THEN 'scoped'
    ELSE 'global'
  END;

  -- Owner/escalator terminal -> owner queue.
  IF v_current IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.users WHERE id = v_current AND role = 'owner'
  ) THEN
    UPDATE public.complaints
       SET status = 'escalated',
           assigned_admin_id = NULL,
           escalated_at = now(),
           escalated_from_admin_id = auth.uid(),
           updated_at = now()
     WHERE id = p_complaint_id;
    INSERT INTO public.escalation_events
      (entity_type, entity_id, from_admin_id, to_admin_id, actor_id, reason,
       previous_scope, new_scope)
    VALUES ('complaint', p_complaint_id, v_current, NULL, auth.uid(), p_reason,
            v_prev_scope, 'owner');
    PERFORM public.write_audit(
      'COMPLAINT_ESCALATED', 'complaints', p_complaint_id::text,
      jsonb_build_object('reason', p_reason, 'from_admin_id', auth.uid(),
                         'to_admin_id', NULL, 'terminal', true)
    );
    RETURN;
  END IF;

  -- Strict upward routing: an already-owner-queued complaint is terminal.
  IF v_current IS NULL AND EXISTS (
    SELECT 1 FROM public.escalation_events e
     WHERE e.entity_type = 'complaint'
       AND e.entity_id = p_complaint_id
       AND e.new_scope = 'owner'
  ) THEN
    RETURN;
  END IF;

  -- Route to the NEXT HIGHER tier from the current assignee (never down):
  --   unassigned -> best regional (else global/owner)
  --   scoped     -> global tier (else owner)
  --   global     -> owner queue (terminal)
  IF v_current IS NULL THEN
    v_next := public.resolve_support_admin(v_region, true, NULL);
  ELSIF EXISTS (
    SELECT 1 FROM public.admin_region_assignments WHERE admin_id = v_current
  ) THEN
    v_next := public.resolve_support_admin(v_region, false, v_current);
  ELSE
    v_next := NULL;
  END IF;
  IF v_next IS NULL OR v_next = v_current THEN
    v_assignee := NULL;
    v_new_scope := 'owner';
  ELSE
    v_assignee := v_next;
    v_new_scope := CASE
      WHEN EXISTS (SELECT 1 FROM public.users WHERE id = v_next AND role = 'owner') THEN 'owner'
      WHEN EXISTS (SELECT 1 FROM public.admin_region_assignments WHERE admin_id = v_next) THEN 'scoped'
      ELSE 'global'
    END;
  END IF;

  UPDATE public.complaints
     SET status = 'escalated',
         assigned_admin_id = v_assignee,
         escalated_at = now(),
         escalated_from_admin_id = auth.uid(),
         updated_at = now()
   WHERE id = p_complaint_id;

  INSERT INTO public.escalation_events
    (entity_type, entity_id, from_admin_id, to_admin_id, actor_id, reason,
     previous_scope, new_scope)
  VALUES ('complaint', p_complaint_id, v_current, v_next, auth.uid(), p_reason,
          v_prev_scope, v_new_scope);

  INSERT INTO public.member_events (user_id, event_type, payload)
  VALUES (v_complaint.complainant_id, 'complaint_escalated',
          jsonb_build_object('complaint_id', p_complaint_id::text,
                             'escalated_by', auth.uid()::text))
  ON CONFLICT DO NOTHING;

  IF v_assignee IS NOT NULL THEN
    INSERT INTO public.notifications
      (user_id, title, body, type, data, deep_link, idempotency_key,
       sender_id, priority, send_push)
    VALUES (
      v_assignee,
      'Escalated complaint assigned',
      'An escalated complaint requires your review.',
      'complaint_escalated',
      jsonb_build_object('entity_type', 'complaint',
                         'entity_id', p_complaint_id::text,
                         'action', 'escalated'),
      '/admin/complaints',
      'complaint-escalated-' || p_complaint_id::text || '-' || v_assignee::text,
      auth.uid(), 'high', true
    )
    ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
  END IF;

  PERFORM public.write_audit(
    'COMPLAINT_ESCALATED', 'complaints', p_complaint_id::text,
    jsonb_build_object('reason', p_reason, 'from_admin_id', auth.uid(),
                       'to_admin_id', v_next, 'previous_scope', v_prev_scope,
                       'new_scope', v_new_scope)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.escalate_support_chat(p_room_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_room public.chat_rooms%ROWTYPE;
  v_current uuid;
  v_next uuid;
  v_prev_scope text;
  v_new_scope text;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'Escalation requires a reason';
  END IF;
  SELECT * INTO v_room FROM public.chat_rooms WHERE id = p_room_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Room not found';
  END IF;
  IF v_room.status = 'closed' THEN
    RAISE EXCEPTION 'Room is closed';
  END IF;

  v_current := v_room.assigned_admin_id;
  v_prev_scope := CASE
    WHEN v_current IS NULL THEN 'unassigned'
    WHEN EXISTS (SELECT 1 FROM public.users WHERE id = v_current AND role = 'owner') THEN 'owner'
    WHEN EXISTS (SELECT 1 FROM public.admin_region_assignments WHERE admin_id = v_current) THEN 'scoped'
    ELSE 'global'
  END;

  UPDATE public.chat_rooms
     SET escalated_at = now(),
         escalated_from_admin_id = auth.uid()
   WHERE id = p_room_id;

  -- Owner/escalator terminal -> owner queue.
  IF v_current IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.users WHERE id = v_current AND role = 'owner'
  ) THEN
    UPDATE public.chat_rooms
       SET status = 'escalated', assigned_admin_id = NULL
     WHERE id = p_room_id;
    INSERT INTO public.chat_escalations
      (room_id, previous_admin_id, new_admin_id, actor_id, reason,
       previous_scope, new_scope)
    VALUES (p_room_id, v_current, NULL, auth.uid(), p_reason,
            v_prev_scope, 'owner');
    PERFORM public.write_audit(
      'SUPPORT_ESCALATED', 'chat_rooms', p_room_id::text,
      jsonb_build_object('reason', p_reason, 'from_admin_id', auth.uid(),
                         'to_admin_id', NULL, 'terminal', true)
    );
    RETURN;
  END IF;

  v_next := public.resolve_support_admin(v_room.region_id, true, v_current);
  IF v_next IS NULL OR v_next = v_current THEN
    UPDATE public.chat_rooms
       SET status = 'escalated', assigned_admin_id = NULL
     WHERE id = p_room_id;
    v_new_scope := 'owner';
  ELSE
    PERFORM public._assign_chat_to_admin(p_room_id, v_next, 'assigned');
    v_new_scope := CASE
      WHEN EXISTS (SELECT 1 FROM public.users WHERE id = v_next AND role = 'owner') THEN 'owner'
      WHEN EXISTS (SELECT 1 FROM public.admin_region_assignments WHERE admin_id = v_next) THEN 'scoped'
      ELSE 'global'
    END;
  END IF;

  INSERT INTO public.chat_escalations
    (room_id, previous_admin_id, new_admin_id, actor_id, reason,
     previous_scope, new_scope)
  VALUES (p_room_id, v_current, v_next, auth.uid(), p_reason,
          v_prev_scope, v_new_scope);

  PERFORM public.write_audit(
    'SUPPORT_ESCALATED', 'chat_rooms', p_room_id::text,
    jsonb_build_object('reason', p_reason, 'from_admin_id', auth.uid(),
                       'to_admin_id', v_next, 'previous_scope', v_prev_scope,
                       'new_scope', v_new_scope)
  );

  INSERT INTO public.notifications
    (user_id, title, body, type, data, deep_link, idempotency_key)
  VALUES (
    (SELECT participant_ids[1] FROM public.chat_rooms WHERE id = p_room_id),
    'Support chat escalated',
    'Your chat has been escalated to the next support level.',
    'chat_escalated',
    jsonb_build_object('room_id', p_room_id::text),
    '/support/room/' || p_room_id::text,
    'chat-escalated-customer-' || p_room_id::text
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.estimate_delivery_fee(p_service_type text, p_distance_km numeric, p_weight_kg numeric DEFAULT 1.0, p_priority text DEFAULT 'standard'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pricing RECORD;
  v_fee DECIMAL;
  v_multiplier DECIMAL := 1.0;
BEGIN
  SELECT * INTO v_pricing FROM delivery_pricing WHERE service_type = p_service_type AND is_active = true;
  IF v_pricing IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'pricing_not_found');
  END IF;

  v_fee := v_pricing.base_fee + (v_pricing.per_km * p_distance_km) + (v_pricing.per_kg * p_weight_kg);

  IF p_priority = 'priority' THEN
    v_multiplier := v_pricing.priority_multiplier;
  ELSIF p_priority = 'express' THEN
    v_multiplier := v_pricing.express_multiplier;
  END IF;

  v_fee := v_fee * v_multiplier;

  IF v_fee < v_pricing.minimum_fee THEN
    v_fee := v_pricing.minimum_fee;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'fee', ROUND(v_fee, 2),
    'base_fee', v_pricing.base_fee,
    'distance_fee', ROUND(v_pricing.per_km * p_distance_km, 2),
    'weight_fee', ROUND(v_pricing.per_kg * p_weight_kg, 2),
    'multiplier', v_multiplier,
    'currency', v_pricing.currency
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.evaluate_order_eligibility(p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_balance numeric;
  v_grace   public.grace_accounts;
  v_remaining integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'UNAUTHENTICATED');
  END IF;
  SELECT balance INTO v_balance FROM public.wallets WHERE user_id = auth.uid();
  v_balance := COALESCE(v_balance, 0);
  v_grace := public.get_or_create_grace(auth.uid());
  v_remaining := GREATEST(0, v_grace.grace_limit - v_grace.grace_used);

  IF v_balance >= p_amount THEN
    RETURN jsonb_build_object('allowed', true, 'code', 'OK',
      'balance', v_balance, 'grace_remaining', v_remaining);
  END IF;
  IF v_remaining > 0 THEN
    RETURN jsonb_build_object('allowed', true, 'code', 'GRACE_OK',
      'balance', v_balance, 'grace_remaining', v_remaining);
  END IF;
  RETURN jsonb_build_object('allowed', false, 'code', 'INSUFFICIENT_BALANCE',
    'balance', v_balance, 'grace_remaining', 0);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.explain_admin_access(p_member_id uuid, p_region_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_reasons jsonb := '[]'::jsonb;
  v_access boolean := false;
  v_actor_role text;
  v_member_exists boolean;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('access', false, 'reasons', '[]'::jsonb);
  END IF;

  SELECT role INTO v_actor_role FROM public.users WHERE id = v_actor;
  SELECT EXISTS (SELECT 1 FROM public.users WHERE id = p_member_id) INTO v_member_exists;
  IF NOT v_member_exists THEN
    RETURN jsonb_build_object('access', false, 'reasons',
      jsonb_build_array(jsonb_build_object('dimension', 'member', 'detail', 'not-found')));
  END IF;

  IF v_actor_role = 'owner' THEN
    v_access := true;
    v_reasons := v_reasons || jsonb_build_object('dimension', 'role', 'detail', 'owner');
  ELSIF public._is_active_admin_uid(v_actor) THEN
    v_reasons := v_reasons || jsonb_build_object('dimension', 'role', 'detail', 'admin');
    -- region scope
    IF p_region_id IS NULL THEN
      v_reasons := v_reasons || jsonb_build_object('dimension', 'region_scope', 'detail', 'no region supplied');
      v_access := true;
    ELSIF public._region_in_scope(v_actor, p_region_id) THEN
      v_reasons := v_reasons || jsonb_build_object('dimension', 'region_scope', 'detail', 'region covered');
      v_access := true;
    ELSE
      v_reasons := v_reasons || jsonb_build_object('dimension', 'region_scope', 'detail', 'region not covered');
    END IF;
    -- permission dimension (MEMBER_VIEW = default in-scope)
    IF public.has_permission('MEMBER_VIEW', p_region_id) THEN
      v_reasons := v_reasons || jsonb_build_object('dimension', 'permission', 'detail', 'MEMBER_VIEW (default)');
    END IF;
    -- supervisor dimension: is the member an admin under this actor's branch?
    IF EXISTS (
      SELECT 1 FROM public.admin_management m
      WHERE m.admin_id = p_member_id AND public.is_supervisor_of(v_actor, p_member_id)
    ) THEN
      v_reasons := v_reasons || jsonb_build_object('dimension', 'supervisor', 'detail', 'within branch');
    END IF;
  ELSE
    v_reasons := v_reasons || jsonb_build_object('dimension', 'role', 'detail', 'not-admin');
  END IF;

  RETURN jsonb_build_object('access', v_access, 'reasons', v_reasons);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.finalize_driver_earnings(p_period_end timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid       uuid := auth.uid();
  v_settlement_id uuid;
  v_drivers   int := 0;
  v_commissions int := 0;
  v_rec       record;
BEGIN
  -- A NULL uid is the trusted system path (service_role / pg_cron). anon is
  -- blocked outright by the REVOKE ... FROM anon grant on this function. An
  -- authenticated (non-null uid) caller must hold owner or SETTLE.
  IF v_uid IS NOT NULL
     AND NOT (public._is_owner_uid(v_uid) OR public.has_permission('SETTLE', NULL)) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'FORBIDDEN');
  END IF;

  IF p_period_end IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_PERIOD');
  END IF;

  -- Serialize: a second overlapping run (Owner UI + cron, or two SETTLE admins)
  -- blocks until the first commits, then sees settlement_id already set on the
  -- commissions and finds nothing left to finalize. This removes the race where
  -- two runs each INSERT a payout for the same unlinked commissions -> double pay.
  PERFORM pg_advisory_xact_lock(hashtext('delwaqty_finalize_driver_earnings'));

  FOR v_rec IN
    SELECT pc.member_id AS driver_uid,
           d.id        AS driver_id,
           d.user_id,
           SUM(pc.net_amount)::numeric AS payout_total,
           min(pc.currency)            AS currency
      FROM public.platform_commissions pc
      JOIN public.drivers d ON d.user_id = pc.member_id
     WHERE pc.status IN ('computed')
       AND pc.settlement_id IS NULL
       AND pc.created_at < p_period_end
     GROUP BY pc.member_id, d.id, d.user_id
     ORDER BY pc.member_id
  LOOP
    IF v_rec.payout_total <= 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.platform_settlements
      (admin_id, member_id, payout_type, amount, currency, payment_method,
       reference, status, message)
    VALUES
      (v_uid, v_rec.driver_uid, 'driver', v_rec.payout_total,
       COALESCE(v_rec.currency, 'EGP'), 'bank_transfer',
       'driver-settlement', 'pending',
       'Driver earnings payout (period ends ' || p_period_end::text || ')')
    RETURNING id INTO v_settlement_id;

    UPDATE public.platform_commissions
       SET status = 'settled',
           settlement_id = v_settlement_id,
           fulfilled_at = now(),
           updated_at = now()
     WHERE member_id = v_rec.driver_uid
       AND status IN ('computed')
       AND settlement_id IS NULL
       AND created_at < p_period_end;

    v_drivers := v_drivers + 1;
    v_commissions := v_commissions + (
      SELECT count(*) FROM public.platform_commissions
       WHERE settlement_id = v_settlement_id
    );
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'reason', CASE WHEN v_drivers = 0 THEN 'NO_PENDING' ELSE 'OK' END,
    'period_end', p_period_end,
    'drivers', v_drivers,
    'commissions', v_commissions
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.freeze_review_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.merchant_id IS DISTINCT FROM OLD.merchant_id
     OR NEW.product_id IS DISTINCT FROM OLD.product_id
     OR NEW.order_id IS DISTINCT FROM OLD.order_id THEN
    RAISE EXCEPTION 'review identity fields cannot be changed';
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.freeze_service_review_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.user_id is distinct from old.user_id
     or new.provider_id is distinct from old.provider_id
     or new.booking_id is distinct from old.booking_id
     or new.category_type is distinct from old.category_type then
    raise exception 'service review identity fields cannot be changed';
  end if;
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.geo_region_for_point(p_lat double precision, p_lon double precision, p_max_depth integer DEFAULT 2, p_tolerance_m double precision DEFAULT 25000)
 RETURNS TABLE(region_id uuid, code text, name_ar text, name_en text, type text, parent_region_id uuid, governorate_id uuid, governorate_code text, governorate_name_ar text, governorate_name_en text, confidence text, distance_m double precision)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pt geometry;
  v_region_id uuid;
  v_region_type text;
  v_conf text;
  v_dist double precision;
  v_child_id uuid;
  v_child_dist double precision;
  v_child_type text;
BEGIN
  IF p_lat IS NULL OR p_lon IS NULL
     OR p_lat < -90 OR p_lat > 90 OR p_lon < -180 OR p_lon > 180 THEN
    RETURN QUERY SELECT
      NULL::uuid, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::text,
      'INVALID', NULL::double precision;
    RETURN;
  END IF;

  v_pt := ST_SetSRID(ST_MakePoint(p_lon, p_lat), 4326);

  -- (1) point-in-polygon: deepest contained boundary
  SELECT b.region_id
    INTO v_region_id
    FROM public.geo_admin_boundaries b
   WHERE ST_Contains(b.geometry, v_pt)
   ORDER BY b.level DESC
   LIMIT 1;

  IF v_region_id IS NOT NULL THEN
    v_conf := 'HIGH';
    v_dist := 0;
  ELSE
    -- (2) nearest boundary within tolerance (GPS noise / snapping).
    -- geometry bbox prefilter in degrees (m/111320), exact order in meters.
    SELECT b.region_id,
           ST_Distance(b.geometry::geography, v_pt::geography)
      INTO v_region_id, v_dist
      FROM public.geo_admin_boundaries b
     WHERE ST_DWithin(b.geometry, v_pt, p_tolerance_m / 111320.0)
     ORDER BY ST_Distance(b.geometry::geography, v_pt::geography)
     LIMIT 1;
    IF v_region_id IS NOT NULL THEN
      v_conf := 'MEDIUM';
    ELSE
      -- (3) nearest governorate centroid fallback (Option E, LOW)
      SELECT b.region_id,
             ST_Distance(ST_PointOnSurface(b.geometry)::geography, v_pt::geography)
        INTO v_region_id, v_dist
        FROM public.geo_admin_boundaries b
       WHERE b.level = 1
       ORDER BY ST_Distance(ST_PointOnSurface(b.geometry)::geography, v_pt::geography)
       LIMIT 1;
      v_conf := 'LOW';
    END IF;
  END IF;

  IF v_region_id IS NULL THEN
    RETURN QUERY SELECT
      NULL::uuid, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::text,
      'UNVERIFIED', NULL::double precision;
    RETURN;
  END IF;

  SELECT r.type INTO v_region_type
    FROM public.regions r
   WHERE r.id = v_region_id;

  -- (4) centroid refinement to child granularity (optional, HIGH/MEDIUM only)
  IF p_max_depth >= 3
     AND v_conf IN ('HIGH','MEDIUM')
     AND v_region_type IN ('governorate','markaz','district','new_city') THEN
    SELECT r.id, r.type,
           ST_Distance(
             ST_SetSRID(
               ST_MakePoint(
                 (r.metadata->>'lon')::double precision,
                 (r.metadata->>'lat')::double precision), 4326)::geography,
             v_pt::geography)
      INTO v_child_id, v_child_type, v_child_dist
      FROM public.regions r
     WHERE r.parent_region_id = v_region_id
       AND r.type IN ('markaz','district','city','village','new_city','area')
       AND r.metadata->>'lat' IS NOT NULL
       AND r.metadata->>'lon' IS NOT NULL
     ORDER BY ST_Distance(
       ST_SetSRID(
         ST_MakePoint(
           (r.metadata->>'lon')::double precision,
           (r.metadata->>'lat')::double precision), 4326)::geography,
       v_pt::geography)
     LIMIT 1;

    IF v_child_id IS NOT NULL
       AND v_child_dist IS NOT NULL
       AND v_child_dist <= p_tolerance_m THEN
      v_region_id := v_child_id;
      v_region_type := v_child_type;
      v_dist := v_child_dist;
    END IF;
  END IF;

  -- (5) matched region + governorate ancestor
  RETURN QUERY
  WITH RECURSIVE chain AS (
    SELECT r.id, r.parent_region_id, r.code, r.type, r.name_ar, r.name_en,
           1 AS depth
      FROM public.regions r
     WHERE r.id = v_region_id
    UNION ALL
    SELECT r.id, r.parent_region_id, r.code, r.type, r.name_ar, r.name_en,
           c.depth + 1
      FROM public.regions r
      JOIN chain c ON r.id = c.parent_region_id
     WHERE c.depth < 10
  ),
  gov AS (
    SELECT ch.id, ch.code, ch.name_ar, ch.name_en FROM chain ch
     WHERE ch.type = 'governorate' LIMIT 1
  ),
  country AS (
    SELECT ch.id, ch.code, ch.name_ar, ch.name_en FROM chain ch
     WHERE ch.type = 'country' LIMIT 1
  )
  SELECT ch.id, ch.code, ch.name_ar, ch.name_en, ch.type, ch.parent_region_id,
         COALESCE((SELECT g.id FROM gov g), (SELECT c0.id FROM country c0)),
         COALESCE((SELECT g.code FROM gov g), (SELECT c0.code FROM country c0)),
         COALESCE((SELECT g.name_ar FROM gov g), (SELECT c0.name_ar FROM country c0)),
         COALESCE((SELECT g.name_en FROM gov g), (SELECT c0.name_en FROM country c0)),
         v_conf, v_dist
    FROM chain ch
   WHERE ch.depth = 1;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.geo_test_alpha(p_lat double precision, p_lon double precision)
 RETURNS TABLE(region_id uuid, code text, confidence text, distance_m double precision)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY SELECT NULL::uuid, NULL::text, 'X'::text, NULL::double precision;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.geo_test_beta(p_lat double precision, p_lon double precision, p_max_depth integer DEFAULT 2, p_tolerance_m double precision DEFAULT 25000)
 RETURNS TABLE(region_id uuid, code text, name_ar text, name_en text, type text, parent_region_id uuid, governorate_id uuid, governorate_code text, governorate_name_ar text, governorate_name_en text, confidence text, distance_m double precision)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pt geometry;
  v_region_id uuid;
  v_region_type text;
  v_conf text;
  v_dist double precision;
  v_child_id uuid;
  v_child_dist double precision;
  v_child_type text;
BEGIN
  IF p_lat IS NULL OR p_lon IS NULL OR p_lat < -90 OR p_lat > 90 OR p_lon < -180 OR p_lon > 180 THEN
  
  SELECT r.type INTO v_region_type
    FROM public.regions r
   WHERE r.id = v_region_id;

  IF p_max_depth >= 3
     AND v_conf IN ('HIGH','MEDIUM')
     AND v_region_type IN ('governorate','markaz','district','new_city') THEN
    SELECT r.id, r.type,
           ST_Distance(
             ST_SetSRID(
               ST_MakePoint(
                 (r.metadata->>'lon')::double precision,
                 (r.metadata->>'lat')::double precision), 4326)::geography,
             v_pt::geography)
      INTO v_child_id, v_child_type, v_child_dist
      FROM public.regions r
     WHERE r.parent_region_id = v_region_id
       AND r.type IN ('markaz','district','city','village','new_city','area')
       AND r.metadata->>'lat' IS NOT NULL
       AND r.metadata->>'lon' IS NOT NULL
     ORDER BY ST_Distance(
       ST_SetSRID(
         ST_MakePoint(
           (r.metadata->>'lon')::double precision,
           (r.metadata->>'lat')::double precision), 4326)::geography,
       v_pt::geography)
     LIMIT 1;

    IF v_child_id IS NOT NULL
       AND v_child_dist IS NOT NULL
       AND v_child_dist <= p_tolerance_m THEN
      v_region_id := v_child_id;
      v_region_type := v_child_type;
      v_dist := v_child_dist;
    END IF;
  END IF;

  RETURN QUERY SELECT NULL::uuid, NULL::text, NULL::text, NULL::text, NULL::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::text, 'INVALID', NULL::double precision;
    RETURN;
  END IF;
  v_pt := ST_SetSRID(ST_MakePoint(p_lon, p_lat), 4326);

  SELECT b.region_id
    INTO v_region_id
    FROM public.geo_admin_boundaries b
   WHERE ST_Contains(b.geometry, v_pt)
   ORDER BY b.level DESC
   LIMIT 1;
  IF v_region_id IS NOT NULL THEN
    v_conf := 'HIGH';
    v_dist := 0;
  ELSE
    SELECT b.region_id,
           ST_Distance(b.geometry::geography, v_pt::geography)
      INTO v_region_id, v_dist
      FROM public.geo_admin_boundaries b
     WHERE ST_DWithin(b.geometry, v_pt, p_tolerance_m / 111320.0)
     ORDER BY ST_Distance(b.geometry::geography, v_pt::geography)
     LIMIT 1;
    IF v_region_id IS NOT NULL THEN
      v_conf := 'MEDIUM';
    ELSE
      SELECT b.region_id,
             ST_Distance(ST_PointOnSurface(b.geometry)::geography, v_pt::geography)
        INTO v_region_id, v_dist
        FROM public.geo_admin_boundaries b
       WHERE b.level = 1
       ORDER BY ST_Distance(ST_PointOnSurface(b.geometry)::geography, v_pt::geography)
       LIMIT 1;
      v_conf := 'LOW';
    END IF;
  END IF;
  IF v_region_id IS NULL THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, NULL::text, NULL::text, NULL::text, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::text, 'UNVERIFIED', NULL::double precision;
    RETURN;
  END IF;
  RETURN QUERY
  WITH RECURSIVE chain AS (
    SELECT r.id, r.parent_region_id, r.code, r.type, r.name_ar, r.name_en, 1 AS depth
      FROM public.regions r
     WHERE r.id = '00000000-0000-0000-0000-000000000001'
    UNION ALL
    SELECT r.id, r.parent_region_id, r.code, r.type, r.name_ar, r.name_en, c.depth + 1
      FROM public.regions r
      JOIN chain c ON r.id = c.parent_region_id
     WHERE c.depth < 10
  ),
  gov AS (
    SELECT id, code, name_ar, name_en FROM chain WHERE type = 'governorate' LIMIT 1
  ),
  country AS (
    SELECT id, code, name_ar, name_en FROM chain WHERE type = 'country' LIMIT 1
  )
  SELECT c.id, c.code, c.name_ar, c.name_en, c.type, c.parent_region_id,
         COALESCE((SELECT id FROM gov), (SELECT id FROM country)),
         COALESCE((SELECT code FROM gov), (SELECT code FROM country)),
         COALESCE((SELECT name_ar FROM gov), (SELECT name_ar FROM country)),
         COALESCE((SELECT name_en FROM gov), (SELECT name_en FROM country)),
         v_conf, v_dist
    FROM chain c
   WHERE c.depth = 1;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_active_campaigns(p_locale text DEFAULT 'ar'::text)
 RETURNS TABLE(id uuid, code text, campaign_type text, priority text, status text, name_ar text, name_en text, subtitle_ar text, subtitle_en text, description_ar text, description_en text, starts_at timestamp with time zone, ends_at timestamp with time zone, published_at timestamp with time zone, image_path text, cta jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_region uuid;
BEGIN
  IF v_uid IS NOT NULL THEN
    v_region := public._member_region_id(v_uid);
  END IF;

  RETURN QUERY
  SELECT c.id,
         c.code,
         c.campaign_type,
         c.priority,
         c.status,
         c.name_ar,
         c.name_en,
         c.subtitle_ar,
         c.subtitle_en,
         c.description_ar,
         c.description_en,
         c.starts_at,
         c.ends_at,
         c.published_at,
         b.image_path,
         b.cta
    FROM public.campaigns c
    LEFT JOIN LATERAL (
      SELECT cb.image_path, cb.cta
        FROM public.campaign_banners cb
       WHERE cb.campaign_id = c.id
         AND cb.placement = 'home_carousel'
         AND cb.is_active
         AND cb.locale = p_locale
       ORDER BY cb.priority ASC, cb.created_at DESC
       LIMIT 1
    ) b ON true
   WHERE c.status = 'published'
     AND c.archived_at IS NULL
     AND (c.starts_at IS NULL OR c.starts_at <= now())
     AND (c.ends_at IS NULL OR c.ends_at >= now())
     AND (
       -- authenticated: 042 region scoping unchanged
       (v_uid IS NOT NULL AND public._campaign_region_visible(c.id, v_region))
       OR
       -- guests (anon): national app-wide banners only
       (v_uid IS NULL AND EXISTS (
         SELECT 1
           FROM public.campaign_targets nt
          WHERE nt.campaign_id = c.id
            AND nt.region_id IS NULL
       ))
     )
   ORDER BY c.priority DESC, c.published_at DESC NULLS LAST, c.created_at DESC;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_active_receiving_accounts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_agg(jsonb_build_object(
    'method', method,
    'display_name', display_name,
    'account_identifier', account_identifier,
    'instructions', instructions,
    'display_order', display_order
  ) ORDER BY display_order) INTO v_result
  FROM public.financial_receiving_accounts
  WHERE is_active = true;

  RETURN jsonb_build_object(
    'ok', true,
    'accounts', COALESCE(v_result, '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_admin_analytics(date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_from TIMESTAMPTZ := COALESCE(date_from, NOW() - INTERVAL '30 days');
  v_to   TIMESTAMPTZ := COALESCE(date_to, NOW());
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  RETURN jsonb_build_object(
    -- All-time true totals (key names preserved for existing callers)
    'total_orders',    (SELECT COUNT(*) FROM public.orders),
    'total_revenue',   (SELECT COALESCE(SUM(total_amount), 0) FROM public.orders WHERE status = 'delivered'),
    'total_users',     (SELECT COUNT(*) FROM public.users),
    'total_drivers',   (SELECT COUNT(*) FROM public.drivers),
    'total_merchants', (SELECT COUNT(*) FROM public.merchants),
    -- Windowed values, explicitly labeled
    'window_orders',        (SELECT COUNT(*) FROM public.orders WHERE created_at BETWEEN v_from AND v_to),
    'window_revenue',       (SELECT COALESCE(SUM(total_amount), 0) FROM public.orders WHERE status = 'delivered' AND created_at BETWEEN v_from AND v_to),
    'window_new_users',     (SELECT COUNT(*) FROM public.users WHERE created_at BETWEEN v_from AND v_to),
    'window_new_drivers',   (SELECT COUNT(*) FROM public.drivers WHERE created_at BETWEEN v_from AND v_to),
    'window_new_merchants', (SELECT COUNT(*) FROM public.merchants WHERE created_at BETWEEN v_from AND v_to),
    -- POS walk-in revenue (status 'completed' excludes voided sales)
    'pos_revenue_total',  (SELECT COALESCE(SUM(total_amount), 0) FROM public.pos_sales WHERE status = 'completed'),
    'pos_sales_count',    (SELECT COUNT(*) FROM public.pos_sales WHERE status = 'completed'),
    'pos_revenue_window', (SELECT COALESCE(SUM(total_amount), 0) FROM public.pos_sales WHERE status = 'completed' AND created_at BETWEEN v_from AND v_to),
    'window_from', v_from,
    'window_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_admin_audit_history(p_admin_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_rows jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;
  IF NOT (public._is_owner_uid(v_actor)
          OR v_actor = p_admin_id
          OR public.is_supervisor_of(v_actor, p_admin_id)) THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', id,
           'action', action,
           'resource', resource,
           'resource_id', resource_id,
           'details', details,
           'timestamp', timestamp)
         ORDER BY timestamp DESC), '[]'::jsonb)
    INTO v_rows
    FROM public.activity_logs
   WHERE user_id = p_admin_id::text
      OR (resource = 'admin_management' AND resource_id = p_admin_id::text)
      OR (resource = 'admin_permission_grants' AND resource_id = p_admin_id::text)
      OR (resource = 'admin_region_assignments' AND resource_id = p_admin_id::text);

  RETURN v_rows;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_admin_permissions(p_admin_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_grants text[];
  v_default text[];
  v_effective text[];
  v_all text[] := ARRAY[
    'ADMIN_CREATE','ADMIN_ASSIGN','ADMIN_ROLE_ASSIGN','ADMIN_REGION_ASSIGN',
    'ADMIN_SUPERVISOR_ASSIGN','ADMIN_SUSPEND',
    'MEMBER_VIEW','MEMBER_VIEW_LOCATION','MEMBER_VIEW_CHAT_HISTORY',
    'MEMBER_VIEW_COMPLAINTS','MEMBER_VIEW_TIMELINE','MEMBER_VIEW_DOCUMENTS',
    'MEMBER_MODERATE','MEMBER_WARN','MEMBER_RESTRICT','MEMBER_SUSPEND',
    'MEMBER_BAN','MEMBER_DELETE',
    'EMERGENCY_VIEW','EMERGENCY_AUDIO',
    'OFFER_CREATE','OFFER_REVIEW','OFFER_APPROVE','OFFER_PUBLISH'
  ];
  v_default_set text[] := ARRAY[
    'ADMIN_CREATE','ADMIN_ASSIGN','ADMIN_ROLE_ASSIGN','ADMIN_REGION_ASSIGN',
    'ADMIN_SUPERVISOR_ASSIGN','ADMIN_SUSPEND',
    'MEMBER_VIEW','MEMBER_VIEW_LOCATION','MEMBER_VIEW_CHAT_HISTORY',
    'MEMBER_VIEW_COMPLAINTS','MEMBER_VIEW_TIMELINE',
    'MEMBER_MODERATE','MEMBER_WARN','MEMBER_RESTRICT','MEMBER_SUSPEND',
    'EMERGENCY_VIEW','OFFER_CREATE','OFFER_REVIEW'
  ];
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('authorized', false, 'grants', '[]'::jsonb, 'effective', '[]'::jsonb);
  END IF;
  IF NOT (public._is_owner_uid(v_actor)
          OR v_actor = p_admin_id
          OR public.is_supervisor_of(v_actor, p_admin_id)) THEN
    RETURN jsonb_build_object('authorized', false, 'grants', '[]'::jsonb, 'effective', '[]'::jsonb);
  END IF;

  SELECT COALESCE(array_agg(permission ORDER BY permission), ARRAY[]::text[])
    INTO v_grants
    FROM public.admin_permission_grants
   WHERE admin_id = p_admin_id;

  IF public._is_owner_uid(p_admin_id) THEN
    v_effective := v_all;
  ELSIF public._is_active_admin_uid(p_admin_id) THEN
    v_effective := v_default_set || v_grants;
  ELSE
    v_effective := v_grants;
  END IF;

  SELECT array_agg(DISTINCT x) INTO v_effective FROM unnest(v_effective) x;

  RETURN jsonb_build_object(
    'authorized', true,
    'grants', to_jsonb(v_grants),
    'effective', to_jsonb(v_effective)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_admin_profile(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid;
  v_role text;
  v_region_name text;
  v_earnings numeric := 0;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT id, role INTO v_uid, v_role
    FROM public.users
   WHERE lower(email) = lower(btrim(p_email));
  IF NOT FOUND THEN
    RAISE EXCEPTION 'User not found';
  END IF;
  IF v_uid <> auth.uid() AND NOT public._is_owner_uid(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(NULLIF(r.name_en, ''), r.name_ar)
    INTO v_region_name
    FROM public.admin_region_assignments a
    LEFT JOIN public.regions r ON r.id = a.region_id
   WHERE a.admin_id = v_uid
   ORDER BY a.created_at DESC
   LIMIT 1;

  IF to_regclass('public.platform_commissions') IS NOT NULL THEN
    SELECT COALESCE(SUM(commission_amount), 0)
      INTO v_earnings
      FROM public.platform_commissions
     WHERE member_id = v_uid AND status = 'fulfilled';
  END IF;

  RETURN jsonb_build_object(
    'email', p_email,
    'role', v_role,
    'is_owner', public._is_owner_uid(v_uid),
    'region_name', v_region_name,
    'total_earnings', v_earnings
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_all_admins()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rows jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'email', u.email,
           'role', u.role,
           'region_name', r.name_en,
           'is_active', COALESCE(m.is_active, true),
           'supervisor_email', su.email,
           'created_at', u.created_at)
         ORDER BY u.created_at), '[]'::jsonb)
    INTO v_rows
    FROM public.users u
    LEFT JOIN public.admin_management m ON m.admin_id = u.id
    LEFT JOIN public.users su ON su.id = m.supervisor_id
    LEFT JOIN LATERAL (
      SELECT rr.name_en
        FROM public.admin_region_assignments aa
        LEFT JOIN public.regions rr ON rr.id = aa.region_id
       WHERE aa.admin_id = u.id
       ORDER BY aa.created_at DESC
       LIMIT 1
    ) r ON true
   WHERE u.role IN ('owner','admin')
      OR m.admin_id IS NOT NULL;

  RETURN v_rows;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_commission_rate(p_account_type text, p_service_category text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rate numeric;
BEGIN
  -- 3. specific account override (highest specificity)
  IF p_user_id IS NOT NULL THEN
    SELECT c.rate INTO v_rate
      FROM public.commission_rules c
     WHERE c.entity_type = 'account'
       AND c.entity_key = p_user_id::text
       AND c.is_active
       AND c.effective_from <= CURRENT_DATE
       AND (c.effective_to IS NULL OR c.effective_to >= CURRENT_DATE)
     ORDER BY c.effective_from DESC, c.created_at DESC
     LIMIT 1;
    IF v_rate IS NOT NULL THEN
      RETURN v_rate;
    END IF;
  END IF;

  -- 2. service_category
  IF p_service_category IS NOT NULL THEN
    SELECT c.rate INTO v_rate
      FROM public.commission_rules c
     WHERE c.entity_type = 'service_category'
       AND c.entity_key = p_service_category
       AND c.is_active
       AND c.effective_from <= CURRENT_DATE
       AND (c.effective_to IS NULL OR c.effective_to >= CURRENT_DATE)
     ORDER BY c.effective_from DESC, c.created_at DESC
     LIMIT 1;
    IF v_rate IS NOT NULL THEN
      RETURN v_rate;
    END IF;
  END IF;

  -- 1. account_type default
  SELECT c.rate INTO v_rate
    FROM public.commission_rules c
   WHERE c.entity_type = 'account_type'
     AND c.entity_key = COALESCE(p_account_type, 'customer')
     AND c.is_active
     AND c.effective_from <= CURRENT_DATE
     AND (c.effective_to IS NULL OR c.effective_to >= CURRENT_DATE)
   ORDER BY c.effective_from DESC, c.created_at DESC
   LIMIT 1;
  RETURN v_rate;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_driver_performance(p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_total_trips INTEGER;
  v_completed_trips INTEGER;
  v_cancelled_by_driver INTEGER;
  v_total_offers INTEGER;
  v_acceptance_count INTEGER;
  v_avg_rating DECIMAL;
  v_today_earnings DECIMAL;
  v_week_earnings DECIMAL;
  v_month_earnings DECIMAL;
  v_balance DECIMAL;
  v_bonus DECIMAL;
  v_incentive DECIMAL;
  v_pending_withdrawals DECIMAL;
BEGIN
  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = p_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN');
  END IF;

  SELECT COALESCE(total_trips, 0) INTO v_total_trips FROM drivers WHERE id = p_driver_id;

  SELECT COUNT(*) INTO v_completed_trips
  FROM rides WHERE driver_id = p_driver_id AND status = 'completed';

  SELECT COUNT(*) INTO v_cancelled_by_driver
  FROM rides WHERE driver_id = p_driver_id AND status = 'cancelled' AND cancelled_by = 'driver';

  SELECT COUNT(*) INTO v_total_offers
  FROM ride_requests WHERE driver_id = p_driver_id;

  SELECT COUNT(*) INTO v_acceptance_count
  FROM ride_requests WHERE driver_id = p_driver_id AND status = 'accepted';

  SELECT COALESCE(rating, 0) INTO v_avg_rating FROM drivers WHERE id = p_driver_id;

  SELECT COALESCE(SUM(amount), 0) INTO v_today_earnings
  FROM driver_earnings WHERE driver_id = p_driver_id
    AND created_at >= date_trunc('day', NOW());

  SELECT COALESCE(SUM(amount), 0) INTO v_week_earnings
  FROM driver_earnings WHERE driver_id = p_driver_id
    AND created_at >= date_trunc('week', NOW());

  SELECT COALESCE(SUM(amount), 0) INTO v_month_earnings
  FROM driver_earnings WHERE driver_id = p_driver_id
    AND created_at >= date_trunc('month', NOW());

  SELECT COALESCE(earnings_balance, 0) INTO v_balance FROM drivers WHERE id = p_driver_id;

  SELECT COALESCE(SUM(amount), 0) INTO v_bonus
  FROM driver_earnings WHERE driver_id = p_driver_id AND type = 'bonus';

  SELECT COALESCE(SUM(amount), 0) INTO v_incentive
  FROM driver_earnings WHERE driver_id = p_driver_id AND type = 'incentive';

  SELECT COALESCE(SUM(amount), 0) INTO v_pending_withdrawals
  FROM withdrawal_requests WHERE driver_id = p_driver_id AND status = 'pending';

  RETURN jsonb_build_object(
    'total_trips', v_total_trips,
    'completed_trips', v_completed_trips,
    'cancelled_trips', v_cancelled_by_driver,
    'rating', v_avg_rating,
    'acceptance_rate', CASE WHEN v_total_offers > 0 THEN ROUND(v_acceptance_count::DECIMAL / v_total_offers * 100, 1) ELSE 100 END,
    'cancellation_rate', CASE WHEN (v_completed_trips + v_cancelled_by_driver) > 0 THEN ROUND(v_cancelled_by_driver::DECIMAL / (v_completed_trips + v_cancelled_by_driver) * 100, 1) ELSE 0 END,
    'today_rides', (SELECT COUNT(*) FROM rides WHERE driver_id = p_driver_id AND status = 'completed' AND completed_at >= date_trunc('day', NOW())),
    'today_earnings', v_today_earnings,
    'week_earnings', v_week_earnings,
    'month_earnings', v_month_earnings,
    'balance', v_balance,
    'bonus_balance', v_bonus,
    'incentive_balance', v_incentive,
    'pending_withdrawals', v_pending_withdrawals,
    'currency', 'EGP'
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_driver_wallet_detail(p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_balance DECIMAL;
  v_bonus DECIMAL;
  v_incentive DECIMAL;
  v_pending_withdrawals DECIMAL;
  v_total_withdrawn DECIMAL;
BEGIN
  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = p_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('error', 'FORBIDDEN');
  END IF;

  SELECT COALESCE(earnings_balance, 0) INTO v_balance FROM drivers WHERE id = p_driver_id;

  SELECT COALESCE(SUM(amount), 0) INTO v_bonus
  FROM driver_earnings WHERE driver_id = p_driver_id AND type = 'bonus';

  SELECT COALESCE(SUM(amount), 0) INTO v_incentive
  FROM driver_earnings WHERE driver_id = p_driver_id AND type = 'incentive';

  SELECT COALESCE(SUM(amount), 0) INTO v_pending_withdrawals
  FROM withdrawal_requests WHERE driver_id = p_driver_id AND status = 'pending';

  SELECT COALESCE(SUM(amount), 0) INTO v_total_withdrawn
  FROM withdrawal_requests WHERE driver_id = p_driver_id AND status IN ('approved','paid');

  RETURN jsonb_build_object(
    'balance', COALESCE(v_balance, 0),
    'bonus_balance', v_bonus,
    'incentive_balance', v_incentive,
    'pending_withdrawals', v_pending_withdrawals,
    'total_withdrawn', v_total_withdrawn,
    'currency', 'EGP'
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_escalation_events(p_complaint_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rows jsonb;
  v_region uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF p_complaint_id IS NOT NULL THEN
    SELECT public._member_region_id(c.complainant_id)
      INTO v_region FROM public.complaints c WHERE c.id = p_complaint_id;
    IF NOT public.has_permission('MEMBER_VIEW_COMPLAINTS', v_region) THEN
      RAISE EXCEPTION 'Not authorized for this complaint region';
    END IF;
    SELECT jsonb_agg(to_jsonb(e) ORDER BY e.created_at DESC)
      INTO v_rows
      FROM public.escalation_events e
     WHERE e.entity_type = 'complaint' AND e.entity_id = p_complaint_id;
  ELSE
    SELECT jsonb_agg(to_jsonb(e) ORDER BY e.created_at DESC)
      INTO v_rows
      FROM public.escalation_events e
     WHERE e.entity_type = 'complaint'
       AND (
         public.has_permission('MEMBER_VIEW_COMPLAINTS', NULL)
         OR EXISTS (
           SELECT 1 FROM public.complaints c
           WHERE c.id = e.entity_id
             AND public.has_permission(
                   'MEMBER_VIEW_COMPLAINTS',
                   public._member_region_id(c.complainant_id))
         )
       );
  END IF;

  RETURN COALESCE(v_rows, '[]'::jsonb);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_live_share_by_token(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.live_share_sessions%rowtype;
begin
  select * into v_row
    from public.live_share_sessions
   where share_token = btrim(coalesce(p_token, ''))
     and is_active = true
     and expires_at > now()
   limit 1;

  if v_row.id is null then
    return null;
  end if;

  return jsonb_build_object(
    'id', v_row.id,
    'ride_id', v_row.ride_id,
    'expires_at', v_row.expires_at
  );
end;
$function$
;
CREATE OR REPLACE FUNCTION public.get_live_share_session(p_ride_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session RECORD;
  v_ride RECORD;
BEGIN
  SELECT * INTO v_ride FROM rides WHERE id = p_ride_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Authorization: rider, driver, or admin/owner
  IF NOT (
    v_ride.rider_id = auth.uid()
    OR EXISTS (SELECT 1 FROM public.drivers d WHERE d.id = v_ride.driver_id AND d.user_id = auth.uid())
    OR public._is_owner_uid(auth.uid())
    OR public.is_admin()
  ) THEN
    RETURN NULL;
  END IF;

  SELECT id, share_token, expires_at, is_active, created_at
  INTO v_session
  FROM live_share_sessions
  WHERE ride_id = p_ride_id AND is_active = true AND expires_at > NOW()
  ORDER BY created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'session_id', v_session.id,
    'share_token', v_session.share_token,
    'expires_at', v_session.expires_at,
    'is_active', v_session.is_active
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_member_ops_profile(p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$

DECLARE
  v_uid          uuid := auth.uid();
  v_member_regid uuid;
  v_can_loc      boolean;
  v_can_chat     boolean;
  v_can_docs     boolean;
  v_can_mod      boolean;
  v_exists       boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT region_id INTO v_member_regid
    FROM public.user_region_preferences
   WHERE user_id = p_member_id
   ORDER BY updated_at DESC LIMIT 1;

  IF NOT public.has_permission('MEMBER_VIEW', v_member_regid) THEN
    RETURN NULL;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.users WHERE id = p_member_id
  ) INTO v_exists;
  IF NOT v_exists THEN
    RETURN NULL;
  END IF;

  v_can_loc  := public.has_permission('MEMBER_VIEW_LOCATION', v_member_regid);
  v_can_chat := public.has_permission('MEMBER_VIEW_CHAT_HISTORY', v_member_regid);
  v_can_docs := public.has_permission('MEMBER_VIEW_DOCUMENTS', v_member_regid);
  v_can_mod  := public.has_permission('MEMBER_MODERATE', v_member_regid);

  RETURN jsonb_build_object(
    'member', (
      SELECT jsonb_build_object(
        'id', u.id, 'full_name', u.full_name, 'email', u.email, 'phone', u.phone,
        'avatar_url', u.avatar_url, 'username', u.username,
        'role', u.role, 'user_type', u.user_type,
        'account_status', COALESCE(u.account_status, 'active'),
        'verification_status', COALESCE(u.verification_status, 'unverified'),
        'language', u.language, 'is_onboarded', u.is_onboarded,
        'date_of_birth', u.date_of_birth,
        'created_at', u.created_at, 'updated_at', u.updated_at)
        FROM public.users u WHERE u.id = p_member_id
    ),
    'region', (
      SELECT jsonb_build_object(
        'region_id', up.region_id,
        'label', public._region_label_path(up.region_id))
        FROM public.user_region_preferences up
       WHERE up.user_id = p_member_id ORDER BY up.updated_at DESC LIMIT 1
    ),
    'location', CASE WHEN v_can_loc THEN (
      SELECT jsonb_build_object(
        'latitude', l.latitude, 'longitude', l.longitude,
        'accuracy', l.accuracy, 'recorded_at', l.recorded_at,
        'is_moving', l.is_moving)
        FROM public.location_updates l
       WHERE l.user_id = p_member_id
       ORDER BY l.recorded_at DESC LIMIT 1)
      ELSE NULL END,
    'last_seen', (
      SELECT GREATEST(
        (SELECT MAX(recorded_at) FROM public.location_updates lu WHERE lu.user_id = p_member_id),
        (SELECT MAX(last_seen_at) FROM public.notification_tokens nt WHERE nt.user_id = p_member_id))
    ),
    'driver', (
      SELECT jsonb_build_object(
        'id', id, 'vehicle_type', vehicle_type, 'vehicle_plate', vehicle_plate,
        'is_online', is_online, 'is_verified', is_verified,
        'verification_status', verification_status,
        'status', status, 'rating', rating, 'total_deliveries', total_deliveries,
        'total_trips', total_trips, 'earnings_balance', earnings_balance,
        'background_check_status', background_check_status,
        'service_types', service_types)
        FROM public.drivers WHERE user_id = p_member_id
    ),
    'merchants', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id, 'name', name, 'type', type, 'status', status,
        'rating', rating, 'total_orders', total_orders,
        'delivery_fee', delivery_fee, 'min_order', min_order,
        'is_featured', is_featured))
        FROM public.merchants WHERE owner_user_id = p_member_id)
    , '[]'::jsonb),
    'providers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id, 'name', name, 'category_type', category_type,
        'is_verified', is_verified, 'is_available', is_available,
        'rating', rating, 'rating_count', rating_count,
        'hourly_rate', hourly_rate, 'fixed_price_min', fixed_price_min,
        'fixed_price_max', fixed_price_max, 'city', city))
        FROM public.service_providers WHERE user_id = p_member_id)
    , '[]'::jsonb),
    'orders', COALESCE((
      SELECT jsonb_agg(j)
        FROM (
          SELECT jsonb_build_object(
            'id', id, 'merchant_id', merchant_id, 'driver_id', driver_id,
            'status', status, 'payment_status', payment_status,
            'total_amount', total_amount, 'created_at', created_at) AS j
          FROM public.orders WHERE user_id = p_member_id
          ORDER BY created_at DESC LIMIT 10) s)
    , '[]'::jsonb),
    'rides', COALESCE((
      SELECT jsonb_agg(j)
        FROM (
          SELECT jsonb_build_object(
            'id', id, 'service_type', service_type, 'status', status,
            'fare', fare, 'driver_rating', driver_rating, 'created_at', created_at) AS j
          FROM public.rides WHERE rider_id = p_member_id
          ORDER BY created_at DESC LIMIT 10) s)
    , '[]'::jsonb),
    'bookings', COALESCE((
      SELECT jsonb_agg(j)
        FROM (
          SELECT jsonb_build_object(
            'id', id, 'category_type', category_type, 'status', status,
            'provider_name', provider_name, 'final_price', final_price,
            'created_at', created_at) AS j
          FROM public.service_bookings WHERE user_id = p_member_id
          ORDER BY created_at DESC LIMIT 10) s)
    , '[]'::jsonb),
    'wallet', (
      SELECT jsonb_build_object(
        'balance', w.balance, 'currency', w.currency,
        'transactions', COALESCE((
          SELECT jsonb_agg(j)
            FROM (
              SELECT jsonb_build_object(
                'id', t.id, 'type', t.type, 'amount', t.amount,
                'reference_type', t.reference_type, 'balance_after', t.balance_after,
                'created_at', t.created_at) AS j
              FROM public.wallet_transactions t WHERE t.wallet_id = w.id
              ORDER BY t.created_at DESC LIMIT 10) s)
        , '[]'::jsonb))
        FROM public.wallets w WHERE w.user_id = p_member_id
    ),
    'financials', (
      SELECT jsonb_build_object(
        'gross_orders', COALESCE(SUM(o.total_amount), 0),
        'orders_count', COUNT(o.id),
        'commission_rate', public.get_commission_rate(u.user_type::text, NULL::text),
        'commission_estimated', ROUND(COALESCE(SUM(o.total_amount), 0)
                                  * COALESCE(public.get_commission_rate(u.user_type::text, NULL::text), 0) / 100.0, 2),
        'commissions', COALESCE((
          SELECT jsonb_agg(j)
            FROM (
              SELECT jsonb_build_object(
                'reference_type', c.reference_type, 'gross_amount', c.gross_amount,
                'commission_rate', c.commission_rate, 'commission_amount', c.commission_amount,
                'net_amount', c.net_amount, 'status', c.status, 'created_at', c.created_at) AS j
              FROM public.platform_commissions c WHERE c.member_id = p_member_id
              ORDER BY c.created_at DESC LIMIT 10) s)
        , '[]'::jsonb))
        FROM public.users u
        LEFT JOIN public.orders o ON o.user_id = u.id
       WHERE u.id = p_member_id
       GROUP BY u.user_type
    ),
    'active_sanctions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id, 'sanction_type', sanction_type, 'reason', reason,
        'amount', amount, 'start_date', start_date, 'end_date', end_date,
        'is_active', is_active, 'issued_by', issued_by, 'created_at', created_at))
        FROM public.sanctions
       WHERE target_user_id = p_member_id AND is_active)
    , '[]'::jsonb),
    'complaints', (
      SELECT jsonb_build_object(
        'filed_count', (SELECT COUNT(*) FROM public.complaints WHERE complainant_id = p_member_id),
        'received_count', (SELECT COUNT(*) FROM public.complaints WHERE respondent_id = p_member_id),
        'related', COALESCE((
          SELECT jsonb_agg(j)
            FROM (
              SELECT jsonb_build_object(
                'id', id, 'complaint_type', complaint_type, 'category', category,
                'status', status, 'priority', priority, 'subject', subject, 'created_at', created_at) AS j
              FROM public.complaints
             WHERE complainant_id = p_member_id OR respondent_id = p_member_id
             ORDER BY created_at DESC LIMIT 10) s)
        , '[]'::jsonb))
    ),
    'support', (
      SELECT jsonb_build_object(
        'rooms_count', (SELECT COUNT(*) FROM public.chat_rooms
                         WHERE p_member_id = ANY(participant_ids)),
        'rooms', COALESCE((
          SELECT jsonb_agg(j)
            FROM (
              SELECT jsonb_build_object(
                'id', id, 'room_type', room_type, 'status', status,
                'priority', priority, 'last_message_at', last_message_at, 'created_at', created_at) AS j
              FROM public.chat_rooms
             WHERE p_member_id = ANY(participant_ids)
             ORDER BY last_message_at DESC NULLS LAST LIMIT 10) s)
        , '[]'::jsonb))
    ),
    'timeline', COALESCE((
      SELECT jsonb_agg(j)
        FROM (
          SELECT jsonb_build_object(
            'id', id, 'event_type', event_type, 'title', title,
            'payload', payload, 'created_at', created_at) AS j
          FROM public.member_events WHERE user_id = p_member_id
          ORDER BY created_at DESC LIMIT 20) s)
    , '[]'::jsonb),
    'permissions', jsonb_build_object(
      'can_view_location',   v_can_loc,
      'can_view_chat',       v_can_chat,
      'can_view_documents',  v_can_docs,
      'can_moderate',        v_can_mod
    )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_member_profile(p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row record;
  v_region uuid;
  v_loc boolean;
  v_docs boolean;
  v_support boolean;
  v_mod boolean;
  v_tl boolean;
  v_em boolean;
  v_region_name text;
  v_docs_row record;
  v_support_rows jsonb;
  v_mods jsonb;
  v_events jsonb;
  v_sos jsonb;
  v_result jsonb;
BEGIN
  SELECT role, user_type, verification_status, account_status, language, created_at, updated_at
  INTO v_row
  FROM public.users WHERE id = p_member_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;

  v_region := public._member_region_id(p_member_id);
  IF NOT public.has_permission('MEMBER_VIEW', v_region) THEN
    RAISE EXCEPTION 'Not authorized for this member';
  END IF;
  v_loc := public.has_permission('MEMBER_VIEW_LOCATION', v_region);
  v_docs := public.has_permission('MEMBER_VIEW_DOCUMENTS', v_region);
  v_support := public.has_permission('MEMBER_VIEW_CHAT_HISTORY', v_region);
  v_mod := public.has_permission('MEMBER_VIEW_COMPLAINTS', v_region)
           OR public.has_permission('MEMBER_MODERATE', v_region);
  v_tl := public.has_permission('MEMBER_VIEW_TIMELINE', v_region);
  v_em := public.has_permission('EMERGENCY_VIEW', v_region);

  v_result := jsonb_build_object(
    'member_id', p_member_id::text,
    'basic', jsonb_build_object(
      'role', v_row.role, 'user_type', v_row.user_type,
      'verification_status', v_row.verification_status,
      'account_status', v_row.account_status,
      'language', v_row.language,
      'created_at', v_row.created_at,
      'updated_at', v_row.updated_at));

  IF v_loc THEN
    SELECT r.name_en INTO v_region_name
    FROM public.user_region_preferences p
    LEFT JOIN public.regions r ON r.id = p.region_id
    WHERE p.user_id = p_member_id
    ORDER BY p.updated_at DESC
    LIMIT 1;
    v_result := v_result || jsonb_build_object(
      'location', jsonb_build_object('region_id', v_region, 'region_name', v_region_name));
  END IF;

  IF v_docs THEN
    SELECT id_card_url, trade_license_url, driving_license_url, profile_photo_url
    INTO v_docs_row
    FROM public.users WHERE id = p_member_id;
    v_result := v_result || jsonb_build_object(
      'documents', jsonb_build_object(
        'id_card_url', v_docs_row.id_card_url,
        'trade_license_url', v_docs_row.trade_license_url,
        'driving_license_url', v_docs_row.driving_license_url,
        'profile_photo_url', v_docs_row.profile_photo_url));
  END IF;

  -- Support-chat section lights up when support_rooms lands (master schema).
  IF v_support AND to_regclass('public.support_rooms') IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(
             jsonb_build_object('room_id', sr.id::text, 'created_at', sr.created_at)
             ORDER BY sr.created_at DESC), '[]'::jsonb)
    INTO v_support_rows
    FROM public.support_rooms sr
    WHERE sr.customer_id = p_member_id;
    v_result := v_result || jsonb_build_object('support', v_support_rows);
  END IF;

  IF v_mod THEN
    v_mods := jsonb_build_object(
      'complaints',
      (SELECT count(*) FROM public.complaints c
       WHERE c.respondent_id = p_member_id OR c.complainant_id = p_member_id),
      'sanctions',
      (SELECT COALESCE(jsonb_agg(
               jsonb_build_object('sanction_type', s.sanction_type, 'reason', s.reason,
                                  'start_date', s.start_date, 'end_date', s.end_date,
                                  'action_status', s.action_status)
               ORDER BY s.created_at DESC), '[]'::jsonb)
       FROM public.sanctions s WHERE s.target_user_id = p_member_id));
    v_result := v_result || jsonb_build_object('moderation', v_mods);
  END IF;

  IF v_tl THEN
    v_events := (SELECT COALESCE(jsonb_agg(
                   jsonb_build_object('event_type', e.event_type, 'created_at', e.created_at)
                   ORDER BY e.created_at DESC), '[]'::jsonb)
                 FROM (SELECT e.event_type, e.created_at
                       FROM public.member_events e
                       WHERE e.user_id = p_member_id
                       ORDER BY e.created_at DESC LIMIT 10) e);
    v_result := v_result || jsonb_build_object('timeline_summary', v_events);
  END IF;

  IF v_em THEN
    v_sos := (SELECT COALESCE(jsonb_agg(
                jsonb_build_object('id', a.id::text, 'alert_type', a.alert_type,
                                   'status', a.status, 'created_at', a.created_at)
                ORDER BY a.created_at DESC), '[]'::jsonb)
              FROM (SELECT a.id, a.alert_type, a.status, a.created_at
                    FROM public.sos_alerts a
                    WHERE a.user_id = p_member_id
                    ORDER BY a.created_at DESC LIMIT 10) a);
    v_result := v_result || jsonb_build_object('emergency', v_sos);
  END IF;

  v_result := v_result || jsonb_build_object('access', jsonb_build_object(
    'location', v_loc, 'documents', v_docs, 'support', v_support,
    'moderation', v_mod, 'timeline', v_tl, 'emergency', v_em));
  RETURN v_result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_member_status(p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row record;
  v_ok boolean;
  v_sanctions jsonb;
BEGIN
  SELECT role, user_type, verification_status, account_status, created_at, updated_at
  INTO v_row
  FROM public.users WHERE id = p_member_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;
  v_ok := (auth.uid() = p_member_id)
          OR public.has_permission('MEMBER_VIEW', public._member_region_id(p_member_id));
  IF NOT v_ok THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object('id', s.id::text, 'sanction_type', s.sanction_type,
                              'reason', s.reason, 'start_date', s.start_date,
                              'end_date', s.end_date)
           ORDER BY s.created_at DESC), '[]'::jsonb)
  INTO v_sanctions
  FROM public.sanctions s
  WHERE s.target_user_id = p_member_id
    AND s.is_active
    AND s.action_status = 'active';

  RETURN jsonb_build_object(
    'member_id', p_member_id::text,
    'role', v_row.role,
    'user_type', v_row.user_type,
    'verification_status', v_row.verification_status,
    'account_status', v_row.account_status,
    'created_at', v_row.created_at,
    'updated_at', v_row.updated_at,
    'active_sanctions', v_sanctions);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_member_timeline(p_member_id uuid, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_self boolean;
  v_admin boolean;
  v_rows jsonb;
BEGIN
  IF p_limit < 1 OR p_limit > 50 THEN
    RAISE EXCEPTION 'Invalid limit';
  END IF;
  v_self := auth.uid() = p_member_id;
  v_admin := public.has_permission('MEMBER_VIEW_TIMELINE', public._member_region_id(p_member_id));
  IF NOT (v_self OR v_admin) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object('event_type', e.event_type, 'title', e.title,
                              'payload', e.payload, 'created_at', e.created_at)
           ORDER BY e.created_at DESC), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT e.event_type, e.title, e.payload, e.created_at
    FROM public.member_events e
    WHERE e.user_id = p_member_id
      AND (p_before IS NULL OR e.created_at < p_before)
      AND (v_self = false OR e.event_type IN (
            'account_created','login',
            'support_opened','support_resolved',
            'complaint_created','complaint_resolved',
            'moderation_action','suspension','ban',
            'sos','emergency_opened','emergency_resolved',
            'document_verified','birthday_reward','anniversary_reward',
            'account_deactivated'))
    ORDER BY e.created_at DESC
    LIMIT p_limit
  ) e;

  RETURN v_rows;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_merchant_rating_summary(p_merchant_id uuid)
 RETURNS TABLE(avg_rating numeric, total_reviews bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  SELECT ROUND(AVG(rating)::numeric, 2) AS avg_rating, COUNT(*)::bigint AS total_reviews
  FROM reviews
  WHERE merchant_id = p_merchant_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_capabilities()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'customer', EXISTS(SELECT 1 FROM users WHERE id = auth.uid()),
    'driver',   EXISTS(SELECT 1 FROM drivers WHERE user_id = auth.uid()),
    'provider', EXISTS(SELECT 1 FROM service_providers WHERE user_id = auth.uid()),
    'merchant', EXISTS(SELECT 1 FROM merchants WHERE owner_user_id = auth.uid()),
    'admin',    EXISTS(SELECT 1 FROM users WHERE id = auth.uid() AND role IN ('admin','owner')),
    'owner',    EXISTS(SELECT 1 FROM users WHERE id = auth.uid() AND role = 'owner'),
    'can_use_customer', EXISTS(SELECT 1 FROM users WHERE id = auth.uid()),
    'can_use_delivery',  EXISTS(SELECT 1 FROM drivers WHERE user_id = auth.uid())
                          OR EXISTS(SELECT 1 FROM users WHERE id = auth.uid() AND role = 'owner'),
    'can_use_provider',  EXISTS(SELECT 1 FROM service_providers WHERE user_id = auth.uid())
                          OR EXISTS(SELECT 1 FROM merchants WHERE owner_user_id = auth.uid())
                          OR EXISTS(SELECT 1 FROM users WHERE id = auth.uid() AND role = 'owner'),
    'can_use_admin',     EXISTS(SELECT 1 FROM users WHERE id = auth.uid() AND role IN ('admin','owner'))
  );
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_financial_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$

DECLARE
  v_uid uuid := auth.uid();
  v_balance numeric;
  v_grace jsonb;
  v_rate numeric;
  v_ut text;
  v_pending int;
  v_txns jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT balance INTO v_balance FROM public.wallets WHERE user_id = v_uid;
  v_balance := COALESCE(v_balance, 0);
  v_grace := public.get_my_grace();
  SELECT user_type INTO v_ut FROM public.users WHERE id = v_uid;
  v_rate := public.get_commission_rate(v_ut::text, NULL::text);

  SELECT count(*) INTO v_pending FROM public.topup_requests
   WHERE account_id = v_uid AND status = 'pending';

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', id, 'type', type, 'amount', amount, 'description', description,
    'balance_after', balance_after, 'created_at', created_at)), '[]'::jsonb) INTO v_txns
  FROM (
    SELECT * FROM public.wallet_transactions wt
     WHERE wallet_id = (SELECT id FROM public.wallets WHERE user_id = v_uid)
    ORDER BY created_at DESC LIMIT 10
  ) sub;

  RETURN jsonb_build_object(
    'balance', v_balance,
    'grace_limit', (v_grace ->> 'grace_limit')::int,
    'grace_used', (v_grace ->> 'grace_used')::int,
    'grace_remaining', (v_grace ->> 'grace_remaining')::int,
    'commission_rate', v_rate,
    'pending_topups', v_pending,
    'recent_transactions', COALESCE(v_txns, '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_grace()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.grace_accounts;
  v_remaining integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;
  v_row := public.get_or_create_grace(auth.uid());
  v_remaining := GREATEST(0, v_row.grace_limit - v_row.grace_used);
  RETURN jsonb_build_object(
    'user_id', v_row.user_id,
    'grace_limit', v_row.grace_limit,
    'grace_used', v_row.grace_used,
    'grace_remaining', v_remaining
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_merchant_ledger()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_merchant_id uuid;
  v_balance numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  SELECT id INTO v_merchant_id FROM public.merchants WHERE owner_user_id = auth.uid() LIMIT 1;
  IF v_merchant_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NO_MERCHANT');
  END IF;
  SELECT COALESCE(sum(CASE WHEN entry_type = 'credit' THEN amount ELSE -amount END), 0)
    INTO v_balance FROM public.merchant_ledger WHERE merchant_id = v_merchant_id;
  RETURN jsonb_build_object(
    'ok', true, 'balance', v_balance,
    'entries', COALESCE((
      SELECT jsonb_agg(row_to_json(l) ORDER BY l.created_at DESC)
        FROM (SELECT * FROM public.merchant_ledger
               WHERE merchant_id = v_merchant_id
               ORDER BY created_at DESC LIMIT 100) l
    ), '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_obligations()
 RETURNS SETOF driver_obligations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_driver_id uuid;
  v_driver_uid uuid := auth.uid();
  ob RECORD;
BEGIN
  IF v_driver_uid IS NULL THEN
    RETURN;
  END IF;
  PERFORM public._settlement_escalation_sweep();
  SELECT id INTO v_driver_id FROM public.drivers WHERE user_id = v_driver_uid;
  IF v_driver_id IS NULL THEN
    RETURN;
  END IF;

  -- Reminder ladder: 4h before due, then once when overdue.
  FOR ob IN
    SELECT * FROM public.driver_obligations
     WHERE driver_id = v_driver_id AND status = 'open'
       AND due_at - interval '4 hours' < now() AND reminded_due_soon_at IS NULL
       AND due_at > now()
  LOOP
    INSERT INTO public.notifications (user_id, title, body, type, data, send_push)
    VALUES (v_driver_uid, 'تذكير بتسوية كاش',
            'فاضل أقل من ٤ ساعات على استحقاق توريد ' || ob.amount::text || ' ' || ob.currency || '.',
            'settlement', jsonb_build_object('obligation_id', ob.id), true);
    UPDATE public.driver_obligations SET reminded_due_soon_at = now() WHERE id = ob.id;
  END LOOP;

  FOR ob IN
    SELECT * FROM public.driver_obligations
     WHERE driver_id = v_driver_id AND status = 'open'
       AND due_at < now() AND reminded_overdue_at IS NULL
  LOOP
    INSERT INTO public.notifications (user_id, title, body, type, data, send_push, priority)
    VALUES (v_driver_uid, 'مديونية متأخرة',
            'عدّى ميعاد توريد ' || ob.amount::text || ' ' || ob.currency ||
              '. سددها عشان تفضل قادر تاخد طلبات كاش.',
            'settlement', jsonb_build_object('obligation_id', ob.id), true, 'high');
    UPDATE public.driver_obligations SET reminded_overdue_at = now() WHERE id = ob.id;
  END LOOP;

  RETURN QUERY
    SELECT * FROM public.driver_obligations
     WHERE driver_id = v_driver_id
     ORDER BY created_at DESC;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_provider_profiles()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_owner boolean;
  v_active text;
  v_cat text;
  v_target jsonb;
  v_m record;
  v_sp record;
  v_owner_cats text[] := ARRAY[
    'restaurant', 'grocery', 'pharmacy', 'bakery', 'home_services', 'electronics', 'fashion'
  ];
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  v_is_owner := public._is_owner_uid(v_uid);
  SELECT active_provider_category INTO v_active FROM public.users WHERE id = v_uid;

  IF v_is_owner THEN
    FOREACH v_cat IN ARRAY v_owner_cats LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.provider_business_profiles
         WHERE user_id = v_uid AND category_type = v_cat
      ) THEN
        v_target := public._provision_business_target(v_uid, v_cat, 'Delwaqty ' || initcap(replace(v_cat, '_', ' ')));
        INSERT INTO public.provider_business_profiles (
          user_id, category_type, display_name, status,
          merchant_id, service_provider_id, reviewed_by, reviewed_at
        )
        VALUES (
          v_uid,
          v_cat,
          'Delwaqty ' || initcap(replace(v_cat, '_', ' ')),
          'approved',
          (v_target->>'merchant_id')::uuid,
          (v_target->>'service_provider_id')::uuid,
          v_uid,
          now()
        )
        ON CONFLICT (user_id, category_type) DO UPDATE
          SET status = 'approved',
              merchant_id = COALESCE(public.provider_business_profiles.merchant_id, EXCLUDED.merchant_id),
              service_provider_id = COALESCE(public.provider_business_profiles.service_provider_id, EXCLUDED.service_provider_id);
      END IF;
    END LOOP;
    IF v_active IS NULL OR btrim(v_active) = '' THEN
      v_active := 'restaurant';
      UPDATE public.users SET active_provider_category = v_active WHERE id = v_uid;
    END IF;
  ELSE
    -- Ensure existing merchants / service_providers are synced into provider_business_profiles
    FOR v_m IN
      SELECT id, name, type FROM public.merchants WHERE owner_user_id = v_uid ORDER BY created_at ASC
    LOOP
      INSERT INTO public.provider_business_profiles (
        user_id, category_type, display_name, status, merchant_id
      )
      VALUES (
        v_uid, COALESCE(NULLIF(v_m.type, ''), 'restaurant'), COALESCE(NULLIF(v_m.name, ''), 'My Store'), 'approved', v_m.id
      )
      ON CONFLICT (user_id, category_type) DO NOTHING;
    END LOOP;

    FOR v_sp IN
      SELECT id, name, category_type FROM public.service_providers WHERE user_id = v_uid ORDER BY created_at ASC
    LOOP
      INSERT INTO public.provider_business_profiles (
        user_id, category_type, display_name, status, service_provider_id
      )
      VALUES (
        v_uid, 'home_services', COALESCE(NULLIF(v_sp.name, ''), 'My Service'), 'approved', v_sp.id
      )
      ON CONFLICT (user_id, category_type) DO NOTHING;
    END LOOP;

    IF v_active IS NULL OR btrim(v_active) = '' THEN
      SELECT category_type INTO v_active
        FROM public.provider_business_profiles
       WHERE user_id = v_uid AND status = 'approved'
       ORDER BY created_at ASC
       LIMIT 1;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'is_owner', v_is_owner,
    'active_category', COALESCE(v_active, 'restaurant'),
    'profiles', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', id,
          'category_type', category_type,
          'display_name', display_name,
          'status', status,
          'merchant_id', merchant_id,
          'service_provider_id', service_provider_id,
          'rejection_reason', rejection_reason,
          'created_at', created_at
        )
        ORDER BY (status = 'approved') DESC, created_at ASC
      )
      FROM public.provider_business_profiles
      WHERE user_id = v_uid
    ), '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_settlements()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_rows jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'created_at' DESC), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT jsonb_build_object(
               'id', s.id,
               'amount', s.amount,
               'currency', s.currency,
               'status', s.status,
               'created_at', s.created_at,
               'period_message', s.message
             ) x
        FROM public.platform_settlements s
       WHERE s.payout_type = 'driver' AND s.member_id = v_uid
    ) sub;

  RETURN jsonb_build_object('ok', true, 'settlements', v_rows);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_my_topup_requests()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object(
    'requests',
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', id,
          'amount', amount,
          'currency', currency,
          'status', status,
          'payment_method', payment_method,
          'transfer_reference', transfer_reference,
