CREATE OR REPLACE FUNCTION public.get_or_create_grace(p_user_id uuid)
 RETURNS grace_accounts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.grace_accounts;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;
  IF auth.uid() <> p_user_id AND NOT public.is_admin() THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_row FROM public.grace_accounts WHERE user_id = p_user_id;
  IF v_row IS NULL THEN
    INSERT INTO public.grace_accounts (user_id) VALUES (p_user_id)
    ON CONFLICT (user_id) DO NOTHING;
    SELECT * INTO v_row FROM public.grace_accounts WHERE user_id = p_user_id;
  END IF;
  RETURN v_row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_peak_hours()
 RETURNS TABLE(hour integer, count bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN QUERY
  WITH hour_counts AS (
    SELECT EXTRACT(HOUR FROM created_at)::integer AS hr, COUNT(*) AS cnt
    FROM rides
    WHERE created_at >= NOW() - INTERVAL '30 days'
    GROUP BY hr
  )
  SELECT hr, cnt
  FROM hour_counts
  ORDER BY cnt DESC;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_pending_deletions()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rows jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', a.id::text,
           'member_email', COALESCE(u.email, ''),
           'member_name', COALESCE(u.full_name, ''),
           'requested_by', COALESCE(ru.email, ''),
           'reason', COALESCE(a.reason, ''),
           'created_at', a.created_at)
         ORDER BY a.created_at DESC), '[]'::jsonb)
    INTO v_rows
    FROM public.approval_requests a
    LEFT JOIN public.users u ON u.id = a.entity_id
    LEFT JOIN public.users ru ON ru.id = a.requested_by
   WHERE a.request_type = 'member_delete'
     AND a.state = 'pending';

  RETURN v_rows;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_region_collection_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_region uuid;
  v_today numeric := 0;
  v_week  numeric := 0;
  v_month numeric := 0;
  v_total numeric := 0;
  v_pending numeric := 0;
  v_approved numeric := 0;
  v_rejected numeric := 0;
  v_settled numeric := 0;
  v_outstanding numeric := 0;
BEGIN
  IF v_uid IS NULL OR NOT public.is_admin() THEN
    RETURN NULL;
  END IF;
  -- Primary assigned region (admins may serve several; summarize the first).
  SELECT region_id INTO v_region FROM public.admin_region_assignments
   WHERE admin_id = v_uid LIMIT 1;

  SELECT
    COALESCE(SUM(amount) FILTER (WHERE received_at >= date_trunc('day', now())), 0),
    COALESCE(SUM(amount) FILTER (WHERE received_at >= date_trunc('week', now())), 0),
    COALESCE(SUM(amount) FILTER (WHERE received_at >= date_trunc('month', now())), 0),
    COALESCE(SUM(amount), 0)
  INTO v_today, v_week, v_month, v_total
  FROM public.regional_collections c
  WHERE (v_region IS NULL OR c.region_id = v_region)
    AND (c.region_id IS NULL OR public.is_admin_for_region(c.region_id));

  SELECT
    COALESCE(SUM(amount) FILTER (WHERE t.status = 'pending'), 0),
    COALESCE(SUM(amount) FILTER (WHERE t.status = 'approved'), 0),
    COALESCE(SUM(amount) FILTER (WHERE t.status = 'rejected'), 0),
    COALESCE(SUM(amount) FILTER (WHERE t.status = 'approved'), 0)
  INTO v_pending, v_approved, v_rejected, v_settled
  FROM public.topup_requests t
  WHERE (v_region IS NULL OR t.region_id = v_region)
    AND (t.region_id IS NULL OR public.is_admin_for_region(t.region_id));

  -- Outstanding = collected - approved settlements (immutable ledger math).
  v_outstanding := v_total - COALESCE((
    SELECT SUM(s.amount) FROM public.platform_settlements s
     WHERE s.status = 'approved'
       AND (v_region IS NULL OR s.region_id = v_region)
       AND (s.region_id IS NULL OR public.is_admin_for_region(s.region_id))
  ), 0);

  RETURN jsonb_build_object(
    'region_id', v_region,
    'today', v_today, 'week', v_week, 'month', v_month, 'total', v_total,
    'pending', v_pending, 'approved', v_approved, 'rejected', v_rejected,
    'settled', v_settled, 'outstanding', GREATEST(0, v_outstanding)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_service_rating_summary(p_category_type text)
 RETURNS TABLE(avg_rating numeric, total_reviews bigint, five_star bigint, four_star bigint, three_star bigint, two_star bigint, one_star bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT ROUND(AVG(rating)::numeric, 1),
         COUNT(*)::bigint,
         COUNT(*) FILTER (WHERE rating = 5)::bigint,
         COUNT(*) FILTER (WHERE rating = 4)::bigint,
         COUNT(*) FILTER (WHERE rating = 3)::bigint,
         COUNT(*) FILTER (WHERE rating = 2)::bigint,
         COUNT(*) FILTER (WHERE rating = 1)::bigint
  FROM service_reviews
  WHERE category_type = p_category_type;
$function$
;
CREATE OR REPLACE FUNCTION public.get_support_room_contact(p_room_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_room public.chat_rooms%ROWTYPE;
  v_other_id uuid;
  v_user record;
  v_support_phone text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_room FROM public.chat_rooms WHERE id = p_room_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF NOT (v_uid = ANY(v_room.participant_ids) OR public.is_admin()) THEN
    RETURN NULL;
  END IF;

  -- Pick counterparty (non-self participant, or assigned admin if user is caller)
  SELECT pid INTO v_other_id
    FROM unnest(v_room.participant_ids) AS pid
   WHERE pid <> v_uid
   LIMIT 1;

  IF v_other_id IS NULL AND v_room.assigned_admin_id IS NOT NULL AND v_room.assigned_admin_id <> v_uid THEN
    v_other_id := v_room.assigned_admin_id;
  END IF;

  IF v_other_id IS NOT NULL THEN
    SELECT id, full_name, phone, role INTO v_user
      FROM public.users
     WHERE id = v_other_id;
  END IF;

  SELECT support_phone INTO v_support_phone
    FROM public.platform_settings
   WHERE id = 'default';

  RETURN jsonb_build_object(
    'reference_number', v_room.reference_number,
    'other_user_id', v_other_id,
    'other_name', v_user.full_name,
    'other_phone', COALESCE(NULLIF(btrim(v_user.phone), ''), v_support_phone),
    'other_role', v_user.role,
    'support_phone', v_support_phone
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_unread_notification_count(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cnt integer;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN 0;
  END IF;
  -- SECURITY DEFINER: current_user is always postgres, so authz must key off
  -- auth.uid(): NULL (service_role / server-side) bypasses; otherwise enforce
  -- own-user-or-admin.
  IF auth.uid() IS NOT NULL
     AND p_user_id <> auth.uid()
     AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COUNT(*) INTO v_cnt
    FROM public.notifications
   WHERE user_id = p_user_id AND is_read = false;
  RETURN COALESCE(v_cnt, 0);
END;
$function$
;
