CREATE OR REPLACE FUNCTION public.get_wallet_balance(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_wallet_id uuid; v_balance numeric; v_currency text;
BEGIN
  IF auth.uid() IS NOT NULL AND p_user_id IS DISTINCT FROM auth.uid() THEN RETURN NULL; END IF;
  IF p_user_id IS NULL THEN RETURN NULL; END IF;
  v_wallet_id := public._ensure_wallet(p_user_id);
  SELECT balance, currency INTO v_balance, v_currency FROM public.wallets WHERE id = v_wallet_id;
  RETURN jsonb_build_object('wallet_id', v_wallet_id, 'balance', COALESCE(v_balance, 0), 'currency', COALESCE(v_currency, 'EGP'));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.grant_admin_permission(p_admin_id uuid, p_permission text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public._is_active_admin_uid(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF NOT public._valid_permission(p_permission) THEN
    RAISE EXCEPTION 'Unknown permission';
  END IF;
  IF p_admin_id = auth.uid() THEN
    RAISE EXCEPTION 'Cannot grant a permission to yourself';
  END IF;
  -- grantor must possess the permission (or be owner); target must be an admin
  -- under the grantor's branch
  IF NOT public._is_owner_uid(auth.uid()) THEN
    IF NOT public.has_permission(p_permission) THEN
      RAISE EXCEPTION 'You do not hold this permission';
    END IF;
    IF NOT public.is_supervisor_of(auth.uid(), p_admin_id) THEN
      RAISE EXCEPTION 'Not authorized for this admin';
    END IF;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_management m
    JOIN public.users u ON u.id = m.admin_id
    WHERE m.admin_id = p_admin_id AND m.is_active AND u.role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Not an active admin';
  END IF;

  INSERT INTO public.admin_permission_grants (admin_id, permission, granted_by)
  VALUES (p_admin_id, p_permission, auth.uid())
  ON CONFLICT (admin_id, permission) DO NOTHING;

  PERFORM public.write_audit(
    'ADMIN_PERMISSION_GRANTED', 'admin_permission_grants', p_admin_id::text,
    jsonb_build_object('permission', p_permission));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.grant_financial_permission(p_user_id uuid, p_permission text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public._is_owner_uid(auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_USER');
  END IF;

  IF p_permission IS NULL OR p_permission NOT IN (
    'approve_wallet_funding',
    'reject_wallet_funding',
    'view_funding_requests',
    'manage_receiving_accounts',
    'view_financial_transactions',
    'adjust_wallet_balance'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_PERMISSION');
  END IF;

  IF p_user_id = auth.uid() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SELF_GRANT_NOT_ALLOWED');
  END IF;

  IF public._is_owner_uid(p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'OWNER_ALREADY_AUTHORIZED');
  END IF;

  INSERT INTO public.financial_permissions (user_id, permission, granted_by)
  VALUES (p_user_id, p_permission, auth.uid())
  ON CONFLICT (user_id, permission) DO UPDATE SET
    revoked_at = NULL,
    revoked_by = NULL,
    granted_by = EXCLUDED.granted_by,
    granted_at = now();

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'user_id', p_user_id, 'permission', p_permission);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.guard_notifications_user_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Push-dispatch marker set by the SECURITY DEFINER dispatch functions.
  IF current_setting('app.notify_dispatch', true) = 'true' THEN
    RETURN NEW;
  END IF;
  -- No-JWT server calls (service_role / cron / edge worker).
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  -- Admins may keep full control (read-state or content).
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;

  IF NEW.is_read IS DISTINCT FROM OLD.is_read
     OR NEW.read_at IS DISTINCT FROM OLD.read_at THEN
    -- read-state change is the ONLY column change permitted for the owner.
    IF NEW.title IS DISTINCT FROM OLD.title
       OR NEW.body IS DISTINCT FROM OLD.body
       OR NEW.type IS DISTINCT FROM OLD.type
       OR NEW.data IS DISTINCT FROM OLD.data
       OR NEW.deep_link IS DISTINCT FROM OLD.deep_link
       OR NEW.image_url IS DISTINCT FROM OLD.image_url
       OR NEW.priority IS DISTINCT FROM OLD.priority
       OR NEW.sender_id IS DISTINCT FROM OLD.sender_id
       OR NEW.send_push IS DISTINCT FROM OLD.send_push
       OR NEW.push_status IS DISTINCT FROM OLD.push_status
       OR NEW.push_sent_at IS DISTINCT FROM OLD.push_sent_at
       OR NEW.push_error IS DISTINCT FROM OLD.push_error
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'Users may only update their own notification read state';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Users may only update their own notification read state';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.guard_platform_settings_owner_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    IF TG_OP = 'UPDATE' AND NEW.require_provider_documents IS DISTINCT FROM OLD.require_provider_documents THEN
      IF NOT public._is_owner_uid(auth.uid()) THEN
        RAISE EXCEPTION 'Only the platform owner can change provider document requirements';
      END IF;
    ELSIF TG_OP = 'INSERT' AND NEW.require_provider_documents IS TRUE THEN
      IF NOT public._is_owner_uid(auth.uid()) THEN
        RAISE EXCEPTION 'Only the platform owner can change provider document requirements';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.guard_vehicle_verification()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF current_user IN ('authenticated','anon') AND NOT public.is_admin() THEN
  IF TG_OP='INSERT' THEN
   IF COALESCE(NEW.is_verified,false) THEN RAISE EXCEPTION 'Vehicle verification requires admin review'; END IF;
  ELSE
   IF NEW.is_verified IS DISTINCT FROM OLD.is_verified OR NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN
    RAISE EXCEPTION 'Vehicle verification and ownership are server-managed';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_type TEXT := COALESCE(
    NULLIF(NEW.raw_user_meta_data->>'user_type', ''),
    'customer'
  );
  v_require_docs BOOLEAN := false;
  v_verification TEXT;
  v_full_name TEXT := COALESCE(
    NULLIF(NEW.raw_user_meta_data->>'full_name', ''),
    'User'
  );
  v_phone TEXT := COALESCE(
    NULLIF(NEW.phone, ''),
    NULLIF(NEW.raw_user_meta_data->>'phone', '')
  );
  v_language TEXT := COALESCE(
    NULLIF(NEW.raw_user_meta_data->>'language', ''),
    'ar'
  );
BEGIN
  SELECT COALESCE(require_provider_documents, false)
    INTO v_require_docs
    FROM public.platform_settings
   WHERE id = 'default';

  -- SECURITY: never trust verification_status from client-supplied signup
  -- metadata (anyone with the public anon key can set it). Derive it here.
  v_verification := CASE
    WHEN v_user_type = 'customer' THEN 'approved'
    WHEN v_user_type IN ('merchant', 'provider') AND NOT COALESCE(v_require_docs, false) THEN 'approved'
    ELSE 'pending'
  END;

  INSERT INTO public.users (
    id, email, full_name, phone, language, is_onboarded,
    role, user_type, verification_status, created_at, updated_at
  )
  VALUES (
    NEW.id,
    COALESCE(NEW.email, ''),
    v_full_name,
    v_phone,
    v_language,
    true,
    v_user_type,
    v_user_type,
    v_verification,
    NOW(),
    NOW()
  )
  ON CONFLICT (id) DO UPDATE
    SET phone = COALESCE(EXCLUDED.phone, public.users.phone),
        full_name = CASE
          WHEN public.users.full_name IS NULL OR public.users.full_name = '' OR public.users.full_name = 'User'
          THEN EXCLUDED.full_name
          ELSE public.users.full_name
        END,
        verification_status = CASE
          WHEN v_user_type IN ('merchant', 'provider') AND NOT COALESCE(v_require_docs, false)
          THEN 'approved'
          ELSE public.users.verification_status
        END,
        updated_at = NOW();

  -- Auto-provision a merchant storefront row for merchant/provider accounts
  IF v_user_type IN ('merchant', 'provider') THEN
    IF NOT EXISTS (SELECT 1 FROM public.merchants WHERE owner_user_id = NEW.id) THEN
      INSERT INTO public.merchants (
        owner_user_id, name, email, phone, type, status, is_open,
        delivery_fee, min_order, delivery_time_min, rating
      )
      VALUES (
        NEW.id,
        v_full_name,
        COALESCE(NEW.email, ''),
        v_phone,
        CASE WHEN v_user_type = 'provider' THEN 'service' ELSE 'restaurant' END,
        'active',
        true,
        15,
        0,
        30,
        5.0
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.has_financial_permission(p_user_id uuid, p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_has_permission BOOLEAN;
BEGIN
  IF public._is_owner_uid(p_user_id) THEN
    RETURN TRUE;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.financial_permissions
    WHERE user_id = p_user_id
      AND permission = p_permission
      AND revoked_at IS NULL
  ) INTO v_has_permission;

  RETURN COALESCE(v_has_permission, FALSE);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.has_permission(p_permission text, p_region_id uuid DEFAULT NULL::uuid, p_target_admin_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_granted boolean;
  v_default_in_scope boolean;
BEGIN
  IF v_actor IS NULL OR p_permission IS NULL OR btrim(p_permission) = '' THEN
    RETURN false;
  END IF;

  -- Owner has absolute, universal authority across every permission
  IF public._is_owner_uid(v_actor) THEN
    RETURN true;
  END IF;

  -- Validate permission vocabulary for non-owner admins
  IF NOT public._valid_permission(p_permission) THEN
    RETURN false;
  END IF;

  IF NOT public._is_active_admin_uid(v_actor) THEN
    RETURN false;
  END IF;

  -- Geographic scope gate
  IF p_region_id IS NOT NULL AND NOT public._region_in_scope(v_actor, p_region_id) THEN
    RETURN false;
  END IF;

  -- Target-admin gate (ADMIN_* actions are always supervisor-scoped)
  IF p_target_admin_id IS NOT NULL
     AND NOT public.is_supervisor_of(v_actor, p_target_admin_id) THEN
    RETURN false;
  END IF;

  -- Explicit grant check
  SELECT EXISTS (
    SELECT 1 FROM public.admin_permission_grants g
    WHERE g.admin_id = v_actor AND g.permission = p_permission
  ) INTO v_granted;
  IF v_granted THEN
    RETURN true;
  END IF;

  -- Default in-scope matrix for subordinate admins
  SELECT p_permission IN (
    'ADMIN_CREATE','ADMIN_ASSIGN','ADMIN_ROLE_ASSIGN','ADMIN_REGION_ASSIGN',
    'ADMIN_SUPERVISOR_ASSIGN','ADMIN_SUSPEND',
    'MEMBER_VIEW','MEMBER_VIEW_LOCATION','MEMBER_VIEW_CHAT_HISTORY',
    'MEMBER_VIEW_COMPLAINTS','MEMBER_VIEW_TIMELINE',
    'MEMBER_MODERATE','MEMBER_WARN','MEMBER_RESTRICT','MEMBER_SUSPEND',
    'EMERGENCY_VIEW','OFFER_CREATE','OFFER_REVIEW',
    'ORDER_VIEW', 'MERCHANT_VIEW', 'DRIVER_VIEW', 'ANALYTICS_VIEW', 'AUDIT_LOG_VIEW'
  ) INTO v_default_in_scope;
  RETURN v_default_in_scope;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.haversine_km(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision)
 RETURNS double precision
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  r DOUBLE PRECISION := 6371;
  dlat DOUBLE PRECISION := radians(lat2 - lat1);
  dlon DOUBLE PRECISION := radians(lon2 - lon1);
  a DOUBLE PRECISION;
BEGIN
  a := sin(dlat / 2) * sin(dlat / 2)
     + cos(radians(lat1)) * cos(radians(lat2))
     * sin(dlon / 2) * sin(dlon / 2);
  RETURN r * 2 * asin(least(1, sqrt(a)));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.increment_coupon_usage(p_coupon_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id UUID;
  v_used INTEGER;
  v_limit INTEGER;
BEGIN
  SELECT id, used_count, usage_limit INTO v_id, v_used, v_limit
  FROM coupons
  WHERE code = p_coupon_code;

  IF v_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'coupon_not_found');
  END IF;

  IF v_limit IS NOT NULL AND v_used >= v_limit THEN
    RETURN jsonb_build_object('success', false, 'reason', 'usage_limit_reached');
  END IF;

  UPDATE coupons
  SET used_count = COALESCE(v_used, 0) + 1
  WHERE id = v_id;

  RETURN jsonb_build_object('success', true);
END;
$function$
;
