 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public._is_owner_uid(auth.uid()) THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object(
    'transactions',
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
