$function$
;
CREATE OR REPLACE FUNCTION public.list_approval_requests(p_state text DEFAULT 'pending'::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rows jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN NULL;
  END IF;
  IF p_state NOT IN ('pending', 'approved', 'rejected', 'all') THEN
    RAISE EXCEPTION 'Invalid state';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', a.id::text,
           'request_type', a.request_type,
           'entity_type', a.entity_type,
           'entity_id', a.entity_id::text,
           'payload', a.payload,
           'requested_by', a.requested_by::text,
           'required_approver', a.required_approver::text,
           'state', a.state,
           'reason', a.reason,
           'decided_by', a.decided_by::text,
           'created_at', a.created_at)
         ), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT * FROM public.approval_requests a
       WHERE p_state = 'all' OR a.state = p_state
       ORDER BY a.created_at DESC
       LIMIT GREATEST(1, p_limit)
    ) a;

  RETURN jsonb_build_object('requests', v_rows);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_commission_rules(p_entity_type text DEFAULT NULL::text, p_only_active boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rules jsonb;
BEGIN
  IF NOT public.has_permission('PLATFORM_REVENUE', NULL) THEN
    RETURN NULL;
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', c.id::text,
           'entity_type', c.entity_type,
           'entity_key', c.entity_key,
           'rate', c.rate,
           'currency', c.currency,
           'effective_from', c.effective_from,
           'effective_to', c.effective_to,
           'is_active', c.is_active,
           'description', c.description,
           'created_at', c.created_at,
           'updated_at', c.updated_at)
         ORDER BY c.effective_from DESC, c.created_at DESC),
         '[]'::jsonb)
    INTO v_rules
    FROM public.commission_rules c
   WHERE (p_entity_type IS NULL OR c.entity_type = p_entity_type)
     AND (NOT p_only_active OR c.is_active);
  RETURN jsonb_build_object('rules', v_rules);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_delivery_incidents(p_status text DEFAULT 'open'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS SETOF delivery_incidents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  return query
    select i.* from public.delivery_incidents i
    where (p_status is null or i.status = p_status)
      and public._admin_scope_allows(
            (select u.region_id from public.orders o
              join public.users u on u.id = o.user_id
             where o.id = i.order_id))
    order by i.created_at desc
    limit least(coalesce(p_limit, 100), 500) offset coalesce(p_offset, 0);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.list_driver_settlements()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  SELECT jsonb_agg(to_jsonb(t)) INTO v_result FROM (
    SELECT ps.id, ps.admin_id, ps.member_id, ps.region_id, ps.payout_type,
           ps.amount, ps.currency, ps.payment_method, ps.reference,
           ps.proof_path, ps.message, ps.status, ps.created_at,
           ps.reviewed_at, ps.reviewed_by, ps.rejection_reason,
           u.full_name AS driver_name, u.email AS driver_email,
           d.id AS driver_surrogate_id
      FROM public.platform_settlements ps
      JOIN public.drivers d  ON d.user_id = ps.member_id
      JOIN public.users    u ON u.id = ps.member_id
     WHERE ps.member_id IS NOT NULL
       AND ps.status IN ('pending', 'approved', 'rejected', 'paid')
     ORDER BY ps.created_at DESC
     LIMIT 200
  ) t;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_members(p_search text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_account_status text DEFAULT NULL::text, p_region_id uuid DEFAULT NULL::uuid, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, full_name text, email text, phone text, role text, account_status text, verification_status text, region_id uuid, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_limit  int := LEAST(COALESCE(p_limit, 20), 50);
BEGIN
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  IF NOT public.has_permission('MEMBER_VIEW', public._member_region_id(v_uid)) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT u.id,
         u.full_name,
         u.email,
         u.phone,
         u.role,
         COALESCE(u.account_status, 'active'),
         COALESCE(u.verification_status, 'unverified'),
         up.region_id,
         u.created_at
    FROM public.users u
    LEFT JOIN public.user_region_preferences up ON up.user_id = u.id
      AND up.updated_at = (
        SELECT MAX(up2.updated_at)
          FROM public.user_region_preferences up2
         WHERE up2.user_id = u.id
      )
   WHERE (p_search IS NULL
           OR u.full_name ILIKE '%' || p_search || '%'
           OR u.email ILIKE '%' || p_search || '%')
     AND (p_role IS NULL OR u.role = p_role)
     AND (p_account_status IS NULL
           OR COALESCE(u.account_status, 'active') = p_account_status)
     AND (p_region_id IS NULL
           OR up.region_id = p_region_id
           OR up.region_id IN (
             WITH RECURSIVE region_chain AS (
               SELECT p_region_id AS rid
               UNION ALL
               SELECT r.parent_region_id
                 FROM public.regions r
                 JOIN region_chain rc ON r.id = rc.rid
                WHERE r.parent_region_id IS NOT NULL
             )
             SELECT rid FROM region_chain
           ))
     AND (p_cursor IS NULL OR u.created_at < p_cursor)
   ORDER BY u.created_at DESC
   LIMIT v_limit;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_platform_receiving_accounts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object(
    'accounts',
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', id,
          'method_type', method_type,
          'display_name', display_name,
          'account_name', account_name,
          'account_number', account_number,
          'wallet_number', wallet_number,
          'instructions', instructions,
          'is_active', is_active
        )
        ORDER BY created_at
      )
      FROM public.platform_receiving_accounts
    ), '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_provider_profile_requests(p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RETURN '[]'::jsonb;
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', p.id,
        'user_id', p.user_id,
        'category_type', p.category_type,
        'display_name', p.display_name,
        'status', p.status,
        'rejection_reason', p.rejection_reason,
        'created_at', p.created_at,
        'user_name', u.full_name,
        'user_email', u.email,
        'user_phone', u.phone
      )
      ORDER BY p.created_at DESC
    )
    FROM public.provider_business_profiles p
    LEFT JOIN public.users u ON u.id = p.user_id
    WHERE (p_status IS NULL OR p.status = p_status)
  ), '[]'::jsonb);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_region_topup_requests(p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR NOT public.is_admin() THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object('requests', COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', t.id, 'account_id', t.account_id, 'region_id', t.region_id,
      'amount', t.amount, 'currency', t.currency, 'status', t.status,
      'payment_method', t.payment_method, 'transfer_reference', t.transfer_reference,
      'proof_path', t.proof_path, 'message', t.message,
      'created_at', t.created_at, 'reviewed_by', t.reviewed_by,
      'rejection_reason', t.rejection_reason))
    FROM public.topup_requests t
    WHERE (p_status IS NULL OR t.status = p_status)
      AND (t.region_id IS NULL OR public.is_admin_for_region(t.region_id))
    ORDER BY t.created_at DESC
  ), '[]'::jsonb));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_user_financial_permissions(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  IF NOT public._is_owner_uid(auth.uid()) AND auth.uid() IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'permission', permission,
    'granted_at', granted_at,
    'granted_by', granted_by,
    'revoked_at', revoked_at,
    'revoked_by', revoked_by,
    'active', revoked_at IS NULL
  )) INTO v_result
  FROM public.financial_permissions
  WHERE user_id = p_user_id;

  RETURN jsonb_build_object('ok', true, 'permissions', COALESCE(v_result, '[]'::jsonb));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_wallet_funding_requests(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result JSONB;
  v_count INTEGER;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF NOT public.has_financial_permission(auth.uid(), 'view_funding_requests')
     AND NOT public._is_owner_uid(auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF p_status IS NOT NULL AND p_status NOT IN ('pending', 'approved', 'rejected', 'cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATUS', 'status', p_status);
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'id', r.id,
    'user_id', r.user_id,
    'user_email', u.email,
    'user_name', u.full_name,
    'amount', r.amount,
    'method', r.method,
    'reference', r.reference,
    'proof_url', r.proof_url,
    'status', r.status,
    'created_at', r.created_at,
    'processed_at', r.processed_at,
    'processed_by', r.processed_by,
    'rejection_reason', r.rejection_reason
  ) ORDER BY r.created_at DESC)
  INTO v_result
  FROM public.wallet_funding_requests r
  LEFT JOIN public.users u ON u.id = r.user_id
  WHERE (p_status IS NULL OR r.status = p_status)
  LIMIT p_limit OFFSET p_offset;

  SELECT count(*) INTO v_count
  FROM public.wallet_funding_requests r
  WHERE (p_status IS NULL OR r.status = p_status);

  RETURN jsonb_build_object(
    'ok', true,
    'requests', COALESCE(v_result, '[]'::jsonb),
    'count', v_count
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.log_admin_action(p_action text, p_resource text, p_resource_id text, p_before jsonb DEFAULT NULL::jsonb, p_after jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text, p_scope text DEFAULT 'GLOBAL'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role  text;
  v_id    uuid;
begin
  if v_actor is null then
    insert into public.audit_log (actor, actor_role, scope, action, resource, resource_id, before, after, reason)
    values (null, 'system', p_scope, p_action, p_resource, p_resource_id, p_before, p_after, p_reason)
    returning id into v_id;
    return v_id;
  end if;

  select role into v_role from public.users where id = v_actor;
  insert into public.audit_log (actor, actor_role, scope, action, resource, resource_id, before, after, reason)
  values (v_actor, v_role, p_scope, p_action, p_resource, p_resource_id, p_before, p_after, p_reason)
  returning id into v_id;
  return v_id;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.lookup_email_by_phone(p_phone text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_norm text := public._normalize_egypt_phone(p_phone);
  v_digits text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
  v_last10 text;
  v_email text;
begin
  if length(v_digits) < 9 then
    return null;
  end if;

  if not public._lookup_rate_allow('phone:' || coalesce(v_norm, v_digits), 10) then
    return null;
  end if;
  if not public._lookup_rate_allow('ip:' || public._lookup_caller_ip(), 30) then
    return null;
  end if;

  v_last10 := right(v_digits, 10);

  select email into v_email
    from public.users
   where account_status <> 'deactivated'
     and email is not null
     and email <> ''
     and email not like '%@anonymized.invalid'
     and (
       public._normalize_egypt_phone(phone) = v_norm
       or right(regexp_replace(coalesce(phone, ''), '[^0-9]', '', 'g'), 10) = v_last10
     )
   order by created_at desc
   limit 1;

  return v_email;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.lookup_email_by_username(p_username text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text;
  v_uname text := lower(btrim(coalesce(p_username, '')));
begin
  if v_uname = '' then
    return null;
  end if;

  if not public._lookup_rate_allow('uname:' || v_uname, 10) then
    return null;
  end if;
  if not public._lookup_rate_allow('ip:' || public._lookup_caller_ip(), 30) then
    return null;
  end if;

  select email into v_email
    from public.users
  where username is not null
    and lower(username) = v_uname
    and account_status <> 'deactivated'
    and email not like '%@anonymized.invalid'
  limit 1;

  return v_email;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.mark_order_paid_by_merchant_order(p_merchant_order_id text, p_provider_transaction_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order_id uuid;
  v_order public.orders;
BEGIN
  IF coalesce(auth.role(), '') IS DISTINCT FROM 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF p_merchant_order_id IS NULL OR p_merchant_order_id = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MISSING_MERCHANT_ORDER_ID');
  END IF;
  SELECT * INTO v_order
    FROM public.orders
   WHERE payment_provider_order_id = p_merchant_order_id
   FOR UPDATE;
  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ORDER_NOT_FOUND');
  END IF;
  IF v_order.payment_status = 'paid' THEN
    RETURN jsonb_build_object('ok', true, 'code', 'ALREADY_PAID', 'order_id', v_order.id);
  END IF;
  IF v_order.payment_status = 'refunded' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ORDER_REFUNDED', 'order_id', v_order.id);
  END IF;
  UPDATE public.orders
     SET payment_status = 'paid',
         payment_provider_transaction_id = COALESCE(p_provider_transaction_id, v_order.payment_provider_transaction_id),
         confirmed_at = COALESCE(v_order.confirmed_at, now()),
         updated_at = now()
   WHERE id = v_order.id;
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'order_id', v_order.id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.member_financial_summary(p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_member_regid uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT region_id INTO v_member_regid
    FROM public.user_region_preferences
   WHERE user_id = p_member_id ORDER BY updated_at DESC LIMIT 1;
  IF NOT public.has_permission('MEMBER_VIEW', v_member_regid) THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'wallet', (
      SELECT jsonb_build_object('balance', balance, 'currency', currency)
        FROM public.wallets WHERE user_id = p_member_id
    ),
    'ledger', COALESCE((
      SELECT jsonb_agg(j)
        FROM (
          SELECT jsonb_build_object(
            'id', t.id, 'type', t.type, 'amount', t.amount,
            'reference_type', t.reference_type, 'reference_id', t.reference_id,
            'balance_after', t.balance_after, 'description', t.description, 'created_at', t.created_at) AS j
          FROM public.wallet_transactions t
          JOIN public.wallets w ON w.id = t.wallet_id
         WHERE w.user_id = p_member_id
         ORDER BY t.created_at DESC LIMIT 25) s)
    , '[]'::jsonb),
    'riders_driver', (
      SELECT jsonb_build_object(
        'earnings_balance', earnings_balance,
        'gross_rides', COALESCE(SUM(r.gross), 0),
        'rides_count', COUNT(r.ride_id))
        FROM public.drivers d
        LEFT JOIN LATERAL (
          SELECT r.id AS ride_id, COALESCE(r.fare, r.base_fare, 0) AS gross
            FROM public.rides r
           WHERE r.driver_id = d.id AND r.status = 'completed'
        ) r ON true
       WHERE d.user_id = p_member_id
       GROUP BY earnings_balance
    ),
    'commissions', COALESCE((
      SELECT jsonb_agg(j)
        FROM (
          SELECT jsonb_build_object(
            'reference_type', c.reference_type, 'reference_id', c.reference_id,
            'gross_amount', c.gross_amount, 'commission_rate', c.commission_rate,
            'commission_amount', c.commission_amount, 'net_amount', c.net_amount,
            'status', c.status, 'created_at', c.created_at) AS j
          FROM public.platform_commissions c WHERE c.member_id = p_member_id
          ORDER BY c.created_at DESC LIMIT 25) s)
    , '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.member_ops_count(p_search text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_user_type text DEFAULT NULL::text, p_account_status text DEFAULT NULL::text, p_verification_status text DEFAULT NULL::text, p_service_category text DEFAULT NULL::text, p_region_id uuid DEFAULT NULL::uuid, p_sanction_status text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_admin_scoped boolean;
  v_count bigint;
BEGIN
  IF v_uid IS NULL THEN
    RETURN 0;
  END IF;
  IF NOT (public._is_owner_uid(v_uid) OR public.has_permission('MEMBER_VIEW', NULL)) THEN
    RETURN 0;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.admin_region_assignments WHERE admin_id = v_uid
  ) INTO v_admin_scoped;

  SELECT COUNT(*) INTO v_count
    FROM public.users u
    LEFT JOIN LATERAL (
      SELECT region_id FROM public.user_region_preferences up
       WHERE up.user_id = u.id ORDER BY up.updated_at DESC LIMIT 1
    ) up ON true
   WHERE (p_search IS NULL
           OR u.full_name ILIKE '%' || p_search || '%'
           OR u.email ILIKE '%' || p_search || '%'
           OR u.phone ILIKE '%' || p_search || '%'
           OR u.username ILIKE '%' || p_search || '%')
     AND (p_role IS NULL OR u.role = p_role)
     AND (p_user_type IS NULL OR u.user_type = p_user_type)
     AND (p_account_status IS NULL
           OR COALESCE(u.account_status, 'active') = p_account_status)
     AND (p_verification_status IS NULL
           OR COALESCE(u.verification_status, 'unverified') = p_verification_status)
     AND (p_region_id IS NULL OR up.region_id = p_region_id)
     AND (p_sanction_status IS NULL
           OR (p_sanction_status = 'active'
               AND EXISTS (SELECT 1 FROM public.sanctions s
                            WHERE s.target_user_id = u.id AND s.is_active))
           OR (p_sanction_status = 'none'
               AND NOT EXISTS (SELECT 1 FROM public.sanctions s
                                WHERE s.target_user_id = u.id AND s.is_active)))
     AND (NOT v_admin_scoped OR up.region_id IS NULL
           OR public._region_in_scope(v_uid, up.region_id));

  RETURN v_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.member_ops_list(p_search text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_user_type text DEFAULT NULL::text, p_account_status text DEFAULT NULL::text, p_verification_status text DEFAULT NULL::text, p_service_category text DEFAULT NULL::text, p_region_id uuid DEFAULT NULL::uuid, p_sanction_status text DEFAULT NULL::text, p_sort text DEFAULT 'newest'::text, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_offset integer DEFAULT 0, p_limit integer DEFAULT 25)
 RETURNS TABLE(id uuid, full_name text, email text, phone text, avatar_url text, username text, role text, user_type text, account_status text, verification_status text, region_id uuid, region_label text, last_seen_at timestamp with time zone, is_online boolean, service_types text[], service_categories text[], orders_count bigint, rides_count bigint, bookings_count bigint, wallet_balance numeric, wallet_currency text, active_sanctions_count bigint, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_limit  int := LEAST(COALESCE(p_limit, 25), 100);
  v_offset int := GREATEST(COALESCE(p_offset, 0), 0);
  v_admin_scoped boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN;
  END IF;
  IF NOT (public._is_owner_uid(v_uid) OR public.has_permission('MEMBER_VIEW', NULL)) THEN
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.admin_region_assignments WHERE admin_id = v_uid
  ) INTO v_admin_scoped;

  RETURN QUERY
  SELECT u.id,
         u.full_name,
         u.email,
         u.phone,
         u.avatar_url,
         u.username,
         u.role,
         u.user_type,
         COALESCE(u.account_status, 'active'),
         COALESCE(u.verification_status, 'unverified'),
         up.region_id,
         CASE WHEN up.region_id IS NULL THEN NULL
              ELSE public._region_label_path(up.region_id) END,
         GREATEST(
           (SELECT MAX(lu.recorded_at) FROM public.location_updates lu WHERE lu.user_id = u.id),
           (SELECT MAX(nt.last_seen_at)   FROM public.notification_tokens nt WHERE nt.user_id = u.id)
         ),
         EXISTS (
           SELECT 1 FROM public.drivers d WHERE d.user_id = u.id AND d.is_online
         ) OR EXISTS (
           SELECT 1 FROM public.service_providers sp WHERE sp.user_id = u.id AND sp.is_available
         ),
         ARRAY(
           SELECT DISTINCT st FROM (
             SELECT UNNEST(d.service_types) AS st
               FROM public.drivers d WHERE d.user_id = u.id
             UNION
             SELECT sp.category_type
               FROM public.service_providers sp WHERE sp.user_id = u.id
           ) s WHERE st IS NOT NULL
         ),
         ARRAY(
           SELECT DISTINCT ct FROM (
             SELECT m.type AS ct FROM public.merchants m WHERE m.owner_user_id = u.id
             UNION
             SELECT sp.category_type FROM public.service_providers sp WHERE sp.user_id = u.id
           ) c WHERE ct IS NOT NULL
         ),
         (SELECT COUNT(*) FROM public.orders o WHERE o.user_id = u.id),
         (SELECT COUNT(*) FROM public.rides r WHERE r.rider_id = u.id),
         (SELECT COUNT(*) FROM public.service_bookings b WHERE b.user_id = u.id),
         (SELECT w.balance FROM public.wallets w WHERE w.user_id = u.id),
         (SELECT w.currency FROM public.wallets w WHERE w.user_id = u.id),
         (SELECT COUNT(*) FROM public.sanctions s
           WHERE s.target_user_id = u.id AND s.is_active),
         u.created_at
    FROM public.users u
    LEFT JOIN LATERAL (
      SELECT up.user_id AS user_id, up.region_id AS region_id
        FROM public.user_region_preferences up
       WHERE up.user_id = u.id
       ORDER BY up.updated_at DESC
       LIMIT 1
    ) up ON true
   WHERE (p_search IS NULL
           OR u.full_name ILIKE '%' || p_search || '%'
           OR u.email ILIKE '%' || p_search || '%'
           OR u.phone ILIKE '%' || p_search || '%'
           OR u.username ILIKE '%' || p_search || '%')
     AND (p_role IS NULL OR u.role = p_role)
     AND (p_user_type IS NULL OR u.user_type = p_user_type)
     AND (p_account_status IS NULL
           OR COALESCE(u.account_status, 'active') = p_account_status)
     AND (p_verification_status IS NULL
           OR COALESCE(u.verification_status, 'unverified') = p_verification_status)
     AND (p_region_id IS NULL OR up.region_id = p_region_id)
     AND (p_sanction_status IS NULL
           OR (p_sanction_status = 'active'
               AND EXISTS (SELECT 1 FROM public.sanctions s
                            WHERE s.target_user_id = u.id AND s.is_active))
           OR (p_sanction_status = 'none'
               AND NOT EXISTS (SELECT 1 FROM public.sanctions s
                                WHERE s.target_user_id = u.id AND s.is_active)))
     AND (p_service_category IS NULL
           OR EXISTS (SELECT 1 FROM public.merchants m
                       WHERE m.owner_user_id = u.id AND m.type = p_service_category)
           OR EXISTS (SELECT 1 FROM public.service_providers sp
                       WHERE sp.user_id = u.id AND sp.category_type = p_service_category)
           OR EXISTS (SELECT 1 FROM public.drivers d
                       WHERE d.user_id = u.id AND p_service_category = ANY(d.service_types)))
     AND (NOT v_admin_scoped OR up.region_id IS NULL
           OR public._region_in_scope(v_uid, up.region_id))
     AND (p_cursor IS NULL
           OR u.created_at < p_cursor
           OR (u.created_at = p_cursor AND u.id < p_cursor_id))
    ORDER BY
      CASE WHEN p_sort = 'oldest' THEN u.created_at END ASC NULLS LAST,
      CASE WHEN COALESCE(p_sort, 'newest') <> 'oldest' THEN u.created_at END
        DESC NULLS LAST,
      CASE p_sort WHEN 'name' THEN u.full_name END ASC NULLS LAST,
      CASE p_sort WHEN 'orders'
            THEN (SELECT COUNT(*)::text FROM public.orders o WHERE o.user_id = u.id)
        END DESC NULLS LAST,
      CASE p_sort WHEN 'wallet'
            THEN (SELECT w.balance::text FROM public.wallets w WHERE w.user_id = u.id)
        END DESC NULLS LAST,
      u.id DESC
    LIMIT v_limit OFFSET v_offset;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.merchant_complete_order(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_order public.orders%ROWTYPE;
  v_merchant_uid uuid;
  v_merchant_type text;
  v_rate numeric;
  v_commission numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'UNAUTHENTICATED');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_FOUND');
  END IF;
  IF NOT public.is_merchant_owner(v_order.merchant_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'FORBIDDEN');
  END IF;
  IF v_order.status = 'delivered' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'ALREADY_DONE');
  END IF;
  IF v_order.status NOT IN ('ready','delivering') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'BAD_STATE');
  END IF;
  -- Ride-linked orders complete through the driver handoff flow,
  -- which verifies the recipient OTP and records both legs.
  IF EXISTS (SELECT 1 FROM public.rides r WHERE r.order_id = p_order_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'USE_ASSIGNED_DELIVERY_FLOW');
  END IF;

  UPDATE public.orders
     SET status = 'delivered', updated_at = now()
   WHERE id = p_order_id;

  -- Merchant leg: subtotal minus the merchant commission rate.
  SELECT owner_user_id, type INTO v_merchant_uid, v_merchant_type
    FROM public.merchants WHERE id = v_order.merchant_id;
  v_rate := COALESCE(public.get_commission_rate('merchant', v_merchant_type, v_merchant_uid), 3);
  v_commission := public.calculate_commission(COALESCE(v_order.subtotal,0), v_rate);
  INSERT INTO public.platform_commissions(
      member_id, reference_type, reference_id, gross_amount, commission_rate,
      commission_amount, net_amount, currency, status)
  VALUES (
      v_merchant_uid, 'order', p_order_id, COALESCE(v_order.subtotal,0), v_rate,
      v_commission, COALESCE(v_order.subtotal,0) - v_commission,
      'EGP', 'computed')
  ON CONFLICT (reference_type, reference_id) DO NOTHING;

  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.merchant_confirm_obligation_paid(p_obligation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ob public.driver_obligations%ROWTYPE;
BEGIN
  SELECT * INTO v_ob FROM public.driver_obligations WHERE id = p_obligation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.merchants m
     WHERE m.id = v_ob.merchant_id AND m.owner_user_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF v_ob.status <> 'open' OR v_ob.owed_to <> 'merchant' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE');
  END IF;
  UPDATE public.driver_obligations
     SET status = 'settled', settled_at = now(), settled_via = 'merchant_confirm',
         updated_at = now()
   WHERE id = p_obligation_id;
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.merchant_dispatch_order_driver(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order record;
  v_merchant record;
  v_customer record;
  v_ride_id uuid;
  v_pickup_lat double precision;
  v_pickup_lng double precision;
  v_dropoff_lat double precision;
  v_dropoff_lng double precision;
  v_items_summary text;
  v_dispatch jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_order
    FROM public.orders
   WHERE id = p_order_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  IF NOT public.is_merchant_owner(v_order.merchant_id) THEN
    RAISE EXCEPTION 'Not authorized to dispatch this order';
  END IF;

  SELECT * INTO v_merchant
    FROM public.merchants
   WHERE id = v_order.merchant_id;

  SELECT full_name, phone INTO v_customer
    FROM public.users
   WHERE id = v_order.user_id;

  SELECT string_agg(
           COALESCE(oi.quantity::text, '1') || 'x ' || COALESCE(NULLIF(oi.product_name, ''), 'Item'),
           ', '
         )
    INTO v_items_summary
    FROM public.order_items oi
   WHERE oi.order_id = p_order_id;

  IF v_order.status IN ('delivered','cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_ORDER_STATE');
  END IF;
  IF v_merchant.latitude IS NULL OR v_merchant.longitude IS NULL
     OR v_order.delivery_latitude IS NULL OR v_order.delivery_longitude IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'MISSING_DELIVERY_LOCATION');
  END IF;
  v_pickup_lat := v_merchant.latitude;
  v_pickup_lng := v_merchant.longitude;
  v_dropoff_lat := v_order.delivery_latitude;
  v_dropoff_lng := v_order.delivery_longitude;

  -- A delivery ride is unique per order.
  SELECT id INTO v_ride_id
    FROM public.rides
   WHERE order_id = p_order_id
     AND status IN ('searching', 'matched', 'arrived', 'inTrip')
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_ride_id IS NULL THEN
    INSERT INTO public.rides (
      rider_id,
      merchant_id,
      order_id,
      service_type,
      ride_type,
      status,
      delivery_status,
      pickup_address,
      pickup_latitude,
      pickup_longitude,
      dropoff_address,
      dropoff_latitude,
      dropoff_longitude,
      fare,
      distance,
      estimated_minutes,
      payment_method,
      payment_status,
      currency,
      recipient_name,
      recipient_phone,
      items_summary,
      pickup_notes,
      dropoff_notes,
      otp_required
    )
    VALUES (
      v_order.user_id,
      v_order.merchant_id,
      p_order_id,
      'food_delivery',
      'motorcycle',
      'searching',
      'searching',
      COALESCE(NULLIF(v_merchant.address, ''), COALESCE(v_merchant.name, 'Store Pickup')),
      v_pickup_lat,
      v_pickup_lng,
      COALESCE(NULLIF(v_order.delivery_address, ''), 'Customer Address'),
      v_dropoff_lat,
      v_dropoff_lng,
      GREATEST(COALESCE(v_order.delivery_fee, v_merchant.delivery_fee, 20), 15),
      3.5,
      COALESCE(v_merchant.delivery_time_min, 30),
      COALESCE(v_order.payment_method, 'cash'),
      COALESCE(v_order.payment_status, 'pending'),
      'EGP',
      v_customer.full_name,
      v_customer.phone,
      COALESCE(v_items_summary, v_order.notes),
      v_merchant.name,
      COALESCE(v_order.notes, v_order.special_instructions),
      false
    )
    RETURNING id INTO v_ride_id;
  END IF;

  IF EXISTS (SELECT 1 FROM public.rides WHERE id=v_ride_id AND status <> 'searching') THEN
    RETURN jsonb_build_object('ok', true, 'order_id', p_order_id,
      'ride_id', v_ride_id, 'reason', 'ALREADY_ASSIGNED');
  END IF;
  v_dispatch := public.dispatch_delivery(v_ride_id, 25.0, 15);
  IF COALESCE((v_dispatch->>'success')::boolean, false) = false
     AND v_dispatch->>'reason' <> 'no_drivers_available' THEN
    RAISE EXCEPTION 'Dispatch failed: %', v_dispatch->>'reason';
  END IF;

  UPDATE public.orders
     SET dispatch_status = CASE WHEN (v_dispatch->>'success')::boolean THEN 'OFFERED' ELSE 'PENDING_DISPATCH' END,
         status = CASE
           WHEN status IN ('pending', 'confirmed', 'accepted', 'preparing') THEN 'ready'
           ELSE status
         END,
         updated_at = now()
   WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'dispatch', v_dispatch,
    'ok', true,
    'order_id', p_order_id,
    'ride_id', v_ride_id,
    'dispatch_status', CASE WHEN (v_dispatch->>'success')::boolean THEN 'OFFERED' ELSE 'PENDING_DISPATCH' END
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.merchant_order_contacts(p_merchant_id uuid)
 RETURNS TABLE(order_id uuid, full_name text, phone text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT (
    public.is_admin()
    OR EXISTS (
      SELECT 1 FROM public.merchants m
      WHERE m.id = p_merchant_id AND m.owner_user_id = v_uid
    )
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  RETURN QUERY
  SELECT o.id, u.full_name, u.phone
  FROM public.orders o
  JOIN public.users u ON u.id = o.user_id
  WHERE o.merchant_id = p_merchant_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.merchant_ready_for_dispatch(p_ride_id uuid, p_merchant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ride RECORD;
BEGIN
  IF NOT (EXISTS (
        SELECT 1 FROM public.merchants m
         WHERE m.id = p_merchant_id AND m.owner_user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid()) OR public.is_admin()) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;

  SELECT * INTO v_ride FROM rides WHERE id = p_ride_id AND merchant_id = p_merchant_id;
  IF v_ride IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'order_not_found');
  END IF;
  IF v_ride.status != 'searching' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'already_dispatched');
  END IF;

  -- The merchant confirms the order is ready; dispatch engine takes over
  RETURN jsonb_build_object('success', true, 'ride_id', p_ride_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.merchant_reject_order(p_order_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_order public.orders%rowtype;
  v_short text;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  end if;
  if not public.is_merchant_owner(v_order.merchant_id) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  if v_order.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', 'NOT_PENDING', 'status', v_order.status);
  end if;

  perform public._finalize_order_cancel(
    p_order_id, 'merchant',
    coalesce(nullif(btrim(p_reason), ''), 'رفض المتجر الطلب'),
    true, true, true, 'system');

  v_short := right(p_order_id::text, 6);
  insert into public.notifications (user_id, title, body, type, data, send_push)
  values (v_order.user_id,
          'المتجر اعتذر عن طلبك',
          'المتجر اعتذر عن تنفيذ الطلب رقم ' || v_short || '.' ||
            case when v_order.payment_status = 'paid'
                 then ' رجّعنا فلوسك كاملة في محفظتك.' else '' end ||
            case when v_order.coupon_id is not null
                 then ' والكوبون اللي استخدمته رجعلك تاني.' else '' end,
          'order',
          jsonb_build_object('order_id', p_order_id, 'status', 'cancelled',
                             'reason', 'merchant_rejected'),
          true);
  return jsonb_build_object('ok', true, 'code', 'OK', 'status', 'cancelled');
end;
$function$
;
CREATE OR REPLACE FUNCTION public.merchant_report_obligation_unpaid(p_obligation_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ob public.driver_obligations%ROWTYPE;
  v_merchant_uid uuid;
  v_driver_uid uuid;
BEGIN
  SELECT * INTO v_ob FROM public.driver_obligations WHERE id = p_obligation_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  SELECT owner_user_id INTO v_merchant_uid FROM public.merchants
   WHERE id = v_ob.merchant_id;
  IF auth.uid() IS NULL OR v_merchant_uid IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF v_ob.status <> 'open' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE');
  END IF;
  SELECT user_id INTO v_driver_uid FROM public.drivers WHERE id = v_ob.driver_id;
  INSERT INTO public.complaints
    (order_id, ride_id, complainant_id, respondent_id, reporter_id,
     complaint_type, category, subject, description, status, priority)
  VALUES
    (v_ob.order_id, v_ob.ride_id, v_merchant_uid, v_driver_uid, v_merchant_uid,
     'driver', 'settlement_unpaid',
     'التاجر يبلّغ: الكابتن لم يسدّد',
       'مديونية ' || v_ob.amount::text || ' ' || v_ob.currency ||
       ' عن الطلب ' || COALESCE(v_ob.order_id::text, '-') ||
       COALESCE('. ملاحظة التاجر: ' || p_note, ''),
     'pending', 'high');
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.merchant_request_payout(p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_merchant public.merchants%ROWTYPE;
  v_balance numeric;
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  SELECT * INTO v_merchant FROM public.merchants
   WHERE owner_user_id = auth.uid() LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NO_MERCHANT');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_AMOUNT');
  END IF;
  SELECT COALESCE(sum(CASE WHEN entry_type = 'credit' THEN amount ELSE -amount END), 0)
    INTO v_balance
    FROM public.merchant_ledger WHERE merchant_id = v_merchant.id;
  IF p_amount > v_balance THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INSUFFICIENT_BALANCE', 'balance', v_balance);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.merchant_payout_requests
     WHERE merchant_id = v_merchant.id AND status = 'pending'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'PENDING_EXISTS');
  END IF;
  INSERT INTO public.merchant_payout_requests (merchant_id, amount, requested_by)
  VALUES (v_merchant.id, p_amount, auth.uid())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok', true, 'id', v_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.merchant_set_settlement_model(p_model text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_merchant public.merchants%ROWTYPE;
  v_balance numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  IF p_model NOT IN ('platform','direct') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_MODEL');
  END IF;
  SELECT * INTO v_merchant FROM public.merchants
   WHERE owner_user_id = auth.uid() LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NO_MERCHANT');
  END IF;
  IF p_model = 'direct' AND v_merchant.settlement_model IS DISTINCT FROM 'direct' THEN
    SELECT COALESCE(sum(CASE WHEN entry_type = 'credit' THEN amount ELSE -amount END), 0)
      INTO v_balance
      FROM public.merchant_ledger WHERE merchant_id = v_merchant.id;
    IF v_balance > 0 THEN
      RETURN jsonb_build_object('ok', false, 'code', 'UNPAID_BALANCE', 'balance', v_balance);
    END IF;
  END IF;
  UPDATE public.merchants SET settlement_model = p_model, updated_at = now()
   WHERE id = v_merchant.id;
  RETURN jsonb_build_object('ok', true, 'model', p_model);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.merchants_guard_sensitive_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user in ('authenticated', 'anon') and not public.is_admin() then
    if NEW.owner_user_id is distinct from OLD.owner_user_id then
      raise exception 'owner_user_id is immutable';
    end if;
    if NEW.status is distinct from OLD.status then
      raise exception 'status is managed by the admin RPCs';
    end if;
    if NEW.rating is distinct from OLD.rating then
      raise exception 'rating is managed by the rating engine';
    end if;
    if NEW.total_reviews is distinct from OLD.total_reviews then
      raise exception 'total_reviews is managed by the rating engine';
    end if;
    if NEW.total_orders is distinct from OLD.total_orders then
      raise exception 'total_orders is managed by the order engine';
    end if;
    if NEW.delivery_fee is distinct from OLD.delivery_fee then
      raise exception 'delivery_fee is managed by the admin RPCs';
    end if;
    if NEW.min_order is distinct from OLD.min_order then
      raise exception 'min_order is managed by the admin RPCs';
    end if;
    if NEW.is_featured is distinct from OLD.is_featured then
      raise exception 'is_featured is managed by the admin RPCs';
    end if;
  end if;
  return NEW;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.modify_reservation(p_reservation_id uuid, p_party_size integer DEFAULT NULL::integer, p_reservation_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_special_requests text DEFAULT NULL::text, p_table_number text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_r public.reservations; v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  SELECT * INTO v_r FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF v_r IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF v_r.user_id IS DISTINCT FROM v_uid AND NOT public.is_admin() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  UPDATE public.reservations SET
     party_size       = COALESCE(p_party_size, v_r.party_size),
     reservation_time = COALESCE(p_reservation_time, v_r.reservation_time),
     special_requests = CASE WHEN p_special_requests IS NULL THEN v_r.special_requests ELSE p_special_requests END,
     table_number     = CASE WHEN p_table_number IS NULL THEN v_r.table_number ELSE p_table_number END
   WHERE id = v_r.id;
  RETURN jsonb_build_object('ok', true, 'code', 'OK');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.next_chat_reference()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN 'DWQ-' || nextval('public.chat_reference_seq')::text;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.normalize_arabic(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v text := lower(coalesce(p_text, ''));
BEGIN
  -- strip tatweel (U+0640) and all Arabic diacritics
  v := translate(v, E'\u0640\u064B\u064C\u064D\u064E\u064F\u0650\u0651\u0652\u0670', '');
  -- unify alef forms -> ا
  v := translate(v, E'\u0623\u0625\u0622\u0671\u0675', E'\u0627\u0627\u0627\u0627\u0627');
  -- ى -> ي ; ة -> ه ; آ handled above
  v := translate(v, E'\u0649\u0629', E'\u064A\u0647');
  -- strip common prefix ال / لل on token starts (approximate)
  v := regexp_replace(v, '\u0627\u0644', '', 'g');
  RETURN btrim(v);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notify_chat_message_reply()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_room public.chat_rooms%ROWTYPE;
  v_prev_sender uuid;
  v_customer uuid;
  v_admin_id uuid;
BEGIN
  IF NEW.sender_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_room FROM public.chat_rooms WHERE id = NEW.room_id;
  IF NOT FOUND OR COALESCE(v_room.room_type, '') <> 'support'
     OR COALESCE(v_room.is_active, true) = false
     OR v_room.status = 'closed' THEN
    RETURN NEW;
  END IF;

  -- Noise suppression: only the FIRST message of a turn (author change).
  SELECT sender_id INTO v_prev_sender
    FROM public.chat_messages
   WHERE room_id = NEW.room_id AND id <> NEW.id
   ORDER BY created_at DESC, id DESC
   LIMIT 1;
  IF v_prev_sender IS NOT NULL AND v_prev_sender = NEW.sender_id THEN
    RETURN NEW;
  END IF;

  IF public._is_active_admin_uid(NEW.sender_id) THEN
    -- Admin replied -> notify the customer participant(s).
    FOREACH v_customer IN ARRAY v_room.participant_ids LOOP
      IF v_customer IS NULL OR public._is_active_admin_uid(v_customer) THEN
        CONTINUE;
      END IF;
      INSERT INTO public.notifications
        (user_id, title, body, type, data, deep_link, idempotency_key,
         sender_id, priority, send_push)
      VALUES
        (v_customer, 'New support message', 'You have a new reply in support chat', 'message',
         jsonb_build_object('entity_type','room','entity_id', NEW.room_id::text,'action','reply'),
         '/support/room/' || NEW.room_id::text,
         'chat-msg-' || NEW.id::text,
         NEW.sender_id, 'normal', true)
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    END LOOP;
  ELSE
    -- Customer replied -> notify assigned admin; unassigned -> in-scope admins.
    v_admin_id := v_room.assigned_admin_id;
    IF v_admin_id IS NOT NULL THEN
      INSERT INTO public.notifications
        (user_id, title, body, type, data, deep_link, idempotency_key,
         sender_id, priority, send_push)
      VALUES
        (v_admin_id, 'New customer message', 'A customer replied in support chat', 'message',
         jsonb_build_object('entity_type','room','entity_id', NEW.room_id::text,'action','reply'),
         '/admin/support-chat/room/' || NEW.room_id::text,
         'chat-msg-' || NEW.id::text,
         NEW.sender_id, 'normal', true)
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    ELSE
      FOR v_admin_id IN
        SELECT u.id FROM public.users u
         WHERE public._is_active_admin_uid(u.id)
           AND (v_room.region_id IS NULL OR public._region_in_scope(u.id, v_room.region_id))
      LOOP
        INSERT INTO public.notifications
          (user_id, title, body, type, data, deep_link, idempotency_key,
           sender_id, priority, send_push)
        VALUES
          (v_admin_id, 'New customer message', 'A customer replied in support chat', 'message',
           jsonb_build_object('entity_type','room','entity_id', NEW.room_id::text,'action','reply'),
           '/admin/support-chat/room/' || NEW.room_id::text,
           'chat-msg-' || NEW.id::text || '-' || v_admin_id::text,
           NEW.sender_id, 'normal', true)
        ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
      END LOOP;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notify_complaint_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid;
  v_region uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- New complaint filed -> notify in-scope admins (fallback: all admins).
    v_region := public._member_region_id(NEW.complainant_id);
    FOR v_uid IN
      SELECT u.id FROM public.users u
       WHERE public._is_active_admin_uid(u.id)
         AND (v_region IS NULL OR public._region_in_scope(u.id, v_region))
    LOOP
      INSERT INTO public.notifications
        (user_id, title, body, type, data, deep_link, idempotency_key,
         sender_id, priority, send_push)
      VALUES
        (v_uid, 'New complaint', 'A new complaint requires review', 'complaint',
         jsonb_build_object('entity_type','complaint','entity_id', NEW.id::text,'action','new'),
         '/admin/complaints',
         'complaint-new-' || NEW.id::text || '-' || v_uid::text,
         NEW.complainant_id, 'normal', true)
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    END LOOP;
  ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    -- Status change -> complainant + reporter (if present and distinct).
    FOR v_uid IN
      SELECT DISTINCT t.uid FROM (
        SELECT NEW.complainant_id AS uid
        UNION ALL
        SELECT NEW.reporter_id
      ) t WHERE t.uid IS NOT NULL
    LOOP
      INSERT INTO public.notifications
        (user_id, title, body, type, data, deep_link, idempotency_key,
         sender_id, priority, send_push)
      VALUES
        (v_uid, 'Complaint update', 'Your complaint status changed to ' || NEW.status, 'complaint',
         jsonb_build_object('entity_type','complaint','entity_id', NEW.id::text,'action', NEW.status),
         '/my-complaints',
         'complaint-' || NEW.id::text || '-' || NEW.status || '-' || v_uid::text,
         NEW.complainant_id, 'normal', true)
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    END LOOP;
  END IF;

  RETURN NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notify_driver_delivery_assigned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
BEGIN
  IF NEW.service_type <> 'ride'
     AND NEW.driver_id IS NOT NULL
     AND (OLD.driver_id IS DISTINCT FROM NEW.driver_id) THEN
    SELECT user_id INTO v_uid FROM public.drivers WHERE id = NEW.driver_id;
    IF v_uid IS NOT NULL THEN
      INSERT INTO public.notifications
        (user_id, title, body, type, data, deep_link, idempotency_key, send_push)
      VALUES
        (v_uid, 'طلب توصيل جديد', 'عندك طلب توصيل جديد مستنييك', 'delivery',
         jsonb_build_object('entity_type', 'delivery', 'entity_id', NEW.id::text, 'action', 'assigned'),
         '/driver/hub',
         'delivery-assigned-' || NEW.id::text || '-' || v_uid::text,
         true)
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    END IF;
  END IF;
  RETURN NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notify_driver_delivery_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_user uuid;
BEGIN
 IF NEW.status <> 'offered' OR NEW.expires_at <= now() THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.rides WHERE id=NEW.ride_id AND service_type <> 'ride') THEN RETURN NEW; END IF;
 SELECT user_id INTO v_user FROM public.drivers WHERE id=NEW.driver_id;
 IF v_user IS NOT NULL THEN
   INSERT INTO public.notifications(user_id,title,body,type,data,deep_link,idempotency_key,send_push)
   VALUES(v_user,'عرض توصيل متاح','افتح التطبيق لمراجعة عرض التوصيل قبل انتهاء وقته','delivery',
     jsonb_build_object('entity_type','delivery','entity_id',NEW.ride_id::text,'action','offer','expires_at',NEW.expires_at),
     '/driver/hub','delivery-offer-'||NEW.id::text,true)
   ON CONFLICT(idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.notify_notification_push()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.send_push IS NOT TRUE OR NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;
  PERFORM public._enqueue_push(NEW.id);
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notify_order_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_title text;
  v_body text;
  v_merchant_name text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT name INTO v_merchant_name FROM public.merchants WHERE id = NEW.merchant_id;
    INSERT INTO public.notifications
      (user_id, title, body, type, data, deep_link, idempotency_key, sender_id, priority, send_push)
    SELECT
      m.owner_user_id,
      'طلب جديد 🛎️',
      'عندك طلب جديد بقيمة ' || COALESCE(NEW.total_amount::text, '?') || ' جنيه',
      'order',
      jsonb_build_object('entity_type', 'order', 'entity_id', NEW.id::text, 'action', 'new'),
      '/merchant-dashboard/orders',
      'order-new-' || NEW.id::text,
      NEW.user_id, 'high', true
    FROM public.merchants m
    WHERE m.id = NEW.merchant_id
      AND m.owner_user_id IS NOT NULL
    ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    RETURN NULL;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    v_title := CASE NEW.status
      WHEN 'confirmed' THEN 'تم تأكيد طلبك ✅'
      WHEN 'preparing' THEN 'طلبك بيتحضر 👨‍🍳'
      WHEN 'ready' THEN 'طلبك جاهز 📦'
      WHEN 'delivering' THEN 'طلبك في الطريق 🛵'
      WHEN 'delivered' THEN 'تم توصيل طلبك 🎉'
      WHEN 'cancelled' THEN 'تم إلغاء الطلب ❌'
      ELSE NULL
    END;
    v_body := CASE NEW.status
      WHEN 'confirmed' THEN 'المتجر أكد طلبك وهيبدأ يجهزه'
      WHEN 'preparing' THEN 'المتجر بيحضر طلبك دلوقتي'
      WHEN 'ready' THEN 'طلبك جاهز ومستني التوصيل'
      WHEN 'delivering' THEN 'الطيار في الطريق إليك بطلبك'
      WHEN 'delivered' THEN 'طلبك وصل، بالهنا والشفا 🌹'
      WHEN 'cancelled' THEN COALESCE(NULLIF(NEW.cancelled_reason, ''), 'اتأسفنا، الطلب اتلغى')
      ELSE NULL
    END;

    IF v_title IS NOT NULL THEN
      INSERT INTO public.notifications
        (user_id, title, body, type, data, deep_link, idempotency_key, sender_id, priority, send_push)
      VALUES
        (NEW.user_id, v_title, v_body, 'order',
         jsonb_build_object('entity_type', 'order', 'entity_id', NEW.id::text, 'action', NEW.status),
         '/orders/' || NEW.id::text || '/tracking',
         'order-' || NEW.id::text || '-' || NEW.status,
         NEW.merchant_id, 'normal', true)
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    END IF;
  END IF;

  RETURN NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.notify_sos_alert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_region uuid;
  v_uid uuid;
BEGIN
  v_region := public._member_region_id(NEW.user_id);
  FOR v_uid IN
    SELECT u.id FROM public.users u
     WHERE public._is_active_admin_uid(u.id)
       AND (v_region IS NULL OR public._region_in_scope(u.id, v_region))
  LOOP
    INSERT INTO public.notifications
      (user_id, title, body, type, data, deep_link, idempotency_key,
       sender_id, priority, send_push)
    VALUES
      (v_uid, 'SOS Emergency Alert', 'A user triggered an SOS alert', 'emergency',
       jsonb_build_object('entity_type','sos','entity_id', NEW.id::text,'action','sos'),
       '/admin/live-tracking',
       'sos-notify-' || NEW.id::text || '-' || v_uid::text,
       NEW.user_id, 'high', true)
    ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
  END LOOP;

  -- NOTE: sos trusted_contacts are external phone/email records (owner-scoped),
  -- NOT app users, so no in-app notifications row can target them. SMS/call
  -- alerting to contacts is out of scope for Phase 2.4.1 (documented, HANDOFF-35).
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.open_emergency_chat(p_lat double precision, p_lon double precision, p_message text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_room_id uuid;
  v_region_id uuid;
  v_admin_id uuid;
  v_customer_id uuid := auth.uid();
BEGIN
  SELECT g.region_id INTO v_region_id
  FROM public.geo_region_for_point(p_lat, p_lon, 2, 25000) g
  WHERE g.confidence IN ('HIGH','MEDIUM')
  LIMIT 1;

  INSERT INTO public.chat_rooms
    (room_type, participant_ids, priority, status, region_id)
  VALUES
    ('support', ARRAY[v_customer_id], 'emergency', 'open', v_region_id)
  RETURNING id INTO v_room_id;

  IF p_message IS NOT NULL AND btrim(p_message) <> '' THEN
    INSERT INTO public.chat_messages
      (room_id, sender_id, message, message_type)
    VALUES (v_room_id, v_customer_id, p_message, 'text');
  END IF;

  v_admin_id := public.resolve_support_admin(v_region_id, true);
  IF v_admin_id IS NOT NULL THEN
    PERFORM public._assign_chat_to_admin(v_room_id, v_admin_id, 'assigned');
    INSERT INTO public.notifications
      (user_id, title, body, type, data, deep_link, idempotency_key)
    VALUES (
      v_admin_id,
      'EMERGENCY support request',
      'Immediate assistance required.',
      'emergency_alert',
      jsonb_build_object('room_id', v_room_id::text, 'region_id', v_region_id),
      '/admin/support-chat/room/' || v_room_id::text,
      'emergency-alert-' || v_room_id::text
    );
  END IF;

  PERFORM public.write_audit(
    'EMERGENCY_OPENED', 'chat_rooms', v_room_id::text,
    jsonb_build_object('region_id', v_region_id, 'assigned_admin_id', v_admin_id,
                       'lat', p_lat, 'lon', p_lon)
  );

  RETURN v_room_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.orders_guard_sensitive()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_merchant_owner boolean;
begin
  -- DEFINER RPCs and backend run as the table owner.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if public._is_active_admin_uid(auth.uid()) then
    return new;
  end if;

  -- Freeze everything except status + updated_at for ALL direct client writes.
  if (to_jsonb(new) - 'status' - 'updated_at') is distinct from
     (to_jsonb(old) - 'status' - 'updated_at') then
    raise exception 'order fields are managed by the order RPCs';
  end if;

  v_merchant_owner := public.is_merchant_owner(old.merchant_id);

  if new.status is distinct from old.status then
    if not v_merchant_owner then
      raise exception 'order status is managed by the order RPCs';
    end if;
    -- Forward-only kitchen pairs; delivered/cancelled are terminal here;
    -- completion via merchant_complete_order, cancellation via RPCs.
    if not (
      (old.status = 'pending'   and new.status = 'confirmed') or
      (old.status = 'confirmed' and new.status = 'preparing') or
      (old.status = 'preparing' and new.status = 'ready') or
      (old.status = 'ready'     and new.status = 'delivering')
    ) then
      raise exception 'unsupported order status transition: % -> %', old.status, new.status;
    end if;
  end if;

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.owner_create_receiving_account(p_method_type text, p_display_name text, p_account_name text DEFAULT NULL::text, p_account_number text DEFAULT NULL::text, p_wallet_number text DEFAULT NULL::text, p_instructions text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF NOT public._is_owner_uid(auth.uid()) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  INSERT INTO public.platform_receiving_accounts
    (method_type, display_name, account_name, account_number, wallet_number, instructions)
  VALUES
    (p_method_type, p_display_name, p_account_name, p_account_number, p_wallet_number, p_instructions)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.owner_delete_member(p_member_id uuid, p_reason text DEFAULT 'Deleted by owner'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public._is_owner_uid(auth.uid()) THEN
    RAISE EXCEPTION 'Only the owner can delete accounts directly';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_member_id) THEN
    RAISE EXCEPTION 'Member not found';
  END IF;
  IF public._is_owner_uid(p_member_id) THEN
    RAISE EXCEPTION 'Cannot delete the owner account';
  END IF;

  -- If member is an admin, deactivate them through the admin hierarchy first
  IF EXISTS (
    SELECT 1 FROM public.admin_management
    WHERE admin_id = p_member_id AND is_active
  ) THEN
    PERFORM public._admin_exec_deactivate(auth.uid(), p_member_id, COALESCE(p_reason, 'Deleted by owner'));
  END IF;

  PERFORM public._member_exec_delete(auth.uid(), p_member_id, COALESCE(p_reason, 'Deleted by owner'));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.owner_update_receiving_account(p_id uuid, p_is_active boolean DEFAULT NULL::boolean, p_display_name text DEFAULT NULL::text, p_account_name text DEFAULT NULL::text, p_account_number text DEFAULT NULL::text, p_wallet_number text DEFAULT NULL::text, p_instructions text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public._is_owner_uid(auth.uid()) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  UPDATE public.platform_receiving_accounts
     SET is_active = COALESCE(p_is_active, is_active),
         display_name = COALESCE(p_display_name, display_name),
         account_name = COALESCE(p_account_name, account_name),
         account_number = COALESCE(p_account_number, account_number),
         wallet_number = COALESCE(p_wallet_number, wallet_number),
         instructions = COALESCE(p_instructions, instructions),
         updated_at = now()
   WHERE id = p_id;
  RETURN found;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.pharmacy_import_drug(p_drug_id uuid, p_merchant_id uuid, p_price numeric DEFAULT NULL::numeric, p_stock integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_merchant public.merchants%ROWTYPE;
  v_drug public.drug_catalog%ROWTYPE;
  v_product_id uuid;
  v_price numeric;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_stock IS NULL OR p_stock < 0 THEN
    RAISE EXCEPTION 'INVALID_STOCK';
  END IF;

  SELECT * INTO v_merchant FROM public.merchants WHERE id = p_merchant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'MERCHANT_NOT_FOUND';
  END IF;
  IF v_merchant.owner_user_id <> v_uid AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'NOT_YOUR_STORE';
  END IF;

  SELECT * INTO v_drug FROM public.drug_catalog
    WHERE id = p_drug_id AND is_active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DRUG_NOT_FOUND';
  END IF;

  -- Default to the official retail price when the caller does not set one.
  v_price := COALESCE(p_price, v_drug.official_price_egp);
  IF v_price IS NULL OR v_price < 0 THEN
    RAISE EXCEPTION 'INVALID_PRICE';
  END IF;

  -- Duplicate guard: re-importing the same drug returns the existing product.
  SELECT id INTO v_product_id FROM public.products
   WHERE merchant_id = p_merchant_id
     AND ((v_drug.barcode IS NOT NULL AND barcode = v_drug.barcode)
          OR (v_drug.barcode IS NULL
              AND name = v_drug.name_en || COALESCE(' ' || v_drug.strength, '')))
   ORDER BY created_at
   LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'product_id', v_product_id, 'duplicate', true);
  END IF;

  INSERT INTO public.products (
    merchant_id, name, name_ar, description, description_ar, price,
    category, stock_quantity, is_available, barcode
  ) VALUES (
    p_merchant_id,
    v_drug.name_en || COALESCE(' ' || v_drug.strength, ''),
    v_drug.name_ar,
    concat_ws(' · ', v_drug.active_ingredient, v_drug.strength,
              v_drug.dosage_form, v_drug.manufacturer),
    NULL,
    v_price,
    'pharmacy',
    p_stock,
    true,
    v_drug.barcode
  )
  RETURNING id INTO v_product_id;

  RETURN jsonb_build_object('ok', true, 'product_id', v_product_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_collection_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_total       numeric := 0;
  v_settled     numeric := 0;
  v_outstanding numeric := 0;
  v_today       numeric := 0;
  v_week        numeric := 0;
  v_month       numeric := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT public._is_owner_uid(auth.uid()) THEN
    RETURN NULL;
  END IF;

  SELECT
    COALESCE(SUM(amount), 0),
    COALESCE(SUM(amount) FILTER (WHERE status = 'settled'), 0),
    COALESCE(SUM(amount) FILTER (WHERE received_at >= date_trunc('day', now())), 0),
    COALESCE(SUM(amount) FILTER (WHERE received_at >= date_trunc('week', now())), 0),
    COALESCE(SUM(amount) FILTER (WHERE received_at >= date_trunc('month', now())), 0)
  INTO v_total, v_settled, v_today, v_week, v_month
  FROM public.regional_collections;

  v_outstanding := GREATEST(0, v_total - v_settled);

  RETURN jsonb_build_object(
    'summary', jsonb_build_object(
      'total', v_total, 'settled', v_settled, 'outstanding', v_outstanding,
      'today', v_today, 'week', v_week, 'month', v_month
    ),
    'by_region', COALESCE((
      SELECT jsonb_agg(r) FROM (
        SELECT jsonb_build_object(
          'region_id', c.region_id,
          'total', COALESCE(SUM(c.amount), 0),
          'settled', COALESCE(SUM(c.amount) FILTER (WHERE c.status = 'settled'), 0),
          'outstanding', GREATEST(0, COALESCE(SUM(c.amount), 0)
            - COALESCE(SUM(c.amount) FILTER (WHERE c.status = 'settled'), 0))
        ) AS r
        FROM public.regional_collections c
        GROUP BY c.region_id
        ORDER BY SUM(c.amount) DESC
      ) sub
    ), '[]'::jsonb),
    'rows', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', c.id, 'admin_id', c.admin_id, 'region_id', c.region_id,
        'account_id', c.account_id, 'amount', c.amount, 'currency', c.currency,
        'reference', c.reference, 'status', c.status, 'received_at', c.received_at
      ))
      FROM (
        SELECT * FROM public.regional_collections ORDER BY received_at DESC LIMIT 200
      ) c
    ), '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_commission_for_reference(p_reference_type text, p_reference_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid           uuid := auth.uid();
  v_member_id     uuid;
  v_account_type  text;
  v_category      text;
  v_gross         numeric;
  v_rate          numeric;
  v_commission    numeric;
  v_net           numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;
  IF NOT (public._is_owner_uid(v_uid)
          OR public.has_permission('MEMBER_VIEW', NULL)) THEN
    RETURN NULL;
  END IF;

  IF p_reference_type = 'order' THEN
    SELECT m.owner_user_id, 'merchant', m.type, o.total_amount
      INTO v_member_id, v_account_type, v_category, v_gross
      FROM public.orders o
      JOIN public.merchants m ON m.id = o.merchant_id
     WHERE o.id = p_reference_id;
  ELSIF p_reference_type = 'ride' THEN
    SELECT d.user_id, 'driver', NULL, COALESCE(r.fare, r.base_fare)
      INTO v_member_id, v_account_type, v_category, v_gross
      FROM public.rides r
      JOIN public.drivers d ON d.id = r.driver_id
     WHERE r.id = p_reference_id;
  ELSIF p_reference_type = 'service_booking' THEN
    SELECT sp.user_id, 'provider', sb.category_type,
           COALESCE(sb.final_price, sb.estimated_price)
      INTO v_member_id, v_account_type, v_category, v_gross
      FROM public.service_bookings sb
      JOIN public.service_providers sp ON sp.id = sb.provider_id
     WHERE sb.id = p_reference_id;
  END IF;

  IF v_member_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_gross := COALESCE(v_gross, 0);
  v_rate  := public.get_commission_rate(v_account_type, v_category, v_member_id);
  IF v_rate IS NULL THEN
    RETURN NULL;
  END IF;
  v_commission := public.calculate_commission(v_gross, v_rate);
  v_net        := ROUND(v_gross - v_commission, 2);

  INSERT INTO public.platform_commissions
    (member_id, reference_type, reference_id, gross_amount, commission_rate,
     commission_amount, net_amount, currency, created_by)
  VALUES
    (v_member_id, p_reference_type, p_reference_id, v_gross, v_rate,
     v_commission, v_net, 'SAR', v_uid)
  ON CONFLICT (reference_type, reference_id) DO NOTHING;  -- preserve first snapshot

  RETURN jsonb_build_object(
    'member_id',       v_member_id,
    'reference_type',  p_reference_type,
    'reference_id',    p_reference_id,
    'account_type',    v_account_type,
    'service_category', v_category,
    'gross_amount',    v_gross,
    'commission_rate', v_rate,
    'commission_amount', v_commission,
    'net_amount',      v_net,
    'currency',        'SAR'
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_commission_summary(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_has_revenue boolean;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;
  v_has_revenue := has_permission('PLATFORM_REVENUE', v_member_id);
  IF NOT v_has_revenue THEN
    RETURN jsonb_build_object('error', 'insufficient_permissions');
  END IF;

  RETURN jsonb_build_object(
    'total_commission',     (SELECT COALESCE(SUM(commission_amount), 0) FROM platform_commissions WHERE created_at >= v_from AND created_at <= v_to),
    'fulfilled_commission', (SELECT COALESCE(SUM(commission_amount), 0) FROM platform_commissions WHERE status = 'fulfilled' AND created_at >= v_from AND created_at <= v_to),
    'pending_commission',   (SELECT COALESCE(SUM(commission_amount), 0) FROM platform_commissions WHERE status = 'pending' AND created_at >= v_from AND created_at <= v_to),
    'commission_by_rate', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('rate', commission_rate, 'amount', commission_amount)), '[]'::jsonb)
      FROM platform_commissions WHERE created_at >= v_from AND created_at <= v_to
    ),
    'active_rules', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'entity_type', entity_type, 'entity_key', entity_key, 'rate', rate, 'currency', currency
      )), '[]'::jsonb)
      FROM commission_rules WHERE is_active = true
    ),
    'date_from', v_from,
    'date_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_complaint_summary(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'total_complaints',    (SELECT count(*) FROM complaints WHERE created_at >= v_from AND created_at <= v_to),
    'open_complaints',     (SELECT count(*) FROM complaints WHERE status NOT IN ('resolved','closed')),
    'escalated_complaints', (SELECT count(*) FROM complaints WHERE escalated_at IS NOT NULL AND status NOT IN ('resolved','closed')),
    'resolved_complaints', (SELECT count(*) FROM complaints WHERE status IN ('resolved','closed') AND resolved_at >= v_from AND resolved_at <= v_to),
    'complaints_by_status', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('status', status, 'count', cnt)), '[]'::jsonb)
      FROM (SELECT status, count(*) as cnt FROM complaints WHERE created_at >= v_from AND created_at <= v_to GROUP BY status) sub
    ),
    'escalation_events',   (SELECT count(*) FROM escalation_events WHERE created_at >= v_from AND created_at <= v_to),
    'date_from', v_from,
    'date_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_delivery_intelligence(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_has_revenue boolean;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;
  v_has_revenue := has_permission('PLATFORM_REVENUE', v_member_id);

  RETURN jsonb_build_object(
    'total_drivers',       (SELECT count(*) FROM drivers),
    'online_drivers',      (SELECT count(*) FROM drivers WHERE is_online = true),
    'verified_drivers',    (SELECT count(*) FROM drivers WHERE is_verified = true),
    'pending_drivers',     (SELECT count(*) FROM drivers WHERE verification_status = 'pending'),
    'completed_deliveries',(SELECT count(*) FROM rides WHERE service_type != 'ride' AND status = 'completed' AND completed_at >= v_from AND completed_at <= v_to),
    'pending_deliveries',  (SELECT count(*) FROM rides WHERE service_type != 'ride' AND status IN ('searching','matched','arrived')),
    'cancelled_deliveries',(SELECT count(*) FROM rides WHERE service_type != 'ride' AND status = 'cancelled' AND cancelled_at >= v_from AND cancelled_at <= v_to),
    'delivery_gmv',        CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(fare), 0) FROM rides WHERE service_type != 'ride' AND status = 'completed' AND completed_at >= v_from AND completed_at <= v_to)
    ELSE 0 END,
    'driver_earnings_total',CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(amount), 0) FROM driver_earnings WHERE created_at >= v_from AND created_at <= v_to)
    ELSE 0 END,
    'pending_withdrawals',    (SELECT count(*) FROM withdrawal_requests WHERE status = 'pending'),
    'pending_withdrawal_amount', CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(amount), 0) FROM withdrawal_requests WHERE status = 'pending')
    ELSE 0 END,
    'paid_withdrawals',       (SELECT count(*) FROM withdrawal_requests WHERE status = 'paid'),
    'paid_withdrawal_amount', CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(amount), 0) FROM withdrawal_requests WHERE status = 'paid')
    ELSE 0 END,
    'date_from', v_from,
    'date_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_kpi_summary(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_region_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_member_id uuid;
  v_has_revenue boolean;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
  v_result jsonb;
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL THEN
    RETURN NULL;
  END IF;
  IF NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;

  v_has_revenue := has_permission('PLATFORM_REVENUE', v_member_id);

  SELECT jsonb_build_object(
    -- Members
    'total_users',         (SELECT count(*) FROM users),
    'customers',           (SELECT count(*) FROM users WHERE user_type = 'customer'),
    'providers',           (SELECT count(*) FROM users WHERE user_type = 'provider'),
    'delivery_users',      (SELECT count(*) FROM users WHERE user_type = 'delivery'),
    'merchant_users',      (SELECT count(*) FROM users WHERE user_type = 'merchant'),
    'driver_users',        (SELECT count(*) FROM users WHERE user_type = 'driver'),
    'new_users_period',    (SELECT count(*) FROM users WHERE created_at >= v_from AND created_at <= v_to),
    'pending_verification',(SELECT count(*) FROM users WHERE verification_status = 'pending'),
    'verified_members',    (SELECT count(*) FROM users WHERE verification_status = 'approved'),
    'rejected_members',    (SELECT count(*) FROM users WHERE verification_status = 'rejected'),
    'new_today',           (SELECT count(*) FROM users WHERE created_at >= date_trunc('day', v_now)),
    'new_this_week',       (SELECT count(*) FROM users WHERE created_at >= date_trunc('week', v_now)),
    'new_this_month',      (SELECT count(*) FROM users WHERE created_at >= date_trunc('month', v_now)),

    -- Drivers
    'total_drivers',       (SELECT count(*) FROM drivers),
    'online_drivers',      (SELECT count(*) FROM drivers WHERE is_online = true),
    'verified_drivers',    (SELECT count(*) FROM drivers WHERE is_verified = true),

    -- Merchants
    'total_merchants',     (SELECT count(*) FROM merchants),
    'active_merchants',    (SELECT count(*) FROM merchants WHERE status = 'active'),
    'merchants_by_type',   (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('type', type, 'count', c)), '[]'::jsonb)
      FROM (SELECT type, count(*) as c FROM merchants GROUP BY type) sub
    ),

    -- Orders
    'total_orders',        (SELECT count(*) FROM orders),
    'orders_today',        (SELECT count(*) FROM orders WHERE created_at >= date_trunc('day', v_now)),
    'orders_this_week',    (SELECT count(*) FROM orders WHERE created_at >= date_trunc('week', v_now)),
    'orders_this_month',   (SELECT count(*) FROM orders WHERE created_at >= date_trunc('month', v_now)),
    'completed_orders',    (SELECT count(*) FROM orders WHERE status = 'completed'),
    'pending_orders',      (SELECT count(*) FROM orders WHERE status = 'pending'),
    'cancelled_orders',    (SELECT count(*) FROM orders WHERE status = 'cancelled'),

    -- Rides & Deliveries
    'total_rides',         (SELECT count(*) FROM rides WHERE service_type = 'ride'),
    'completed_rides',     (SELECT count(*) FROM rides WHERE service_type = 'ride' AND status = 'completed'),
    'active_rides',        (SELECT count(*) FROM rides WHERE service_type = 'ride' AND status IN ('searching','matched','arrived','inTrip')),
    'total_deliveries',    (SELECT count(*) FROM rides WHERE service_type != 'ride'),
    'completed_deliveries',(SELECT count(*) FROM rides WHERE service_type != 'ride' AND status = 'completed'),
    'active_deliveries',   (SELECT count(*) FROM rides WHERE service_type != 'ride' AND status IN ('searching','matched','arrived','inTrip')),

    -- Service Bookings
    'total_service_bookings',  (SELECT count(*) FROM service_bookings),
    'completed_service_bookings',(SELECT count(*) FROM service_bookings WHERE status = 'completed'),

    -- Financial (conditional on permission)
    'total_gmv',           CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(total_amount), 0) FROM orders WHERE status = 'completed' AND created_at >= v_from AND created_at <= v_to)
    ELSE 0 END,
    'ride_gmv',            CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(fare), 0) FROM rides WHERE service_type = 'ride' AND status = 'completed' AND completed_at >= v_from AND completed_at <= v_to)
    ELSE 0 END,
    'delivery_gmv',        CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(fare), 0) FROM rides WHERE service_type != 'ride' AND status = 'completed' AND completed_at >= v_from AND completed_at <= v_to)
    ELSE 0 END,
    'service_gmv',         CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(final_price), 0) FROM service_bookings WHERE status = 'completed' AND completed_at >= v_from AND completed_at <= v_to)
    ELSE 0 END,
    'platform_commission', CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(commission_amount), 0) FROM platform_commissions WHERE created_at >= v_from AND created_at <= v_to)
    ELSE 0 END,
    'driver_earnings_total',CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(amount), 0) FROM driver_earnings WHERE created_at >= v_from AND created_at <= v_to)
    ELSE 0 END,
    'total_wallet_liability',CASE WHEN v_has_revenue THEN
      (SELECT COALESCE(SUM(balance), 0) FROM wallets)
    ELSE 0 END,
    'commission_7pct',     CASE WHEN v_has_revenue THEN
      public._commission_bucket_amount(v_from, v_to, 'provider')
    ELSE 0 END,
    'commission_3pct',     CASE WHEN v_has_revenue THEN
      public._commission_bucket_amount(v_from, v_to, 'merchant')
    ELSE 0 END,

    -- Risk
    'open_complaints',     (SELECT count(*) FROM complaints WHERE status NOT IN ('resolved','closed')),
    'escalated_complaints', (SELECT count(*) FROM complaints WHERE escalated_at IS NOT NULL AND status NOT IN ('resolved','closed')),
    'active_sanctions',    (SELECT count(*) FROM sanctions WHERE is_active = true),
    'sos_active',          (SELECT count(*) FROM sos_alerts WHERE status = 'active'),
    'pending_withdrawals', (SELECT count(*) FROM withdrawal_requests WHERE status = 'pending'),
    'payment_failures',    (SELECT count(*) FROM payment_transactions WHERE status = 'failed' AND created_at >= v_from AND created_at <= v_to),

    -- Period
    'date_from', v_from
  ) || jsonb_build_object('date_to', v_to) INTO v_result;

  RETURN v_result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_merchant_intelligence(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_has_rev boolean;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;
  v_has_rev := has_permission('PLATFORM_REVENUE', v_member_id);

  RETURN jsonb_build_object(
    'total_merchants', (SELECT count(*) FROM merchants),
    'active_merchants', (SELECT count(*) FROM merchants WHERE status='active'),
    'merchants_by_type', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('type', sub.typ, 'count', sub.cnt)), '[]'::jsonb)
      FROM (SELECT m2.type as typ, count(*) as cnt FROM merchants m2 GROUP BY m2.type) sub
    ),
    'merchants', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', m2.id, 'name', m2.name, 'type', m2.type, 'status', m2.status,
        'rating', m2.rating, 'total_orders', m2.total_orders
      ) ORDER BY m2.total_orders DESC NULLS LAST), '[]'::jsonb)
      FROM merchants m2
    ),
    'date_from', v_from,
    'date_to', v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_operational_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_alerts jsonb := '[]'::jsonb;
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;

  IF (SELECT count(*) FROM users WHERE verification_status = 'pending') > 0 THEN
    v_alerts := v_alerts || jsonb_build_object(
      'type', 'verification_backlog', 'severity', 'warning',
      'message', 'Pending verification backlog',
      'count', (SELECT count(*) FROM users WHERE verification_status = 'pending'),
      'action_route', '/admin/verifications'
    );
  END IF;

  IF (SELECT count(*) FROM complaints WHERE status NOT IN ('resolved','closed')) > 0 THEN
    v_alerts := v_alerts || jsonb_build_object(
      'type', 'open_complaints', 'severity', 'warning',
      'message', 'Open complaints require attention',
      'count', (SELECT count(*) FROM complaints WHERE status NOT IN ('resolved','closed')),
      'action_route', '/admin/complaints'
    );
  END IF;

  IF (SELECT count(*) FROM complaints WHERE escalated_at IS NOT NULL AND status NOT IN ('resolved','closed')) > 0 THEN
    v_alerts := v_alerts || jsonb_build_object(
      'type', 'escalated_complaints', 'severity', 'critical',
      'message', 'Escalated complaints need immediate attention',
      'count', (SELECT count(*) FROM complaints WHERE escalated_at IS NOT NULL AND status NOT IN ('resolved','closed')),
      'action_route', '/admin/escalations'
    );
  END IF;

  IF (SELECT count(*) FROM sos_alerts WHERE status = 'active') > 0 THEN
    v_alerts := v_alerts || jsonb_build_object(
      'type', 'active_sos', 'severity', 'critical',
      'message', 'Active emergency SOS alerts',
      'count', (SELECT count(*) FROM sos_alerts WHERE status = 'active'),
      'action_route', '/admin/live-tracking'
    );
  END IF;

  IF (SELECT count(*) FROM withdrawal_requests WHERE status = 'pending') > 0 THEN
    v_alerts := v_alerts || jsonb_build_object(
      'type', 'pending_withdrawals', 'severity', 'info',
      'message', 'Pending withdrawal requests',
      'count', (SELECT count(*) FROM withdrawal_requests WHERE status = 'pending'),
      'action_route', '/admin/drivers'
    );
  END IF;

  IF (SELECT count(*) FROM payment_transactions WHERE status = 'failed' AND created_at >= now() - interval '24 hours') > 0 THEN
    v_alerts := v_alerts || jsonb_build_object(
      'type', 'payment_failures', 'severity', 'warning',
      'message', 'Payment failures in last 24 hours',
      'count', (SELECT count(*) FROM payment_transactions WHERE status = 'failed' AND created_at >= now() - interval '24 hours'),
      'action_route', '/admin/orders'
    );
  END IF;

  IF (SELECT count(*) FROM sanctions WHERE is_active = true) > 0 THEN
    v_alerts := v_alerts || jsonb_build_object(
      'type', 'active_sanctions', 'severity', 'info',
      'message', 'Active sanctions on platform',
      'count', (SELECT count(*) FROM sanctions WHERE is_active = true),
      'action_route', '/admin/sanctions'
    );
  END IF;

  RETURN jsonb_build_object('alerts', v_alerts, 'count', jsonb_array_length(v_alerts));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_orders_timeseries(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, v_now - interval '30 days');
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'orders_by_status', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('status', status, 'count', cnt)), '[]'::jsonb)
      FROM (SELECT status, count(*) as cnt FROM orders WHERE created_at >= v_from AND created_at <= v_to GROUP BY status) sub
    ),
    'rides_by_status', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('status', status, 'count', cnt)), '[]'::jsonb)
      FROM (SELECT status, count(*) as cnt FROM rides WHERE service_type = 'ride' AND created_at >= v_from AND created_at <= v_to GROUP BY status) sub
    ),
    'deliveries_by_status', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('status', status, 'service_type', service_type, 'count', cnt)), '[]'::jsonb)
      FROM (SELECT status, service_type, count(*) as cnt FROM rides WHERE service_type != 'ride' AND created_at >= v_from AND created_at <= v_to GROUP BY status, service_type) sub
    ),
    'service_bookings_by_status', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('status', status, 'category_type', category_type, 'count', cnt)), '[]'::jsonb)
      FROM (SELECT status, category_type, count(*) as cnt FROM service_bookings WHERE created_at >= v_from AND created_at <= v_to GROUP BY status, category_type) sub
    ),
    'orders_by_day', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('date', day, 'count', cnt)), '[]'::jsonb)
      FROM (SELECT date_trunc('day', created_at)::date as day, count(*) as cnt FROM orders WHERE created_at >= v_from AND created_at <= v_to GROUP BY day ORDER BY day) sub
    ),
    'date_from', v_from,
    'date_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_provider_intelligence(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'total_providers',    (SELECT count(*) FROM service_providers),
    'verified_providers', (SELECT count(*) FROM service_providers WHERE is_verified = true),
    'available_providers',(SELECT count(*) FROM service_providers WHERE is_available = true),
    'providers_by_category', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('category', category_type, 'count', cnt, 'avg_rating', avg_r)), '[]'::jsonb)
      FROM (
        SELECT category_type, count(*) as cnt, COALESCE(AVG(rating), 0) as avg_r
        FROM service_providers GROUP BY category_type
      ) sub
    ),
    'bookings_by_category', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('category', category_type, 'total', t, 'completed', c, 'gmv', g)), '[]'::jsonb)
      FROM (
        SELECT category_type, count(*) as t,
          count(*) FILTER (WHERE status = 'completed') as c,
          COALESCE(SUM(final_price) FILTER (WHERE status = 'completed'), 0) as g
        FROM service_bookings WHERE created_at >= v_from AND created_at <= v_to
        GROUP BY category_type
      ) sub
    ),
    'date_from', v_from,
    'date_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_revenue_breakdown(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_region_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_member_id uuid;
  v_has_revenue boolean;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;
  v_has_revenue := has_permission('PLATFORM_REVENUE', v_member_id);
  IF NOT v_has_revenue THEN
    RETURN jsonb_build_object('error', 'insufficient_permissions');
  END IF;

  RETURN jsonb_build_object(
    'orders_gmv',     (SELECT COALESCE(SUM(total_amount), 0) FROM orders WHERE status = 'completed' AND created_at >= v_from AND created_at <= v_to),
    'ride_gmv',       (SELECT COALESCE(SUM(fare), 0) FROM rides WHERE service_type = 'ride' AND status = 'completed' AND completed_at >= v_from AND completed_at <= v_to),
    'delivery_gmv',   (SELECT COALESCE(SUM(fare), 0) FROM rides WHERE service_type != 'ride' AND status = 'completed' AND completed_at >= v_from AND completed_at <= v_to),
    'service_gmv',    (SELECT COALESCE(SUM(final_price), 0) FROM service_bookings WHERE status = 'completed' AND completed_at >= v_from AND completed_at <= v_to),
    'total_gmv',      (SELECT COALESCE(SUM(total_amount), 0) FROM orders WHERE status = 'completed' AND created_at >= v_from AND created_at <= v_to)
      + (SELECT COALESCE(SUM(fare), 0) FROM rides WHERE status = 'completed' AND completed_at >= v_from AND completed_at <= v_to)
      + (SELECT COALESCE(SUM(final_price), 0) FROM service_bookings WHERE status = 'completed' AND completed_at >= v_from AND completed_at <= v_to),
    'total_commission',     (SELECT COALESCE(SUM(commission_amount), 0) FROM platform_commissions WHERE created_at >= v_from AND created_at <= v_to),
    'fulfilled_commission', (SELECT COALESCE(SUM(commission_amount), 0) FROM platform_commissions WHERE status = 'fulfilled' AND created_at >= v_from AND created_at <= v_to),
    'pending_commission',   (SELECT COALESCE(SUM(commission_amount), 0) FROM platform_commissions WHERE status = 'pending' AND created_at >= v_from AND created_at <= v_to),
    'commission_7pct',      public._commission_bucket_amount(v_from, v_to, 'provider'),
    'commission_3pct',      public._commission_bucket_amount(v_from, v_to, 'merchant'),
    'provider_earnings',    (SELECT COALESCE(SUM(final_price), 0) FROM service_bookings WHERE status = 'completed' AND completed_at >= v_from AND completed_at <= v_to),
    'driver_earnings',      (SELECT COALESCE(SUM(amount), 0) FROM driver_earnings WHERE created_at >= v_from AND created_at <= v_to),
    'refund_count',         (SELECT count(*) FROM orders WHERE status = 'cancelled' AND created_at >= v_from AND created_at <= v_to),
    'financial_by_day', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('date', day, 'gmv', gmv, 'commission', 0)), '[]'::jsonb)
      FROM (
        SELECT date_trunc('day', created_at)::date as day, COALESCE(SUM(total_amount), 0) as gmv
        FROM orders WHERE status = 'completed' AND created_at >= v_from AND created_at <= v_to
        GROUP BY day ORDER BY day
      ) sub
    ),
    'date_from', v_from,
    'date_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_revenue_overview(p_period text DEFAULT 'all'::text, p_service_category text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_member_id uuid;
  v_has_revenue boolean;
  v_now timestamptz := now();
  v_from timestamptz;
  v_to   timestamptz;
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;
  v_has_revenue := has_permission('PLATFORM_REVENUE', v_member_id);
  IF NOT v_has_revenue THEN
    RETURN jsonb_build_object('error', 'insufficient_permissions');
  END IF;

  v_to := v_now;
  v_from := CASE p_period
    WHEN 'today' THEN date_trunc('day', v_now)
    WHEN 'yesterday' THEN date_trunc('day', v_now) - interval '1 day'
    WHEN '7d' THEN v_now - interval '7 days'
    WHEN '30d' THEN v_now - interval '30 days'
    WHEN 'month' THEN date_trunc('month', v_now)
    WHEN 'last_month' THEN date_trunc('month', v_now) - interval '1 month'
    WHEN 'year' THEN date_trunc('year', v_now)
    WHEN 'custom' THEN COALESCE(p_from::timestamptz, '1970-01-01'::timestamptz)
    ELSE '1970-01-01'::timestamptz
  END;

  IF p_period = 'custom' AND p_to IS NOT NULL THEN
    v_to := p_to::timestamptz + interval '1 day';
  END IF;

  RETURN jsonb_build_object(
    'total_gmv',      (SELECT COALESCE(SUM(total_amount), 0) FROM orders WHERE status = 'completed' AND created_at >= v_from AND created_at <= v_to)
      + (SELECT COALESCE(SUM(fare), 0) FROM rides WHERE status = 'completed' AND completed_at >= v_from AND completed_at <= v_to)
      + (SELECT COALESCE(SUM(final_price), 0) FROM service_bookings WHERE status = 'completed' AND completed_at >= v_from AND completed_at <= v_to),
    'total_commission',(SELECT COALESCE(SUM(commission_amount), 0) FROM platform_commissions WHERE created_at >= v_from AND created_at <= v_to),
    'commission_7pct', public._commission_bucket_amount(v_from, v_to, 'provider'),
    'commission_3pct', public._commission_bucket_amount(v_from, v_to, 'merchant'),
    'refund_count',    (SELECT count(*) FROM orders WHERE status = 'cancelled' AND created_at >= v_from AND created_at <= v_to),
    'period',          p_period,
    'date_from',       v_from,
    'date_to',         v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_rides_timeseries(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, v_now - interval '30 days');
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'rides_by_day', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('date', day, 'count', cnt, 'gmv', gmv)), '[]'::jsonb)
      FROM (
        SELECT date_trunc('day', created_at)::date as day, count(*) as cnt,
          COALESCE(SUM(fare) FILTER (WHERE status = 'completed'), 0) as gmv
        FROM rides WHERE service_type = 'ride' AND created_at >= v_from AND created_at <= v_to
        GROUP BY day ORDER BY day
      ) sub
    ),
    'deliveries_by_day', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('date', day, 'count', cnt, 'gmv', gmv)), '[]'::jsonb)
      FROM (
        SELECT date_trunc('day', created_at)::date as day, count(*) as cnt,
          COALESCE(SUM(fare) FILTER (WHERE status = 'completed'), 0) as gmv
        FROM rides WHERE service_type != 'ride' AND created_at >= v_from AND created_at <= v_to
        GROUP BY day ORDER BY day
      ) sub
    ),
    'date_from', v_from,
    'date_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_service_performance(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'delivery_services', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'service_type', service_type, 'total', total, 'completed', completed,
        'cancelled', cancelled, 'gmv', gmv
      )), '[]'::jsonb)
      FROM (
        SELECT service_type, count(*) as total,
          count(*) FILTER (WHERE status = 'completed') as completed,
          count(*) FILTER (WHERE status = 'cancelled') as cancelled,
          COALESCE(SUM(fare) FILTER (WHERE status = 'completed'), 0) as gmv
        FROM rides WHERE service_type != 'ride' AND created_at >= v_from AND created_at <= v_to
        GROUP BY service_type
      ) sub
    ),
    'home_services', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'category_type', category_type, 'total', total, 'completed', completed,
        'cancelled', cancelled, 'gmv', gmv, 'avg_rating', avg_rating
      )), '[]'::jsonb)
      FROM (
        SELECT sb.category_type, count(*) as total,
          count(*) FILTER (WHERE sb.status = 'completed') as completed,
          count(*) FILTER (WHERE sb.status = 'cancelled') as cancelled,
          COALESCE(SUM(sb.final_price) FILTER (WHERE sb.status = 'completed'), 0) as gmv,
          COALESCE(AVG(sp.rating), 0) as avg_rating
        FROM service_bookings sb
        LEFT JOIN service_providers sp ON sp.user_id = sb.provider_id
        WHERE sb.created_at >= v_from AND sb.created_at <= v_to
        GROUP BY sb.category_type
      ) sub
    ),
    'ride_services', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'ride_type', ride_type, 'total', total, 'completed', completed,
        'cancelled', cancelled, 'gmv', gmv
      )), '[]'::jsonb)
      FROM (
        SELECT ride_type, count(*) as total,
          count(*) FILTER (WHERE status = 'completed') as completed,
          count(*) FILTER (WHERE status = 'cancelled') as cancelled,
          COALESCE(SUM(fare) FILTER (WHERE status = 'completed'), 0) as gmv
        FROM rides WHERE service_type = 'ride' AND created_at >= v_from AND created_at <= v_to
        GROUP BY ride_type
      ) sub
    ),
    'date_from', v_from,
    'date_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_settlement_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_total           numeric := 0;
  v_pending         numeric := 0;
  v_under_review    numeric := 0;
  v_approved        numeric := 0;
  v_rejected        numeric := 0;
  v_outstanding     numeric := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT public._is_owner_uid(auth.uid()) THEN
    RETURN NULL;
  END IF;

  SELECT
    COALESCE(SUM(amount), 0),
    COALESCE(SUM(amount) FILTER (WHERE status = 'pending'), 0),
    COALESCE(SUM(amount) FILTER (WHERE status = 'under_review'), 0),
    COALESCE(SUM(amount) FILTER (WHERE status = 'approved'), 0),
    COALESCE(SUM(amount) FILTER (WHERE status = 'rejected'), 0)
  INTO v_total, v_pending, v_under_review, v_approved, v_rejected
  FROM public.platform_settlements;

  v_outstanding := GREATEST(0, v_pending + v_under_review);

  RETURN jsonb_build_object(
    'summary', jsonb_build_object(
      'total', v_total, 'pending', v_pending, 'under_review', v_under_review,
      'approved', v_approved, 'rejected', v_rejected, 'outstanding', v_outstanding
    ),
    'by_region', COALESCE((
      SELECT jsonb_agg(r) FROM (
        SELECT jsonb_build_object(
          'region_id', s.region_id,
          'total', COALESCE(SUM(s.amount), 0),
          'pending', COALESCE(SUM(s.amount) FILTER (WHERE s.status = 'pending'), 0),
          'under_review', COALESCE(SUM(s.amount) FILTER (WHERE s.status = 'under_review'), 0),
          'approved', COALESCE(SUM(s.amount) FILTER (WHERE s.status = 'approved'), 0),
          'rejected', COALESCE(SUM(s.amount) FILTER (WHERE s.status = 'rejected'), 0)
        ) AS r
        FROM public.platform_settlements s
        GROUP BY s.region_id
        ORDER BY SUM(s.amount) DESC
      ) sub
    ), '[]'::jsonb),
    'rows', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', s.id, 'admin_id', s.admin_id, 'region_id', s.region_id,
        'amount', s.amount, 'currency', s.currency, 'status', s.status,
        'payment_method', s.payment_method, 'reference', s.reference,
        'created_at', s.created_at, 'reviewed_by', s.reviewed_by
      ))
      FROM (
        SELECT * FROM public.platform_settlements ORDER BY created_at DESC LIMIT 200
      ) s
    ), '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_transaction_ledger(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_type text DEFAULT NULL::text, p_member_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_auth_id uuid;
  v_has_rev boolean;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
  v_total integer;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_auth_id) THEN
    RETURN NULL;
  END IF;
  v_has_rev := has_permission('PLATFORM_REVENUE', v_auth_id);
  IF NOT v_has_rev THEN
    RETURN jsonb_build_object('error', 'insufficient_permissions');
  END IF;

  SELECT count(*) INTO v_total
  FROM platform_commissions pc
  WHERE pc.created_at >= v_from AND pc.created_at <= v_to
    AND (p_type IS NULL OR pc.reference_type = p_type)
    AND (p_member_id IS NULL OR pc.member_id = p_member_id);

  RETURN jsonb_build_object(
    'total', v_total,
    'page', (p_offset / p_limit) + 1,
    'page_size', p_limit,
    'total_pages', CEIL(v_total::float / p_limit),
    'items', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', x.id, 'member_id', x.member_id, 'reference_type', x.reference_type,
        'reference_id', x.reference_id, 'gross_amount', x.gross_amount,
        'commission_rate', x.commission_rate, 'commission_amount', x.commission_amount,
        'net_amount', x.net_amount, 'currency', x.currency, 'status', x.status,
        'created_at', x.created_at
      )), '[]'::jsonb)
      FROM (
        SELECT pc2.id, pc2.member_id, pc2.reference_type, pc2.reference_id,
               pc2.gross_amount, pc2.commission_rate, pc2.commission_amount,
               pc2.net_amount, pc2.currency, pc2.status, pc2.created_at
        FROM platform_commissions pc2
        WHERE pc2.created_at >= v_from AND pc2.created_at <= v_to
          AND (p_type IS NULL OR pc2.reference_type = p_type)
          AND (p_member_id IS NULL OR pc2.member_id = p_member_id)
        ORDER BY pc2.created_at DESC
        LIMIT p_limit OFFSET p_offset
      ) x
    )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.platform_wallet_intelligence(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id uuid;
  v_has_revenue boolean;
  v_now timestamptz := now();
  v_from timestamptz := COALESCE(p_from, '1970-01-01'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, v_now);
BEGIN
  v_member_id := auth.uid();
  IF v_member_id IS NULL OR NOT has_permission('MEMBER_VIEW', v_member_id) THEN
    RETURN NULL;
  END IF;
  v_has_revenue := has_permission('PLATFORM_REVENUE', v_member_id);
  IF NOT v_has_revenue THEN
    RETURN jsonb_build_object('error', 'insufficient_permissions');
  END IF;

  RETURN jsonb_build_object(
    'wallet_count',      (SELECT count(*) FROM wallets),
    'total_liability',   (SELECT COALESCE(SUM(balance), 0) FROM wallets),
    'avg_balance',       (SELECT COALESCE(AVG(balance), 0) FROM wallets),
    'transactions_by_type', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('type', type, 'count', cnt, 'total', total)), '[]'::jsonb)
      FROM (
        SELECT type, count(*) as cnt, COALESCE(SUM(amount), 0) as total
        FROM wallet_transactions WHERE created_at >= v_from AND created_at <= v_to
        GROUP BY type
      ) sub
    ),
    'total_transactions', (SELECT count(*) FROM wallet_transactions WHERE created_at >= v_from AND created_at <= v_to),
    'date_from', v_from,
    'date_to',   v_to
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.populate_ride_recipient_info()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rider record;
BEGIN
  IF NEW.rider_id IS NOT NULL AND (NEW.recipient_name IS NULL OR NEW.recipient_phone IS NULL) THEN
    SELECT full_name, phone INTO v_rider
      FROM public.users
     WHERE id = NEW.rider_id;
    IF FOUND THEN
      NEW.recipient_name := COALESCE(NULLIF(btrim(NEW.recipient_name), ''), v_rider.full_name);
      NEW.recipient_phone := COALESCE(NULLIF(btrim(NEW.recipient_phone), ''), v_rider.phone);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.pos_create_sale(p_merchant_id uuid, p_items jsonb, p_discount numeric DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_customer_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_merchant public.merchants%ROWTYPE;
  v_item jsonb;
  v_product public.products%ROWTYPE;
  v_qty int;
  v_subtotal numeric := 0;
  v_total numeric;
  v_discount numeric := 0;
  v_lines jsonb := '[]'::jsonb;
  v_sale_id uuid;
  v_existing uuid;
  v_rate numeric;
  v_commission numeric;
  v_touched int;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_payment_method NOT IN ('cash', 'instapay', 'vodafone_cash') THEN
    RAISE EXCEPTION 'INVALID_PAYMENT_METHOD';
  END IF;

  SELECT * INTO v_merchant FROM public.merchants WHERE id = p_merchant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'MERCHANT_NOT_FOUND';
  END IF;
  IF v_merchant.owner_user_id <> v_uid AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'NOT_YOUR_STORE';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_existing FROM public.pos_sales
      WHERE idempotency_key = p_idempotency_key;
    IF FOUND THEN
      RETURN (
        SELECT jsonb_build_object(
          'ok', true, 'sale_id', s.id, 'idempotent', true,
          'subtotal', s.subtotal, 'discount', s.discount,
          'total', s.total_amount, 'items', s.items)
        FROM public.pos_sales s WHERE s.id = v_existing);
    END IF;
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'EMPTY_CART';
  END IF;

  -- Price every line from the live products table; stock-check and decrement
  -- atomically so two tills cannot sell the same last unit.
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_qty := COALESCE((v_item->>'qty')::int, 0);
    IF v_qty <= 0 THEN
      RAISE EXCEPTION 'INVALID_QTY';
    END IF;
    SELECT * INTO v_product FROM public.products
      WHERE id = (v_item->>'product_id')::uuid
        AND merchant_id = p_merchant_id
        AND is_available;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'PRODUCT_UNAVAILABLE';
    END IF;

    -- NULL stock_quantity means untracked inventory: always sellable, never decremented.
    IF v_product.stock_quantity IS NOT NULL THEN
      UPDATE public.products
         SET stock_quantity = stock_quantity - v_qty,
             updated_at = now()
       WHERE id = v_product.id
         AND stock_quantity >= v_qty;
      GET DIAGNOSTICS v_touched = ROW_COUNT;
      IF v_touched = 0 THEN
        RAISE EXCEPTION 'INSUFFICIENT_STOCK';
      END IF;
    END IF;

    v_subtotal := v_subtotal + (v_product.price * v_qty);
    v_lines := v_lines || jsonb_build_object(
      'product_id', v_product.id,
      'name', v_product.name,
      'name_ar', v_product.name_ar,
      'qty', v_qty,
      'unit_price', v_product.price,
      'line_total', v_product.price * v_qty
    );
  END LOOP;

  v_discount := LEAST(GREATEST(COALESCE(p_discount, 0), 0), v_subtotal);
  v_total := v_subtotal - v_discount;

  INSERT INTO public.pos_sales
    (merchant_id, cashier_user_id, items, subtotal, discount, total_amount,
     payment_method, customer_name, notes, idempotency_key)
  VALUES
    (p_merchant_id, v_uid, v_lines, v_subtotal, v_discount, v_total,
     p_payment_method, NULLIF(btrim(COALESCE(p_customer_name, '')), ''),
     p_notes, p_idempotency_key)
  RETURNING id INTO v_sale_id;

  -- Same commission posting as orders/bookings: merchant owes the platform
  -- its rate on the walk-in gross, once.
  v_rate := COALESCE(
    public.get_commission_rate('merchant', v_merchant.type, v_merchant.owner_user_id), 0);
  IF v_rate > 0 THEN
    v_commission := public.calculate_commission(v_total, v_rate);
    INSERT INTO public.platform_commissions
      (member_id, reference_type, reference_id, gross_amount, commission_rate,
       commission_amount, net_amount, currency, status)
    VALUES (v_merchant.owner_user_id, 'pos_sale', v_sale_id, v_total, v_rate,
            v_commission, v_total - v_commission, 'EGP', 'computed')
    ON CONFLICT (reference_type, reference_id) DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'sale_id', v_sale_id,
    'subtotal', v_subtotal,
    'discount', v_discount,
    'total', v_total,
    'items', v_lines
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.pos_void_sale(p_sale_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_sale public.pos_sales%ROWTYPE;
  v_merchant public.merchants%ROWTYPE;
  v_line jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  SELECT * INTO v_sale FROM public.pos_sales WHERE id = p_sale_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'SALE_NOT_FOUND';
  END IF;
  SELECT * INTO v_merchant FROM public.merchants WHERE id = v_sale.merchant_id;
  IF v_sale.cashier_user_id <> v_uid
     AND v_merchant.owner_user_id <> v_uid
     AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED';
  END IF;
  IF v_sale.status = 'voided' THEN
    RETURN jsonb_build_object('ok', true, 'sale_id', v_sale.id, 'already_voided', true);
  END IF;

  -- Restore stock for tracked items only (NULL stock = untracked).
  FOR v_line IN SELECT * FROM jsonb_array_elements(v_sale.items) LOOP
    UPDATE public.products
       SET stock_quantity = stock_quantity + COALESCE((v_line->>'qty')::int, 0),
           updated_at = now()
     WHERE id = (v_line->>'product_id')::uuid
       AND stock_quantity IS NOT NULL;
  END LOOP;

  -- Reverse the still-open platform commission posting, if any.
  UPDATE public.platform_commissions
     SET status = 'reversed'
   WHERE reference_type = 'pos_sale'
     AND reference_id = v_sale.id
     AND status = 'computed';

  UPDATE public.pos_sales
     SET status = 'voided', voided_at = now(), voided_by = v_uid,
         void_reason = NULLIF(btrim(COALESCE(p_reason, '')), '')
   WHERE id = v_sale.id;

  RETURN jsonb_build_object('ok', true, 'sale_id', v_sale.id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.provider_create_banner_campaign(p_name_ar text, p_name_en text, p_subtitle_ar text, p_subtitle_en text, p_region_id uuid DEFAULT NULL::uuid, p_image_path text DEFAULT NULL::text, p_starts_at timestamp with time zone DEFAULT now(), p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_campaign_id uuid;
  v_request_id uuid;
  v_code text;
  v_clean_image text := NULLIF(btrim(p_image_path), '');
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT (
    EXISTS (SELECT 1 FROM public.merchants m WHERE m.owner_user_id = v_uid)
    OR EXISTS (SELECT 1 FROM public.merchant_profiles mp WHERE mp.user_id = v_uid)
    OR EXISTS (SELECT 1 FROM public.service_providers sp WHERE sp.user_id = v_uid)
  ) THEN
    RAISE EXCEPTION 'Not authorized: merchant or provider profile required';
  END IF;

  IF NULLIF(btrim(p_name_ar), '') IS NULL THEN
    RAISE EXCEPTION 'Arabic title is required';
  END IF;

  IF p_ends_at IS NOT NULL AND p_starts_at IS NOT NULL AND p_ends_at <= p_starts_at THEN
    RAISE EXCEPTION 'ends_at must be after starts_at';
  END IF;

  v_code := 'prv_banner_' || replace(gen_random_uuid()::text, '-', '');

  INSERT INTO public.campaigns (
    code,
    campaign_type,
    priority,
    name_ar,
    name_en,
    subtitle_ar,
    subtitle_en,
    status,
    starts_at,
    ends_at,
    proposed_by,
    created_by
  )
  VALUES (
    v_code,
    'promotion',
    'normal',
    btrim(p_name_ar),
    NULLIF(btrim(p_name_en), ''),
    NULLIF(btrim(p_subtitle_ar), ''),
    NULLIF(btrim(p_subtitle_en), ''),
    'draft',
    COALESCE(p_starts_at, now()),
    p_ends_at,
    v_uid,
    v_uid
  )
  RETURNING id INTO v_campaign_id;

  IF v_clean_image IS NOT NULL THEN
    INSERT INTO public.campaign_banners (
      campaign_id, placement, locale, image_path
    )
    VALUES
      (v_campaign_id, 'home_carousel', 'ar', v_clean_image),
      (v_campaign_id, 'home_carousel', 'en', v_clean_image);
  END IF;

  INSERT INTO public.campaign_targets (campaign_id, region_id, created_by)
  VALUES (v_campaign_id, p_region_id, v_uid);

  v_request_id := public.campaign_submit(v_campaign_id, 'provider_banner_submission');

  RETURN jsonb_build_object(
    'campaign_id', v_campaign_id,
    'request_id', v_request_id,
    'code', v_code,
    'status', 'pending_review'
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.provider_delete_document(p_doc_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_deleted integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_doc_type IS NULL OR btrim(p_doc_type) = '' THEN
    RAISE EXCEPTION 'Document type is required';
  END IF;

  -- The ownership column is `provider_id` (069_provider_documents.sql:11),
  -- not `user_id`: provider_documents has no user_id column at all.
  DELETE FROM public.provider_documents
   WHERE provider_id = v_uid
     AND doc_type = p_doc_type;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  IF v_deleted = 0 THEN
    -- Nothing owned by this caller with that type: either it never
    -- existed or it belongs to somebody else. Report it honestly
    -- instead of pretending the delete succeeded.
    RETURN false;
  END IF;

  RETURN true;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.provider_get_availability()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid         uuid := auth.uid();
  v_merchant_id uuid;
  v_merchant    record;
  v_sp          record;
  v_category    text;
  v_is_open     boolean;
  v_schedule    jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  v_merchant_id := public.resolve_my_merchant();

  IF v_merchant_id IS NOT NULL THEN
    SELECT id, type, is_open INTO v_merchant
      FROM public.merchants
     WHERE id = v_merchant_id;

    IF v_merchant.id IS NOT NULL THEN
      v_category := v_merchant.type;
      v_is_open := v_merchant.is_open;
      SELECT COALESCE(
        jsonb_agg(jsonb_build_object(
          'day_of_week', day_of_week,
          'open_time', open_time,
          'close_time', close_time,
          'is_closed', is_closed
        ) ORDER BY day_of_week),
        '[]'::jsonb)
      INTO v_schedule
      FROM public.working_hours
      WHERE merchant_id = v_merchant_id;
    END IF;
  END IF;

  IF v_category IS NULL THEN
    SELECT id, category_type, is_available INTO v_sp
      FROM public.service_providers
     WHERE user_id = v_uid;
    IF v_sp.id IS NOT NULL THEN
      v_category := v_sp.category_type;
      v_is_open := v_sp.is_available;
      v_schedule := '[]'::jsonb;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'category', COALESCE(v_category, 'restaurant'),
    'is_open', COALESCE(v_is_open, true),
    'schedule', COALESCE(v_schedule, '[]'::jsonb)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.provider_get_documents()
 RETURNS SETOF provider_documents
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT * FROM public.provider_documents
  WHERE provider_id = auth.uid()
  ORDER BY created_at DESC;
$function$
;
CREATE OR REPLACE FUNCTION public.provider_list_my_campaigns()
 RETURNS TABLE(id uuid, code text, name_ar text, name_en text, subtitle_ar text, subtitle_en text, status text, region_id uuid, image_path text, starts_at timestamp with time zone, ends_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.code,
    c.name_ar,
    c.name_en,
    c.subtitle_ar,
    c.subtitle_en,
    c.status,
    ct.region_id,
    cb.image_path,
    c.starts_at,
    c.ends_at,
    c.created_at
  FROM public.campaigns c
  LEFT JOIN LATERAL (
    SELECT t.region_id
    FROM public.campaign_targets t
    WHERE t.campaign_id = c.id
    ORDER BY t.created_at ASC
    LIMIT 1
  ) ct ON true
  LEFT JOIN LATERAL (
    SELECT b.image_path
    FROM public.campaign_banners b
    WHERE b.campaign_id = c.id
      AND b.placement = 'home_carousel'
      AND b.is_active = true
    ORDER BY (b.locale = 'ar') DESC, b.created_at ASC
    LIMIT 1
  ) cb ON true
  WHERE c.created_by = v_uid
  ORDER BY c.created_at DESC;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.provider_set_availability(p_is_open boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid         uuid := auth.uid();
  v_merchant_id uuid;
  v_updated     boolean := false;
  v_category    text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  IF p_is_open IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID');
  END IF;

  v_merchant_id := public.resolve_my_merchant();

  IF v_merchant_id IS NOT NULL THEN
    UPDATE public.merchants
       SET is_open = p_is_open,
           updated_at = now()
     WHERE id = v_merchant_id
    RETURNING type INTO v_category;
    IF FOUND THEN
      v_updated := true;
    END IF;
  END IF;

  IF NOT v_updated THEN
    UPDATE public.service_providers
       SET is_available = p_is_open
     WHERE user_id = v_uid
    RETURNING category_type INTO v_category;
    IF FOUND THEN
      v_updated := true;
    END IF;
  END IF;

  IF NOT v_updated THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NO_PROVIDER');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'code', 'OK',
    'is_open', p_is_open,
    'category', COALESCE(v_category, 'restaurant')
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.provider_set_working_hours(p_schedule jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_merchant uuid;
  v_entry jsonb;
  v_day int;
  v_open text;
  v_close text;
  v_closed boolean;
  v_stored int := 0;
BEGIN
  v_merchant := public.resolve_my_merchant();
  IF v_merchant IS NULL THEN
    RAISE EXCEPTION 'No merchant store for this account';
  END IF;

  IF p_schedule IS NULL OR jsonb_typeof(p_schedule) <> 'array' THEN
    RAISE EXCEPTION 'Schedule must be a JSON array';
  END IF;

  -- Replace the whole schedule atomically so a partial failure can never
  -- leave the store with half a week defined.
  DELETE FROM public.working_hours WHERE merchant_id = v_merchant;

  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_schedule) LOOP
    v_day := COALESCE((v_entry->>'day')::int, -1);
    v_open := v_entry->>'open';
    v_close := v_entry->>'close';
    v_closed := COALESCE((v_entry->>'closed')::boolean, false);

    IF v_day < 0 OR v_day > 6 THEN
      RAISE EXCEPTION 'Invalid day of week: %', v_day;
    END IF;

    IF NOT v_closed
       AND (v_open IS NULL OR v_close IS NULL
            OR v_open !~ '^[0-2][0-9]:[0-5][0-9]$'
            OR v_close !~ '^[0-2][0-9]:[0-5][0-9]$') THEN
      RAISE EXCEPTION 'Invalid time format for day % (expected HH:MM)', v_day;
    END IF;

    IF NOT v_closed AND v_open >= v_close THEN
      RAISE EXCEPTION 'Closing time must be after opening time on day %', v_day;
    END IF;

    INSERT INTO public.working_hours
      (merchant_id, day_of_week, open_time, close_time, is_closed)
    VALUES
      (v_merchant, v_day, v_open::time, v_close::time, v_closed);

    v_stored := v_stored + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'rows', v_stored,
    'merchant_id', v_merchant
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.provider_submit_verification(p_id_card_url text, p_profile_photo_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_status text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  IF btrim(COALESCE(p_id_card_url, '')) = ''
     OR btrim(COALESCE(p_profile_photo_url, '')) = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MISSING_DOCUMENTS');
  END IF;

  SELECT verification_status INTO v_status FROM public.users WHERE id = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;

  -- Rejected accounts must use reapply_verification (keeps one state machine).
  IF v_status = 'rejected' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'USE_REAPPLY');
  END IF;

  UPDATE public.users
    SET id_card_url = btrim(p_id_card_url),
        profile_photo_url = btrim(p_profile_photo_url),
        verification_status = 'pending',
        rejection_reason = NULL,
        rejection_reason_at = NULL,
        updated_at = now()
    WHERE id = v_uid;

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'status', 'pending');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.provider_upsert_document(p_doc_type text, p_file_url text)
 RETURNS provider_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.provider_documents;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF btrim(COALESCE(p_file_url, '')) = '' THEN
    RAISE EXCEPTION 'Document URL is required';
  END IF;
  INSERT INTO public.provider_documents (provider_id, doc_type, file_url, status)
  VALUES (v_uid, p_doc_type, btrim(p_file_url), 'pending')
  ON CONFLICT (provider_id, doc_type) DO UPDATE
    SET file_url = EXCLUDED.file_url,
        status = 'pending',
        rejection_reason = NULL,
        reviewed_at = NULL,
        created_at = now()
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.rate_recipient(p_delivery_id uuid, p_driver_id uuid, p_stars integer, p_comment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r rides%ROWTYPE;
  v_owner UUID;
BEGIN
  SELECT user_id INTO v_owner FROM drivers WHERE id = p_driver_id;
  IF v_owner IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;
  SELECT * INTO r FROM rides WHERE id = p_delivery_id;
  IF r.driver_id IS DISTINCT FROM p_driver_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_your_ride');
  END IF;
  IF r.service_type = 'ride' THEN
    RETURN jsonb_build_object('success',false,'reason','not_a_delivery');
  END IF;
  IF r.status IS DISTINCT FROM 'completed' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_completed');
  END IF;
  IF p_stars < 1 OR p_stars > 5 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invalid_stars');
  END IF;
  UPDATE rides SET driver_rating = p_stars, driver_feedback = p_comment WHERE id = p_delivery_id;
  INSERT INTO ride_ratings (ride_id, rater_id, ratee_role, stars, comment)
    VALUES (p_delivery_id, auth.uid(), 'rider', p_stars, p_comment)
  ON CONFLICT (ride_id, rater_id) DO UPDATE
    SET stars = EXCLUDED.stars, comment = EXCLUDED.comment;
  RETURN jsonb_build_object('success', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.rate_ride(p_ride_id uuid, p_rating integer, p_feedback text DEFAULT NULL::text, p_tip numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_fare numeric;
  v_tip numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'UNAUTHENTICATED');
  END IF;
  IF p_rating < 1 OR p_rating > 5 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_RATING');
  END IF;
  SELECT fare INTO v_fare FROM public.rides WHERE id = p_ride_id AND rider_id = v_uid FOR UPDATE;
  IF v_fare IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_YOUR_RIDE');
  END IF;
  -- Clamp tip to [0, fare]
  v_tip := COALESCE(p_tip, 0);
  IF v_tip < 0 THEN v_tip := 0; END IF;
  IF v_tip > COALESCE(v_fare, 0) THEN v_tip := COALESCE(v_fare, 0); END IF;

  UPDATE public.rides
     SET rating = p_rating, feedback = p_feedback, tip = v_tip
   WHERE id = p_ride_id AND rider_id = v_uid;
  RETURN jsonb_build_object('ok', true, 'tip', v_tip);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reapply_verification(p_id_card_url text, p_profile_photo_url text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_old_status text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF btrim(COALESCE(p_id_card_url, '')) = ''
     OR btrim(COALESCE(p_profile_photo_url, '')) = '' THEN
    RAISE EXCEPTION 'Both documents are required';
  END IF;

  SELECT verification_status INTO v_old_status
    FROM public.users WHERE id = v_uid FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;

  IF v_old_status <> 'rejected' THEN
    RAISE EXCEPTION 'Verification can only be re-applied after a rejection';
  END IF;

  UPDATE public.users
    SET verification_status = 'pending',
        id_card_url = p_id_card_url,
        profile_photo_url = p_profile_photo_url,
        rejection_reason = NULL,
        rejection_reason_at = NULL,
        updated_at = now()
    WHERE id = v_uid;

  INSERT INTO public.notifications
    (user_id, title, body, type, data, deep_link, idempotency_key, send_push)
  VALUES (
    v_uid,
    'Verification re-submitted',
    'Your documents are under review again.',
    'verification',
    jsonb_build_object(
      'status', 'pending',
      'reapply', true
    ),
    '/pending-verification',
    'verification-reapply-' || v_uid::text || '-' || now()::timestamptz(3)::text,
    false
  );

  PERFORM public.write_audit(
    'VERIFICATION_REAPPLIED',
    'users',
    v_uid::text,
    jsonb_build_object(
      'previous_status', v_old_status,
      'new_status', 'pending'
    )
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.redeem_coupon(p_coupon_code text, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_coupon public.coupons%ROWTYPE;
BEGIN
  -- Self-only: a redemption binds the caller's identity; no anon or
  -- cross-account redemption (prevents usage burn, targeted blocking and
  -- the redeemed-or-not oracle).
  IF auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;

  SELECT * INTO v_coupon FROM public.coupons WHERE code = btrim(p_coupon_code);
  IF v_coupon.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'coupon_not_found');
  END IF;
  IF NOT v_coupon.is_active THEN
    RETURN jsonb_build_object('success', false, 'reason', 'coupon_inactive');
  END IF;
  IF v_coupon.expires_at IS NOT NULL AND v_coupon.expires_at < now() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'coupon_expired');
  END IF;
  IF v_coupon.usage_limit IS NOT NULL AND COALESCE(v_coupon.used_count, 0) >= v_coupon.usage_limit THEN
    RETURN jsonb_build_object('success', false, 'reason', 'usage_limit_reached');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.coupon_redemptions r
    WHERE r.coupon_id = v_coupon.id AND r.user_id = p_user_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'already_redeemed');
  END IF;

  UPDATE public.coupons
  SET used_count = COALESCE(used_count, 0) + 1
  WHERE id = v_coupon.id;
  INSERT INTO public.coupon_redemptions (coupon_id, user_id)
  VALUES (v_coupon.id, p_user_id);

  RETURN jsonb_build_object(
    'success', true,
    'coupon_id', v_coupon.id,
    'discount_type', v_coupon.discount_type,
    'discount_value', v_coupon.discount_value,
    'minimum_order', v_coupon.minimum_order,
    'maximum_discount', v_coupon.maximum_discount,
    'merchant_id', v_coupon.merchant_id
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.redispatch_delayed_order(p_ride_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_ride public.rides%rowtype;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  select * into v_ride from public.rides where id = p_ride_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'RIDE_NOT_FOUND');
  end if;
  if not (public.is_admin()
          or (v_ride.merchant_id is not null and public.is_merchant_owner(v_ride.merchant_id))) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  return public._driver_delay_redispatch(p_ride_id, p_reason, 'merchant');
end;
$function$
;
CREATE OR REPLACE FUNCTION public.refresh_token_heartbeat(p_token text, p_device_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_token IS NULL OR btrim(p_token) = '' THEN
    RETURN;
  END IF;

  UPDATE public.notification_tokens
     SET last_seen_at = now(),
         device_id = COALESCE(p_device_id, device_id)
   WHERE user_id = auth.uid()
     AND token = p_token;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.register_device_token(p_token text, p_platform text, p_device_id text, p_app_version text DEFAULT NULL::text, p_app text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;
  if p_token is null or btrim(p_token) = '' then
    raise exception 'token is required';
  end if;
  if p_platform is null or btrim(p_platform) = '' then
    raise exception 'platform is required';
  end if;

  insert into public.notification_tokens
    (user_id, token, platform, device_id, app_version, app, is_active, last_seen_at)
  values
    (v_uid, p_token, p_platform, p_device_id, p_app_version, p_app, true, now())
  on conflict (user_id, token)
  do update set
    platform = excluded.platform,
    device_id = excluded.device_id,
    app_version = excluded.app_version,
    app = coalesce(excluded.app, notification_tokens.app),
    is_active = true,
    last_seen_at = now(),
    updated_at = now();

  -- Token rotation: other ACTIVE tokens of this user on the same device AND
  -- SAME APP are superseded (re-install / refresh). Other flavors on the same
  -- device keep their own tokens. Legacy untagged calls (p_app null) rotate
  -- only untagged tokens.
  if p_device_id is not null and btrim(p_device_id) <> '' then
    update public.notification_tokens
       set is_active = false, updated_at = now()
     where user_id = v_uid
       and device_id = p_device_id
       and token <> p_token
       and is_active = true
       and app is not distinct from p_app;

    -- Cross-account leak fix (189): another account's token for the SAME app
    -- on the SAME device must not keep receiving pushes after an account switch.
    if p_app is not null and btrim(p_app) <> '' then
      update public.notification_tokens
         set is_active = false, updated_at = now()
       where device_id = p_device_id
         and app = p_app
         and user_id <> v_uid
         and is_active = true;
    end if;
  end if;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.reject_delivery_request(p_delivery_id uuid, p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN public.reject_ride_request(p_delivery_id, p_driver_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reject_member_deletion(p_deletion_id uuid, p_reason text DEFAULT 'Rejected by admin'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM public.decide_approval_request(p_deletion_id, 'reject', p_reason);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reject_ride_request(p_ride_id uuid, p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_owner UUID;
BEGIN
  SELECT user_id INTO v_owner FROM drivers WHERE id = p_driver_id;
  IF v_owner IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;
  UPDATE ride_requests SET status = 'rejected', responded_at = NOW()
    WHERE ride_id = p_ride_id AND driver_id = p_driver_id AND status = 'offered';
  INSERT INTO trip_events (ride_id, event_type, actor) VALUES (p_ride_id, 'rejected', 'driver');
  RETURN jsonb_build_object('success', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reject_settlement_request(p_settlement_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  s public.platform_settlements;
BEGIN
  IF auth.uid() IS NULL OR NOT public._is_owner_uid(auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  SELECT * INTO s FROM public.platform_settlements
   WHERE id = p_settlement_id FOR UPDATE;
  IF s IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF s.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ALREADY_PROCESSED', 'status', s.status);
  END IF;
  UPDATE public.platform_settlements
     SET status = 'rejected', reviewed_at = now(), reviewed_by = auth.uid(),
         rejection_reason = p_reason
   WHERE id = s.id;
  RETURN jsonb_build_object('ok', true, 'code', 'OK');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reject_topup_request(p_request_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r public.topup_requests;
BEGIN
  IF auth.uid() IS NULL OR NOT public._is_owner_uid(auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN_OWNER_ONLY');
  END IF;
  SELECT * INTO r FROM public.topup_requests WHERE id = p_request_id FOR UPDATE;
  IF r IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF r.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ALREADY_PROCESSED', 'status', r.status);
  END IF;
  -- Idempotent: a reject cannot be flipped to a credit later (status no longer
  -- 'pending'), so re-attempting an approval returns ALREADY_PROCESSED.
  UPDATE public.topup_requests
     SET status = 'rejected', reviewed_at = now(), reviewed_by = auth.uid(),
         rejection_reason = p_reason
   WHERE id = r.id;
  PERFORM public.write_audit('TOPUP_REJECTED', 'topup_requests', r.id::text,
    jsonb_build_object('account', r.account_id, 'amount', r.amount,
      'reviewed_by', auth.uid(), 'reason', p_reason));
  INSERT INTO public.notifications (user_id, title, body, type, data)
  VALUES
    (r.account_id, 'Top-up rejected', 'Your top-up request was not approved.',
     'topup_rejected', jsonb_build_object('topup_request_id', r.id, 'reason', p_reason, 'deep_link', '/wallet'));
  RETURN jsonb_build_object('ok', true, 'code', 'OK');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reject_wallet_funding_request(p_funding_request_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request RECORD;
BEGIN
  IF p_funding_request_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_REQUEST_ID');
  END IF;
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF NOT public.has_financial_permission(auth.uid(), 'reject_wallet_funding') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  SELECT * INTO STRICT v_request
  FROM public.wallet_funding_requests
  WHERE id = p_funding_request_id
  FOR UPDATE;

  IF auth.uid() = v_request.user_id THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SELF_REJECT_NOT_ALLOWED');
  END IF;

  IF v_request.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATUS', 'current_status', v_request.status);
  END IF;

  UPDATE public.wallet_funding_requests
  SET status = 'rejected',
      processed_at = now(),
      processed_by = auth.uid(),
      rejection_reason = p_reason,
      updated_at = now()
  WHERE id = p_funding_request_id;

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'funding_request_id', p_funding_request_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.release_grace(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_log public.grace_audit_log;
  v_after integer;
BEGIN
  SELECT * INTO v_log FROM public.grace_audit_log
   WHERE order_id = p_order_id AND account_id = auth.uid()
   ORDER BY created_at DESC LIMIT 1;
  IF v_log IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NO_SLOT');
  END IF;
  IF (v_log.after - v_log.before) <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ALREADY_RELEASED');
  END IF;
  UPDATE public.grace_accounts
     SET grace_used = GREATEST(0, grace_used - 1), updated_at = now()
   WHERE user_id = auth.uid();
  INSERT INTO public.grace_audit_log
    (account_id, order_id, before, after, actor, reason, created_at)
  VALUES
    (auth.uid(), p_order_id, v_log.after, v_log.before, auth.uid(),
     'grace_released', now());
  SELECT grace_used INTO v_after FROM public.grace_accounts WHERE user_id = auth.uid();
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'grace_used', v_after);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.reply_to_merchant_review(p_review_id uuid, p_reply text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_merchant uuid;
  v_review_user uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_reply IS NULL OR btrim(p_reply) = '' THEN
    RAISE EXCEPTION 'Reply cannot be empty';
  END IF;

  -- The caller must own the merchant this review belongs to.
  SELECT id INTO v_merchant
    FROM public.merchants
   WHERE owner_user_id = v_uid
   LIMIT 1;

  IF v_merchant IS NULL THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  SELECT r.user_id INTO v_review_user
    FROM public.reviews r
   WHERE r.id = p_review_id
     AND r.merchant_id = v_merchant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Review not found';
  END IF;

  -- Writes ONLY the reply columns: the customer's comment, rating and
  -- every other field are unreachable from here.
  UPDATE public.reviews
     SET merchant_reply = btrim(p_reply),
         merchant_replied_at = now()
   WHERE id = p_review_id;

  RETURN true;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.report_delivery_incident(p_ride_id uuid, p_kind text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r rides%ROWTYPE;
  v_role text;
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;
  SELECT * INTO r FROM rides WHERE id = p_ride_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;
  IF r.rider_id = auth.uid() THEN
    v_role := 'rider';
  ELSIF EXISTS (SELECT 1 FROM drivers WHERE id = r.driver_id AND user_id = auth.uid()) THEN
    v_role := 'driver';
  ELSE
    RETURN jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;
  IF r.status NOT IN ('matched','arrived','inTrip') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_transition');
  END IF;
  IF p_kind IS NULL OR btrim(p_kind) = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_kind');
  END IF;

  INSERT INTO public.delivery_incidents (ride_id, order_id, reporter_user_id, reporter_role, kind, note)
    VALUES (p_ride_id, r.order_id, auth.uid(), v_role, btrim(p_kind), NULLIF(btrim(p_note), ''))
    RETURNING id INTO v_id;
  INSERT INTO trip_events (ride_id, event_type, actor)
    VALUES (p_ride_id, 'incident_reported', v_role);
  RETURN jsonb_build_object('ok', true, 'incident_id', v_id, 'role', v_role);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.report_delivery_refusal(p_order_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_order public.orders%rowtype;
  v_driver public.drivers%rowtype;
  v_count int;
  v_merchant_uid uuid;
  v_short text;
  v_actor uuid;
  v_ride_id uuid;
begin
  if v_uid is null then
    raise exception 'UNAUTHENTICATED';
  end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;
  select * into v_driver from public.drivers where id = v_order.driver_id;
  if v_driver.user_id is distinct from v_uid and not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  if v_order.status <> 'delivering' then
    raise exception 'NOT_OUT_FOR_DELIVERY %', v_order.status;
  end if;

  -- One refusal report per order. The 3rd-refusal branch below intentionally
  -- leaves the order in 'delivering'; without this guard every retried report
  -- stacked another refusal_event and re-executed the 5-day suspension.
  if exists (select 1 from public.refusal_events where order_id = p_order_id) then
    return jsonb_build_object('ok', true, 'action', 'already_reported',
                              'order_id', p_order_id);
  end if;

  -- Lifetime stat kept for records; the policy window is MONTHLY (mig 185),
  -- counted from refusal_events (188) so that refused-but-uncancelled orders
  -- on the 3rd-refusal path still count.
  update public.users set refusal_count = refusal_count + 1
   where id = v_order.user_id;
  insert into public.refusal_events (user_id, order_id)
  values (v_order.user_id, v_order.id);
  select count(*) into v_count
    from public.refusal_events
   where user_id = v_order.user_id
     and created_at >= date_trunc('month', now() at time zone 'Africa/Cairo') at time zone 'Africa/Cairo';

  -- 188: the 3rd monthly refusal is NOT processed as a cancellation - the
  -- order must still be received. The 5-day suspension executes at the
  -- driver's report; ops resolves the in-flight order via the incident flow.
  if v_count >= 3 then
    v_actor := coalesce(
      (select id from public.users where role = 'owner' order by created_at limit 1),
      v_order.user_id);
    perform public._member_exec_sanction(
      v_actor, v_order.user_id, 'suspension',
      'رفض استلام الطلب للمرة الثالثة خلال شهر واحد', 5);

    select id into v_ride_id from public.rides
     where order_id = v_order.id and status not in ('completed', 'cancelled')
     order by created_at desc limit 1;
    if v_ride_id is not null then
      insert into public.delivery_incidents (ride_id, order_id, reporter_user_id, reporter_role, kind, note)
      values (v_ride_id, v_order.id, v_uid, 'driver', 'final_refusal_suspension',
              coalesce(p_reason, 'رفض الاستلام للمرة الثالثة - العميل موقوف 5 أيام والطلب يحتاج حسم'));
    end if;

    v_short := right(v_order.id::text, 6);
    insert into public.notifications (user_id, title, body, type, data, send_push)
    values (v_order.user_id,
            'تم إيقاف حسابك 5 أيام',
            'ده تالت رفض استلام منك هذا الشهر. اتوقف حسابك 5 أيام من لحظة بلاغ الكابتن. طلبك رقم ' || v_short || ' لازم يتسلم، والدعم هيحسم الموضوع معاك. تقدر تقدّم التماس من التطبيق والمسؤول عن منطقتك هيراجعه.',
            'account',
            jsonb_build_object('event', 'refusal_suspension', 'refusal_count', v_count,
                               'order_id', v_order.id, 'duration_days', 5),
            true);

    select owner_user_id into v_merchant_uid from public.merchants where id = v_order.merchant_id;
    if v_merchant_uid is not null then
      insert into public.notifications (user_id, title, body, type, data, send_push)
      values (v_merchant_uid,
              'العميل رفض الاستلام للمرة الثالثة',
              'الطلب رقم ' || v_short || ': تم إيقاف العميل 5 أيام، والدعم هيحسم الطلب (استلام إجباري أو إرجاع للمطعم).',
              'order',
              jsonb_build_object('order_id', v_order.id, 'event', 'final_refusal'),
              true);
    end if;

    return jsonb_build_object('ok', true, 'action', 'account_suspended',
                              'refusal_count', v_count, 'suspension_days', 5,
                              'order_cancelled', false);
  end if;

  -- 194: shared finalizer (coupon release included since 193's policy).
  perform public._finalize_order_cancel(
    p_order_id, 'customer_refusal', coalesce(p_reason, 'رفض الاستلام'),
    true, true, true, 'system');

  v_short := right(v_order.id::text, 6);
  select owner_user_id into v_merchant_uid from public.merchants where id = v_order.merchant_id;
  if v_merchant_uid is not null then
    insert into public.notifications (user_id, title, body, type, data, send_push)
    values (v_merchant_uid,
            'العميل رفض استلام الطلب',
            'تم إلغاء الطلب رقم ' || v_short || ' بسبب رفض العميل الاستلام.',
            'order',
            jsonb_build_object('order_id', v_order.id, 'status', 'cancelled',
                               'reason', 'customer_refusal'),
            true);
  end if;

  insert into public.notifications (user_id, title, body, type, data, send_push)
  values (v_order.user_id,
          'تحذير ' || v_count || ' من 2 هذا الشهر: رفض استلام الطلب',
          'تم تسجيل رفضك استلام الطلب رقم ' || v_short || '. رفض الاستلام مرة أخرى بعد تحذيرين يؤدي إلى إيقاف الحساب 5 أيام، وطلبك القادم لازم يتسلم.',
          'account',
          jsonb_build_object('event', 'refusal_warning', 'refusal_count', v_count),
          true);
  return jsonb_build_object('ok', true, 'action', 'warning', 'refusal_count', v_count);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.report_driver_delay(p_ride_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_driver_id uuid;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  select id into v_driver_id from public.drivers where user_id = v_uid;
  if v_driver_id is null then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  if not public.is_admin()
     and not exists (select 1 from public.rides
                      where id = p_ride_id and driver_id = v_driver_id) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  return public._driver_delay_redispatch(p_ride_id, p_reason, 'driver');
end;
$function$
;
CREATE OR REPLACE FUNCTION public.request_additional_provider_profile(p_category_type text, p_display_name text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cat text := lower(btrim(COALESCE(p_category_type, '')));
  v_is_owner boolean;
  v_name text := btrim(COALESCE(p_display_name, ''));
  v_target jsonb;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF v_cat = '' THEN
    RAISE EXCEPTION 'Category is required';
  END IF;

  v_is_owner := public._is_owner_uid(v_uid);
  IF v_name = '' THEN
    SELECT COALESCE(NULLIF(btrim(full_name), ''), 'Delwaqty ' || initcap(v_cat))
      INTO v_name
      FROM public.users
     WHERE id = v_uid;
  END IF;

  IF v_is_owner THEN
    v_target := public._provision_business_target(v_uid, v_cat, v_name);
    INSERT INTO public.provider_business_profiles (
      user_id, category_type, display_name, status,
      merchant_id, service_provider_id, reviewed_by, reviewed_at
    )
    VALUES (
      v_uid, v_cat, v_name, 'approved',
      (v_target->>'merchant_id')::uuid,
      (v_target->>'service_provider_id')::uuid,
      v_uid, now()
    )
    ON CONFLICT (user_id, category_type) DO UPDATE
      SET status = 'approved',
          display_name = EXCLUDED.display_name,
          updated_at = now()
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('ok', true, 'id', v_id, 'status', 'approved');
  END IF;

  INSERT INTO public.provider_business_profiles (
    user_id, category_type, display_name, status
  )
  VALUES (v_uid, v_cat, v_name, 'pending')
  ON CONFLICT (user_id, category_type) DO UPDATE
    SET display_name = EXCLUDED.display_name,
        status = CASE
          WHEN public.provider_business_profiles.status = 'approved' THEN 'approved'
          ELSE 'pending'
        END,
        rejection_reason = NULL,
        updated_at = now()
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'status', 'pending');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.request_delivery(p_pickup_latitude numeric, p_pickup_longitude numeric, p_pickup_address text, p_dropoff_latitude numeric, p_dropoff_longitude numeric, p_dropoff_address text, p_items_summary text, p_weight_kg numeric DEFAULT 0, p_dropoff_notes text DEFAULT NULL::text, p_priority text DEFAULT 'standard'::text, p_payment_method text DEFAULT 'cash'::text, p_otp_required boolean DEFAULT true, p_vehicle_type text DEFAULT 'motorcycle'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_pricing RECORD;
  v_distance double precision;
  v_fee numeric;
  v_multiplier numeric := 1.0;
  v_delivery_id uuid;
  v_currency text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'UNAUTHENTICATED');
  END IF;

  IF p_pickup_latitude IS NULL OR p_pickup_longitude IS NULL OR
     p_dropoff_latitude IS NULL OR p_dropoff_longitude IS NULL OR
     p_items_summary IS NULL OR p_dropoff_address IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_INPUT');
  END IF;

  SELECT * INTO v_pricing
    FROM delivery_pricing
   WHERE service_type = 'marketplace_delivery' AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'PRICING_UNAVAILABLE');
  END IF;

  SELECT haversine_km(
           p_pickup_latitude::double precision,
           p_pickup_longitude::double precision,
           p_dropoff_latitude::double precision,
           p_dropoff_longitude::double precision
         ) INTO v_distance;
  v_distance := GREATEST(COALESCE(v_distance, 0), 0.1);

  v_fee := v_pricing.base_fee
           + (v_pricing.per_km * v_distance)
           + (COALESCE(p_weight_kg, 0) * COALESCE(v_pricing.per_kg, 0));

  IF p_priority = 'priority' THEN
    v_multiplier := v_pricing.priority_multiplier;
  ELSIF p_priority = 'express' THEN
    v_multiplier := v_pricing.express_multiplier;
  END IF;

  v_fee := v_fee * v_multiplier;

  IF v_fee < v_pricing.minimum_fee THEN
    v_fee := v_pricing.minimum_fee;
  END IF;
  v_fee := ROUND(v_fee, 2);
  v_currency := v_pricing.currency;

  INSERT INTO public.rides (
    rider_id,
    pickup_latitude, pickup_longitude, pickup_address,
    dropoff_latitude, dropoff_longitude, dropoff_address,
    ride_type, service_type, status, fare,
    distance, estimated_minutes,
    items_summary, weight_kg, dropoff_notes,
    priority, payment_method, currency,
    otp_required
  ) VALUES (
    v_uid,
    p_pickup_latitude, p_pickup_longitude, p_pickup_address,
    p_dropoff_latitude, p_dropoff_longitude, p_dropoff_address,
    COALESCE(p_vehicle_type, 'motorcycle'), 'marketplace_delivery', 'searching',
    v_fee, ROUND(v_distance::numeric, 4),
    GREATEST(CEIL(v_distance / 25.0 * 60)::int, 5),
    p_items_summary, COALESCE(p_weight_kg, 0), p_dropoff_notes,
    COALESCE(p_priority, 'standard'), COALESCE(p_payment_method, 'cash'),
    v_currency, COALESCE(p_otp_required, true)
  ) RETURNING id INTO v_delivery_id;

  RETURN jsonb_build_object(
    'ok', true,
    'delivery_id', v_delivery_id,
    'fare', v_fee,
    'distance_km', ROUND(v_distance::numeric, 2),
    'currency', v_currency
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.request_member_deletion(p_member_id uuid, p_confirmation_email text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE v_email text; v_token text; BEGIN IF auth.uid() IS NOT NULL AND p_member_id <> auth.uid() AND NOT public.is_admin() THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT email INTO v_email FROM public.users WHERE id = p_member_id; IF NOT FOUND THEN RAISE EXCEPTION 'Member not found'; END IF; IF v_email IS NOT NULL AND btrim(v_email) <> '' THEN IF lower(btrim(COALESCE(p_confirmation_email, ''))) <> lower(btrim(v_email)) THEN RAISE EXCEPTION 'Email does not match this member'; END IF; v_token := 'DELETE-' || encode(sha256(lower(btrim(v_email))::bytea), 'hex'); ELSE v_token := 'DELETE-' || encode(sha256(p_member_id::text::bytea), 'hex'); END IF; IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'Reason is required'; END IF; RETURN public.delete_member_account(p_member_id, v_token, p_reason); END; $function$
;
CREATE OR REPLACE FUNCTION public.request_reward_config_change(p_reward_type text, p_config jsonb, p_region_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_benefit jsonb;
  v_entity_id uuid;
  v_admin_user uuid := auth.uid();
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_reward_type NOT IN ('birthday','anniversary') THEN
    RAISE EXCEPTION 'Invalid reward type';
  END IF;
  IF p_config IS NULL OR p_config = '{}'::jsonb THEN
    RAISE EXCEPTION 'Empty reward config';
  END IF;
  IF COALESCE((p_config ->> 'enabled')::boolean, false) IS NULL THEN
    RAISE EXCEPTION 'Missing enabled flag';
  END IF;
  v_benefit := COALESCE(p_config -> 'benefit', '{"kind":"none"}'::jsonb);
  IF NOT public._reward_benefit_valid(v_benefit) THEN
    RAISE EXCEPTION 'Invalid reward benefit';
  END IF;

  IF p_region_id IS NULL THEN
    IF NOT public._is_owner_uid(v_admin_user) THEN
      RAISE EXCEPTION 'Only owner can request global reward config changes';
    END IF;
    v_entity_id := '00000000-0000-0000-0000-000000000000';
  ELSE
    IF NOT public._region_in_scope(v_admin_user, p_region_id) THEN
      RAISE EXCEPTION 'Not authorized for this region';
    END IF;
    v_entity_id := p_region_id;
  END IF;

  RETURN public.submit_approval_request(
    'reward_config_change',
    'platform_settings',
    v_entity_id,
    jsonb_build_object(
      'reward_type', p_reward_type,
      'region_id', p_region_id,
      'config', p_config),
    p_reason,
    NULL);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.request_whatsapp_otp(p_phone text, p_purpose text DEFAULT 'register'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_norm text := public._normalize_egypt_phone(p_phone);
  v_otp text;
  v_support_phone text;
  v_recent int;
begin
  if length(v_norm) < 10 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_PHONE');
  end if;

  -- c) request cap: 3 codes per phone per 10 minutes
  select count(*) into v_recent
    from public.whatsapp_otp_verifications
   where phone = v_norm
     and created_at > now() - interval '10 minutes';
  if v_recent >= 3 then
    return jsonb_build_object('ok', false, 'code', 'RATE_LIMITED');
  end if;

  -- a) invalidate all older unexpired codes for this phone
  update public.whatsapp_otp_verifications
     set expires_at = now()
   where phone = v_norm
     and expires_at > now()
     and verified = false;

  v_otp := lpad((floor(random() * 900000) + 100000)::int::text, 6, '0');

  insert into public.whatsapp_otp_verifications (phone, otp_code, purpose, verified, expires_at)
  values (v_norm, v_otp, coalesce(nullif(btrim(p_purpose), ''), 'register'), false, now() + interval '10 minutes');

  select coalesce(nullif(support_phone, ''), '+201000000000')
    into v_support_phone
    from public.platform_settings
   where id = 'default';

  return jsonb_build_object(
    'ok', true,
    'phone', v_norm,
    'otp_code', v_otp,
    'whatsapp_number', coalesce(v_support_phone, '+201000000000'),
    'expires_in_seconds', 600
  );
end;
$function$
;
CREATE OR REPLACE FUNCTION public.request_withdrawal(p_driver_id uuid, p_amount double precision, p_method text DEFAULT 'bank'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE v_owner uuid; v_balance numeric; v_id uuid; BEGIN IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'reason', 'unauthenticated'); END IF; SELECT user_id, COALESCE(earnings_balance, 0) INTO v_owner, v_balance FROM public.drivers WHERE id = p_driver_id FOR UPDATE; IF v_owner IS NULL THEN RETURN jsonb_build_object('success', false, 'reason', 'driver_not_found'); END IF; IF v_owner IS DISTINCT FROM auth.uid() THEN RETURN jsonb_build_object('success', false, 'reason', 'forbidden'); END IF; IF p_amount IS NULL OR p_amount <= 0 OR p_amount > v_balance THEN RETURN jsonb_build_object('success', false, 'reason', 'insufficient_balance'); END IF; INSERT INTO public.withdrawal_requests (driver_id, amount, status, method) VALUES (p_driver_id, p_amount, 'pending', p_method) RETURNING id INTO v_id; INSERT INTO public.driver_earnings (driver_id, type, amount, description) VALUES (p_driver_id, 'withdrawal', -p_amount, 'Withdrawal request'); UPDATE public.drivers SET earnings_balance = earnings_balance - p_amount WHERE id = p_driver_id; RETURN jsonb_build_object('success', true, 'withdrawal_id', v_id); END; $function$
;
CREATE OR REPLACE FUNCTION public.reservations_guard_customer_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  IF current_user IN ('authenticated', 'anon') THEN
    IF public.is_admin() OR public.is_merchant_owner(OLD.merchant_id) THEN
      RETURN NEW;
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status <> 'cancelled' THEN
      RAISE EXCEPTION 'Only the merchant or platform can change reservation status';
    END IF;
    IF NEW.merchant_id IS DISTINCT FROM OLD.merchant_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN
      RAISE EXCEPTION 'Reservation ownership cannot change';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_delivery_incident(p_incident_id uuid, p_resolution text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  i public.delivery_incidents%rowtype;
  v_region uuid;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if p_resolution not in ('redelivered','returned_to_merchant','cancelled','dismissed') then
    return jsonb_build_object('ok', false, 'reason', 'invalid_resolution');
  end if;
  select * into i from public.delivery_incidents where id = p_incident_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if i.status = 'resolved' then
    return jsonb_build_object('ok', false, 'reason', 'already_resolved');
  end if;

  -- Region lock (194): the incident's order customer's region governs.
  select u.region_id into v_region
    from public.orders o join public.users u on u.id = o.user_id
   where o.id = i.order_id;
  if not public._admin_scope_allows(v_region) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden_region');
  end if;

  -- Returned goods end the ride and the order; a plain cancel of the order
  -- closes it out. Redelivery keeps the ride alive for the driver to finish.
  -- 194: incident-cancels do NOT restock (goods may be unsellable) but DO
  -- refund and release the coupon, and clear the driver + ride.
  if p_resolution in ('returned_to_merchant','cancelled') then
    perform public._finalize_order_cancel(
      i.order_id, 'incident', 'incident: ' || p_resolution,
      false, true, true, 'system');
  end if;

  update public.delivery_incidents
     set status = 'resolved', resolution = p_resolution,
         note = coalesce(nullif(btrim(p_note), ''), note),
         resolved_by = auth.uid(), resolved_at = now()
   where id = p_incident_id;
  insert into trip_events (ride_id, event_type, actor)
    values (i.ride_id, 'incident_resolved_' || p_resolution, 'support');
  return jsonb_build_object('ok', true, 'resolution', p_resolution);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_my_merchant()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_active_cat text;
  v_owned uuid;
  v_user record;
  v_seeded uuid;
  v_seeded_count integer;
  v_is_staff boolean;
  v_approved boolean;
begin
  if v_uid is null then
    return null;
  end if;

  select active_provider_category into v_active_cat from public.users where id = v_uid;

  if v_active_cat is not null and btrim(v_active_cat) <> '' and not public._is_home_service_category(v_active_cat) then
    select id into v_owned
      from public.merchants
     where owner_user_id = v_uid and lower(type) = lower(v_active_cat)
     order by created_at asc
     limit 1;
    if v_owned is not null then
      return v_owned;
    end if;
  end if;

  select id into v_owned
    from public.merchants
   where owner_user_id = v_uid or id = v_uid
   order by (owner_user_id = v_uid) desc, created_at asc
   limit 1;

  if v_owned is not null then
    return v_owned;
  end if;

  select id, full_name, email, phone, role, user_type, verification_status
    into v_user
    from public.users
   where id = v_uid;

  v_is_staff := v_user.role in ('owner', 'admin');
  v_approved := v_user.verification_status = 'approved';

  if v_user.id is not null and (
    v_is_staff
    or v_user.role in ('merchant', 'provider')
    or v_user.user_type in ('merchant', 'provider')
  ) then
    insert into public.merchants (
      owner_user_id, name, email, phone, type, status, is_open,
      delivery_fee, min_order, delivery_time_min, rating
    )
    values (
      v_uid,
      coalesce(nullif(btrim(v_user.full_name), ''), 'Delwaqty Store'),
      coalesce(v_user.email, ''),
      v_user.phone,
      case
        when v_active_cat is not null and not public._is_home_service_category(v_active_cat) then v_active_cat
        when v_user.user_type = 'provider' or v_user.role = 'provider' then 'service'
        else 'restaurant'
      end,
      case when v_is_staff or v_approved then 'active' else 'pending' end,
      case when v_is_staff or v_approved then true else false end,
      15,
      0,
      30,
      0
    )
    returning id into v_owned;

    return v_owned;
  end if;

  select count(*) into v_seeded_count
    from public.merchants
   where owner_user_id is null;

  if v_seeded_count = 1 then
    select id into v_seeded
      from public.merchants
     where owner_user_id is null
     limit 1;
    return v_seeded;
  end if;

  return null;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_my_service_provider()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_sp_id uuid;
  v_user record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT id INTO v_sp_id
    FROM public.service_providers
   WHERE user_id = v_uid
   ORDER BY created_at ASC
   LIMIT 1;

  IF v_sp_id IS NOT NULL THEN
    RETURN v_sp_id;
  END IF;

  SELECT id, full_name, avatar_url, profile_photo_url
    INTO v_user
    FROM public.users
   WHERE id = v_uid;

  IF v_user.id IS NOT NULL THEN
    INSERT INTO public.service_providers (
      user_id, name, category_type, description, profile_image_url,
      rating, rating_count, is_verified, is_available, hourly_rate
    )
    VALUES (
      v_uid,
      COALESCE(NULLIF(btrim(v_user.full_name), ''), 'Delwaqty Provider'),
      'plumbing',
      '',
      COALESCE(v_user.profile_photo_url, v_user.avatar_url),
      NULL,   -- no self-issued rating
      0,
      false,  -- not verified until an admin verifies
      false,  -- not publicly listed until activated
      NULL    -- rate set through the admin RPCs
    )
    RETURNING id INTO v_sp_id;
  END IF;

  RETURN v_sp_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_receiver_for_account()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_region uuid;
  v_wallet jsonb;
  v_platform jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT region_id INTO v_region FROM public.user_region_preferences
   WHERE user_id = auth.uid() LIMIT 1;

  SELECT jsonb_build_object(
    'admin_id', w.admin_id, 'region_id', w.region_id,
    'method_type', w.method_type, 'wallet_number', w.wallet_number,
    'account_name', w.account_name, 'provider', w.provider
  ) INTO v_wallet
  FROM public.admin_receiving_wallets w
  WHERE w.is_active
    AND (v_region IS NULL OR w.region_id = v_region)
  ORDER BY w.region_id NULLS LAST
  LIMIT 1;

  IF v_wallet IS NOT NULL THEN
    RETURN jsonb_build_object('source', 'regional_admin', 'receiver', v_wallet,
      'region_id', v_region);
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'id', a.id, 'method_type', a.method_type, 'display_name', a.display_name,
    'account_name', a.account_name, 'account_number', a.account_number,
    'wallet_number', a.wallet_number, 'instructions', a.instructions
  )) INTO v_platform
  FROM public.platform_receiving_accounts a
  WHERE a.is_active;

  RETURN jsonb_build_object('source', 'platform', 'receivers', COALESCE(v_platform, '[]'::jsonb),
    'region_id', v_region);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_sos_alert(p_alert_id uuid, p_status text DEFAULT 'resolved'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_resolver uuid := auth.uid();
  v_owner    uuid;
  v_alert    record;
BEGIN
  IF v_resolver IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_authenticated');
  END IF;

  SELECT sa.*, u.id AS user_id INTO v_alert
    FROM public.sos_alerts sa
    JOIN public.users u ON u.id = sa.user_id
   WHERE sa.id = p_alert_id;

  IF v_alert IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'alert_not_found');
  END IF;

  IF v_alert.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'alert_not_active');
  END IF;

  v_owner := v_alert.user_id;

  UPDATE public.sos_alerts
     SET status     = p_status,
         resolved_at = now()
   WHERE id = p_alert_id;

  INSERT INTO public.notifications
    (user_id, title, body, type, data, deep_link, idempotency_key,
     sender_id, priority, send_push)
  VALUES
    (v_owner,
     'SOS Alert Resolved',
     'Your SOS alert has been marked as ' || p_status || '.',
     'emergency_resolved',
     jsonb_build_object('entity_type', 'sos_alert', 'entity_id', p_alert_id::text, 'action', p_status),
     '/safety',
     'sos-resolved-' || p_alert_id::text || '-' || v_owner::text,
     v_resolver, 'high', true)
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  INSERT INTO public.member_events (user_id, event_type, payload)
  VALUES (v_owner, 'emergency_resolved',
          jsonb_build_object('alert_id', p_alert_id::text, 'resolved_by', v_resolver::text, 'status', p_status))
  ON CONFLICT DO NOTHING;

  INSERT INTO public.member_events (user_id, event_type, payload)
  VALUES (v_resolver, 'emergency_resolved',
          jsonb_build_object('alert_id', p_alert_id::text, 'owner_id', v_owner::text, 'status', p_status))
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object('success', true, 'alert_id', p_alert_id, 'status', p_status);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_support_admin(p_region_id uuid, p_prefer_region boolean DEFAULT true, p_exclude_admin_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_admin_id uuid;
BEGIN
  IF p_prefer_region AND p_region_id IS NOT NULL THEN
    SELECT best.admin_id
      INTO v_admin_id
      FROM (
        WITH RECURSIVE chain(id, parent_id, depth) AS (
          SELECT r.id, r.parent_region_id, 0
          FROM public.regions r
          WHERE r.id = p_region_id
          UNION ALL
          SELECT r.id, r.parent_region_id, c.depth + 1
          FROM public.regions r
          JOIN chain c ON r.id = c.parent_id
          WHERE c.depth <= 10
        )
        SELECT a.admin_id,
               MIN(c.depth) AS eff_depth,
               COUNT(DISTINCT r2.id) FILTER (
                 WHERE r2.status IN ('open','assigned')) AS open_count
        FROM public.admin_region_assignments a
        JOIN chain c ON c.id = a.region_id
        LEFT JOIN public.chat_rooms r2 ON r2.assigned_admin_id = a.admin_id
        JOIN public.users u ON u.id = a.admin_id AND u.role = 'admin'
        WHERE (a.scope = 'self' AND c.depth = 0)
           OR a.scope = 'descendants'
        GROUP BY a.admin_id
      ) best
      WHERE best.admin_id IS DISTINCT FROM p_exclude_admin_id
      ORDER BY best.eff_depth ASC, best.open_count ASC, best.admin_id ASC
      LIMIT 1;
    IF v_admin_id IS NOT NULL THEN
      RETURN v_admin_id;
    END IF;
  END IF;

  SELECT u.id
    INTO v_admin_id
    FROM public.users u
    LEFT JOIN public.admin_region_assignments a ON a.admin_id = u.id
    LEFT JOIN public.chat_rooms r2
           ON r2.assigned_admin_id = u.id AND r2.status IN ('open','assigned')
   WHERE u.role = 'admin'
     AND a.admin_id IS NULL
     AND u.id IS DISTINCT FROM p_exclude_admin_id
   GROUP BY u.id
   ORDER BY COUNT(DISTINCT r2.id) ASC, u.id ASC
   LIMIT 1;
  IF v_admin_id IS NOT NULL THEN
    RETURN v_admin_id;
  END IF;

  SELECT u.id
    INTO v_admin_id
    FROM public.users u
   WHERE u.role = 'owner'
     AND u.id IS DISTINCT FROM p_exclude_admin_id
   ORDER BY u.id ASC
   LIMIT 1;

  RETURN v_admin_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_topup_receivers()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_receivers jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT jsonb_agg(jsonb_build_object(
    'id', a.id,
    'method_type', a.method_type,
    'display_name', a.display_name,
    'account_name', a.account_name,
    'account_number', a.account_number,
    'wallet_number', a.wallet_number,
    'instructions', a.instructions
  ) ORDER BY a.method_type, a.display_name)
  INTO v_receivers
  FROM public.platform_receiving_accounts a
  WHERE a.is_active;

  RETURN jsonb_build_object('receivers', COALESCE(v_receivers, '[]'::jsonb));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.restore_user(p_user_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_status text;
  v_sanction record;
  v_revoked int := 0;
BEGIN
  SELECT account_status INTO v_status
  FROM public.users
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;

  IF public._is_active_admin_uid(p_user_id) THEN
    RAISE EXCEPTION 'Admins are managed through the admin lifecycle';
  END IF;

  IF v_status IS DISTINCT FROM 'restricted' AND v_status IS DISTINCT FROM 'suspended' THEN
    RAISE EXCEPTION 'Member account is not restricted or suspended';
  END IF;

  IF NOT public.has_permission('MEMBER_MODERATE', public._member_region_id(p_user_id)) THEN
    RAISE EXCEPTION 'Not authorized for this member';
  END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason is required';
  END IF;

  FOR v_sanction IN
    SELECT s.id
    FROM public.sanctions s
    WHERE s.target_user_id = p_user_id
      AND s.is_active
      AND s.action_status = 'active'
  LOOP
    PERFORM public._member_exec_revoke_sanction(
      auth.uid(), v_sanction.id, p_reason
    );
    v_revoked := v_revoked + 1;
  END LOOP;

  PERFORM public._enforce_member_status(p_user_id);

  SELECT account_status INTO v_status
  FROM public.users
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'revoked_sanctions', v_revoked,
    'account_status', v_status
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.review_driver_application(p_driver_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE d public.drivers%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR NOT public.is_admin() THEN
  RETURN jsonb_build_object('success',false,'reason','FORBIDDEN');
 END IF;
 SELECT * INTO d FROM public.drivers WHERE id=p_driver_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'reason','DRIVER_NOT_FOUND'); END IF;
 IF p_approve IS NULL THEN RETURN jsonb_build_object('success',false,'reason','INVALID_DECISION'); END IF;
 IF p_approve THEN
  IF NOT public.driver_application_documents_ready(p_driver_id) THEN
   RETURN jsonb_build_object('success',false,'reason','REQUIRED_DOCUMENTS_MISSING');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.vehicles WHERE driver_id=p_driver_id AND is_active) THEN
   RETURN jsonb_build_object('success',false,'reason','ACTIVE_VEHICLE_REQUIRED');
  END IF;
 ELSE
  IF btrim(COALESCE(p_reason,''))='' THEN RETURN jsonb_build_object('success',false,'reason','REASON_REQUIRED'); END IF;
 END IF;
 UPDATE public.driver_documents SET status=CASE WHEN p_approve THEN 'verified' ELSE 'rejected' END,
   reviewed_at=now(), rejection_reason=CASE WHEN p_approve THEN NULL ELSE p_reason END
   WHERE driver_id=p_driver_id AND doc_type IN ('driving_license','vehicle_registration');
 UPDATE public.drivers SET is_verified=p_approve,
   verification_status=CASE WHEN p_approve THEN 'verified' ELSE 'rejected' END,updated_at=now()
   WHERE id=p_driver_id;
 IF p_approve THEN UPDATE public.vehicles SET is_verified=true WHERE driver_id=p_driver_id AND is_active; END IF;
 INSERT INTO public.notifications(user_id,title,body,type,data,deep_link,send_push)
 VALUES(d.user_id,CASE WHEN p_approve THEN 'تمت مراجعة حساب السائق' ELSE 'مستندات السائق محتاجة مراجعة' END,
 CASE WHEN p_approve THEN 'تم قبول المستندات وتفعيل حساب السائق' ELSE p_reason END,
 'verification',jsonb_build_object('driver_id',p_driver_id,'approved',p_approve),'/driver/documents',true);
 RETURN jsonb_build_object('success',true);
END; $function$
;
CREATE OR REPLACE FUNCTION public.revoke_admin_permission(p_admin_id uuid, p_permission text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public._is_active_admin_uid(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_admin_id = auth.uid() THEN
    RAISE EXCEPTION 'Cannot revoke a permission from yourself';
  END IF;
  IF NOT public._is_owner_uid(auth.uid())
     AND NOT public.is_supervisor_of(auth.uid(), p_admin_id) THEN
    RAISE EXCEPTION 'Not authorized for this admin';
  END IF;

  DELETE FROM public.admin_permission_grants
  WHERE admin_id = p_admin_id AND permission = p_permission;

  PERFORM public.write_audit(
    'ADMIN_PERMISSION_REVOKED', 'admin_permission_grants', p_admin_id::text,
    jsonb_build_object('permission', p_permission));
END;
$function$
;
CREATE OR REPLACE FUNCTION public.revoke_financial_permission(p_user_id uuid, p_permission text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public._is_owner_uid(auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_USER');
  END IF;

  IF p_permission IS NULL OR p_permission NOT IN (
    'approve_wallet_funding',
    'reject_wallet_funding',
    'view_funding_requests',
    'manage_receiving_accounts',
    'view_financial_transactions',
    'adjust_wallet_balance'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_PERMISSION');
  END IF;

  IF public._is_owner_uid(p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'OWNER_CANNOT_BE_REVOKED');
  END IF;

  UPDATE public.financial_permissions
  SET revoked_at = now(),
      revoked_by = auth.uid()
  WHERE user_id = p_user_id
    AND permission = p_permission
    AND revoked_at IS NULL;

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'user_id', p_user_id, 'permission', p_permission);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.revoke_sanction(p_sanction_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_member_id uuid;
BEGIN
  SELECT target_user_id INTO v_member_id FROM public.sanctions WHERE id = p_sanction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sanction not found';
  END IF;
  IF NOT public.has_permission('MEMBER_MODERATE', public._member_region_id(v_member_id)) THEN
    RAISE EXCEPTION 'Not authorized for this member';
  END IF;
  PERFORM public._member_exec_revoke_sanction(auth.uid(), p_sanction_id, p_reason);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.rides_guard_client_writes()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;
  IF public._is_active_admin_uid(auth.uid()) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- No app flow updates rides directly as a client; every
    -- legitimate transition goes through a SECURITY DEFINER RPC.
    RAISE EXCEPTION 'ride fields are managed by the delivery RPCs';
  END IF;

  -- INSERT: a rider may request a ride, but never a pre-paid or
  -- pre-assigned one. Force money and assignment fields back to
  -- system defaults.
  NEW.payment_status := 'pending';
  NEW.status := 'searching';
  NEW.driver_id := NULL;
  NEW.driver_name := NULL;
  NEW.driver_phone := NULL;
  NEW.driver_photo := NULL;
  NEW.driver_latitude := NULL;
  NEW.driver_longitude := NULL;
  NEW.driver_heading := NULL;
  NEW.accepted_at := NULL;
  NEW.arrived_at := NULL;
  NEW.matched_at := NULL;
  NEW.started_at := NULL;
  NEW.picked_up_at := NULL;
  NEW.completed_at := NULL;
  NEW.delivered_at := NULL;
  NEW.cancelled_at := NULL;
  NEW.cancelled_by := NULL;
  NEW.cash_collected_at := NULL;
  NEW.cash_collected_by := NULL;
  NEW.rating := NULL;
  NEW.driver_rating := NULL;
  NEW.reassign_count := 0;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.route_support_chat(p_room_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_room public.chat_rooms%ROWTYPE;
  v_admin_id uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT * INTO v_room FROM public.chat_rooms WHERE id = p_room_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Room not found';
  END IF;
  IF v_room.status = 'closed' THEN
    RAISE EXCEPTION 'Room is closed';
  END IF;
  IF v_room.assigned_admin_id IS NOT NULL THEN
    RETURN v_room.assigned_admin_id;
  END IF;

  v_admin_id := public.resolve_support_admin(v_room.region_id, true);
  IF v_admin_id IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM public._assign_chat_to_admin(p_room_id, v_admin_id, 'assigned');
  PERFORM public.write_audit(
    'SUPPORT_ASSIGNED', 'chat_rooms', p_room_id::text,
    jsonb_build_object('admin_id', v_admin_id, 'priority', v_room.priority)
  );
  RETURN v_admin_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.run_member_engines(p_run_date date DEFAULT ((now() AT TIME ZONE 'Africa/Cairo'::text))::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user record;
  v_config jsonb;
  v_benefit jsonb;
  v_campaign_id uuid;
  v_deep_link text;
  v_title text;
  v_body text;
  v_lang text;
  v_years int;
  v_birthday_granted int := 0;
  v_anniversary_granted int := 0;
  v_skipped int := 0;
  v_campaigns_expired int := 0;
  v_rewards_expired int := 0;
  v_region_id uuid;
  v_retention jsonb;
BEGIN
  -- ── birthday pass (region-aware config; idempotent ledger) ────────
  FOR v_user IN
    SELECT u.id, u.full_name, u.language
    FROM public.users u
    WHERE u.account_status = 'active'
      AND u.date_of_birth IS NOT NULL
      AND EXTRACT(month FROM u.date_of_birth) = EXTRACT(month FROM p_run_date)
      AND EXTRACT(day FROM u.date_of_birth) = EXTRACT(day FROM p_run_date)
      AND u.role IN ('customer','provider','driver','delivery','merchant')
      AND NOT EXISTS (
        SELECT 1 FROM public.member_rewards mr
        WHERE mr.user_id = u.id
          AND mr.reward_type = 'birthday'
          AND mr.period_key =
              'birthday:' || EXTRACT(year FROM p_run_date)::int
      )
  LOOP
    SELECT public._member_region_id(v_user.id) INTO v_region_id;
    v_config := public._reward_config('birthday', v_region_id);
    IF COALESCE((v_config ->> 'enabled')::boolean, false) = false THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;
    v_benefit := COALESCE(v_config -> 'benefit', '{"kind":"none"}'::jsonb);
    IF NOT public._reward_benefit_valid(v_benefit) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;
    v_campaign_id := NULL;
    IF v_config ? 'campaign_id' THEN
      BEGIN
        SELECT c.id INTO v_campaign_id
        FROM public.campaigns c
        WHERE c.id = (v_config ->> 'campaign_id')::uuid;
      EXCEPTION WHEN others THEN
        v_campaign_id := NULL;
      END;
    END IF;

    INSERT INTO public.member_rewards
      (user_id, reward_type, period_key, benefit, campaign_id, status, notified_at)
    VALUES (
      v_user.id, 'birthday',
      'birthday:' || EXTRACT(year FROM p_run_date)::int,
      v_benefit, v_campaign_id, 'granted', now()
    )
    ON CONFLICT (user_id, reward_type, period_key) DO NOTHING;

    IF FOUND THEN
      v_birthday_granted := v_birthday_granted + 1;
      v_lang := COALESCE(v_user.language, 'en');
      IF v_lang = 'ar' THEN
        v_title := COALESCE(v_config ->> 'title_ar', v_config ->> 'title_en', '');
        v_body := COALESCE(v_config ->> 'body_ar', v_config ->> 'body_en', '');
      ELSE
        v_title := COALESCE(v_config ->> 'title_en', v_config ->> 'title_ar', '');
        v_body := COALESCE(v_config ->> 'body_en', v_config ->> 'body_ar', '');
      END IF;
      v_title := replace(v_title, '{{name}}',
                         COALESCE(v_user.full_name, ''));
      v_body := replace(v_body, '{{name}}',
                        COALESCE(v_user.full_name, ''));
      v_deep_link := COALESCE(v_config ->> 'deep_link', '/profile');

      INSERT INTO public.member_events (user_id, event_type, title, payload)
      VALUES (v_user.id, 'birthday_reward', 'Birthday reward',
              jsonb_build_object(
                'period_key', 'birthday:' || EXTRACT(year FROM p_run_date)::int,
                'benefit', v_benefit,
                'region_id', v_region_id));

      INSERT INTO public.notifications
        (user_id, title, body, type, data, deep_link, idempotency_key)
      VALUES (
        v_user.id, v_title, v_body, 'reward',
        jsonb_build_object('reward_type', 'birthday',
                           'period_key', 'birthday:' || EXTRACT(year FROM p_run_date)::int),
        v_deep_link,
        'reward-birthday-' || EXTRACT(year FROM p_run_date)::int || '-' || v_user.id::text
      )
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    END IF;
  END LOOP;

  -- ── anniversary pass (region-aware config; idempotent ledger) ──────
  FOR v_user IN
    SELECT u.id, u.full_name, u.language, u.created_at
    FROM public.users u
    WHERE u.account_status = 'active'
      AND u.created_at IS NOT NULL
      AND EXTRACT(year FROM p_run_date) > EXTRACT(year FROM (u.created_at AT TIME ZONE 'Africa/Cairo'))
      AND EXTRACT(month FROM (u.created_at AT TIME ZONE 'Africa/Cairo')) =
          EXTRACT(month FROM p_run_date)
      AND EXTRACT(day FROM (u.created_at AT TIME ZONE 'Africa/Cairo')) =
          EXTRACT(day FROM p_run_date)
      AND u.role IN ('customer','provider','driver','delivery','merchant')
      AND NOT EXISTS (
        SELECT 1 FROM public.member_rewards mr
        WHERE mr.user_id = u.id
          AND mr.reward_type = 'anniversary'
          AND mr.period_key =
              'anniversary:' || (EXTRACT(year FROM p_run_date)::int
                                 - EXTRACT(year FROM u.created_at)::int)
      )
  LOOP
    SELECT public._member_region_id(v_user.id) INTO v_region_id;
    v_config := public._reward_config('anniversary', v_region_id);
    IF COALESCE((v_config ->> 'enabled')::boolean, false) = false THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;
    v_benefit := COALESCE(v_config -> 'benefit', '{"kind":"none"}'::jsonb);
    IF NOT public._reward_benefit_valid(v_benefit) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;
    v_years := EXTRACT(year FROM p_run_date)::int
               - EXTRACT(year FROM v_user.created_at)::int;
    v_campaign_id := NULL;
    IF v_config ? 'campaign_id' THEN
      BEGIN
        SELECT c.id INTO v_campaign_id
        FROM public.campaigns c
        WHERE c.id = (v_config ->> 'campaign_id')::uuid;
      EXCEPTION WHEN others THEN
        v_campaign_id := NULL;
      END;
    END IF;

    INSERT INTO public.member_rewards
      (user_id, reward_type, period_key, benefit, campaign_id, status, notified_at)
    VALUES (v_user.id, 'anniversary', 'anniversary:' || v_years,
            v_benefit, v_campaign_id, 'granted', now())
    ON CONFLICT (user_id, reward_type, period_key) DO NOTHING;

    IF FOUND THEN
      v_anniversary_granted := v_anniversary_granted + 1;
      v_lang := COALESCE(v_user.language, 'en');
      IF v_lang = 'ar' THEN
        v_title := COALESCE(v_config ->> 'title_ar', v_config ->> 'title_en', '');
        v_body := COALESCE(v_config ->> 'body_ar', v_config ->> 'body_en', '');
      ELSE
        v_title := COALESCE(v_config ->> 'title_en', v_config ->> 'title_ar', '');
        v_body := COALESCE(v_config ->> 'body_en', v_config ->> 'body_ar', '');
      END IF;
      v_title := replace(replace(v_title, '{{name}}',
                                 COALESCE(v_user.full_name, '')),
                         '{{years}}', v_years::text);
      v_body := replace(replace(v_body, '{{name}}',
                                COALESCE(v_user.full_name, '')),
                        '{{years}}', v_years::text);
      v_deep_link := COALESCE(v_config ->> 'deep_link', '/profile');

      INSERT INTO public.member_events (user_id, event_type, title, payload)
      VALUES (v_user.id, 'anniversary_reward', 'Anniversary reward',
              jsonb_build_object('period_key', 'anniversary:' || v_years,
                                 'years', v_years, 'benefit', v_benefit,
                                 'region_id', v_region_id));

      INSERT INTO public.notifications
        (user_id, title, body, type, data, deep_link, idempotency_key)
      VALUES (
        v_user.id, v_title, v_body, 'reward',
        jsonb_build_object('reward_type', 'anniversary',
                           'period_key', 'anniversary:' || v_years,
                           'years', v_years),
        v_deep_link,
        'reward-anniversary-' || v_years || '-' || v_user.id::text
      )
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    END IF;
  END LOOP;

  -- ── config-driven reward expiry (granted -> expired) ────────────────
  -- valid_days lives in the reward config (global or regional override);
  -- absent/missing => rewards never auto-expire. No hardcoded windows.
  UPDATE public.member_rewards mr
  SET status = 'expired'
  WHERE mr.status = 'granted'
    AND (
      SELECT COALESCE(NULLIF(public._reward_config(
          mr.reward_type, public._member_region_id(mr.user_id)) ->> 'valid_days', '')::int, 0)
    ) > 0
    AND mr.created_at < now() - make_interval(days => (
      SELECT COALESCE(NULLIF(public._reward_config(
          mr.reward_type, public._member_region_id(mr.user_id)) ->> 'valid_days', '')::int, 0)
    ));
  GET DIAGNOSTICS v_rewards_expired = ROW_COUNT;

  -- ── campaign expiry (039 whitelist: published -> expired) ───────────
  UPDATE public.campaigns SET status = 'expired'
  WHERE status = 'published'
    AND ends_at IS NOT NULL
    AND ends_at < now();
  GET DIAGNOSTICS v_campaigns_expired = ROW_COUNT;

  IF v_rewards_expired > 0 THEN
    PERFORM public.write_audit(
      'REWARDS_EXPIRED', 'member_rewards', NULL,
      jsonb_build_object('expired', v_rewards_expired));
  END IF;

  -- ── retention purge ────────────────────────────────────────────────
  v_retention := public.apply_retention_policies();

  RETURN jsonb_build_object(
    'run_date', p_run_date::text,
    'birthday_granted', v_birthday_granted,
    'anniversary_granted', v_anniversary_granted,
    'skipped', v_skipped,
    'rewards_expired', v_rewards_expired,
    'campaigns_expired', v_campaigns_expired,
    'retention', v_retention);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.search_intent_category(p_query text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN lower(coalesce(p_query,'')) ~ E'(\\mطع|حمار|اكل|اكلات|مقلى|براستد|شاورما|بيتزا|برجر|كشري|فول|طعميه)'  THEN 'food'
    WHEN lower(coalesce(p_query,'')) ~ E'(\\mصيدا|دواء|دويه|علاج|ادويه|aspirin|بندول|بانادول)'             THEN 'pharmacy'
    WHEN lower(coalesce(p_query,'')) ~ E'(\\mخضار|فاكهه|بقاله|سوبر|ماركت|زيت|ارز|سكر|شاي)'               THEN 'grocery'
    WHEN lower(coalesce(p_query,'')) ~ E'(\\mعايز|ابعت|يوصل|توصيل|هيصلك|مندوب|شحنه|وصل|ابعت طلب|حد يوصل)' THEN 'delivery'
    WHEN lower(coalesce(p_query,'')) ~ E'(\\mسباك|كهربا|تكييف|صيانه|عامل|نجار|دهان|نظافه|خدمه)'           THEN 'service'
    ELSE 'general'
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.service_bookings_guard_client_writes()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'booking fields are managed by update_service_booking_status';
END;
$function$
;
CREATE OR REPLACE FUNCTION public.service_bookings_normalize_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_provider public.service_providers%rowtype;
begin
  -- Lifecycle and payment state are server-owned; a fresh booking is always
  -- a pending, unpaid request with no completion or collection markers.
  new.status := 'pending';
  new.completed_at := null;
  new.payment_status := 'unpaid';
  new.cash_collected_at := null;
  new.cash_collected_by := null;
  new.final_price := null;

  -- Provider truth comes from the provider row, never the client payload.
  select * into v_provider from public.service_providers where id = new.provider_id;
  if not found then
    raise exception 'PROVIDER_NOT_FOUND';
  end if;
  new.provider_name := v_provider.name;
  new.category_type := v_provider.category_type;

  -- 196: no zero/negative estimates; the provider floor still applies.
  if new.estimated_price is not null and new.estimated_price <= 0 then
    raise exception 'INVALID_PRICE';
  end if;
  if v_provider.fixed_price_min is not null
     and (new.estimated_price is null or new.estimated_price < v_provider.fixed_price_min) then
    new.estimated_price := v_provider.fixed_price_min;
  end if;

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.service_providers_guard_sensitive_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_user IN ('authenticated', 'anon') AND NOT public.is_admin() THEN
    IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
      RAISE EXCEPTION 'user_id is immutable';
    END IF;
    IF NEW.is_verified IS DISTINCT FROM OLD.is_verified THEN
      RAISE EXCEPTION 'is_verified is managed by the admin verification RPCs';
    END IF;
    IF NEW.rating IS DISTINCT FROM OLD.rating THEN
      RAISE EXCEPTION 'rating is managed by the rating engine';
    END IF;
    IF NEW.rating_count IS DISTINCT FROM OLD.rating_count THEN
      RAISE EXCEPTION 'rating_count is managed by the rating engine';
    END IF;
    IF NEW.hourly_rate IS DISTINCT FROM OLD.hourly_rate THEN
      RAISE EXCEPTION 'hourly_rate is managed by the admin RPCs';
    END IF;
    IF NEW.fixed_price_min IS DISTINCT FROM OLD.fixed_price_min THEN
      RAISE EXCEPTION 'fixed_price_min is managed by the admin RPCs';
    END IF;
    IF NEW.fixed_price_max IS DISTINCT FROM OLD.fixed_price_max THEN
      RAISE EXCEPTION 'fixed_price_max is managed by the admin RPCs';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_admin_availability(p_available boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  insert into public.admin_availability (admin_id, is_available, note, updated_at)
  values (auth.uid(), p_available, p_note, now())
  on conflict (admin_id)
  do update set is_available = excluded.is_available,
                note = excluded.note,
                updated_at = now();
  return jsonb_build_object('ok', true, 'is_available', p_available);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.set_commission_rate(p_entity_type text, p_entity_key text, p_rate numeric, p_effective_from date DEFAULT CURRENT_DATE, p_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_new_id uuid;
  v_current_id uuid;
  v_current_from date;
  v_old_to date;
  v_region uuid;
BEGIN
  IF NOT public.has_permission('PLATFORM_REVENUE', NULL) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_entity_type NOT IN ('account', 'account_type', 'service_type', 'service_category') THEN
    RAISE EXCEPTION 'Invalid entity type';
  END IF;
  IF p_entity_key IS NULL OR btrim(p_entity_key) = '' THEN
    RAISE EXCEPTION 'Entity key is required';
  END IF;
  IF p_rate IS NULL OR p_rate < 0 OR p_rate > 100 THEN
    RAISE EXCEPTION 'Rate must be between 0 and 100';
  END IF;

  -- Regional scope: a per-account override may only target a user whose
  -- region is within the caller's authorized scope. Global rules
  -- (account_type/service_type/service_category) are platform-wide.
  IF p_entity_type = 'account' THEN
    SELECT urp.region_id INTO v_region
      FROM public.user_region_preferences urp
     WHERE urp.user_id = p_entity_key::uuid
     LIMIT 1;
    IF v_region IS NOT NULL AND NOT public._region_in_scope(auth.uid(), v_region) THEN
      RAISE EXCEPTION 'Outside authorized region';
    END IF;
  END IF;

  p_effective_from := COALESCE(p_effective_from, CURRENT_DATE);

  SELECT c.id, c.effective_from INTO v_current_id, v_current_from
    FROM public.commission_rules c
   WHERE c.entity_type = p_entity_type
     AND c.entity_key = p_entity_key
     AND c.is_active
   ORDER BY c.effective_from DESC, c.created_at DESC
   LIMIT 1;

  IF v_current_id IS NOT NULL THEN
    v_old_to := GREATEST(v_current_from, p_effective_from);
    UPDATE public.commission_rules
       SET is_active = false,
           effective_to = v_old_to,
           updated_at = now()
     WHERE id = v_current_id;
  END IF;

  INSERT INTO public.commission_rules
    (entity_type, entity_key, rate, currency, effective_from,
     is_active, description, created_by, approved_by)
  VALUES (
    p_entity_type, p_entity_key, p_rate, 'SAR', p_effective_from,
    p_effective_from <= CURRENT_DATE,
    p_description, auth.uid(), auth.uid()
  )
  RETURNING id INTO v_new_id;

  PERFORM public.write_audit(
    'COMMISSION_RATE_CHANGED', 'commission_rules', v_new_id::text,
    jsonb_build_object('entity_type', p_entity_type,
                       'entity_key', p_entity_key,
                       'rate', p_rate,
                       'effective_from', p_effective_from,
                       'description', p_description));

  RETURN v_new_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_require_provider_documents(p_required boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public._is_owner_uid(auth.uid()) THEN
    RAISE EXCEPTION 'Only the platform owner can change provider document requirements';
  END IF;

  INSERT INTO public.platform_settings (id, require_provider_documents, updated_at)
  VALUES ('default', COALESCE(p_required, false), now())
  ON CONFLICT (id) DO UPDATE
    SET require_provider_documents = COALESCE(p_required, false),
        updated_at = now();

  -- When requirement is disabled, unlock pending merchants/providers automatically
  IF NOT COALESCE(p_required, false) THEN
    UPDATE public.users
       SET verification_status = 'approved',
           updated_at = now()
     WHERE (role IN ('merchant', 'provider') OR user_type IN ('merchant', 'provider'))
       AND verification_status = 'pending';
  END IF;

  PERFORM public.write_audit(
    'SET_REQUIRE_PROVIDER_DOCUMENTS',
    'platform_settings',
    'default',
    jsonb_build_object('require_provider_documents', COALESCE(p_required, false))
  );

  RETURN jsonb_build_object(
    'ok', true,
    'require_provider_documents', COALESCE(p_required, false)
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.share_ride(p_ride_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'UNAUTHENTICATED');
  END IF;
  UPDATE public.rides
     SET is_shared_trip = true
   WHERE id = p_ride_id AND rider_id = v_uid;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_YOUR_RIDE');
  END IF;
  RETURN jsonb_build_object('ok', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.start_delivery(p_delivery_id uuid, p_driver_id uuid, p_otp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN public.start_trip(p_delivery_id, p_driver_id, p_otp);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.start_live_share(p_ride_id uuid, p_duration_minutes integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ride RECORD;
  v_token uuid;
  v_expires timestamptz;
BEGIN
  SELECT * INTO v_ride FROM rides WHERE id = p_ride_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'ride_not_found');
  END IF;

  IF NOT (
    v_ride.rider_id = auth.uid()
    OR EXISTS (SELECT 1 FROM public.drivers d WHERE d.id = v_ride.driver_id AND d.user_id = auth.uid())
    OR public._is_owner_uid(auth.uid())
    OR public.is_admin()
  ) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;

  v_token := gen_random_uuid();
  v_expires := NOW() + (p_duration_minutes || ' minutes')::interval;

  INSERT INTO live_share_sessions (ride_id, user_id, share_token, expires_at, is_active)
  VALUES (p_ride_id, auth.uid(), v_token, v_expires, true);

  RETURN jsonb_build_object('success', true, 'share_token', v_token, 'expires_at', v_expires);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.start_trip(p_ride_id uuid, p_driver_id uuid, p_otp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r rides%ROWTYPE;
  v_owner UUID;
BEGIN
  SELECT user_id INTO v_owner FROM drivers WHERE id = p_driver_id;
  IF v_owner IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'reason', 'forbidden');
  END IF;
  SELECT * INTO r FROM rides WHERE id = p_ride_id FOR UPDATE;
  IF r.driver_id IS DISTINCT FROM p_driver_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'not_your_ride');
  END IF;
  IF r.status <> 'arrived' THEN
    RETURN jsonb_build_object('success', false, 'reason', 'invalid_transition');
  END IF;
  IF NOT public._verify_delivery_handoff(p_ride_id,'pickup',p_otp) THEN
    RETURN jsonb_build_object('success',false,'reason','INVALID_OR_LOCKED_PICKUP_CODE');
  END IF;
  UPDATE rides SET status = 'inTrip', started_at = NOW(), picked_up_at = NOW()
    WHERE id = p_ride_id;
  INSERT INTO trip_events (ride_id, event_type, actor) VALUES (p_ride_id, 'picked_up', 'driver');
  RETURN jsonb_build_object('success', true, 'status', 'inTrip');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.stop_live_share(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session RECORD;
BEGIN
  SELECT * INTO v_session FROM live_share_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'session_not_found');
  END IF;

  IF NOT (
    v_session.user_id = auth.uid()
    OR public._is_owner_uid(auth.uid())
    OR public.is_admin()
  ) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;

  UPDATE live_share_sessions SET is_active = false WHERE id = p_session_id;
  RETURN jsonb_build_object('success', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_appeal(p_sanction_id uuid, p_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_sanction public.sanctions%rowtype;
  v_region uuid;
  v_admin uuid;
  v_appeal uuid;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  select * into v_sanction from public.sanctions where id = p_sanction_id;
  if not found or v_sanction.target_user_id is distinct from v_uid then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  end if;
  if not (v_sanction.is_active and v_sanction.action_status = 'active') then
    return jsonb_build_object('ok', false, 'code', 'SANCTION_NOT_ACTIVE');
  end if;
  if exists (select 1 from public.appeals
              where sanction_id = p_sanction_id and status = 'pending') then
    return jsonb_build_object('ok', false, 'code', 'APPEAL_ALREADY_PENDING');
  end if;
  v_region := public._member_region_id(v_uid);
  v_admin := public._duty_admin_for_region(v_region);
  insert into public.appeals (user_id, sanction_id, message, region_id, assigned_admin_id)
  values (v_uid, p_sanction_id, nullif(btrim(p_message), ''), v_region, v_admin)
  returning id into v_appeal;
  if v_admin is not null then
    insert into public.notifications (user_id, title, body, type, data, send_push)
    values (v_admin,
            'التماس مراجعة إيقاف',
            'مستخدم موقوف قدّم التماس مراجعة في منطقتك. القرار قرارك: إعادة التفعيل أو الرفض.',
            'appeal',
            jsonb_build_object('appeal_id', v_appeal, 'sanction_id', p_sanction_id, 'member_id', v_uid),
            true);
  end if;
  insert into public.notifications (user_id, title, body, type, data, send_push)
  values (v_uid,
          'تم استلام التماسك',
          'وصل التماسك للمسؤول عن منطقتك وهيوصلك الرد هنا فور مراجعته.',
          'appeal',
          jsonb_build_object('appeal_id', v_appeal, 'sanction_id', p_sanction_id),
          true);
  return jsonb_build_object('ok', true, 'appeal_id', v_appeal, 'assigned_admin_id', v_admin);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_approval_request(p_request_type text, p_entity_type text, p_entity_id uuid, p_payload jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text, p_required_approver uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF NOT public._valid_approval_type(p_request_type) THEN
    RAISE EXCEPTION 'Unknown request type';
  END IF;
  IF p_required_approver IS NOT NULL
     AND NOT (public._is_owner_uid(p_required_approver)
              OR (public._is_active_admin_uid(p_required_approver)
                  AND public.is_supervisor_of(p_required_approver, auth.uid()))) THEN
    RAISE EXCEPTION 'Invalid required approver';
  END IF;

  BEGIN
    INSERT INTO public.approval_requests
      (request_type, entity_type, entity_id, payload, requested_by,
       required_approver, state, reason)
    VALUES (
      p_request_type, p_entity_type, p_entity_id,
      COALESCE(p_payload, '{}'::jsonb),
      auth.uid(), p_required_approver, 'pending', p_reason
    )
    RETURNING id INTO v_id;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'A pending request for this entity already exists';
  END;

  PERFORM public.write_audit(
    'APPROVAL_REQUESTED', 'approval_requests', v_id::text,
    jsonb_build_object('request_type', p_request_type,
                       'entity_type', p_entity_type,
                       'entity_id', p_entity_id,
                       'required_approver', p_required_approver));

  INSERT INTO public.notifications (user_id, title, body, type, data, deep_link, idempotency_key)
  VALUES (
    COALESCE(p_required_approver, (SELECT id FROM public.users WHERE role = 'owner' LIMIT 1)),
    'New approval request',
    p_request_type || ' for ' || COALESCE(p_entity_type, '?'),
    'approval',
    jsonb_build_object('request_id', v_id::text, 'request_type', p_request_type),
    '/admin/approvals',
    'approval-request-' || v_id::text
  );

  RETURN v_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_driver_onboarding(p_driver_id uuid, p_full_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_national_id text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_profile_photo_url text DEFAULT NULL::text, p_onboarding_step integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = p_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;

  UPDATE drivers SET
    full_name = COALESCE(p_full_name, full_name),
    phone = COALESCE(p_phone, phone),
    national_id_number = COALESCE(p_national_id, national_id_number),
    address = COALESCE(p_address, address),
    profile_photo_url = COALESCE(p_profile_photo_url, profile_photo_url),
    onboarding_step = p_onboarding_step,
    updated_at = NOW()
  WHERE id = p_driver_id;
  RETURN jsonb_build_object('success', true, 'step', p_onboarding_step);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_merchant_reply(p_review_id uuid, p_reply text)
 RETURNS reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_merchant_id UUID;
  v_updated public.reviews;
BEGIN
  IF p_reply IS NULL OR btrim(p_reply) = '' THEN
    RAISE EXCEPTION 'Reply must not be empty';
  END IF;

  SELECT r.merchant_id INTO v_merchant_id
  FROM public.reviews r
  WHERE r.id = p_review_id;

  IF v_merchant_id IS NULL THEN
    RAISE EXCEPTION 'Review not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.merchants m
    WHERE m.id = v_merchant_id
      AND m.owner_user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not the owner of this merchant';
  END IF;

  UPDATE public.reviews r
  SET merchant_reply = p_reply,
      updated_at = NOW()
  WHERE r.id = p_review_id
  RETURNING * INTO v_updated;

  RETURN v_updated;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.submit_settlement_request(p_amount numeric, p_payment_method text DEFAULT 'bank_transfer'::text, p_reference text DEFAULT NULL::text, p_proof_path text DEFAULT NULL::text, p_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_region uuid;
  v_id uuid;
BEGIN
  IF v_uid IS NULL OR NOT public.is_admin() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_AMOUNT');
  END IF;
  SELECT region_id INTO v_region FROM public.admin_region_assignments
   WHERE admin_id = v_uid LIMIT 1;

  INSERT INTO public.platform_settlements
    (admin_id, region_id, amount, currency, payment_method, reference, proof_path, message)
  VALUES
    (v_uid, v_region, p_amount, 'SAR', p_payment_method, p_reference, p_proof_path, p_message)
  RETURNING id INTO v_id;
  -- (reference column uses p_reference; fix below)
  UPDATE public.platform_settlements
     SET reference = p_reference, message = p_message
   WHERE id = v_id;

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'id', v_id, 'status', 'pending');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.switch_active_provider_profile(p_category_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cat text := lower(btrim(COALESCE(p_category_type, '')));
  v_is_owner boolean;
  v_profile public.provider_business_profiles%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF v_cat = '' THEN
    RAISE EXCEPTION 'Category is required';
  END IF;

  v_is_owner := public._is_owner_uid(v_uid);

  SELECT * INTO v_profile
    FROM public.provider_business_profiles
   WHERE user_id = v_uid AND category_type = v_cat;

  IF NOT v_is_owner THEN
    IF NOT FOUND OR v_profile.status <> 'approved' THEN
      RAISE EXCEPTION 'This service profile is not approved for your account yet';
    END IF;
  END IF;

  UPDATE public.users
     SET active_provider_category = v_cat,
         updated_at = now()
   WHERE id = v_uid;

  RETURN jsonb_build_object(
    'ok', true,
    'active_category', v_cat,
    'merchant_id', v_profile.merchant_id,
    'service_provider_id', v_profile.service_provider_id
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sync_delivery_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.delivery_status := CASE NEW.status
      WHEN 'pending' THEN 'pending'::delivery_status
      WHEN 'searching' THEN 'searching'::delivery_status
      WHEN 'matched' THEN 'matched'::delivery_status
      WHEN 'arrived' THEN 'arrived'::delivery_status
      WHEN 'inTrip' THEN 'in_transit'::delivery_status
      WHEN 'completed' THEN 'delivered'::delivery_status
      WHEN 'cancelled' THEN 'cancelled'::delivery_status
      ELSE NULL
    END;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sync_driver_online_from_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.is_online := (NEW.status = 'online');
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sync_linked_delivery_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.order_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.status = 'matched' THEN
    UPDATE public.orders SET driver_id=NEW.driver_id, dispatch_status='ASSIGNED', updated_at=now()
      WHERE id=NEW.order_id AND status NOT IN ('cancelled','delivered');
  ELSIF NEW.status = 'inTrip' THEN
    UPDATE public.orders SET status='delivering', dispatch_status='ACCEPTED', updated_at=now()
      WHERE id=NEW.order_id AND status NOT IN ('cancelled','delivered');
  ELSIF NEW.status = 'completed' THEN
    UPDATE public.orders SET status='delivered', dispatch_status='ACCEPTED', updated_at=now()
      WHERE id=NEW.order_id AND status <> 'cancelled';
  ELSIF NEW.status = 'cancelled' THEN
    UPDATE public.orders SET status='cancelled', updated_at=now()
      WHERE id=NEW.order_id AND status <> 'delivered';
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.sync_service_provider_rating()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op in ('INSERT','UPDATE') and new.provider_id is not null then
    update public.service_providers sp
       set rating = coalesce((
             select round(avg(r.rating)::numeric, 1)
               from public.service_reviews r where r.provider_id = sp.id), 0.0),
           rating_count = (
             select count(*) from public.service_reviews r where r.provider_id = sp.id)
     where sp.id = new.provider_id;
  end if;
  if tg_op in ('UPDATE','DELETE') and old.provider_id is not null
     and (tg_op = 'DELETE' or old.provider_id is distinct from new.provider_id) then
    update public.service_providers sp
       set rating = coalesce((
             select round(avg(r.rating)::numeric, 1)
               from public.service_reviews r where r.provider_id = sp.id), 0.0),
           rating_count = (
             select count(*) from public.service_reviews r where r.provider_id = sp.id)
     where sp.id = old.provider_id;
  end if;
  return null;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.toggle_vehicle_active(p_vehicle_id uuid, p_driver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_current BOOLEAN;
BEGIN
  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = p_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;
  SELECT is_active INTO v_current FROM vehicles WHERE id = p_vehicle_id AND driver_id = p_driver_id;
  UPDATE vehicles SET is_active = NOT v_current, updated_at = NOW()
  WHERE id = p_vehicle_id AND driver_id = p_driver_id;
  RETURN jsonb_build_object('success', true, 'is_active', NOT v_current);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_driver_capabilities(p_driver_id uuid, p_service_types text[], p_accepts_deliveries boolean, p_max_delivery_distance numeric, p_max_weight numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = p_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;
  UPDATE drivers SET
    service_types = p_service_types,
    accepts_deliveries = p_accepts_deliveries,
    max_delivery_distance_km = p_max_delivery_distance,
    max_weight_kg = p_max_weight,
    updated_at = NOW()
  WHERE id = p_driver_id;
  RETURN jsonb_build_object('success', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_driver_vehicle(p_vehicle_id uuid, p_driver_id uuid, p_category text DEFAULT NULL::text, p_make text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_year integer DEFAULT NULL::integer, p_color text DEFAULT NULL::text, p_plate_number text DEFAULT NULL::text, p_seats integer DEFAULT NULL::integer, p_photo_url text DEFAULT NULL::text, p_is_active boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_category IS NOT NULL AND p_category NOT IN ('motorcycle','tuk_tuk','tricycle','car') THEN
    RAISE EXCEPTION 'Invalid delivery vehicle type';
  END IF;
  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = p_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;
  UPDATE vehicles SET
    category = COALESCE(p_category, category),
    make = COALESCE(p_make, make),
    model = COALESCE(p_model, model),
    year = COALESCE(p_year, year),
    color = COALESCE(p_color, color),
    plate_number = COALESCE(p_plate_number, plate_number),
    seats = COALESCE(p_seats, seats),
    photo_url = COALESCE(p_photo_url, photo_url),
    is_active = COALESCE(p_is_active, is_active),
    updated_at = NOW()
  WHERE id = p_vehicle_id AND driver_id = p_driver_id;
  RETURN jsonb_build_object('success', true);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_member_dob(p_date_of_birth date, p_member_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_target uuid;
BEGIN
  v_target := COALESCE(p_member_id, auth.uid());
  IF v_target IS NULL THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_date_of_birth IS NOT NULL THEN
    IF p_date_of_birth > now()::date THEN
      RAISE EXCEPTION 'Date of birth cannot be in the future';
    END IF;
    IF p_date_of_birth < '1900-01-01'::date THEN
      RAISE EXCEPTION 'Date of birth is invalid';
    END IF;
  END IF;
  IF p_member_id IS NOT NULL
     AND p_member_id <> auth.uid()
     AND NOT public.has_permission('MEMBER_VIEW', public._member_region_id(p_member_id)) THEN
    RAISE EXCEPTION 'Not authorized for this member';
  END IF;
  UPDATE public.users SET date_of_birth = p_date_of_birth WHERE id = v_target;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_my_storefront(p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_logo_url text DEFAULT NULL::text, p_cover_url text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_latitude double precision DEFAULT NULL::double precision, p_longitude double precision DEFAULT NULL::double precision, p_delivery_fee numeric DEFAULT NULL::numeric, p_min_order numeric DEFAULT NULL::numeric, p_delivery_time_min integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_merchant uuid;
BEGIN
  v_merchant := public.resolve_my_merchant();
  IF v_merchant IS NULL THEN
    RAISE EXCEPTION 'No merchant store for this account';
  END IF;

  IF p_name IS NOT NULL AND btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Store name cannot be empty';
  END IF;

  -- COALESCE keeps every field optional so the caller can PATCH one
  -- value without resending the whole storefront.
  UPDATE public.merchants
     SET name = COALESCE(NULLIF(btrim(p_name), ''), name),
         description = COALESCE(p_description, description),
         logo_url = COALESCE(p_logo_url, logo_url),
         cover_url = COALESCE(p_cover_url, cover_url),
         phone = COALESCE(p_phone, phone),
         address = COALESCE(p_address, address),
         latitude = COALESCE(p_latitude, latitude),
         longitude = COALESCE(p_longitude, longitude),
         delivery_fee = COALESCE(p_delivery_fee, delivery_fee),
         min_order = COALESCE(p_min_order, min_order),
         delivery_time_min = COALESCE(p_delivery_time_min, delivery_time_min),
         updated_at = now()
   WHERE id = v_merchant;

  -- Return the stored row, not the inputs.
  RETURN (
    SELECT jsonb_build_object(
      'id', m.id, 'name', m.name, 'description', m.description,
      'logo_url', m.logo_url, 'cover_url', m.cover_url,
      'phone', m.phone, 'address', m.address,
      'latitude', m.latitude, 'longitude', m.longitude,
      'delivery_fee', m.delivery_fee, 'min_order', m.min_order,
      'delivery_time_min', m.delivery_time_min
    )
    FROM public.merchants m
    WHERE m.id = v_merchant
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_my_storefront(p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_logo_url text DEFAULT NULL::text, p_cover_url text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_latitude double precision DEFAULT NULL::double precision, p_longitude double precision DEFAULT NULL::double precision, p_delivery_fee numeric DEFAULT NULL::numeric, p_min_order numeric DEFAULT NULL::numeric, p_delivery_time_min integer DEFAULT NULL::integer, p_is_open boolean DEFAULT NULL::boolean, p_type text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_merchant uuid;
BEGIN
  v_merchant := public.resolve_my_merchant();
  IF v_merchant IS NULL THEN
    RAISE EXCEPTION 'No merchant record found for caller';
  END IF;

  IF p_name IS NOT NULL AND length(btrim(p_name)) = 0 THEN
    RAISE EXCEPTION 'Merchant name cannot be empty';
  END IF;

  UPDATE public.merchants
     SET name              = COALESCE(NULLIF(btrim(p_name), ''), name),
         description       = COALESCE(p_description, description),
         logo_url          = COALESCE(p_logo_url, logo_url),
         cover_url         = COALESCE(p_cover_url, cover_url),
         phone             = COALESCE(p_phone, phone),
         address           = COALESCE(p_address, address),
         latitude          = COALESCE(p_latitude, latitude),
         longitude         = COALESCE(p_longitude, longitude),
         delivery_fee      = COALESCE(p_delivery_fee, delivery_fee),
         min_order         = COALESCE(p_min_order, min_order),
         delivery_time_min = COALESCE(p_delivery_time_min, delivery_time_min),
         is_open           = COALESCE(p_is_open, is_open),
         type              = COALESCE(NULLIF(btrim(p_type), ''), type),
         updated_at        = now()
   WHERE id = v_merchant;

  RETURN v_merchant;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_order_status(p_order_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_order    public.orders;
  v_is_admin boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;

  -- Authorize: merchant owner of the order, OR admin
  IF NOT public.is_admin() THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.merchants m
       WHERE m.id = v_order.merchant_id AND m.owner_user_id = v_uid
    ) THEN
      RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
    END IF;
  END IF;

  IF p_status NOT IN ('confirmed','preparing','ready','delivering','delivered','cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATUS');
  END IF;

  -- Merchants are limited to fulfillment statuses (delivering is admin-only)
  IF NOT public.is_admin() AND p_status IN ('confirmed','delivering') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MERCHANT_STATUS_FORBIDDEN');
  END IF;

  -- Terminal states cannot be changed
  IF v_order.status IN ('delivered','cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'TERMINAL_STATE', 'status', v_order.status);
  END IF;

  UPDATE public.orders
     SET status = p_status, updated_at = now()
   WHERE id = p_order_id;

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'status', p_status);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_payment_transactions_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_receiving_account(p_method text, p_display_name text DEFAULT NULL::text, p_account_identifier text DEFAULT NULL::text, p_instructions text DEFAULT NULL::text, p_is_active boolean DEFAULT NULL::boolean, p_display_order integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row RECORD;
BEGIN
  IF NOT public.has_financial_permission(auth.uid(), 'manage_receiving_accounts') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;

  IF p_method IS NULL OR p_method = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_METHOD');
  END IF;

  SELECT * INTO STRICT v_row
  FROM public.financial_receiving_accounts
  WHERE method = p_method
  FOR UPDATE;

  UPDATE public.financial_receiving_accounts
  SET display_name = COALESCE(p_display_name, display_name),
      account_identifier = COALESCE(p_account_identifier, account_identifier),
      instructions = COALESCE(p_instructions, instructions),
      is_active = COALESCE(p_is_active, is_active),
      display_order = COALESCE(p_display_order, display_order),
      updated_at = now()
  WHERE method = p_method;

  RETURN jsonb_build_object('ok', true, 'code', 'OK');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_reservation_status(p_reservation_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_r public.reservations;
  v_uid uuid := auth.uid();
  v_merchant_ok boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('pending','confirmed','cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATUS');
  END IF;
  SELECT * INTO v_r FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF v_r IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.merchants m
     WHERE m.id = v_r.merchant_id AND m.owner_user_id = v_uid
  ) INTO v_merchant_ok;
  IF v_r.user_id IS DISTINCT FROM v_uid AND NOT v_merchant_ok AND NOT public.is_admin() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  -- Customers may only cancel their own reservation; confirming is the
  -- merchant's (or platform's) call.
  IF NOT v_merchant_ok AND NOT public.is_admin() AND p_status <> 'cancelled' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MERCHANT_ONLY_STATUS');
  END IF;
  IF p_status = 'cancelled' AND v_r.status = 'cancelled' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ALREADY_CANCELLED');
  END IF;
  UPDATE public.reservations SET status = p_status WHERE id = v_r.id;
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'status', p_status);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_service_booking_status(p_booking_id uuid, p_status text, p_final_price numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_book service_bookings%ROWTYPE;
  v_is_customer boolean;
  v_is_provider boolean;
  v_is_admin boolean := false;
  v_region uuid;
  v_allowed boolean := false;
  v_cur_status text;
  v_provider_uid uuid;
  v_gross numeric;
  v_rate numeric;
  v_commission numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'UNAUTHENTICATED');
  END IF;
  IF p_status NOT IN ('confirmed','inProgress','completed','cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_STATUS');
  END IF;
  IF p_final_price IS NOT NULL AND p_final_price <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_PRICE');
  END IF;

  SELECT * INTO v_book
    FROM public.service_bookings
   WHERE id = p_booking_id
   FOR UPDATE;
  IF v_book.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_FOUND');
  END IF;

  v_is_customer := v_book.user_id = v_uid;
  v_is_provider := public.is_service_provider_owner(v_book.provider_id);

  -- Admin branch is region-scoped (195/196): the booking's region is the
  -- booking customer's users.region_id; NULL-region customers fall back to
  -- owner/global admins only (_admin_scope_allows), matching the 194
  -- incident pattern and the 190 appeals precedent.
  IF NOT (v_is_customer OR v_is_provider) THEN
    IF public._is_owner_uid(v_uid) THEN
      v_is_admin := true;
    ELSE
      SELECT region_id INTO v_region FROM public.users WHERE id = v_book.user_id;
      v_is_admin := (public.has_permission('SERVICE_MANAGE', NULL, NULL)
                  OR public.has_permission('MEMBER_MODERATE', NULL, NULL))
                AND public._admin_scope_allows(v_region);
    END IF;
  END IF;

  IF NOT (v_is_customer OR v_is_provider OR v_is_admin) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'NOT_YOUR_BOOKING');
  END IF;

  v_cur_status := v_book.status;
  IF v_cur_status IN ('completed','cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'TERMINAL_STATE', 'status', v_cur_status);
  END IF;

  -- Role transition matrix.
  IF v_is_customer THEN
    v_allowed := p_status = 'cancelled' AND v_cur_status IN ('pending','confirmed');
  ELSIF v_is_provider THEN
    v_allowed := (v_cur_status = 'pending'    AND p_status = 'confirmed')
              OR (v_cur_status = 'confirmed'  AND p_status = 'inProgress')
              OR (v_cur_status = 'inProgress' AND p_status = 'completed');
  ELSE -- region-scoped admin: support cancellation only
    v_allowed := p_status = 'cancelled';
  END IF;

  IF NOT v_allowed THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_TRANSITION',
      'from', v_cur_status, 'to', p_status);
  END IF;

  -- Only the provider may quote the final price, and only while the booking
  -- is live (196: commission base = provider final_price, else estimate).
  IF p_final_price IS NOT NULL AND NOT v_is_provider THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'PRICE_PROVIDER_ONLY');
  END IF;

  -- 199: completion needs a real price. A quote-less completion (NULL
  -- estimate, no stored final, no completion-time quote) would price the
  -- platform commission at zero.
  IF p_status = 'completed'
     AND COALESCE(p_final_price, v_book.final_price, v_book.estimated_price, 0) <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'PRICE_REQUIRED');
  END IF;

  UPDATE public.service_bookings
     SET status = p_status,
         final_price = CASE WHEN p_final_price IS NOT NULL THEN p_final_price ELSE final_price END,
         completed_at = CASE WHEN p_status = 'completed' THEN now() ELSE completed_at END,
         updated_at = now()
   WHERE id = p_booking_id;

  -- Completion records the platform's commission on the provider: the agreed
  -- price (final when set, else the estimate) at the provider rate, once.
  -- 197: price from the POST-update values - p_final_price lands in the same
  -- statement, so the pre-update v_book copy is stale here.
  IF p_status = 'completed' THEN
    SELECT user_id INTO v_provider_uid
      FROM public.service_providers WHERE id = v_book.provider_id;
    IF v_provider_uid IS NOT NULL THEN
      v_gross := COALESCE(p_final_price, v_book.final_price, v_book.estimated_price, 0);
      v_rate := COALESCE(
        public.get_commission_rate('provider', v_book.category_type, v_provider_uid), 0);
      v_commission := public.calculate_commission(v_gross, v_rate);
      INSERT INTO public.platform_commissions
        (member_id, reference_type, reference_id, gross_amount, commission_rate,
         commission_amount, net_amount, currency, status)
      VALUES (v_provider_uid, 'service_booking', p_booking_id, v_gross, v_rate,
              v_commission, v_gross - v_commission, 'EGP', 'computed')
      ON CONFLICT (reference_type, reference_id) DO NOTHING;
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'status', p_status);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.upsert_driver_document(p_driver_id uuid, p_doc_type text, p_file_url text, p_file_name text DEFAULT NULL::text, p_file_size integer DEFAULT NULL::integer, p_expires_at date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id UUID;
  v_existing UUID;
  v_driver_id UUID;
BEGIN
  -- Canonical identity: caller may provide either the drivers.id (canonical) or,
  -- defensively, the users.id of their own account. Both must be owned by the
  -- caller unless they are an owner.
  v_driver_id := p_driver_id;
  IF NOT EXISTS (SELECT 1 FROM public.drivers WHERE id = p_driver_id) THEN
    SELECT id INTO v_driver_id FROM public.drivers WHERE user_id = p_driver_id;
    IF v_driver_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'reason', 'DRIVER_NOT_FOUND');
    END IF;
  END IF;

  IF NOT (EXISTS (
        SELECT 1 FROM public.drivers d
         WHERE d.id = v_driver_id AND d.user_id = auth.uid()
      ) OR public._is_owner_uid(auth.uid())) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'FORBIDDEN');
  END IF;

  IF p_doc_type NOT IN ('identity','driving_license','vehicle_registration','insurance','vehicle_photo','profile_photo')
    OR p_file_url IS NULL OR p_file_url LIKE '%://%'
    OR (split_part(p_file_url,'/',2) <> v_driver_id::text AND split_part(p_file_url,'/',2) <> auth.uid()::text)
    OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='driver-documents' AND name=p_file_url)
    OR (p_expires_at IS NOT NULL AND p_expires_at < current_date) THEN
    RETURN jsonb_build_object('success',false,'reason','INVALID_DOCUMENT');
  END IF;

  PERFORM 1 FROM public.drivers WHERE id=v_driver_id FOR UPDATE;
  SELECT id INTO v_existing FROM driver_documents
  WHERE driver_id = v_driver_id AND doc_type = p_doc_type
  ORDER BY created_at DESC LIMIT 1;

  IF v_existing IS NOT NULL THEN
    UPDATE driver_documents SET
      file_url = p_file_url,
      file_name = COALESCE(p_file_name, file_name),
      file_size = COALESCE(p_file_size, file_size),
      expires_at = p_expires_at,
      status = 'pending',
      rejection_reason = NULL,
      reviewed_at = NULL
    WHERE id = v_existing RETURNING id INTO v_id;
  ELSE
    INSERT INTO driver_documents (driver_id, doc_type, file_url, file_name, file_size, expires_at, status)
    VALUES (v_driver_id, p_doc_type, p_file_url, p_file_name, p_file_size, p_expires_at, 'pending')
    RETURNING id INTO v_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'document_id', v_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.upsert_trusted_contact(p_name text, p_phone text, p_contact_id uuid DEFAULT NULL::uuid, p_email text DEFAULT NULL::text, p_relationship text DEFAULT NULL::text, p_notify_on_ride boolean DEFAULT true, p_notification_preference text DEFAULT 'both'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_id UUID;
BEGIN
  v_user_id := auth.uid();

  IF p_contact_id IS NOT NULL THEN
    UPDATE trusted_contacts
    SET name = p_name, phone = p_phone, email = p_email,
        relationship = p_relationship, notify_on_ride = p_notify_on_ride,
        notification_preference = p_notification_preference
    WHERE id = p_contact_id AND user_id = v_user_id
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'reason', 'contact_not_found');
    END IF;
  ELSE
    INSERT INTO trusted_contacts (user_id, name, phone, email, relationship, notify_on_ride, notification_preference)
    VALUES (v_user_id, p_name, p_phone, p_email, p_relationship, p_notify_on_ride, p_notification_preference)
    RETURNING id INTO v_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'contact_id', v_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.users_guard_account_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    return NEW;
  end if;
  if current_user in ('authenticated', 'anon') then
    if NEW.role is distinct from OLD.role then
      raise exception 'Role is managed by the admin lifecycle RPCs';
    end if;
    if NEW.account_status is distinct from OLD.account_status then
      raise exception 'Account status is managed by the moderation RPCs';
    end if;
    if NEW.date_of_birth is distinct from OLD.date_of_birth then
      raise exception 'Date of birth must be updated via update_member_dob';
    end if;
    if NEW.anonymized_at is distinct from OLD.anonymized_at then
      raise exception 'Anonymization is managed by the member deletion RPC';
    end if;
    if NEW.verification_status is distinct from OLD.verification_status then
      raise exception 'Verification status is managed by the verification RPCs';
    end if;
    if NEW.user_type is distinct from OLD.user_type then
      raise exception 'User type is managed by the account lifecycle RPCs';
    end if;
  end if;
  return NEW;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.validate_notification_deep_link(p_deep_link text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_segs text[];
  v_pat text[];
  v_i integer;
  v_role text;
  v_row record;
  v_matched boolean;
BEGIN
  IF p_deep_link IS NULL OR btrim(p_deep_link) = '' THEN
    RETURN NULL;
  END IF;
  IF left(p_deep_link, 1) <> '/' THEN
    RETURN NULL;
  END IF;
  -- Reject scheme injection and path traversal outright.
  IF p_deep_link ~* '^/(javascript|http|https|data|vbscript|file):'
     OR p_deep_link ~ '(^|/)\.\.?(/|$)' THEN
    RETURN NULL;
  END IF;

  v_role := NULL;
  -- SECURITY DEFINER: current_user is ALWAYS the function owner (postgres),
  -- so it cannot discriminate the caller. Use auth.uid() instead: NULL for
  -- service_role / server-side calls (no JWT) => role restriction bypassed;
  -- non-NULL for authenticated JWTs => enforce allowed_roles from users.role.
  SELECT role INTO v_role FROM public.users WHERE id = auth.uid();

  v_segs := string_to_array(p_deep_link, '/');
  FOR v_row IN
    SELECT route_pattern, allowed_roles
      FROM public.notification_destinations
     WHERE is_active
     ORDER BY length(route_pattern) DESC
  LOOP
    v_pat := string_to_array(v_row.route_pattern, '/');
    IF cardinality(v_pat) IS DISTINCT FROM cardinality(v_segs) THEN
      CONTINUE;
    END IF;
    v_matched := true;
    FOR v_i IN 1..cardinality(v_segs) LOOP
      IF left(v_pat[v_i], 1) = ':' THEN
        CONTINUE; -- parameterized segment: matches any single value
      END IF;
      IF v_pat[v_i] <> v_segs[v_i] THEN
        v_matched := false;
        EXIT;
      END IF;
    END LOOP;
    IF v_matched THEN
      IF v_row.allowed_roles IS NULL
         OR auth.uid() IS NULL
         OR v_role = ANY(v_row.allowed_roles) THEN
        RETURN p_deep_link;
      END IF;
    END IF;
  END LOOP;

  RETURN NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.validate_promo(p_code text, p_user_id uuid, p_fare double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  pc promo_codes%ROWTYPE;
  used INTEGER;
  discount DECIMAL(10,2);
BEGIN
  SELECT * INTO pc FROM promo_codes
    WHERE code = upper(p_code) AND is_active = true
      AND (valid_until IS NULL OR valid_until > NOW())
      AND valid_from <= NOW();
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'invalid');
  END IF;
  IF pc.min_fare > p_fare THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'min_fare');
  END IF;
  IF pc.usage_limit IS NOT NULL AND pc.used_count >= pc.usage_limit THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'exhausted');
  END IF;
  SELECT COUNT(*) INTO used FROM promo_redemptions
    WHERE promo_id = pc.id AND user_id = p_user_id;
  IF used >= pc.per_user_limit THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'already_used');
  END IF;
  IF pc.discount_type = 'percentage' THEN
    discount := (p_fare * pc.discount_value / 100)::DECIMAL(10,2);
  ELSE
    discount := pc.discount_value;
  END IF;
  IF pc.max_discount IS NOT NULL THEN
    discount := LEAST(discount, pc.max_discount);
  END IF;
  discount := LEAST(discount, p_fare::DECIMAL(10,2));
  RETURN jsonb_build_object('valid', true, 'discount', discount, 'promo_id', pc.id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.verify_whatsapp_otp(p_phone text, p_otp_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_norm text := public._normalize_egypt_phone(p_phone);
  v_code text := btrim(coalesce(p_otp_code, ''));
  v_row public.whatsapp_otp_verifications%rowtype;
begin
  if length(v_norm) < 10 or length(v_code) < 4 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_INPUT');
  end if;

  select * into v_row
    from public.whatsapp_otp_verifications
   where phone = v_norm
     and expires_at > now()
     and verified = false
   order by created_at desc
   limit 1
   for update;

  -- b) lockout: locked phone rejects even correct codes until lock expires
  if v_row.id is not null and v_row.locked_until is not null and v_row.locked_until > now() then
    return jsonb_build_object('ok', false, 'code', 'LOCKED');
  end if;

  if v_row.id is null or v_row.otp_code <> v_code then
    if v_row.id is not null then
      update public.whatsapp_otp_verifications
         set attempts = attempts + 1,
             locked_until = case when attempts + 1 >= 5 then now() + interval '15 minutes' else locked_until end
       where id = v_row.id;
    end if;
    return jsonb_build_object('ok', false, 'code', 'INVALID_OR_EXPIRED_OTP');
  end if;

  update public.whatsapp_otp_verifications
     set verified = true
   where id = v_row.id;

  -- d) stamp phone only for authenticated callers, and never onto an account
  --    when the phone already belongs to a DIFFERENT account
  if auth.uid() is not null
     and not exists (
       select 1 from public.users
        where public._normalize_egypt_phone(phone) = v_norm
          and id <> auth.uid()
     ) then
    update public.users
       set phone = v_norm,
           updated_at = now()
     where id = auth.uid();
  end if;

  return jsonb_build_object(
    'ok', true,
    'verified', true,
    'phone', v_norm
  );
end;
$function$
;
CREATE OR REPLACE FUNCTION public.wallet_adjust(p_account_id uuid, p_amount numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller    uuid := auth.uid();
  v_wallet_id uuid;
  v_before    numeric;
  v_after     numeric;
  v_txn_id    uuid;
begin
  if v_caller is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  if not public._is_owner_uid(v_caller) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN_OWNER_ONLY');
  end if;
  if not exists (select 1 from public.users where id = p_account_id) then
    return jsonb_build_object('ok', false, 'code', 'ACCOUNT_NOT_FOUND');
  end if;
  if p_amount is null or p_amount = 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_AMOUNT');
  end if;

  v_wallet_id := public._ensure_wallet(p_account_id);
  select balance into v_before from public.wallets where id = v_wallet_id for update;
  v_after := coalesce(v_before, 0) + p_amount;
  if v_after < 0 then
    return jsonb_build_object('ok', false, 'code', 'INSUFFICIENT_BALANCE',
      'balance', v_before, 'requested', p_amount);
  end if;

  update public.wallets set balance = v_after, updated_at = now() where id = v_wallet_id;

  insert into public.wallet_transactions
    (wallet_id, type, amount, reference_type, reference_id, description, balance_after)
  values
    (v_wallet_id, case when p_amount > 0 then 'credit' else 'debit' end,
     abs(p_amount), 'admin_adjustment', v_caller,
     'Owner adjustment' || coalesce(' - ' || p_note, ''), v_after)
  returning id into v_txn_id;

  perform public.write_audit('WALLET_ADJUST', 'wallets', v_wallet_id::text,
    jsonb_build_object('actor', v_caller, 'account_id', p_account_id,
      'amount', p_amount, 'balance_before', v_before, 'balance_after', v_after,
      'transaction_id', v_txn_id, 'note', p_note));

  return jsonb_build_object('ok', true, 'code', 'OK', 'wallet_id', v_wallet_id,
    'balance_before', v_before, 'balance_after', v_after, 'transaction_id', v_txn_id);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.wallet_pay(p_user_id uuid, p_amount numeric, p_description text DEFAULT 'Payment'::text, p_reference_type text DEFAULT 'payment'::text, p_reference_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$

DECLARE v_wallet_id uuid; v_balance numeric; v_after numeric; v_tx_id uuid;
BEGIN
  -- Fail closed. The previous form (`auth.uid() IS NOT NULL AND ...`)
  -- was skipped entirely for an anonymous caller, which made this
  -- function reachable by `anon` and let a signed-out request credit
  -- or debit an arbitrary wallet. A wallet RPC is never anonymous:
  -- a top-up has to be distinguishable from a platform grant, so it
  -- stays behind an authenticated, self-only caller.
  IF auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF p_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'code', 'INVALID_USER'); END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN RETURN jsonb_build_object('ok', false, 'code', 'INVALID_AMOUNT'); END IF;
  v_wallet_id := public._ensure_wallet(p_user_id);
  SELECT balance INTO v_balance FROM public.wallets WHERE id = v_wallet_id FOR UPDATE;
  v_balance := COALESCE(v_balance, 0);
  IF v_balance < p_amount THEN RETURN jsonb_build_object('ok', false, 'code', 'INSUFFICIENT_BALANCE', 'current_balance', v_balance, 'required', p_amount); END IF;
  v_after := v_balance - p_amount;
  UPDATE public.wallets SET balance = v_after, updated_at = now() WHERE id = v_wallet_id;
  INSERT INTO public.wallet_transactions (wallet_id, type, amount, reference_type, reference_id, description, balance_after) VALUES (v_wallet_id, 'debit', p_amount, p_reference_type, p_reference_id, p_description, v_after) RETURNING id INTO v_tx_id;
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'wallet_id', v_wallet_id, 'new_balance', v_after, 'transaction_id', v_tx_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.wallet_pay(p_amount numeric, p_description text DEFAULT NULL::text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_wallet public.wallets%ROWTYPE;
  v_new_balance numeric;
  v_tx_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Amount must be positive';
  END IF;

  SELECT * INTO v_wallet
    FROM public.wallets
   WHERE user_id = v_uid
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No wallet';
  END IF;

  IF COALESCE(v_wallet.balance, 0) < p_amount THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INSUFFICIENT_BALANCE');
  END IF;

  v_new_balance := v_wallet.balance - p_amount;

  UPDATE public.wallets
     SET balance = v_new_balance,
         updated_at = now()
   WHERE id = v_wallet.id;

  INSERT INTO public.wallet_transactions
    (wallet_id, user_id, type, amount, balance_after, description,
     reference_type, reference_id)
  VALUES
    (v_wallet.id, v_uid, 'payment', p_amount, v_new_balance,
     COALESCE(p_description, 'Wallet payment'),
     p_reference_type, p_reference_id::uuid)
  RETURNING id INTO v_tx_id;

  RETURN jsonb_build_object(
    'ok', true, 'balance', v_new_balance, 'transaction_id', v_tx_id
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.wallet_refund(p_user_id uuid, p_amount numeric, p_description text DEFAULT 'Refund'::text, p_reference_type text DEFAULT 'refund'::text, p_reference_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null and p_user_id is distinct from auth.uid() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  return public._wallet_credit(p_user_id, p_amount, p_description, p_reference_type, p_reference_id);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.wallet_topup(p_user_id uuid, p_amount numeric, p_description text DEFAULT 'Top-up'::text, p_reference_type text DEFAULT 'topup'::text, p_reference_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$

DECLARE v_wallet_id uuid; v_balance numeric; v_after numeric; v_tx_id uuid;
BEGIN
  -- Fail closed. The previous form (`auth.uid() IS NOT NULL AND ...`)
  -- was skipped entirely for an anonymous caller, which made this
  -- function reachable by `anon` and let a signed-out request credit
  -- or debit an arbitrary wallet. A wallet RPC is never anonymous:
  -- a top-up has to be distinguishable from a platform grant, so it
  -- stays behind an authenticated, self-only caller.
  IF auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  END IF;
  IF p_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'code', 'INVALID_USER'); END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN RETURN jsonb_build_object('ok', false, 'code', 'INVALID_AMOUNT'); END IF;
  v_wallet_id := public._ensure_wallet(p_user_id);
  SELECT balance INTO v_balance FROM public.wallets WHERE id = v_wallet_id FOR UPDATE;
  v_after := COALESCE(v_balance, 0) + p_amount;
  UPDATE public.wallets SET balance = v_after, updated_at = now() WHERE id = v_wallet_id;
  INSERT INTO public.wallet_transactions (wallet_id, type, amount, reference_type, reference_id, description, balance_after) VALUES (v_wallet_id, 'credit', p_amount, p_reference_type, p_reference_id, p_description, v_after) RETURNING id INTO v_tx_id;
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'wallet_id', v_wallet_id, 'new_balance', v_after, 'transaction_id', v_tx_id);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.wallet_topup(p_amount numeric, p_method text DEFAULT 'manual'::text, p_reference text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_wallet public.wallets%ROWTYPE;
  v_new_balance numeric;
  v_tx_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Amount must be positive';
  END IF;

  -- Idempotency: a retried request must never credit twice.
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_tx_id
      FROM public.wallet_transactions
     WHERE user_id = v_uid
       AND reference_id = 'topup:' || p_idempotency_key
     LIMIT 1;
    IF v_tx_id IS NOT NULL THEN
      SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_uid;
      RETURN jsonb_build_object(
        'ok', true, 'duplicate', true, 'balance', v_wallet.balance,
        'transaction_id', v_tx_id
      );
    END IF;
  END IF;

  SELECT * INTO v_wallet
    FROM public.wallets
   WHERE user_id = v_uid
   FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.wallets (user_id, balance, currency)
         VALUES (v_uid, 0, 'EGP')
      RETURNING * INTO v_wallet;
  END IF;

  v_new_balance := COALESCE(v_wallet.balance, 0) + p_amount;

  UPDATE public.wallets
     SET balance = v_new_balance,
         updated_at = now()
   WHERE id = v_wallet.id;

  INSERT INTO public.wallet_transactions
    (wallet_id, user_id, type, amount, balance_after, description, reference_id)
  VALUES
    (v_wallet.id, v_uid, 'topup', p_amount, v_new_balance,
     'Top up via ' || COALESCE(p_method, 'manual'),
     'topup:' || COALESCE(p_idempotency_key, gen_random_uuid()::text))
  RETURNING id INTO v_tx_id;

  RETURN jsonb_build_object(
    'ok', true, 'balance', v_new_balance, 'transaction_id', v_tx_id
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.write_audit(p_action text, p_resource text, p_resource_id text DEFAULT NULL::text, p_details jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  INSERT INTO public.activity_logs
    (user_id, action, resource, resource_id, details, timestamp)
  VALUES (
    COALESCE(auth.uid()::text, 'system'),
    p_action,
    p_resource,
    p_resource_id,
    p_details,
    now()
  );
END;
$function$
;
