CREATE OR REPLACE FUNCTION public.search_merchants_ar(p_query text, p_limit integer DEFAULT 20)
 RETURNS SETOF merchants
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT m.*
    FROM merchants m
   WHERE
     (
       normalize_arabic(m.name) LIKE '%' || normalize_arabic(p_query) || '%'
       OR normalize_arabic(m.description) LIKE '%' || normalize_arabic(p_query) || '%'
       OR similarity(normalize_arabic(m.name), normalize_arabic(p_query)) > 0.3
     )
    ORDER BY similarity(normalize_arabic(m.name), normalize_arabic(p_query)) DESC
    LIMIT p_limit;
$function$
;
CREATE OR REPLACE FUNCTION public.search_products_ar(p_query text, p_limit integer DEFAULT 20)
 RETURNS SETOF products
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p.*
    FROM products p
   WHERE
     (
       p.name_ar IS NOT NULL AND normalize_arabic(p.name_ar) LIKE '%' || normalize_arabic(p_query) || '%'
       OR p.description_ar IS NOT NULL AND normalize_arabic(p.description_ar) LIKE '%' || normalize_arabic(p_query) || '%'
       OR normalize_arabic(p.name) LIKE '%' || normalize_arabic(p_query) || '%'
       OR (similarity(normalize_arabic(COALESCE(p.name_ar, p.name)), normalize_arabic(p_query)) > 0.3)
     )
    ORDER BY
       GREATEST(
         similarity(normalize_arabic(COALESCE(p.name_ar, p.name)), normalize_arabic(p_query)),
         CASE WHEN normalize_arabic(COALESCE(p.name_ar, p.name)) LIKE normalize_arabic(p_query) || '%' THEN 1 ELSE 0 END
       ) DESC
    LIMIT p_limit;
$function$
;
CREATE OR REPLACE FUNCTION public.get_merchant_deliveries(p_merchant_id uuid, p_status text DEFAULT NULL::text)
 RETURNS SETOF rides
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT * FROM rides
  WHERE merchant_id = p_merchant_id
    AND service_type != 'ride'
    AND (p_status IS NULL OR status = p_status)
    AND (EXISTS (
      SELECT 1 FROM public.merchants m
       WHERE m.id = p_merchant_id AND m.owner_user_id = auth.uid()
    ) OR public._is_owner_uid(auth.uid()) OR public.is_admin())
  ORDER BY created_at DESC
  LIMIT 50;
$function$
;
CREATE OR REPLACE FUNCTION public.is_merchant_owner(merchant_uuid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1
      FROM public.merchants m
     WHERE m.id = merchant_uuid
       AND (m.owner_user_id = auth.uid() OR m.id = auth.uid())
  ) OR public.is_admin();
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_can_target_region(p_region_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.is_admin()
    AND (
      NOT EXISTS (
        SELECT 1 FROM public.admin_region_assignments a
        WHERE a.admin_id = auth.uid()
      )
      OR public.is_admin_for_region(p_region_id)
    );
$function$
;
CREATE OR REPLACE FUNCTION public.get_driver_documents(p_driver_id uuid)
 RETURNS SETOF driver_documents
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT * FROM driver_documents
  WHERE driver_id = p_driver_id
    AND (EXISTS (
      SELECT 1 FROM public.drivers d
       WHERE d.id = p_driver_id AND d.user_id = auth.uid()
    ) OR public._is_owner_uid(auth.uid()) OR public.admin_has_permission('DRIVER_DOCUMENT_VIEW', NULL))
  ORDER BY created_at DESC;
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_targets_authorized(p_campaign_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.is_admin()
    AND NOT EXISTS (
      SELECT 1 FROM public.campaign_targets t
      WHERE t.campaign_id = p_campaign_id
        AND NOT public.campaign_can_target_region(t.region_id)
    );
$function$
;
CREATE OR REPLACE FUNCTION public.campaign_scoped_for_storage(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.is_admin()
    AND public.campaign_id_from_storage_path(p_name) IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.campaigns c
      WHERE c.id = public.campaign_id_from_storage_path(p_name)
    )
    AND public.campaign_targets_authorized(public.campaign_id_from_storage_path(p_name));
$function$
;

-- views
CREATE OR REPLACE VIEW public.app_public_config AS  SELECT id,
    app_name,
    support_email,
    support_phone,
    maintenance_mode,
    min_app_version_android,
    min_app_version_ios,
    require_provider_documents
   FROM platform_settings;
CREATE OR REPLACE VIEW public.deliveries AS  SELECT r.id,
    r.order_id,
    r.driver_id,
    COALESCE(m.name, ''::text) AS merchant_name,
    COALESCE(NULLIF(r.pickup_address, ''::text), COALESCE(m.address, ''::text)) AS merchant_address,
    COALESCE(r.recipient_name, u.full_name, ''::text) AS customer_name,
    COALESCE(r.dropoff_address, ''::text) AS delivery_address,
    r.dropoff_latitude AS customer_latitude,
    r.dropoff_longitude AS customer_longitude,
        CASE r.status
            WHEN 'searching'::text THEN 'pending'::text
            WHEN 'matched'::text THEN 'accepted'::text
            WHEN 'arrived'::text THEN 'arrived'::text
            WHEN 'inTrip'::text THEN 'picked_up'::text
            WHEN 'completed'::text THEN 'delivered'::text
            WHEN 'cancelled'::text THEN 'cancelled'::text
            ELSE r.status
        END AS status,
    r.fare AS delivery_fee,
    COALESCE(r.delivery_notes, r.dropoff_notes) AS notes,
    r.created_at,
    r.accepted_at,
    r.picked_up_at,
    r.delivered_at,
    COALESCE(r.recipient_phone, u.phone, ''::text) AS customer_phone
   FROM ((rides r
     LEFT JOIN merchants m ON ((m.id = r.merchant_id)))
     LEFT JOIN users u ON ((u.id = r.rider_id)))
  WHERE ((r.ride_type = 'delivery'::text) OR (r.order_id IS NOT NULL));
CREATE OR REPLACE VIEW public.driver_directory AS  SELECT id,
    full_name,
    profile_photo_url,
    vehicle_type,
    vehicle_model,
    vehicle_color,
    vehicle_plate,
    rating,
    total_deliveries,
    service_types,
    accepts_deliveries,
    max_delivery_distance_km,
    max_weight_kg,
    is_online
   FROM drivers d
  WHERE ((is_online = true) AND (is_verified = true));
CREATE OR REPLACE VIEW public.merchant_storefront AS  SELECT id,
    name,
    type,
    status,
    description,
    logo_url,
    cover_url,
    address,
    latitude,
    longitude,
    rating,
    total_reviews,
    delivery_fee,
    min_order,
    delivery_time_min,
    is_featured,
    is_open
   FROM merchants
  WHERE (status = 'active'::text);

