   FROM drivers
  WHERE (drivers.user_id = auth.uid()))) OR ((ride_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM rides r
  WHERE ((r.id = driver_locations.ride_id) AND ((r.rider_id = auth.uid()) OR (r.driver_id IN ( SELECT drivers.id
