  WHERE ((d.user_id = auth.uid()) AND ((d.id)::text = split_part(objects.name, '/'::text, 2))))))));
CREATE POLICY driver_documents_insert_owner ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'driver-documents'::text) AND (is_admin() OR (split_part(name, '/'::text, 2) = (auth.uid())::text) OR (EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.user_id = auth.uid()) AND ((d.id)::text = split_part(objects.name, '/'::text, 2))))))));
CREATE POLICY driver_documents_select_owner ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'driver-documents'::text) AND (is_admin() OR (split_part(name, '/'::text, 2) = (auth.uid())::text) OR (EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.user_id = auth.uid()) AND ((d.id)::text = split_part(objects.name, '/'::text, 2))))))));
CREATE POLICY driver_documents_update_owner ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'driver-documents'::text) AND (is_admin() OR (split_part(name, '/'::text, 2) = (auth.uid())::text) OR (EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.user_id = auth.uid()) AND ((d.id)::text = split_part(objects.name, '/'::text, 2)))))))) WITH CHECK (((bucket_id = 'driver-documents'::text) AND (is_admin() OR (split_part(name, '/'::text, 2) = (auth.uid())::text) OR (EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.user_id = auth.uid()) AND ((d.id)::text = split_part(objects.name, '/'::text, 2))))))));
CREATE POLICY profiles_delete_owner ON storage.objects AS PERMISSIVE FOR DELETE TO public USING (((bucket_id = 'profiles'::text) AND (is_admin() OR ((split_part(name, '/'::text, 2))::uuid = auth.uid()))));
CREATE POLICY profiles_insert_owner ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK (((bucket_id = 'profiles'::text) AND (is_admin() OR ((split_part(name, '/'::text, 2))::uuid = auth.uid()))));
CREATE POLICY profiles_update_owner ON storage.objects AS PERMISSIVE FOR UPDATE TO public USING (((bucket_id = 'profiles'::text) AND (is_admin() OR ((split_part(name, '/'::text, 2))::uuid = auth.uid()))));
CREATE POLICY topup_proofs_delete_self_owner ON storage.objects AS PERMISSIVE FOR DELETE TO public USING (((bucket_id = 'topup-proofs'::text) AND (((split_part(name, '/'::text, 1))::uuid = auth.uid()) OR _is_owner_uid(auth.uid()))));
CREATE POLICY topup_proofs_insert_self_owner ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK (((bucket_id = 'topup-proofs'::text) AND (((split_part(name, '/'::text, 1))::uuid = auth.uid()) OR _is_owner_uid(auth.uid()))));
CREATE POLICY topup_proofs_select_self_owner ON storage.objects AS PERMISSIVE FOR SELECT TO public USING (((bucket_id = 'topup-proofs'::text) AND (((split_part(name, '/'::text, 1))::uuid = auth.uid()) OR _is_owner_uid(auth.uid()))));
CREATE POLICY topup_proofs_update_self_owner ON storage.objects AS PERMISSIVE FOR UPDATE TO public USING (((bucket_id = 'topup-proofs'::text) AND (((split_part(name, '/'::text, 1))::uuid = auth.uid()) OR _is_owner_uid(auth.uid()))));

